// #region debug-point publish-webtest-regression-log
const DBG_SESSION_ID = "publish-webtest-regression";
const DBG_RUN_ID = "post";
const dbgEmit = (hypothesisId, name, payload) => {
  try {
    const dir = path.join(resolveProjectRoot(), ".dbg");
    fs.mkdirSync(dir, { recursive: true });
    const file = path.join(dir, `trae-debug-log-${DBG_SESSION_ID}.ndjson`);
    const evt = {
      ts: Date.now(),
      sessionId: DBG_SESSION_ID,
      runId: DBG_RUN_ID,
      hypothesisId: String(hypothesisId || ""),
      name: String(name || ""),
      payload: payload && typeof payload === "object" ? payload : { value: payload }
    };
    fs.appendFileSync(file, `${JSON.stringify(evt)}${os.EOL}`, "utf-8");
  } catch {}
};
// #endregion debug-point publish-webtest-regression-log

// #region debug-point xhs-publish-automation-log
let _xhsDbgUrl = "";
const _xhsDbgSessionId = "xhs-publish-automation";
const _xhsDbgResolveUrlOnce = () => {
  if (_xhsDbgUrl) return _xhsDbgUrl;
  try {
    const envFile = path.join(resolveProjectRoot(), ".dbg", `${_xhsDbgSessionId}.env`);
    if (!fs.existsSync(envFile)) return "";
    const text = fs.readFileSync(envFile, "utf-8");
    const lines = String(text || "")
      .split(/\r?\n/)
      .map((x) => String(x || "").trim())
      .filter(Boolean);
    const map = {};
    for (const ln of lines) {
      const idx = ln.indexOf("=");
      if (idx <= 0) continue;
      const k = ln.slice(0, idx).trim();
      const v = ln.slice(idx + 1).trim();
      if (k) map[k] = v;
    }
    const url = String(map.DEBUG_SERVER_URL || "").trim();
    if (!url) return "";
    _xhsDbgUrl = url;
    return _xhsDbgUrl;
  } catch {
    return "";
  }
};
const dbgXhsEmit = (hypothesisId, name, payload) => {
  try {
    const urlText = _xhsDbgResolveUrlOnce();
    if (!urlText) return;
    const u = new URL(urlText);
    const body = Buffer.from(
      JSON.stringify({
        ts: Date.now(),
        sessionId: _xhsDbgSessionId,
        runId: "pre",
        hypothesisId: String(hypothesisId || ""),
        name: String(name || ""),
        payload: payload && typeof payload === "object" ? payload : { value: payload }
      }),
      "utf-8"
    );
    const client = u.protocol === "https:" ? https : http;
    const req = client.request(
      {
        protocol: u.protocol,
        hostname: u.hostname,
        port: u.port,
        path: u.pathname + (u.search || ""),
        method: "POST",
        headers: { "content-type": "application/json", "content-length": body.length }
      },
      (res) => {
        try {
          res.resume();
        } catch {}
      }
    );
    req.on("error", () => {});
    req.end(body);
  } catch {}
};
// #endregion debug-point xhs-publish-automation-log

