const captureInstallerCloseMidwayProcessSnapshot = (hypothesisId, location, stage, extra = {}) => {
  try {
    const child = spawn("tasklist", ["/FO", "CSV", "/NH"], { windowsHide: true });
    let stdout = "";
    let stderr = "";
    child.stdout?.on("data", (buf) => {
      stdout += String(buf || "");
    });
    child.stderr?.on("data", (buf) => {
      stderr += String(buf || "");
    });
    child.on("close", (code) => {
      try {
        const rows = String(stdout || "")
          .split(/\r?\n/)
          .map((line) => String(line || "").trim())
          .filter(Boolean)
          .slice(0, 180);
        const matched = rows
          .map((line) => {
            const normalized = line.replace(/^"|"$/g, "");
            const cols = normalized.split('","');
            return {
              imageName: String(cols[0] || "").trim(),
              pid: String(cols[1] || "").trim(),
              sessionName: String(cols[2] || "").trim(),
              sessionNum: String(cols[3] || "").trim(),
              memUsage: String(cols[4] || "").trim()
            };
          })
          .filter((item) => /不空IP智能体|bukong-ip-agent|crashpad|elevate|un_a|electron/i.test(item.imageName || ""));
        dbgInstallerCloseMidwayEmit(hypothesisId, location, "进程快照", {
          stage: String(stage || "").trim(),
          code: Math.max(-1, Number(code ?? -1) || -1),
          matches: matched,
          stderr: String(stderr || "").trim(),
          ...((extra && typeof extra === "object") ? extra : {})
        });
      } catch {}
    });
    child.on("error", (error) => {
      dbgInstallerCloseMidwayEmit(hypothesisId, location, "抓取进程快照失败", {
        stage: String(stage || "").trim(),
        errorMessage: String(error?.message || error || "").trim(),
        ...((extra && typeof extra === "object") ? extra : {})
      });
    });
  } catch (error) {
    dbgInstallerCloseMidwayEmit(hypothesisId, location, "启动进程快照失败", {
      stage: String(stage || "").trim(),
      errorMessage: String(error?.message || error || "").trim(),
      ...((extra && typeof extra === "object") ? extra : {})
    });
  }
};
// #endregion

