function getTestLogFilePath() {
  return path.join(resolveProjectRoot(), "测试日志.md");
}

function ensureTestLogFile() {
  try {
    const file = getTestLogFilePath();
    if (!fs.existsSync(file)) {
      const head = [
        "# 测试日志",
        "",
        "- 说明：该文件记录软件执行动作、过程反馈与关键结果，便于排查问题。",
        ""
      ].join(os.EOL);
      fs.writeFileSync(file, head, "utf-8");
    }
    return file;
  } catch {
    return "";
  }
}

function appendTestLogLine(source, level, message) {
  try {
    const file = ensureTestLogFile();
    if (!file) return false;
    const now = new Date();
    const pad = (n) => String(n).padStart(2, "0");
    const ts = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;
    const line = `- [${ts}] [${String(source || "系统")}] [${String(level || "info")}] ${String(message || "")}${os.EOL}`;
    fs.appendFileSync(file, line, "utf-8");
    return true;
  } catch {
    return false;
  }
}

function getAccountsLoginLogPath() {
  try {
    return path.join(app.getPath("userData"), "logs", "accounts-login.ndjson");
  } catch {
    return "";
  }
}

function appendAccountsLoginLogLine(payload) {
  try {
    const file = getAccountsLoginLogPath();
    if (!file) return false;
    ensureDir(path.dirname(file));
    const line = `${JSON.stringify(payload && typeof payload === "object" ? payload : { value: payload })}${os.EOL}`;
    fs.appendFileSync(file, line, "utf-8");
    return true;
  } catch {
    return false;
  }
}

function getKuaishouTraceFilePath() {
  return path.join(resolveProjectRoot(), "快手接口测试.md");
}

function ensureKuaishouTraceFile() {
  try {
    const file = getKuaishouTraceFilePath();
    if (!fs.existsSync(file)) {
      const head = ["# 快手接口测试", "", "- 说明：该文件记录快手账号登录、监听、取号、保存的全过程日志，便于排查。", ""].join(os.EOL);
      fs.writeFileSync(file, head, "utf-8");
    }
    return file;
  } catch {
    return "";
  }
}

function appendKuaishouTraceLine(stage, payload) {
  try {
    const file = ensureKuaishouTraceFile();
    if (!file) return false;
    const now = new Date();
    const pad = (n) => String(n).padStart(2, "0");
    const ts = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;
    const body = payload && typeof payload === "object" ? JSON.stringify(payload, null, 0) : String(payload || "");
    const line = `- [${ts}] [${String(stage || "stage")}] ${body}${os.EOL}`;
    fs.appendFileSync(file, line, "utf-8");
    return true;
  } catch {
    return false;
  }
}

