// #region debug-point A:kuaishou-login-report
function dbgKuaishouLoginReport(hypothesisId, location, msg, data) {
  try {
    const fs0 = fs;
    const p = path.join(resolveProjectRoot(), ".dbg", "kuaishou-login-stuck.env");
    let u = "http://127.0.0.1:7777/event";
    let s = "kuaishou-login-stuck";
    try {
      const e = fs0.readFileSync(p, "utf8");
      u = e.match(/DEBUG_SERVER_URL=(.+)/)?.[1] || u;
      s = e.match(/DEBUG_SESSION_ID=(.+)/)?.[1] || s;
    } catch {}
    if (typeof fetch !== "function") return false;
    fetch(String(u || "").trim(), {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        sessionId: s,
        runId: "pre-fix",
        hypothesisId: String(hypothesisId || ""),
        location: String(location || ""),
        msg: `[DEBUG] ${String(msg || "")}`,
        data: data && typeof data === "object" ? data : { value: data },
        ts: Date.now()
      })
    }).catch(() => {});
    return true;
  } catch {
    return false;
  }
}
// #endregion

function startDetachedProcess(exePath, args) {
  const exe = String(exePath || "").trim();
  const list = Array.isArray(args) ? args.map((x) => String(x == null ? "" : x)) : [];
  if (!exe) return { ok: false, message: "empty exe" };
  try {
    if (process.platform === "win32") {
      const q = (s) => `'${String(s || "").replace(/'/g, "''")}'`;
      const script = [
        `$exe = ${q(exe)}`,
        `$argList = @(${list.map((x) => q(x)).join(", ")})`,
        "Start-Process -FilePath $exe -ArgumentList $argList"
      ].join("\r\n");
      const encoded = Buffer.from(script, "utf16le").toString("base64");
      const proc = spawn("powershell.exe", ["-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-EncodedCommand", encoded], {
        windowsHide: true,
        detached: true,
        stdio: "ignore"
      });
      try {
        proc.unref();
      } catch {}
      return { ok: true, method: "powershell-start-process", pid: Number(proc.pid || 0) || 0 };
    }
    const proc = spawn(exe, list, { detached: true, stdio: "ignore" });
    try {
      proc.unref();
    } catch {}
    return { ok: true, method: "spawn-detached", pid: Number(proc.pid || 0) || 0 };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

function startDetachedBrowserUrl(exePath, url, extraArgs) {
  const exe = String(exePath || "").trim();
  const targetUrl = String(url || "").trim();
  const extra = Array.isArray(extraArgs) ? extraArgs.map((x) => String(x == null ? "" : x).trim()).filter(Boolean) : [];
  if (!exe) return Promise.resolve({ ok: false, message: "empty exe" });
  if (!targetUrl) return Promise.resolve({ ok: false, message: "empty url" });
  return new Promise((resolve) => {
    let settled = false;
    let proc = null;
    let spawnOk = false;
    const done = (result) => {
      if (settled) return;
      settled = true;
      resolve(result);
    };
    try {
      const args = extra.concat(["--new-window", targetUrl]);
      proc = spawn(exe, args, {
        detached: true,
        stdio: "ignore",
        windowsHide: false
      });
      const timer = setTimeout(() => {
        try {
          if (proc && typeof proc.unref === "function") proc.unref();
        } catch {}
        if (spawnOk) {
          done({ ok: true, method: "spawn-direct", pid: Number(proc?.pid || 0) || 0, args });
        } else {
          done({ ok: false, message: "chrome spawn timeout" });
        }
      }, 900);
      proc.once("spawn", () => {
        spawnOk = true;
      });
      proc.once("error", (e) => {
        try { clearTimeout(timer); } catch {}
        done({ ok: false, message: String(e?.message || e) });
      });
      proc.once("exit", (code) => {
        if (!spawnOk) {
          try { clearTimeout(timer); } catch {}
          done({ ok: false, message: `chrome exited early: ${String(code)}` });
        }
      });
    } catch (e) {
      done({ ok: false, message: String(e?.message || e) });
    }
  });
}

function resolveOllamaRoot() {
  if (app.isPackaged) {
    const exeDir = path.dirname(process.execPath || "");
    const root = exeDir ? path.join(exeDir, "ollama") : "";
    if (root && fs.existsSync(root)) return root;
    return path.join(process.resourcesPath, "ollama");
  }
  return path.join(resolveProjectRoot(), "ollama");
}

function resolveOllamaExe() {
  const root = resolveOllamaRoot();
  const candidates = [
    path.join(root, "ollama app.exe"),
    path.join(root, "ollama.exe"),
    path.join(root, "ollama"),
    path.join(root, "Ollama", "ollama.exe"),
    path.join(root, "Ollama", "ollama app.exe"),
    path.join(root, "Ollama", "ollama")
  ];
  for (const p of candidates) {
    try {
      if (p && fs.existsSync(p)) return p;
    } catch {}
  }
  const envPath = String(process.env.PATH || "");
  const sep = process.platform === "win32" ? ";" : ":";
  const parts = envPath.split(sep).map((x) => x.trim()).filter(Boolean);
  for (const dir of parts) {
    const p = process.platform === "win32" ? path.join(dir, "ollama.exe") : path.join(dir, "ollama");
    try {
      if (fs.existsSync(p)) return p;
    } catch {}
  }
  if (process.platform === "win32") {
    const candidatesWin = [
      path.join(process.env.LOCALAPPDATA || "", "Programs", "Ollama", "ollama app.exe"),
      path.join(process.env.LOCALAPPDATA || "", "Programs", "Ollama", "ollama.exe"),
      path.join(process.env.ProgramFiles || "", "Ollama", "ollama.exe"),
      path.join(process.env["ProgramFiles(x86)"] || "", "Ollama", "ollama.exe")
    ];
    for (const p of candidatesWin) {
      try {
        if (p && fs.existsSync(p)) return p;
      } catch {}
    }
  }
  return "";
}

function resolveOllamaCliExe() {
  const exePath = resolveOllamaExe();
  if (exePath && /ollama\.exe$/i.test(exePath)) return exePath;
  if (exePath && /ollama app\.exe$/i.test(exePath)) {
    const cli = path.join(path.dirname(exePath), "ollama.exe");
    try {
      if (fs.existsSync(cli)) return cli;
    } catch {}
  }
  if (process.platform === "win32") {
    const p = path.join(process.env.LOCALAPPDATA || "", "Programs", "Ollama", "ollama.exe");
    try {
      if (fs.existsSync(p)) return p;
    } catch {}
  }
  return "";
}

function resolveOllamaInstaller() {
  const root = resolveOllamaRoot();
  const candidates = [
    path.join(root, "OllamaSetup.exe"),
    path.join(root, "Ollama.msi"),
    path.join(root, "installer.exe"),
    path.join(root, "installer.msi")
  ];
  return candidates.find((p) => fs.existsSync(p)) || "";
}

function isOllamaRunningProc() {
  return !!(_ollamaProc && _ollamaProc.pid && !_ollamaProc.killed);
}

async function pingOllamaApi() {
  try {
    const res = await requestUrl("http://127.0.0.1:11434/api/version", { method: "GET", timeoutMs: 2500 });
    const buf = await readResponseBody(res);
    const raw = buf.toString("utf-8");
    return { ok: (res.statusCode || 0) >= 200 && (res.statusCode || 0) < 300, statusCode: res.statusCode || 0, raw };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

ipcMain.handle("ollama:status", async () => {
  try {
    const rootDir = resolveOllamaRoot();
    const exePath = resolveOllamaExe();
    const installerPath = resolveOllamaInstaller();
    const api = await pingOllamaApi();
    return {
      ok: true,
      rootDir,
      exePath,
      installerPath,
      running: api.ok || isOllamaRunningProc(),
      apiOk: api.ok,
      apiRaw: api.raw || ""
    };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

ipcMain.handle("ollama:start", async () => {
  try {
    const api = await pingOllamaApi();
    if (api.ok) return { ok: true, message: "already running" };
    if (isOllamaRunningProc()) return { ok: true, message: "starting" };
    const exePath = resolveOllamaExe();
    if (!exePath) return { ok: false, message: "ollama not found" };
    const args = /ollama app\.exe$/i.test(exePath) ? [] : ["serve"];
    _ollamaProc = spawn(exePath, args, { windowsHide: true, stdio: "ignore" });
    _ollamaProc.on("exit", () => {
      _ollamaProc = null;
    });
    return { ok: true };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

ipcMain.handle("ollama:stop", async () => {
  try {
    if (_ollamaProc) {
      const p = _ollamaProc;
      _ollamaProc = null;
      await killProcTree(p);
      await waitProcExit(p, 6000);
      return { ok: true };
    }
    const cli = resolveOllamaCliExe();
    if (cli) {
      const proc = spawn(cli, ["stop"], { windowsHide: true, stdio: "ignore" });
      await waitProcExit(proc, 6000);
      return { ok: true };
    }
    if (process.platform === "win32") {
      const killByName = (name) =>
        new Promise((resolve) => {
          try {
            const tk = spawn("taskkill", ["/IM", name, "/T", "/F"], { windowsHide: true });
            tk.on("exit", () => resolve(true));
            tk.on("error", () => resolve(false));
          } catch {
            resolve(false);
          }
        });
      await killByName("ollama app.exe");
      await killByName("ollama.exe");
    }
    return { ok: true };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

ipcMain.handle("ollama:install", async () => {
  try {
    const installerPath = resolveOllamaInstaller();
    if (!installerPath) return { ok: false, message: "installer not found" };
    if (process.platform !== "win32") return { ok: false, message: "unsupported platform" };
    const ext = path.extname(installerPath).toLowerCase();
    let proc = null;
    if (ext === ".msi") {
      proc = spawn("msiexec", ["/i", installerPath, "/qn", "/norestart"], { windowsHide: true });
    } else {
      proc = spawn(installerPath, ["/S"], { windowsHide: true });
    }
    const ok = await waitProcExit(proc, 180000);
    if (!ok) return { ok: false, message: "install timeout" };
    return { ok: true };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

ipcMain.handle("ollama:chat", async (_event, payload) => {
  try {
    const model = String(payload?.model || "").trim() || "llama3.1";
    const messages = Array.isArray(payload?.messages) ? payload.messages : [];
    const body = { model, stream: false, messages };
    const { statusCode, data, raw } = await requestJson("http://127.0.0.1:11434/api/chat", {
      timeoutMs: 60000,
      method: "POST",
      headers: {},
      body
    });
    if (statusCode !== 200) return { ok: false, message: `http ${statusCode}`, raw };
    const out = String(data?.message?.content || "").trim();
    return { ok: true, content: out, raw: data };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

function trackDownloadedVideo(filePath) {
  if (!filePath) return;
  try {
    const p = String(filePath);
    if (!p) return;
    downloadedVideoPaths.add(p);
  } catch {}
}

function cleanupDownloadedVideos() {
  if (_cleanupVideosOnce) return;
  _cleanupVideosOnce = true;

  const projectRoot = resolveProjectRoot();
  const candidates = new Set();
  downloadedVideoPaths.forEach((p) => candidates.add(p));

  try {
    const files = fs.readdirSync(projectRoot);
    files.forEach((name) => {
      if (!/^douyin_[A-Za-z0-9]+_\\d+\\.(mp4|mov|webm|mkv)$/i.test(name)) return;
      candidates.add(path.join(projectRoot, name));
    });
  } catch {}

  candidates.forEach((p) => {
    try {
      const abs = path.resolve(p);
      if (!abs.startsWith(path.resolve(projectRoot))) return;
      if (!fs.existsSync(abs)) return;
      const st = fs.statSync(abs);
      if (!st.isFile()) return;
      fs.unlinkSync(abs);
    } catch {}
  });
}

function hashTextKey(value = "", length = 24) {
  return crypto.createHash("sha1").update(String(value || ""), "utf-8").digest("hex").slice(0, Math.max(8, Number(length || 0) || 24));
}

function normalizeCacheComparableUrl(input = "") {
  const text = String(input || "").trim();
  if (!text) return "";
  try {
    const u = new URL(text);
    u.hash = "";
    const params = Array.from(u.searchParams.entries())
      .filter(([key]) => !/^(_?ts|timestamp|from|previous_page|utm_|share_app_id|share_token)$/i.test(String(key || "")))
      .sort(([a], [b]) => String(a).localeCompare(String(b)));
    u.search = "";
    params.forEach(([key, value]) => u.searchParams.append(key, value));
    const pathname = String(u.pathname || "").replace(/\/+$/g, "");
    return `${String(u.origin || "").toLowerCase()}${pathname}${u.search}`;
  } catch {
    return text.replace(/\s+/g, "").replace(/\/+$/g, "");
  }
}

function resolveExtractCopyCacheRoot() {
  const root = path.join(resolveUserRuntimeDataRoot(), "cache", "extract-copy");
  ensureDir(root);
  return root;
}

const EXTRACT_COPY_TASK_LOCK_STALE_MS = 2 * 60 * 1000;

function getExtractCopyTaskLock(cacheKey = "") {
  const key = String(cacheKey || "").trim();
  if (!key) return null;
  const raw = _activeExtractCopyTaskKeys.get(key);
  if (!raw) return null;
  const lock = typeof raw === "string" ? { taskId: raw, createdAt: 0, updatedAt: 0 } : raw;
  const taskId = String(lock?.taskId || "").trim();
  if (!taskId) {
    _activeExtractCopyTaskKeys.delete(key);
    return null;
  }
  const task = runningTasks.get(taskId) || null;
  const now = Date.now();
  const updatedAt = Number(lock?.updatedAt || lock?.createdAt || 0) || 0;
  const isStale = updatedAt > 0 && now - updatedAt > EXTRACT_COPY_TASK_LOCK_STALE_MS;
  const isInactive = !task || ["completed", "failed", "canceled"].includes(String(task?.status || "").trim());
  if (isStale || isInactive) {
    _activeExtractCopyTaskKeys.delete(key);
    return null;
  }
  return {
    taskId,
    createdAt: Number(lock?.createdAt || 0) || now,
    updatedAt
  };
}

function setExtractCopyTaskLock(cacheKey = "", taskId = "") {
  const key = String(cacheKey || "").trim();
  const id = String(taskId || "").trim();
  if (!key || !id) return;
  const now = Date.now();
  const existing = getExtractCopyTaskLock(key);
  _activeExtractCopyTaskKeys.set(key, {
    taskId: id,
    createdAt: Number(existing?.createdAt || now) || now,
    updatedAt: now
  });
}

function touchExtractCopyTaskLock(cacheKey = "", taskId = "") {
  const key = String(cacheKey || "").trim();
  const id = String(taskId || "").trim();
  if (!key || !id) return;
  const raw = _activeExtractCopyTaskKeys.get(key);
  if (!raw) return;
  const existingTaskId = String((typeof raw === "string" ? raw : raw?.taskId) || "").trim();
  if (existingTaskId !== id) return;
  const now = Date.now();
  const createdAt = typeof raw === "string" ? now : Number(raw?.createdAt || now) || now;
  _activeExtractCopyTaskKeys.set(key, { taskId: id, createdAt, updatedAt: now });
}

function deleteExtractCopyTaskLock(cacheKey = "", taskId = "") {
  const key = String(cacheKey || "").trim();
  if (!key) return;
  const raw = _activeExtractCopyTaskKeys.get(key);
  if (!raw) return;
  const existingTaskId = String((typeof raw === "string" ? raw : raw?.taskId) || "").trim();
  if (taskId && existingTaskId && existingTaskId !== String(taskId).trim()) return;
  _activeExtractCopyTaskKeys.delete(key);
}

function buildExtractCopyCacheKey({ inputUrl = "", resolvedUrl = "", awemeId = "" } = {}) {
  const cleanAwemeId = String(awemeId || "").trim();
  if (cleanAwemeId) return `aweme_${cleanAwemeId}`;
  const normalized = normalizeCacheComparableUrl(resolvedUrl || inputUrl);
  return normalized ? `url_${hashTextKey(normalized, 24)}` : `url_${hashTextKey(String(inputUrl || ""), 24)}`;
}

function resolveExtractCopyCacheEntryPaths({ inputUrl = "", resolvedUrl = "", awemeId = "" } = {}) {
  const cacheKey = buildExtractCopyCacheKey({ inputUrl, resolvedUrl, awemeId });
  const root = resolveExtractCopyCacheRoot();
  const entryDir = path.join(root, cacheKey);
  ensureDir(entryDir);
  return {
    cacheKey,
    root,
    entryDir,
    manifestPath: path.join(entryDir, "manifest.json"),
    textPath: path.join(entryDir, "recognized.txt"),
    directVideoPath: path.join(entryDir, "source.mp4"),
    audioPath: path.join(entryDir, "source.wav")
  };
}

function readExtractCopyCacheManifest(manifestPath = "") {
  const manifest = readJsonSafe(manifestPath) || null;
  if (!manifest || typeof manifest !== "object") return null;
  const recognizedText = String(manifest.recognizedText || "").trim();
  if (!recognizedText) return null;
  return manifest;
}

function writeExtractCopyCacheManifest(paths, payload = {}) {
  const manifestPath = String(paths?.manifestPath || "").trim();
  if (!manifestPath) return false;
  const videoPath = String(payload?.videoPath || "").trim();
  const audioPath = String(payload?.audioPath || "").trim();
  const recognizedText = String(payload?.recognizedText || "").trim();
  const manifest = {
    cacheKey: String(paths?.cacheKey || "").trim(),
    sourceUrl: String(payload?.sourceUrl || "").trim(),
    resolvedUrl: String(payload?.resolvedUrl || "").trim(),
    shareUrl: String(payload?.shareUrl || "").trim(),
    awemeId: String(payload?.awemeId || "").trim(),
    recognizedText,
    videoPath,
    audioPath,
    videoExists: !!(videoPath && fs.existsSync(videoPath)),
    audioExists: !!(audioPath && fs.existsSync(audioPath)),
    modelChoice: payload?.modelChoice && typeof payload.modelChoice === "object"
      ? {
          source: String(payload.modelChoice.source || "").trim(),
          type: String(payload.modelChoice.type || "").trim(),
          providerId: String(payload.modelChoice.providerId || "").trim(),
          modelId: String(payload.modelChoice.modelId || payload.modelChoice.model || "").trim(),
          label: String(payload.modelChoice.label || "").trim()
        }
      : null,
    createdAt: Number(payload?.createdAt || Date.now()) || Date.now(),
    updatedAt: Date.now()
  };
  const ok = writeJsonSafe(manifestPath, manifest);
  if (ok && paths?.textPath) {
    try {
      fs.writeFileSync(paths.textPath, recognizedText, "utf-8");
    } catch {}
  }
  return ok;
}

function collectFilesRecursive(rootPath, matcher = null, bucket = []) {
  const root = String(rootPath || "").trim();
  if (!root || !fs.existsSync(root)) return bucket;
  let stat = null;
  try {
    stat = fs.statSync(root);
  } catch {
    return bucket;
  }
  if (stat.isFile()) {
    if (typeof matcher !== "function" || matcher(root, stat) !== false) bucket.push(root);
    return bucket;
  }
  if (!stat.isDirectory()) return bucket;
  let entries = [];
  try {
    entries = fs.readdirSync(root, { withFileTypes: true });
  } catch {
    return bucket;
  }
  entries.forEach((entry) => {
    const fullPath = path.join(root, entry.name);
    if (entry.isDirectory()) {
      collectFilesRecursive(fullPath, matcher, bucket);
      return;
    }
    if (!entry.isFile()) return;
    let fileStat = null;
    try {
      fileStat = fs.statSync(fullPath);
    } catch {}
    if (!fileStat) return;
    if (typeof matcher !== "function" || matcher(fullPath, fileStat) !== false) bucket.push(fullPath);
  });
  return bucket;
}

function summarizeCleanupTargets(targets = []) {
  const summary = { fileCount: 0, totalBytes: 0, existingPaths: [] };
  const visited = new Set();
  const walk = (targetPath) => {
    const normalized = String(targetPath || "").trim();
    if (!normalized || visited.has(normalized) || !fs.existsSync(normalized)) return;
    visited.add(normalized);
    let stat = null;
    try {
      stat = fs.statSync(normalized);
    } catch {
      return;
    }
    summary.existingPaths.push(normalized);
    if (stat.isFile()) {
      summary.fileCount += 1;
      summary.totalBytes += Number(stat.size || 0) || 0;
      return;
    }
    if (!stat.isDirectory()) return;
    let entries = [];
    try {
      entries = fs.readdirSync(normalized, { withFileTypes: true });
    } catch {
      return;
    }
    entries.forEach((entry) => walk(path.join(normalized, entry.name)));
  };
  (Array.isArray(targets) ? targets : []).forEach((item) => walk(item));
  return summary;
}

function pruneEmptyDirs(rootPath) {
  const root = String(rootPath || "").trim();
  if (!root || !fs.existsSync(root)) return;
  let stat = null;
  try {
    stat = fs.statSync(root);
  } catch {
    return;
  }
  if (!stat.isDirectory()) return;
  let entries = [];
  try {
    entries = fs.readdirSync(root, { withFileTypes: true });
  } catch {
    return;
  }
  entries.forEach((entry) => {
    if (!entry.isDirectory()) return;
    pruneEmptyDirs(path.join(root, entry.name));
  });
  try {
    if (fs.readdirSync(root).length === 0) fs.rmdirSync(root);
  } catch {}
}

function resolveCacheCleanupConfigPath() {
  return path.join(resolveUserRuntimeDataRoot(), "cache", "cleanup-settings.json");
}

function getDefaultCacheCleanupConfig() {
  return {
    mode: "manual",
    autoCategories: ["extract-copy-videos", "extract-copy-audios"],
    updatedAt: 0
  };
}

function readCacheCleanupConfig() {
  const raw = readJsonSafe(resolveCacheCleanupConfigPath()) || {};
  const defaults = getDefaultCacheCleanupConfig();
  const mode = String(raw.mode || defaults.mode).trim() === "on-close" ? "on-close" : "manual";
  const autoCategories = Array.isArray(raw.autoCategories)
    ? [...new Set(raw.autoCategories.map((item) => String(item || "").trim()).filter(Boolean))]
    : defaults.autoCategories;
  return {
    mode,
    autoCategories,
    updatedAt: Number(raw.updatedAt || 0) || 0
  };
}

function writeCacheCleanupConfig(config = {}) {
  const normalized = {
    mode: String(config.mode || "").trim() === "on-close" ? "on-close" : "manual",
    autoCategories: Array.isArray(config.autoCategories)
      ? [...new Set(config.autoCategories.map((item) => String(item || "").trim()).filter(Boolean))]
      : [],
    updatedAt: Date.now()
  };
  writeJsonSafe(resolveCacheCleanupConfigPath(), normalized);
  return normalized;
}

function buildCacheCleanupCategoryDefinitions() {
  const extractRoot = resolveExtractCopyCacheRoot();
  const tempRoot = path.join(os.tmpdir(), "ipfactory");
  return [
    {
      key: "extract-copy-manifests",
      label: "提取文案标记文件",
      description: "保存链接、识别文案和关联信息。保留它们时，同链接下次可直接返回文案。",
      collectTargets: () => collectFilesRecursive(extractRoot, (filePath) => path.basename(filePath).toLowerCase() === "manifest.json" || path.basename(filePath).toLowerCase() === "recognized.txt")
    },
    {
      key: "extract-copy-videos",
      label: "提取文案缓存视频",
      description: "首页提取文案时下载下来的源视频缓存。",
      collectTargets: () => collectFilesRecursive(extractRoot, (filePath) => /\.(mp4|mov|webm|mkv)$/i.test(filePath))
    },
    {
      key: "extract-copy-audios",
      label: "提取文案缓存音频",
      description: "首页提取文案时从视频里抽取出来的音频缓存。",
      collectTargets: () => collectFilesRecursive(extractRoot, (filePath) => /\.(wav|mp3|m4a|aac|flac|ogg)$/i.test(filePath))
    },
    {
      key: "voice-preview-cache",
      label: "音色试听缓存",
      description: "系统音色试听和克隆音色预览缓存，清理后下次试听会重新生成。",
      collectTargets: () => [resolveVoicePreviewCacheRoot()]
    },
    {
      key: "app-update-cache",
      label: "自动更新缓存",
      description: "安装包下载缓存、补丁和安装日志。",
      collectTargets: () => [getAppUpdateCacheDir()]
    },
    {
      key: "runtime-temp-ipfactory",
      label: "运行时临时文件",
      description: "系统临时目录下的音频、视频、字幕处理临时文件，建议在空闲时清理。",
      collectTargets: () => [tempRoot]
    }
  ];
}

function buildCacheCleanupOverview() {
  const defs = buildCacheCleanupCategoryDefinitions();
  return defs.map((item) => {
    const targets = item.collectTargets();
    const summary = summarizeCleanupTargets(targets);
    return {
      key: item.key,
      label: item.label,
      description: item.description,
      fileCount: summary.fileCount,
      totalBytes: summary.totalBytes,
      samplePaths: summary.existingPaths.slice(0, 5)
    };
  });
}

function clearCacheByCategories(keys = [], { reason = "manual" } = {}) {
  const selectedKeys = [...new Set((Array.isArray(keys) ? keys : []).map((item) => String(item || "").trim()).filter(Boolean))];
  const defs = buildCacheCleanupCategoryDefinitions().filter((item) => selectedKeys.includes(item.key));
  const removed = [];
  const skipped = [];
  let removedFileCount = 0;
  let removedBytes = 0;
  defs.forEach((item) => {
    const targets = item.collectTargets();
    const summary = summarizeCleanupTargets(targets);
    const uniqueTargets = [...new Set(summary.existingPaths)];
    if (!uniqueTargets.length) {
      skipped.push({ key: item.key, label: item.label, reason: "empty" });
      return;
    }
    uniqueTargets.forEach((targetPath) => {
      try {
        const stat = fs.statSync(targetPath);
        if (stat.isDirectory()) {
          fs.rmSync(targetPath, { recursive: true, force: true });
        } else {
          fs.unlinkSync(targetPath);
        }
      } catch {}
    });
    removed.push({
      key: item.key,
      label: item.label,
      fileCount: summary.fileCount,
      totalBytes: summary.totalBytes
    });
    removedFileCount += summary.fileCount;
    removedBytes += summary.totalBytes;
  });
  pruneEmptyDirs(resolveExtractCopyCacheRoot());
  return {
    ok: true,
    reason,
    removed,
    skipped,
    removedFileCount,
    removedBytes,
    config: readCacheCleanupConfig(),
    categories: buildCacheCleanupOverview()
  };
}

function runAutoCacheCleanupIfNeeded(reason = "app-close") {
  if (_cacheAutoCleanupDone) return { ok: true, skipped: true, reason: "already-cleaned" };
  const config = readCacheCleanupConfig();
  if (config.mode !== "on-close" || !Array.isArray(config.autoCategories) || !config.autoCategories.length) {
    return { ok: true, skipped: true, reason: "manual-mode" };
  }
  _cacheAutoCleanupDone = true;
  return clearCacheByCategories(config.autoCategories, { reason });
}

function requestJson(url, { method = "POST", headers = {}, timeoutMs = 20000, body, signal = null } = {}) {
  return new Promise((resolve, reject) => {
    let settled = false;
    let abortHandler = null;
    const done = (cb, value) => {
      if (settled) return;
      settled = true;
      try {
        if (signal && abortHandler) signal.removeEventListener("abort", abortHandler);
      } catch {}
      cb(value);
    };
    const u = new URL(url);
    const lib = u.protocol === "https:" ? https : http;
    const req = lib.request(
      {
        protocol: u.protocol,
        hostname: u.hostname,
        port: u.port || (u.protocol === "https:" ? 443 : 80),
        path: `${u.pathname}${u.search}`,
        method,
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
          ...headers
        }
      },
      (res) => {
        (async () => {
          const buf = await readResponseBody(res);
          const raw = buf.toString("utf-8");
          done(resolve, { statusCode: res.statusCode || 0, data: raw ? JSON.parse(raw) : null, raw });
        })().catch((error) => done(reject, error));
      }
    );
    req.on("error", (error) => done(reject, error));
    req.setTimeout(timeoutMs, () => {
      try {
        req.destroy(new Error("timeout"));
      } catch {}
    });
    if (signal) {
      if (signal.aborted) {
        try {
          req.destroy(new Error("canceled"));
        } catch {}
        done(reject, new Error("canceled"));
        return;
      }
      abortHandler = () => {
        try {
          req.destroy(new Error("canceled"));
        } catch {}
        done(reject, new Error("canceled"));
      };
      signal.addEventListener("abort", abortHandler, { once: true });
    }
    if (!["GET", "HEAD"].includes(String(method || "POST").toUpperCase())) {
      req.write(JSON.stringify(body ?? {}));
    }
    req.end();
  });
}

function requestText(url, { method = "GET", headers = {}, timeoutMs = 20000, body } = {}) {
  return new Promise((resolve, reject) => {
    const u = new URL(url);
    const lib = u.protocol === "https:" ? https : http;
    const req = lib.request(
      {
        protocol: u.protocol,
        hostname: u.hostname,
        port: u.port || (u.protocol === "https:" ? 443 : 80),
        path: `${u.pathname}${u.search}`,
        method,
        headers: {
          Accept: "application/json,text/plain,*/*",
          "Content-Type": "application/json",
          ...headers
        }
      },
      (res) => {
        (async () => {
          const buf = await readResponseBody(res);
          const raw = buf.toString("utf-8");
          resolve({
            statusCode: res.statusCode || 0,
            raw,
            contentType: String(res.headers?.["content-type"] || "").trim()
          });
        })().catch(reject);
      }
    );
    req.on("error", reject);
    req.setTimeout(timeoutMs, () => {
      try {
        req.destroy(new Error("timeout"));
      } catch {}
    });
    if (!["GET", "HEAD"].includes(String(method || "GET").toUpperCase())) {
      req.write(JSON.stringify(body ?? {}));
    }
    req.end();
  });
}

function requestMultipartForm(
  url,
  { method = "POST", headers = {}, timeoutMs = 120000, fields = {}, fileFieldName = "file", filePath = "", fileName = "", fileContentType = "" } = {}
) {
  return new Promise((resolve, reject) => {
    const resolvedFilePath = String(filePath || "").trim();
    if (!resolvedFilePath || !fs.existsSync(resolvedFilePath)) {
      reject(new Error(`upload file not found: ${resolvedFilePath}`));
      return;
    }
    const boundary = `----IPFactoryBoundary${Date.now().toString(16)}${crypto.randomBytes(8).toString("hex")}`;
    const u = new URL(url);
    const lib = u.protocol === "https:" ? https : http;
    const req = lib.request(
      {
        protocol: u.protocol,
        hostname: u.hostname,
        port: u.port || (u.protocol === "https:" ? 443 : 80),
        path: `${u.pathname}${u.search}`,
        method,
        headers: {
          Accept: "application/json,text/plain,*/*",
          "Content-Type": `multipart/form-data; boundary=${boundary}`,
          ...headers
        }
      },
      (res) => {
        (async () => {
          const buf = await readResponseBody(res);
          resolve({
            statusCode: res.statusCode || 0,
            raw: buf.toString("utf-8"),
            contentType: String(res.headers?.["content-type"] || "").trim()
          });
        })().catch(reject);
      }
    );
    req.on("error", reject);
    req.setTimeout(timeoutMs, () => {
      try {
        req.destroy(new Error("timeout"));
      } catch {}
    });

    Object.entries(fields || {}).forEach(([key, value]) => {
      req.write(`--${boundary}\r\n`);
      req.write(`Content-Disposition: form-data; name="${String(key || "")}"\r\n\r\n`);
      req.write(`${String(value ?? "")}\r\n`);
    });

    const resolvedFileName = String(fileName || path.basename(resolvedFilePath) || "upload.bin").trim() || "upload.bin";
    req.write(`--${boundary}\r\n`);
    req.write(`Content-Disposition: form-data; name="${String(fileFieldName || "file")}"; filename="${resolvedFileName}"\r\n`);
    req.write(`Content-Type: ${String(fileContentType || detectMimeTypeByFilePath(resolvedFilePath, "application/octet-stream"))}\r\n\r\n`);

    const stream = fs.createReadStream(resolvedFilePath);
    stream.on("error", (error) => {
      try {
        req.destroy(error);
      } catch {}
      reject(error);
    });
    stream.on("end", () => {
      req.end(`\r\n--${boundary}--\r\n`);
    });
    stream.pipe(req, { end: false });
  });
}

async function uploadFileToDashscopeTempUrl({ apiKey = "", model = "", filePath = "" } = {}) {
  const resolvedApiKey = String(apiKey || "").trim();
  const resolvedModel = String(model || "").trim();
  const resolvedFilePath = String(filePath || "").trim();
  if (!resolvedApiKey) throw new Error("阿里云百炼 API Key 为空");
  if (!resolvedModel) throw new Error("阿里云百炼模型名称为空");
  if (!resolvedFilePath || !fs.existsSync(resolvedFilePath)) throw new Error(`待上传文件不存在：${resolvedFilePath}`);

  const uploadsUrl = new URL("https://dashscope.aliyuncs.com/api/v1/uploads");
  uploadsUrl.searchParams.set("action", "getPolicy");
  uploadsUrl.searchParams.set("model", resolvedModel);
  const { statusCode, data, raw } = await requestJson(uploadsUrl.toString(), {
    method: "GET",
    timeoutMs: 30000,
    headers: {
      Authorization: `Bearer ${resolvedApiKey}`
    }
  });
  if (statusCode < 200 || statusCode >= 300) {
    throw new Error(`百炼临时文件上传凭证获取失败 HTTP ${statusCode}${raw ? `：${String(raw).slice(0, 200)}` : ""}`);
  }
  const policyData = data?.data && typeof data.data === "object" ? data.data : data;
  const uploadHost = String(policyData?.upload_host || "").trim();
  const uploadDir = String(policyData?.upload_dir || "").trim();
  if (!uploadHost || !uploadDir) throw new Error("百炼临时文件上传凭证返回不完整");

  const originalName = String(path.basename(resolvedFilePath) || "upload.bin").trim() || "upload.bin";
  const ext = path.extname(originalName) || "";
  const base = originalName.slice(0, ext ? -ext.length : undefined).replace(/[^\w.-]+/g, "_") || "upload";
  const key = `${uploadDir}/${base}_${Date.now()}_${hashTextKey(resolvedFilePath, 8)}${ext}`;

  const { statusCode: uploadStatus, raw: uploadRaw } = await requestMultipartForm(uploadHost, {
    timeoutMs: 10 * 60 * 1000,
    fields: {
      OSSAccessKeyId: String(policyData?.oss_access_key_id || "").trim(),
      Signature: String(policyData?.signature || "").trim(),
      policy: String(policyData?.policy || "").trim(),
      "x-oss-object-acl": String(policyData?.x_oss_object_acl || "").trim(),
      "x-oss-forbid-overwrite": String(policyData?.x_oss_forbid_overwrite || "").trim(),
      key,
      success_action_status: "200"
    },
    filePath: resolvedFilePath,
    fileName: originalName,
    fileContentType: detectMimeTypeByFilePath(resolvedFilePath, "application/octet-stream")
  });
  if (uploadStatus < 200 || uploadStatus >= 300) {
    throw new Error(`百炼临时文件上传失败 HTTP ${uploadStatus}${uploadRaw ? `：${String(uploadRaw).slice(0, 200)}` : ""}`);
  }
  return `oss://${key}`;
}

async function pollDashscopeAsyncTask({ apiKey = "", taskId = "", event = null, localTaskId = "", pollUrl = "" } = {}) {
  const resolvedApiKey = String(apiKey || "").trim();
  const resolvedTaskId = String(taskId || "").trim();
  const resolvedPollUrl = String(pollUrl || "").trim();
  if (!resolvedApiKey) throw new Error("阿里云百炼 API Key 为空");
  if (!resolvedTaskId) throw new Error("百炼异步任务 task_id 为空");
  if (!resolvedPollUrl) throw new Error("百炼异步任务轮询地址为空");

  const progressMap = {
    PENDING: 22,
    "PRE-PROCESSING": 36,
    RUNNING: 62,
    "POST-PROCESSING": 82
  };
  let lastStatus = "";
  let lastCode = "";
  let lastMessage = "";
  let pollCount = 0;
  const startedAt = Date.now();
  while (Date.now() - startedAt < 20 * 60 * 1000) {
    const task = _videoTasks.get(String(localTaskId || "").trim()) || null;
    if (task?.canceled === true) return { canceled: true };
    pollCount += 1;

    const { statusCode, data, raw } = await requestJson(resolvedPollUrl, {
      method: "GET",
      timeoutMs: 30000,
      headers: {
        Authorization: `Bearer ${resolvedApiKey}`
      }
    });
    if (statusCode < 200 || statusCode >= 300) {
      throw new Error(`百炼异步任务查询失败 HTTP ${statusCode}${raw ? `：${String(raw).slice(0, 200)}` : ""}`);
    }
    const output = data?.output && typeof data.output === "object" ? data.output : {};
    const taskStatus = String(output?.task_status || "").trim().toUpperCase();
    const taskCode = String(output?.code || data?.code || "").trim();
    const taskMessage = String(output?.message || data?.message || "").trim();
    const elapsedSec = Math.max(0, Math.round((Date.now() - startedAt) / 1000));
    if (taskStatus && taskStatus !== lastStatus) {
      lastStatus = taskStatus;
      sendVideoLog(event, localTaskId, "info", `百炼 VideoRetalk 任务状态：${taskStatus}`);
      sendVideoProgress(event, localTaskId, progressMap[taskStatus] || 45, `云端数字人任务状态：${taskStatus}`);
    }
    if ((taskCode && taskCode !== lastCode) || (taskMessage && taskMessage !== lastMessage)) {
      lastCode = taskCode;
      lastMessage = taskMessage;
      sendVideoLog(event, localTaskId, taskStatus === "FAILED" ? "error" : "warn", `百炼任务详情：${taskCode || "NO_CODE"} ${taskMessage || "无附加信息"}`);
    }
    if (!taskStatus || taskStatus === lastStatus) {
      if (pollCount % 3 === 0) {
        sendVideoLog(event, localTaskId, "info", `百炼 VideoRetalk 轮询中：状态 ${taskStatus || "UNKNOWN"}，已等待 ${elapsedSec}s`);
      }
      if (taskStatus === "PENDING" && elapsedSec >= 90 && pollCount % 6 === 0) {
        sendVideoLog(
          event,
          localTaskId,
          "warn",
          "百炼任务仍在排队/PENDING。若长时间无变化，常见原因包括视频分辨率/FPS不满足要求、人物脸部不够清晰、音频人声不够纯净，或百炼当前队列拥堵。"
        );
      }
    }
    if (taskStatus === "SUCCEEDED") return { ok: true, data };
    if (taskStatus === "FAILED") {
      const code = String(output?.code || "").trim();
      const message = String(output?.message || data?.message || "云端数字人任务失败").trim();
      throw new Error(`${message}${code ? `（${code}）` : ""}`);
    }
    if (taskStatus === "UNKNOWN") throw new Error("百炼 VideoRetalk 任务不存在或状态未知");
    await new Promise((resolve) => setTimeout(resolve, 4000));
  }
  throw new Error("百炼 VideoRetalk 任务轮询超时");
}

async function generateTalkingVideoByAliyunVideoRetalk({ event = null, taskId = "", task = null, videoPath = "", audioPath = "", modelChoice = null } = {}) {
  const apiKey = String(modelChoice?.apiKey || "").trim();
  const endpoint = String(modelChoice?.endpoint || "https://dashscope.aliyuncs.com/api/v1/services/aigc/image2video/video-synthesis/").trim();
  const model = String(modelChoice?.modelId || modelChoice?.model || "videoretalk").trim() || "videoretalk";
  if (!apiKey) return { ok: false, taskId, message: "当前云端数字人模型未配置 API Key" };
  if (!endpoint) return { ok: false, taskId, message: "当前云端数字人模型未配置 endpoint" };

  const ffmpegExe = pickFfmpegExeFromBundles();
  const [videoMeta, audioMeta] = await Promise.all([
    probeVideoMetaViaFfmpeg(ffmpegExe, videoPath),
    probeVideoMetaViaFfmpeg(ffmpegExe, audioPath)
  ]);
  const videoDurationSec = Math.max(0, Number(videoMeta?.durationSec || 0) || 0);
  const audioDurationSec = Math.max(0, Number(audioMeta?.durationSec || 0) || 0);
  const explicitVideoExtension =
    typeof modelChoice?.videoExtension === "boolean"
      ? modelChoice.videoExtension
      : typeof modelChoice?.parameters?.video_extension === "boolean"
        ? modelChoice.parameters.video_extension
        : null;
  const shouldExtendVideo =
    explicitVideoExtension != null
      ? explicitVideoExtension
      : audioDurationSec <= 0 || videoDurationSec <= 0
        ? true
        : audioDurationSec > videoDurationSec + 0.25;
  const queryFaceThresholdRaw = Number(modelChoice?.queryFaceThreshold ?? modelChoice?.parameters?.query_face_threshold);
  const queryFaceThreshold = Number.isFinite(queryFaceThresholdRaw) && queryFaceThresholdRaw >= 120 && queryFaceThresholdRaw <= 200 ? Math.round(queryFaceThresholdRaw) : 170;

  sendVideoProgress(event, taskId, 6, "正在上传视频和音频到阿里云百炼临时存储...");
  sendVideoLog(event, taskId, "info", `云端数字人模型：${String(modelChoice?.label || model || "未命名模型")}`);
  sendVideoLog(
    event,
    taskId,
    "info",
    `VideoRetalk 原视频信息：${videoMeta?.width || 0}x${videoMeta?.height || 0}，${videoMeta?.fps ? `${Number(videoMeta.fps).toFixed(2)}fps` : "未知fps"}，时长 ${videoDurationSec > 0 ? `${videoDurationSec.toFixed(2)}s` : "未知"}`
  );
  sendVideoLog(
    event,
    taskId,
    "info",
    `VideoRetalk 原音频信息：${audioDurationSec > 0 ? `${audioDurationSec.toFixed(2)}s` : "未知"}，video_extension=${shouldExtendVideo ? "true" : "false"}，query_face_threshold=${queryFaceThreshold}`
  );
  sendVideoLog(
    event,
    taskId,
    "info",
    `VideoRetalk 时长检测：原视频 ${videoDurationSec > 0 ? `${videoDurationSec.toFixed(2)}s` : "未知"}，音频 ${audioDurationSec > 0 ? `${audioDurationSec.toFixed(2)}s` : "未知"}，video_extension=${shouldExtendVideo ? "true" : "false"}`
  );
  if ((Number(videoMeta?.width || 0) > 0 && Number(videoMeta?.width || 0) < 640) || (Number(videoMeta?.height || 0) > 0 && Number(videoMeta?.height || 0) < 640)) {
    sendVideoLog(event, taskId, "warn", "当前原视频分辨率边长小于 640，百炼 VideoRetalk 可能会长时间排队后失败或效果异常。");
  }
  if (Number(videoMeta?.fps || 0) > 0 && (Number(videoMeta?.fps || 0) < 15 || Number(videoMeta?.fps || 0) > 60)) {
    sendVideoLog(event, taskId, "warn", "当前原视频 FPS 不在 15~60 范围内，百炼 VideoRetalk 可能会长时间排队后失败或效果异常。");
  }
  const videoUrl = await uploadFileToDashscopeTempUrl({ apiKey, model, filePath: videoPath });
  const audioUrl = await uploadFileToDashscopeTempUrl({ apiKey, model, filePath: audioPath });
  let refImageUrl = "";
  try {
    if (ffmpegExe && fs.existsSync(ffmpegExe)) {
      const tmpDir = path.join(os.tmpdir(), "ipfactory", "videoretalk-ref");
      ensureDir(tmpDir);
      const refPath = path.join(tmpDir, `${sanitizeFsName(taskId || "videoretalk", "videoretalk")}_${Date.now()}_ref.jpg`);
      const ok = await generateVideoThumb(ffmpegExe, videoPath, refPath);
      if (ok && fs.existsSync(refPath)) {
        refImageUrl = await uploadFileToDashscopeTempUrl({ apiKey, model, filePath: refPath });
        sendVideoLog(event, taskId, "info", `百炼参考人脸图已生成：${refImageUrl}`);
      }
    }
  } catch (e) {
    sendVideoLog(event, taskId, "warn", `百炼参考人脸图生成失败，继续按无参考图模式提交：${String(e?.message || e)}`);
  }
  sendVideoLog(event, taskId, "info", `百炼临时视频地址：${videoUrl}`);
  sendVideoLog(event, taskId, "info", `百炼临时音频地址：${audioUrl}`);

  sendVideoProgress(event, taskId, 18, "正在提交阿里云百炼 VideoRetalk 任务...");
  const { statusCode, data, raw } = await requestJson(endpoint, {
    timeoutMs: 60000,
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "X-DashScope-Async": "enable",
      "X-DashScope-OssResourceResolve": "enable"
    },
    body: {
      model,
      input: {
        video_url: videoUrl,
        audio_url: audioUrl,
        ...(refImageUrl ? { ref_image_url: refImageUrl } : {})
      },
      parameters: {
        video_extension: shouldExtendVideo,
        query_face_threshold: queryFaceThreshold
      }
    }
  });
  if (statusCode < 200 || statusCode >= 300) {
    return { ok: false, taskId, message: `阿里云百炼 VideoRetalk 调用失败 HTTP ${statusCode}${raw ? `：${String(raw).slice(0, 220)}` : ""}` };
  }
  const remoteTaskId = String(data?.output?.task_id || data?.task_id || "").trim();
  if (!remoteTaskId) {
    return { ok: false, taskId, message: "阿里云百炼 VideoRetalk 未返回 task_id" };
  }
  sendVideoLog(event, taskId, "info", `百炼 VideoRetalk 任务已提交：${remoteTaskId}`);

  const pollOrigin = `${new URL(endpoint).origin}/api/v1/tasks/${encodeURIComponent(remoteTaskId)}`;
  const pollResult = await pollDashscopeAsyncTask({
    apiKey,
    taskId: remoteTaskId,
    event,
    localTaskId: taskId,
    pollUrl: pollOrigin
  });
  if (pollResult?.canceled) return { canceled: true, taskId };

  const taskData = pollResult?.data || {};
  const output = taskData?.output && typeof taskData.output === "object" ? taskData.output : {};
  const resultVideoUrl = String(output?.video_url || output?.videoUrl || "").trim();
  if (!resultVideoUrl) return { ok: false, taskId, message: "阿里云百炼 VideoRetalk 未返回 video_url" };

  const outRoot = resolveVideoTemplateRoot();
  ensureDir(outRoot);
  const templateId = `talk_${taskId}_${Date.now()}`;
  const templateDir = path.join(outRoot, templateId);
  ensureDir(templateDir);
  const outPath = path.join(templateDir, "result.mp4");

  sendVideoProgress(event, taskId, 90, "正在下载阿里云百炼生成结果...");
  await downloadToFile(resultVideoUrl, outPath, { maxHops: 8, isCanceled: () => task?.canceled === true });
  fs.writeFileSync(
    path.join(templateDir, "meta.json"),
    JSON.stringify(
      {
        id: templateId,
        taskId,
        createdAt: Date.now(),
        type: "talking_video",
        source: "cloud",
        providerId: "aliyun-bailian",
        model,
        remoteTaskId,
        videoExtension: shouldExtendVideo,
        sourceVideoDurationSec: videoDurationSec,
        sourceAudioDurationSec: audioDurationSec,
        usage: taskData?.usage || {}
      },
      null,
      2
    ),
    "utf-8"
  );
  return { ok: true, taskId, videoPath: outPath, templateId, templateDir, source: "cloud" };
}

function summarizeRemoteRawSnippet(raw = "", maxLength = 120) {
  const text = String(raw || "").replace(/\s+/g, " ").trim();
  if (!text) return "";
  return text.slice(0, Math.max(16, Number(maxLength || 0) || 120));
}

function buildManifestFetchErrorMessage({ manifestUrl = "", statusCode = 0, contentType = "", raw = "", errorMessage = "" } = {}) {
  const url = String(manifestUrl || "").trim();
  const type = String(contentType || "").trim();
  const snippet = summarizeRemoteRawSnippet(raw, 160);
  const looksXml = /^\s*</.test(String(raw || "")) || /xml/i.test(type);
  if (errorMessage) {
    return `云端更新清单读取失败：${errorMessage}${url ? `，地址：${url}` : ""}`;
  }
  if (looksXml) {
    return `云端更新清单地址返回的不是 JSON，而是 XML 错误页（HTTP ${statusCode || 0}${type ? `，${type}` : ""}），地址：${url}${snippet ? `，返回片段：${snippet}` : ""}`;
  }
  return `云端更新清单返回的不是有效 JSON（HTTP ${statusCode || 0}${type ? `，${type}` : ""}），地址：${url}${snippet ? `，返回片段：${snippet}` : ""}`;
}

function getDeviceIdFilePath() {
  try {
    return path.join(app.getPath("userData"), "device-id.txt");
  } catch {
    return "";
  }
}

function writeDeviceIdToJson(deviceId) {
  const id = String(deviceId || "").trim();
  if (!id) return { ok: false, message: "empty device id" };
  try {
    const next = { deviceId: id, updatedAt: new Date().toISOString() };
    fs.writeFileSync(JIQIMA_JSON_PATH, JSON.stringify(next, null, 2), "utf-8");
    return { ok: true, deviceId: id };
  } catch (e) {
    return { ok: false, deviceId: id, message: String(e?.message || e) };
  }
}

function readDeviceIdFromJson() {
  try {
    if (!fs.existsSync(JIQIMA_JSON_PATH)) return { ok: false, deviceId: "" };
    const raw = String(fs.readFileSync(JIQIMA_JSON_PATH, "utf-8") || "").trim();
    if (!raw) return { ok: false, deviceId: "" };
    const obj = JSON.parse(raw);
    const deviceId = String(obj?.deviceId || "").trim();
    return { ok: !!deviceId, deviceId, updatedAt: obj?.updatedAt || null };
  } catch (e) {
    return { ok: false, deviceId: "", message: String(e?.message || e) };
  }
}

function getOrCreateDeviceId() {
  const file = getDeviceIdFilePath();
  if (file) {
    try {
      const raw = String(fs.readFileSync(file, "utf-8") || "").trim();
      if (raw) {
        writeDeviceIdToJson(raw);
        return raw;
      }
    } catch {}
    const id = crypto.randomBytes(16).toString("hex");
    try {
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, id, "utf-8");
    } catch {}
    writeDeviceIdToJson(id);
    return id;
  }
  const id = crypto.randomBytes(16).toString("hex");
  writeDeviceIdToJson(id);
  return id;
}

async function tryRewriteViaTokenhub({ content, prompt, apiKey, model, endpoint, systemPrompt, timeoutMs = 60000, signal = null }) {
  const url = (endpoint || "https://tokenhub.tencentmaas.com/v1/chat/completions").trim();
  const modelName = (model || "deepseek-v4-flash").trim();
  if (!apiKey) throw new Error("missing apiKey");
  const sys = systemPrompt?.trim() || "You are a helpful assistant.";
  const userContent = String(content || "").trim();
  const sysPrompt = String(prompt || "").trim();
  const messages =
    userContent.length > 0
      ? [
          { role: "system", content: sys },
          { role: "system", content: sysPrompt },
          { role: "user", content: userContent }
        ]
      : [
          { role: "system", content: sys },
          { role: "user", content: sysPrompt }
        ];
  const { statusCode, data } = await requestJson(url, {
    timeoutMs,
    headers: { Authorization: `Bearer ${apiKey}` },
    signal,
    body: {
      model: modelName,
      messages,
      stream: false
    }
  });
  if (statusCode !== 200) throw new Error(`tokenhub http ${statusCode}`);
  const out = String(data?.choices?.[0]?.message?.content || "").trim();
  if (!out) throw new Error("tokenhub empty response");
  return out;
}

function parseJsonLoose(text) {
  const raw = String(text || "").trim();
  if (!raw) return null;
  const s = raw.indexOf("{");
  const e = raw.lastIndexOf("}");
  if (s < 0 || e < 0 || e <= s) return null;
  try {
    return JSON.parse(raw.slice(s, e + 1));
  } catch {
    return null;
  }
}

function appendRendererLog(line) {
  try {
    const dir = path.join(app.getPath("userData"), "logs");
    fs.mkdirSync(dir, { recursive: true });
    const filePath = path.join(dir, "renderer.log");
    const ts = new Date().toISOString();
    fs.appendFileSync(filePath, `${ts} ${String(line || "")}${os.EOL}`, "utf-8");
  } catch {}
}

function createMainWindow() {
  const win = new BrowserWindow({
    width: 1100,
    height: 720,
    minWidth: 900,
    minHeight: 600,
    show: false,
    backgroundColor: "#0b1020",
    frame: false,
    autoHideMenuBar: true,
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false
    }
  });
  let didShowWindow = false;
  const revealWindow = () => {
    if (didShowWindow) return;
    didShowWindow = true;
    try {
      win.show();
    } catch {}
  };
  const revealFallbackTimer = setTimeout(() => {
    revealWindow();
  }, 1200);

  try {
    win.setMenuBarVisibility(false);
  } catch {}

  win.once("ready-to-show", () => {
    clearTimeout(revealFallbackTimer);
    revealWindow();
  });
  win.webContents.once("did-finish-load", () => {
    clearTimeout(revealFallbackTimer);
    revealWindow();
  });
  win.once("closed", () => {
    clearTimeout(revealFallbackTimer);
  });

  win.webContents.on("did-fail-load", (_e, code, desc, url) => {
    try {
      const line = `[renderer][did-fail-load] code=${code} desc=${desc} url=${url}`;
      console.log(line);
      appendRendererLog(line);
    } catch {}
  });
  win.webContents.on("render-process-gone", (_e, details) => {
    try {
      const line = `[renderer][gone] reason=${details?.reason} exitCode=${details?.exitCode}`;
      console.log(line);
      appendRendererLog(line);
    } catch {}
  });
  win.webContents.on("unresponsive", () => {
    try {
      const line = "[renderer][unresponsive]";
      console.log(line);
      appendRendererLog(line);
    } catch {}
  });
  win.webContents.on("console-message", (_e, level, message, line, sourceId) => {
    try {
      const msg = `[renderer][console:${level}] ${message} (${sourceId}:${line})`;
      console.log(msg);
      appendRendererLog(msg);
    } catch {}
  });

  win.webContents.setWindowOpenHandler(({ url }) => {
    shell.openExternal(url);
    return { action: "deny" };
  });

  win.loadFile(path.join(__dirname, "renderer", "index.html"));

  return win;
}

let dataScreenPopoutWindow = null;
const DATA_SCREEN_POPOUT_HTML_PATH = path.join(__dirname, "renderer", "data-screen-popout.html");

function buildDataScreenPopoutHash({ sceneId = "entity", mode = "front" } = {}) {
  const params = new URLSearchParams();
  params.set("display", "popout");
  params.set("scene", String(sceneId || "entity").trim() || "entity");
  params.set("mode", String(mode || "front").trim() || "front");
  return `/data-screen?${params.toString()}`;
}

function createDataScreenPopoutWindow({ sceneId = "entity", mode = "front" } = {}) {
  const hash = buildDataScreenPopoutHash({ sceneId, mode });
  if (dataScreenPopoutWindow && !dataScreenPopoutWindow.isDestroyed()) {
    try {
      dataScreenPopoutWindow.loadFile(DATA_SCREEN_POPOUT_HTML_PATH, { hash });
    } catch {}
    try {
      if (dataScreenPopoutWindow.isMinimized()) dataScreenPopoutWindow.restore();
    } catch {}
    try {
      dataScreenPopoutWindow.show();
      dataScreenPopoutWindow.focus();
    } catch {}
    return dataScreenPopoutWindow;
  }

  const win = new BrowserWindow({
    width: 1680,
    height: 960,
    minWidth: 1200,
    minHeight: 760,
    show: false,
    backgroundColor: "#07111f",
    autoHideMenuBar: true,
    title: "数据大屏",
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false
    }
  });

  try {
    win.setMenuBarVisibility(false);
  } catch {}

  win.once("ready-to-show", () => {
    try {
      win.show();
      win.maximize();
      win.focus();
    } catch {}
  });

  win.once("closed", () => {
    if (dataScreenPopoutWindow === win) dataScreenPopoutWindow = null;
  });

  win.webContents.setWindowOpenHandler(({ url }) => {
    shell.openExternal(url);
    return { action: "deny" };
  });

  win.loadFile(DATA_SCREEN_POPOUT_HTML_PATH, { hash });
  dataScreenPopoutWindow = win;
  return win;
}

function isDataScreenPopoutWindowOpen() {
  return !!(dataScreenPopoutWindow && !dataScreenPopoutWindow.isDestroyed());
}

function closeDataScreenPopoutWindow() {
  if (!isDataScreenPopoutWindowOpen()) return false;
  try {
    dataScreenPopoutWindow.close();
    return true;
  } catch {
    return false;
  }
}

