function createOpenClawCaptureEvent() {
  const logs = [];
  const progress = [];
  return {
    logs,
    progress,
    event: {
      sender: {
        send(channel, payload) {
          const data = payload && typeof payload === "object" ? payload : {};
          if (/:(log)$/i.test(String(channel || ""))) logs.push(data);
          if (/:(progress)$/i.test(String(channel || ""))) progress.push(data);
        }
      }
    }
  };
}

function ensureOpenClawRuntimeUser(userId) {
  const currentUserId = sanitizeRuntimeUserId(getCurrentRuntimeUserId());
  if (!currentUserId) return "";
  const wanted = sanitizeRuntimeUserId(userId || currentUserId);
  if (wanted && wanted !== currentUserId) return currentUserId;
  return currentUserId;
}

function attachOpenClawTaskState(result) {
  const data = result && typeof result === "object" ? result : {};
  const taskId = String(data.taskId || data.jobId || "").trim();
  if (!taskId) return data;
  const taskState = getTaskStatusResult(taskId);
  return {
    ...data,
    taskState: taskState?.found ? taskState : null
  };
}

function resolveOpenClawExtractAudioOutPath(inputVideo, format) {
  const safeInput = String(inputVideo || "").trim();
  const safeFormat = String(format || "").trim().toLowerCase() || "mp3";
  const ext = safeFormat === "wav" ? "wav" : safeFormat === "aac" ? "aac" : "mp3";
  const baseName = sanitizeFsName(path.basename(safeInput, path.extname(safeInput || "")) || "audio", "audio");
  const root = path.join(resolveVideoEditsRoot(), "audio_extracts");
  ensureDir(root);
  return path.join(root, `${baseName}_${Date.now()}_${crypto.randomBytes(3).toString("hex")}.${ext}`);
}

function safeReadJsonFile(filePath) {
  try {
    return JSON.parse(fs.readFileSync(filePath, "utf8"));
  } catch {
    return null;
  }
}

function readDesktopPublishHistoryItems() {
  const rootDir = __dirname;
  const dirs = fs.existsSync(rootDir)
    ? fs.readdirSync(rootDir, { withFileTypes: true }).filter((entry) => entry.isDirectory() && /^dist-/i.test(entry.name))
    : [];
  const items = [];
  const seen = new Set();

  const pushRecord = (record, filePath) => {
    if (!record || typeof record !== "object") return;
    const releaseId = String(record.releaseId || "").trim();
    const key = releaseId || String(filePath || "").trim();
    if (!key || seen.has(key)) return;
    seen.add(key);
    const publishedAt = String(record.publishedAt || "").trim();
    const statMs = (() => {
      try {
        return fs.statSync(filePath).mtimeMs || 0;
      } catch {
        return 0;
      }
    })();
    items.push({
      releaseId,
      version: String(record.version || "").trim(),
      scene: String(record.scene || "desktop").trim(),
      publishedAt,
      publishedAtMs: publishedAt ? new Date(publishedAt).getTime() || statMs : statMs,
      outputDir: String(record.outputDir || path.dirname(filePath)).trim(),
      releaseRootPath: String(record.releaseRootPath || "").trim(),
      releaseRootUrl: String(record.releaseRootUrl || "").trim(),
      manifestUrl: String(record.manifestUrl || "").trim(),
      downloadUrl: String(record.downloadUrl || "").trim(),
      installerName: String(record.installerName || record.artifactName || "").trim(),
      notes: String(record.notes || "").trim(),
      fileCount: Number(record.fileCount || 0) || 0,
      totalSizeBytes: Number(record.totalSizeBytes || 0) || 0,
      filePath: String(filePath || "").trim()
    });
  };

  dirs.forEach((entry) => {
    const distDir = path.join(rootDir, entry.name);
    const rootRecordPath = path.join(distDir, "dabaojilu.json");
    if (fs.existsSync(rootRecordPath)) pushRecord(safeReadJsonFile(rootRecordPath), rootRecordPath);
    const releaseDesktopRoot = path.join(distDir, "release", "desktop");
    if (!fs.existsSync(releaseDesktopRoot)) return;
    try {
      fs.readdirSync(releaseDesktopRoot, { withFileTypes: true })
        .filter((row) => row.isDirectory())
        .forEach((row) => {
          const nestedRecordPath = path.join(releaseDesktopRoot, row.name, "dabaojilu.json");
          if (fs.existsSync(nestedRecordPath)) pushRecord(safeReadJsonFile(nestedRecordPath), nestedRecordPath);
        });
    } catch {}
  });

  return items.sort((a, b) => Number(b.publishedAtMs || 0) - Number(a.publishedAtMs || 0));
}

function findDesktopPublishHistoryItem(input) {
  const releaseId = String(input?.releaseId || "").trim();
  const version = String(input?.version || "").trim();
  const filePath = String(input?.filePath || "").trim();
  const outputDir = String(input?.outputDir || "").trim();
  const items = readDesktopPublishHistoryItems();
  return items.find((item) => {
    if (releaseId && String(item?.releaseId || "").trim() === releaseId) return true;
    if (filePath && String(item?.filePath || "").trim() === filePath) return true;
    if (outputDir && String(item?.outputDir || "").trim() === outputDir) return true;
    if (version && String(item?.version || "").trim() === version) return true;
    return false;
  }) || null;
}

function normalizeStringList(input) {
  if (Array.isArray(input)) return input.map((item) => String(item || "").trim()).filter(Boolean);
  return String(input || "")
    .split(/[,\n，]/)
    .map((item) => String(item || "").trim())
    .filter(Boolean);
}

