async function handleVoiceCloneImportRequest(_event, payload) {
  try {
    const source = String(payload?.source || "local").trim().toLowerCase() === "cloud" ? "cloud" : "local";
    const inputFilePath = String(payload?.filePath || "").trim();
    const previewFilePath = String(payload?.previewFilePath || "").trim();
    const name = String(payload?.name || path.basename(inputFilePath || previewFilePath || "", path.extname(inputFilePath || previewFilePath || "")) || "").trim();
    if (!name) return { ok: false, message: "empty name" };
    if (source === "local" && !inputFilePath) return { ok: false, message: "empty filePath" };
    if (inputFilePath && !fs.existsSync(inputFilePath)) return { ok: false, message: "file not found" };
    if (previewFilePath && !fs.existsSync(previewFilePath)) return { ok: false, message: "preview file not found" };

    const ffmpegExe = pickFfmpegExeFromBundles();
    if (!ffmpegExe || !fs.existsSync(ffmpegExe)) return { ok: false, message: "ffmpeg.exe not found" };

    const currentItems = readHomeCloneVoiceItems();
    const createdAt = Date.now();
    let item = null;

    if (source === "cloud") {
      const remoteVoiceId = String(payload?.remoteVoiceId || payload?.voiceId || payload?.id || `cloud_${createdAt}_${crypto.randomBytes(3).toString("hex")}`).trim();
      const dir = path.join(resolveVoiceCloneRoot(), sanitizeFsName(remoteVoiceId, remoteVoiceId));
      ensureDir(dir);
      let storedPreviewPath = "";
      const previewSource = previewFilePath || inputFilePath;
      if (previewSource) {
        storedPreviewPath = path.join(dir, "preview.wav");
        await toWavFromAny(ffmpegExe, previewSource, storedPreviewPath, {
          cwd: path.dirname(storedPreviewPath)
        });
      }
      item = {
        id: remoteVoiceId,
        name,
        source: "cloud",
        providerId: String(payload?.providerId || "").trim(),
        providerLabel: String(payload?.providerLabel || "").trim(),
        targetModel: String(payload?.targetModel || "").trim(),
        publicAudioUrl: String(payload?.publicAudioUrl || "").trim(),
        previewWavPath: storedPreviewPath,
        createdAt
      };
      try {
        fs.writeFileSync(path.join(dir, "meta.json"), JSON.stringify(item, null, 2), "utf-8");
      } catch {}
    } else {
      const voiceId = `clone_${createdAt}_${crypto.randomBytes(3).toString("hex")}`;
      const dir = path.join(resolveVoiceCloneRoot(), voiceId);
      ensureDir(dir);
      const promptWavPath = path.join(dir, "prompt.wav");
      const storedPreviewPath = path.join(dir, "preview.wav");
      await toWavFromAny(ffmpegExe, inputFilePath, promptWavPath, {
        cwd: dir
      });
      if (previewFilePath) {
        await toWavFromAny(ffmpegExe, previewFilePath, storedPreviewPath, {
          cwd: dir
        });
      } else {
        fs.copyFileSync(promptWavPath, storedPreviewPath);
      }
      item = {
        id: voiceId,
        name,
        source: "local",
        promptWavPath,
        previewWavPath: storedPreviewPath,
        createdAt
      };
      try {
        fs.writeFileSync(path.join(dir, "meta.json"), JSON.stringify(item, null, 2), "utf-8");
      } catch {}
    }

    const nextItems = [item, ...currentItems.filter((row) => String(row?.id || "").trim() !== String(item?.id || "").trim())];
    const filePath = writeHomeCloneVoiceItems(nextItems);
    return { ok: true, item, filePath, items: readHomeCloneVoiceItems() };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

async function handleVoiceCloneRemoveRequest(_event, payload) {
  try {
    const id = String(payload?.id || payload?.voiceId || "").trim();
    if (!id) return { ok: false, message: "empty id" };
    const items = readHomeCloneVoiceItems();
    const target = items.find((item) => String(item?.id || "").trim() === id) || null;
    if (!target) return { ok: false, message: "not found" };
    const nextItems = items.filter((item) => String(item?.id || "").trim() !== id);
    const filePath = writeHomeCloneVoiceItems(nextItems);
    const candidates = [
      String(target?.promptWavPath || "").trim(),
      String(target?.previewWavPath || "").trim()
    ].filter(Boolean);
    const dirs = new Set();
    candidates.forEach((p) => {
      try {
        if (fs.existsSync(p)) dirs.add(path.dirname(p));
      } catch {}
    });
    dirs.forEach((dir) => {
      try {
        if (dir && fs.existsSync(dir)) fs.rmSync(dir, { recursive: true, force: true });
      } catch {}
    });
    return { ok: true, id, filePath, items: readHomeCloneVoiceItems() };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

async function handleVoiceCloneRevealRequest(_event, payload) {
  try {
    const id = String(payload?.id || payload?.voiceId || "").trim();
    if (!id) return { ok: false, message: "empty id" };
    const item = readHomeCloneVoiceItems().find((row) => String(row?.id || "").trim() === id) || null;
    if (!item) return { ok: false, message: "not found" };
    const targetPath =
      String(item?.promptWavPath || "").trim() ||
      String(item?.previewWavPath || "").trim() ||
      String(item?.publicAudioUrl || "").trim();
    if (!targetPath) return { ok: false, message: "empty path" };
    if (/^https?:\/\//i.test(targetPath)) {
      const opened = await shell.openExternal(targetPath);
      return { ok: opened !== false, path: targetPath, item };
    }
    if (fs.existsSync(targetPath)) {
      shell.showItemInFolder(targetPath);
      return { ok: true, path: targetPath, item };
    }
    const dir = path.dirname(targetPath);
    if (dir && fs.existsSync(dir)) {
      await shell.openPath(dir);
      return { ok: true, path: targetPath, openedDirectory: dir, item };
    }
    return { ok: false, message: "path not found", path: targetPath };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

