function getOpenClawBridgeWindow() {
  try {
    const focused = BrowserWindow.getFocusedWindow();
    if (focused && !focused.isDestroyed()) return focused;
  } catch {}
  try {
    return BrowserWindow.getAllWindows().find((win) => win && !win.isDestroyed()) || null;
  } catch {
    return null;
  }
}

async function readRendererScopedStorageJson(baseKey, fallbackValue) {
  const key = String(baseKey || "").trim();
  if (!key) return { ok: false, message: "empty key", value: fallbackValue };
  const win = getOpenClawBridgeWindow();
  if (!win) return { ok: false, message: "window not ready", value: fallbackValue };
  const scope = String(getCurrentRuntimeUserId() || "")
    .trim()
    .replace(/[^0-9a-zA-Z_.-]/g, "_")
    .slice(0, 80);
  const scopedKey = scope ? `${key}::${scope}` : key;
  const js = `(() => {
    try {
      const raw = localStorage.getItem(${JSON.stringify(scopedKey)}) ?? localStorage.getItem(${JSON.stringify(key)});
      if (!raw) return { ok: true, value: null };
      return { ok: true, value: JSON.parse(raw) };
    } catch (e) {
      return { ok: false, message: String((e && e.message) || e), value: null };
    }
  })()`;
  try {
    const out = await win.webContents.executeJavaScript(js, true);
    return {
      ok: out?.ok !== false,
      message: String(out?.message || "").trim(),
      value: out?.value === undefined || out?.value === null ? fallbackValue : out.value
    };
  } catch (e) {
    return { ok: false, message: String(e?.message || e), value: fallbackValue };
  }
}

