async function handleWorkflowAutorunPrepareRequest(_event, payload) {
  try {
    const goal = String(payload?.goal || "content_to_video").trim() || "content_to_video";
    const copyText = String(payload?.copyText || payload?.text || "").trim();
    const audioPath = String(payload?.audioPath || "").trim();
    const avatarId = String(payload?.avatarId || "").trim();
    const videoPath = String(payload?.videoPath || "").trim();
    const coverPath = String(payload?.coverPath || "").trim();
    const bundles = scanProjectBundles();
    const snapshot = await handleWorkspaceSnapshotRequest();
    const recentAvatars = Array.isArray(snapshot?.recent?.avatars) ? snapshot.recent.avatars : [];
    const suggestedAvatarId = avatarId || String(recentAvatars[0]?.id || "").trim();
    const readiness = {
      hasCopyText: !!copyText,
      hasAudioPath: !!audioPath,
      hasAvatarId: !!suggestedAvatarId,
      hasVideoPath: !!videoPath,
      hasCoverPath: !!coverPath,
      hasTtsBundle: bundles.some((item) => String(item?.type || "").trim() === "TTS"),
      hasVideoSyncBundle: bundles.some((item) => String(item?.type || "").trim() === "VideoSync"),
      hasAsrBundle: bundles.some((item) => String(item?.type || "").trim() === "ASR")
    };
    const recommendedTools = [];
    const blockers = [];
    if (!readiness.hasCopyText && !readiness.hasVideoPath) recommendedTools.push("copy.extract");
    if (readiness.hasCopyText && !readiness.hasAudioPath) {
      if (readiness.hasTtsBundle) recommendedTools.push("tts.generate");
      else blockers.push("缺少 TTS 模型包，无法自动生成音频");
    }
    if ((readiness.hasAudioPath || recommendedTools.includes("tts.generate")) && !readiness.hasVideoPath) {
      if (!readiness.hasAvatarId) blockers.push("当前账号下没有可用数字人形象");
      else if (readiness.hasVideoSyncBundle) recommendedTools.push("videosync.generate");
      else blockers.push("缺少 VideoSync 模型包，无法自动生成口播视频");
    }
    if (readiness.hasVideoPath) {
      if (readiness.hasAsrBundle) recommendedTools.push("subbgm.render");
      recommendedTools.push("cover.generate");
      recommendedTools.push("publish.export");
    }
    return {
      ok: true,
      goal,
      readiness,
      blockers,
      recommendedTools,
      suggestedInput: {
        avatarId: suggestedAvatarId,
        defaultOutputDir: resolveWritableDefaultOutputDir()
      },
      snapshotCounts: snapshot?.counts || {}
    };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

function readSystemVoiceCatalog() {
  try {
    const homeJsPath = path.join(__dirname, "renderer", "app", "pages", "home.js");
    if (!fs.existsSync(homeJsPath)) return [];
    const raw = fs.readFileSync(homeJsPath, "utf-8");
    const match = raw.match(/const SYSTEM_VOICES = (\[[\s\S]*?\n\s*\]);/);
    if (!match || !match[1]) return [];
    const arr = Function(`"use strict"; return (${match[1]});`)();
    return Array.isArray(arr) ? arr : [];
  } catch {
    return [];
  }
}

