async function handleVideoTemplateListRequest() {
  try {
    const root = resolveVideoTemplateRoot();
    ensureDir(root);
    ensurePipAssetLibraryContainer();
    const entries = fs.readdirSync(root, { withFileTypes: true });
    const legacyFiles = entries.filter((d) => d.isFile() && /\.mp4$/i.test(String(d.name || "")));
    for (const f of legacyFiles) {
      const name = String(f.name || "").trim();
      if (!name) continue;
      const src = path.join(root, name);
      if (!fs.existsSync(src)) continue;
      const baseId = path.basename(name, path.extname(name));
      let id = baseId || `legacy_${Date.now()}`;
      let dir = path.join(root, id);
      if (fs.existsSync(dir)) {
        id = `${baseId}_${Date.now()}`;
        dir = path.join(root, id);
      }
      try {
        ensureDir(dir);
        const dst = path.join(dir, "result.mp4");
        try {
          fs.renameSync(src, dst);
        } catch {
          fs.copyFileSync(src, dst);
          fs.unlinkSync(src);
        }
        try {
          const st = fs.statSync(dst);
          const createdAt = Number(st.birthtimeMs || st.mtimeMs || Date.now()) || Date.now();
          fs.writeFileSync(path.join(dir, "meta.json"), JSON.stringify({ id, createdAt, type: "talking_video" }, null, 2), "utf-8");
        } catch {}
      } catch {}
    }

    const dirs = fs.readdirSync(root, { withFileTypes: true }).filter((d) => d.isDirectory());
    const items = [];
    for (const d of dirs) {
      const id = String(d.name || "").trim();
      if (!id) continue;
      const dir = path.join(root, id);
      const metaPath = path.join(dir, "meta.json");
      const meta = readJsonFileSafe(metaPath, {});
      const edit = meta && typeof meta.edit === "object" ? meta.edit : {};
      const type = String(meta?.type || "talking_video").trim() || "talking_video";
      const name = String(meta?.name || id).trim() || id;
      let createdAt = Number(meta?.createdAt || 0);
      if (!createdAt) {
        try {
          const st = fs.statSync(dir);
          createdAt = Number(st.birthtimeMs || st.mtimeMs || 0) || 0;
        } catch {
          createdAt = 0;
        }
      }
      let videoPath = path.join(dir, "result.mp4");
      if (!fs.existsSync(videoPath)) {
        const mp4s = (fs.readdirSync(dir) || []).filter((n) => /\.mp4$/i.test(n));
        videoPath = mp4s.length ? path.join(dir, mp4s[0]) : "";
      }
      if ((!videoPath || !fs.existsSync(videoPath)) && type !== "asset_library") continue;
      const safeVideoPath = videoPath && fs.existsSync(videoPath) ? videoPath : "";
      let renders = [];
      const rendersDir = path.join(dir, "renders");
      if (fs.existsSync(rendersDir)) {
        try {
          const files = fs.readdirSync(rendersDir).filter((n) => /\.mp4$/i.test(n));
          renders = files.map((n) => ({ name: n, videoPath: path.join(rendersDir, n) })).filter((x) => fs.existsSync(x.videoPath));
        } catch {}
      }
      items.push({ id, name, dir, type, videoPath: safeVideoPath, createdAt, renders, edit });
    }
    items.sort((a, b) => Number(b.createdAt || 0) - Number(a.createdAt || 0));
    return { ok: true, items };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

