        input: String(safeArgs.input || "").trim(),
        copyText: String(safeArgs.copyText || safeArgs.text || "").trim(),
        audioPath: String(safeArgs.audioPath || "").trim(),
        avatarId: String(safeArgs.avatarId || "").trim(),
        videoPath: String(safeArgs.videoPath || "").trim(),
        coverPath: String(safeArgs.coverPath || "").trim(),
        outputDir: String(safeArgs.outputDir || "").trim(),
