function buildOpenClawSkillWrappedMarkdown(serviceState = {}, toolList = [], skillName = "bukongip-zongkong") {
  const localUrl = String(serviceState?.state?.localUrl || `http://${OPENCLAW_TOOL_HOST}:${OPENCLAW_TOOL_PORT}`).trim();
  const safeSkillName = String(skillName || "").trim() || "bukongip-zongkong";
  const sourceMarkdown = readOpenClawSkillSourceMarkdown(safeSkillName);
  const body =
    String(sourceMarkdown || "").trim() ||
    buildOpenClawSkillFallbackMarkdown({
      skillName: safeSkillName,
      toolList,
      localUrl
    });
  const header = [
    "# OpenClaw 本地调用补充说明",
    "",
    `- Skill 来源：\`${safeSkillName}\``,
    `- 当前本地地址：\`${localUrl}\``,
    "- OpenClaw 中优先配置：",
    "  - `GET /health`",
    "  - `GET /tools/list`",
    "  - `POST /tools/run`",
    "  - `POST /plan/run`",
    `- 当前开关状态：${serviceState?.config?.enabled !== false ? "开启" : "关闭"}`,
    `- 当前运行状态：${serviceState?.state?.running === true ? "已运行" : "未运行"}`,
    `- 当前登录账号：${String(serviceState?.state?.currentUserId || "").trim() || "未登录"}`,
    `- 当前阻塞原因：${String(serviceState?.state?.blockedReason || "无").trim() || "无"}`,
    "- 小白用户建议先看同目录 `README-先看这个.txt` 再配置 OpenClaw。",
    ""
  ].join("\n");
  return `${header}\n${body}\n`;
}

async function handleOpenClawGenerateSkillPackageRequest(_event, payload = {}) {
  try {
    const outDir = String(payload?.outputDir || "").trim() || getOpenClawSkillDesktopDirPath();
    ensureDir(outDir);
    const serviceState = getOpenClawServiceState();
    const toolList = buildOpenClawToolList().map((item) => ({
      name: String(item?.name || "").trim(),
      description: String(item?.description || "").trim(),
      inputSchema: item?.inputSchema || {},
      outputSchema: item?.outputSchema || {}
    }));
    const localUrl = String(serviceState?.state?.localUrl || `http://${OPENCLAW_TOOL_HOST}:${OPENCLAW_TOOL_PORT}`).trim();
    const skillTargets = getOpenClawSkillExportTargets();
    const primarySkillTarget = skillTargets.find((item) => item.primary) || skillTargets[0];
    const files = [
      {
        name: "README-先看这个.txt",
        content: buildOpenClawSkillReadme({
          localUrl,
          toolList,
          currentUserId: serviceState?.state?.currentUserId,
          enabled: serviceState?.config?.enabled !== false,
          running: serviceState?.state?.running === true,
          blockedReason: serviceState?.state?.blockedReason
        })
      },
      {
        name: "SKILL.md",
        content: buildOpenClawSkillWrappedMarkdown(serviceState, toolList, String(primarySkillTarget?.skillName || "bukongip-zongkong").trim())
      },
      {
        name: "tools-list.json",
        content: JSON.stringify({
          generatedAt: new Date().toISOString(),
          localUrl,
          state: serviceState?.state || {},
          tools: toolList
        }, null, 2)
      },
      {
        name: "plan-run示例-自动工作流.json",
        content: JSON.stringify({
          goal: "从短视频链接自动生成数字人口播视频并导出",
          context: {
            userId: String(serviceState?.state?.currentUserId || "").trim() || "请先登录后再生成",
            outputDir: "E:/IP输出/OpenClaw示例"
          },
          steps: [
            {
              tool: "workflow.autorun.run",
              args: {
                userId: { $ref: "$context.userId" },
                input: "https://www.douyin.com/video/这里换成你的链接",
                outputDir: { $ref: "$context.outputDir" },
                title: "OpenClaw自动工作流示例",
                subtitleEnable: true,
                bgmEnable: false
              },
              saveAs: "autorun1"
            }
          ]
        }, null, 2)
      },
      {
        name: "plan-run示例-精确工具链.json",
        content: JSON.stringify({
          goal: "提取文案、改写、配音、生成口播视频并导出",
          context: {
            userId: String(serviceState?.state?.currentUserId || "").trim() || "请先登录后再生成",
            outputDir: "E:/IP输出/OpenClaw精确示例",
            avatarId: "请先替换成可用的数字人avatarId"
          },
          steps: [
            {
              tool: "copy.extract",
              args: {
                userId: { $ref: "$context.userId" },
                input: "https://www.douyin.com/video/这里换成你的链接"
              },
              saveAs: "copy1"
            },
            {
              tool: "copy.rewrite",
              args: {
                userId: { $ref: "$context.userId" },
                text: { $ref: "copy1.recognizedText" },
                feedback: "更像真人口播，更口语化"
              },
              saveAs: "rewrite1"
            },
            {
              tool: "tts.generate",
              args: {
                userId: { $ref: "$context.userId" },
                voiceId: "sys_default",
                text: { $ref: "rewrite1.rewrittenText" }
              },
              saveAs: "tts1"
            },
            {
              tool: "videosync.generate",
              args: {
                userId: { $ref: "$context.userId" },
                avatarId: { $ref: "$context.avatarId" },
                audioPath: { $ref: "tts1.audioPath" }
              },
              saveAs: "video1"
            },
            {
              tool: "publish.export",
              args: {
                userId: { $ref: "$context.userId" },
                outputDir: { $ref: "$context.outputDir" },
                videoPath: { $ref: "video1.videoPath" },
                title: "OpenClaw精确工具链示例"
              },
              saveAs: "export1"
            }
          ]
        }, null, 2)
      }
    ];
    skillTargets.forEach((item) => {
      const skillName = String(item?.skillName || "").trim();
      if (!skillName) return;
      const content = buildOpenClawSkillWrappedMarkdown(serviceState, toolList, skillName);
      files.push({
        name: String(item?.mirrorName || `${skillName}.md`).trim(),
        content
      });
      files.push({
        name: String(item?.exportPath || "").trim(),
        content
      });
    });
    files.forEach((item) => {
      const filePath = path.join(outDir, item.name);
      ensureDir(path.dirname(filePath));
      fs.writeFileSync(filePath, String(item.content || ""), "utf-8");
    });
    const openFolder = payload?.openFolder !== false;
    if (openFolder) {
      try {
        await shell.openPath(outDir);
      } catch {}
    }
    return {
      ok: true,
      path: outDir,
      fileCount: files.length,
      localUrl,
      currentUserId: String(serviceState?.state?.currentUserId || "").trim(),
      state: serviceState?.state || {},
      files: files.map((item) => ({ name: item.name, path: path.join(outDir, item.name) }))
    };
  } catch (e) {
    return { ok: false, message: String(e?.message || e), path: "" };
  }
}

