registerSingletonHandle("media:listFonts", async () => {
  try {
    const fontSync = syncRuntimeFontsFromInstall();
    const runtimeDir = String(fontSync?.runtimeDir || "").trim() || path.join(resolveRuntimeDataRoot(), "ziti");
    const dir = resolveProjectMediaDir("ziti");
    const listA = listFilesInDir(runtimeDir, [".ttf", ".otf", ".ttc"]);
    const listB = listFilesInDir(dir, [".ttf", ".otf", ".ttc"]);
    const seen = new Set();
    const list = [];
    [...listA, ...listB].forEach((it) => {
      const name = String(it?.name || "").trim();
      if (!name) return;
      const key = name.toLowerCase();
      if (seen.has(key)) return;
      seen.add(key);
      list.push(it);
    });
    dbgPostInstallAssetsMissingEmit("B", "main.js:media:listFonts", "列出字体目录结果", {
      dir,
      runtimeDir,
      exists: !!(dir && fs.existsSync(dir)),
      runtimeExists: !!(runtimeDir && fs.existsSync(runtimeDir)),
      count: Array.isArray(list) ? list.length : 0,
      sample: Array.isArray(list) ? list.slice(0, 10).map((item) => String(item?.name || "").trim()) : []
    });
    return { ok: true, items: list };
  } catch (e) {
    return { ok: false, message: String(e?.message || e), items: [] };
  }
});

registerSingletonHandle("media:listBgms", async () => {
  try {
    const dir = resolveProjectMediaDir("bgm");
    const list = listFilesInDir(dir, [".mp3", ".wav", ".m4a", ".aac", ".flac"]);
    dbgPostInstallAssetsMissingEmit("B", "main.js:media:listBgms", "列出背景音乐目录结果", {
      dir,
      exists: !!(dir && fs.existsSync(dir)),
      count: Array.isArray(list) ? list.length : 0,
      sample: Array.isArray(list) ? list.slice(0, 10).map((item) => String(item?.name || "").trim()) : []
    });
    return { ok: true, items: list };
  } catch (e) {
    return { ok: false, message: String(e?.message || e), items: [] };
  }
});

registerSingletonHandle("dialog:openFile", async (_event, payload) => {
  const filters = Array.isArray(payload?.filters) && payload.filters.length ? payload.filters : [{ name: "All Files", extensions: ["*"] }];
  const properties = Array.isArray(payload?.properties) && payload.properties.length ? payload.properties : ["openFile"];
  const result = await dialog.showOpenDialog({
    title: String(payload?.title || "").trim() || undefined,
    defaultPath: String(payload?.defaultPath || "").trim() || undefined,
    properties,
    filters
  });
  if (result.canceled) return { canceled: true };
  return { canceled: false, filePaths: result.filePaths };
});

registerSingletonHandle("dialog:openDirectory", async () => {
  const result = await dialog.showOpenDialog({
    properties: ["openDirectory", "createDirectory"]
  });
  if (result.canceled) return { canceled: true };
  return { canceled: false, directoryPath: result.filePaths?.[0] || "" };
});

registerSingletonHandle("dialog:saveFile", async (_event, payload) => {
  const result = await dialog.showSaveDialog({
    title: String(payload?.title || "").trim() || undefined,
    defaultPath: String(payload?.defaultPath || "").trim() || undefined,
    filters: Array.isArray(payload?.filters) ? payload.filters : undefined
  });
  if (result.canceled) return { canceled: true };
  return { canceled: false, filePath: String(result.filePath || "").trim() };
});

