const runningTasks = new Map();

registerSingletonHandle("workflow:cancel", async (_event, payload) => {
  const taskId = payload?.taskId;
  const task = taskId ? runningTasks.get(taskId) : null;
  if (!task) return { ok: false };
  task.canceled = true;
  try {
    task.proc?.kill?.();
  } catch {}
  return { ok: true };
});

async function handleWorkflowExtractCopyFromDouyin(event, payload) {
  const taskId = crypto.randomBytes(8).toString("hex");
  const task = { taskId, canceled: false, proc: null, tool: "copy.extract", status: "running", progress: 1, message: "开始提取文案" };
  runningTasks.set(taskId, task);
  updateLiveTaskState(task);

  const sendLog = (level, message) => {
    event.sender.send("workflow:log", { taskId, level, message: String(message || "") });
  };

  const stageProgressMap = {
    parse: 5,
    download_page: 15,
    download_video: 35,
    extract_audio: 72,
    asr: 88,
    done: 100
  };
  const send = (stage, message) => {
    event.sender.send("workflow:progress", { taskId, stage, message });
    sendLog("info", `[${stage}] ${message}`);
    updateLiveTaskState(task, {
      status: stage === "done" ? "completed" : "running",
      progress: Object.prototype.hasOwnProperty.call(stageProgressMap, stage) ? stageProgressMap[stage] : Math.max(0, Number(task.progress || 0) || 0),
      message: String(message || "")
    });
  };

  const fail = (message) => {
    const msg = String(message || "").trim() || "文案提取失败";
    updateLiveTaskState(task, { status: "failed", message: msg });
    return { ok: false, taskId, message: msg };
  };

  const formatProgressSize = (bytes) => {
    const n = Math.max(0, Number(bytes || 0) || 0);
    if (n >= 1024 * 1024) return `${(n / (1024 * 1024)).toFixed(2)}MB`;
    if (n >= 1024) return `${(n / 1024).toFixed(1)}KB`;
    return `${n}B`;
  };

  let lastDownloadProgressAt = 0;
  let lastDownloadProgressBytes = -1;
  const reportDownloadProgress = (received, { totalBytes = 0 } = {}) => {
    const now = Date.now();
    const safeReceived = Math.max(0, Number(received || 0) || 0);
    const safeTotal = Math.max(0, Number(totalBytes || 0) || 0);
    if (safeReceived === lastDownloadProgressBytes && now - lastDownloadProgressAt < 1200) return;
    if (safeTotal > 0 && safeReceived < safeTotal && now - lastDownloadProgressAt < 1200) return;
    lastDownloadProgressAt = now;
    lastDownloadProgressBytes = safeReceived;
    const percent = safeTotal > 0 ? Math.min(100, Math.max(0, Math.round((safeReceived / safeTotal) * 100))) : 0;
    const message =
      safeTotal > 0
        ? `正在下载视频到提取文案缓存... ${percent}%（${formatProgressSize(safeReceived)}/${formatProgressSize(safeTotal)}）`
        : `正在下载视频到提取文案缓存... 已下载 ${formatProgressSize(safeReceived)}`;
    send("download_video", message);
  };

  let lastDownloadError = "";
  let cacheKey = "";
  let downloadReady = false;
  const clearPartialVideoFile = () => {
    try {
      if (videoPath && fs.existsSync(videoPath)) fs.unlinkSync(videoPath);
    } catch {}
  };

  const isCanceled = () => task.canceled === true;

  const headers = {
    "User-Agent":
      "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36",
    Accept: "*/*",
    "Accept-Encoding": "identity"
  };

  const cleanup = [];
  try {
    const input = String(payload?.input || "").trim();
    if (!input) return fail("empty input");
    const modelChoice = payload?.modelChoice && typeof payload.modelChoice === "object" ? payload.modelChoice : null;
    const useCloudRecognition = String(modelChoice?.source || "").trim().toLowerCase() === "cloud";

    send("parse", "正在识别抖音链接...");
    let url = extractDouyinUrl(input) || extractFirstUrl(input);
    if (!url) return fail("未找到有效链接");

    const projectRoot = resolveProjectRoot();
    const ffmpegExe = pickFfmpegExeFromBundles();
    if (!fs.existsSync(ffmpegExe)) return fail(`ffmpeg 不存在：${ffmpegExe}`);

    let bundleDir = "";
    let pythonExe = "";
    let asrScript = "";
    if (!useCloudRecognition) {
      const scan = scanProjectBundles();
      const asrBundles = scan.filter((item) => item.type === "ASR");
      const preferredBundleDir = String(modelChoice?.bundleDir || "").trim().toLowerCase();
      const preferredConfigPath = String(modelChoice?.configPath || "").trim().toLowerCase();
      const asrBundle =
        asrBundles.find((item) => String(item?.bundleDir || "").trim().toLowerCase() === preferredBundleDir) ||
        asrBundles.find((item) => String(item?.configPath || "").trim().toLowerCase() === preferredConfigPath) ||
        asrBundles[0] ||
        null;
      if (!asrBundle) return fail(buildMissingBundleMessage("ASR"));
      bundleDir = asrBundle.bundleDir;
      pythonExe = path.join(bundleDir, "runtime", "asr", "python", "python.exe");
      asrScript = path.join(bundleDir, "services", "asr_server.py");
      if (!fs.existsSync(pythonExe)) return fail(`python 不存在：${pythonExe}`);
      if (!fs.existsSync(asrScript)) return fail(`asr_server.py 不存在：${asrScript}`);
    } else {
      if (!String(modelChoice?.endpoint || "").trim()) return fail("当前云端识别模型未配置 endpoint");
      if (!String(modelChoice?.apiKey || "").trim()) return fail("当前云端识别模型未配置 API Key");
      if (!String(modelChoice?.modelId || modelChoice?.model || "").trim()) return fail("当前云端识别模型未配置 modelId");
    }

    const preCacheKey = buildExtractCopyCacheKey({ inputUrl: url });
    cacheKey = String(preCacheKey || "").trim();
    const preActiveLock = getExtractCopyTaskLock(cacheKey);
    if (cacheKey && preActiveLock && preActiveLock.taskId !== taskId) {
      return fail("当前链接已经在提取中，请等待当前任务完成，本次不会重复下载视频。");
    }
    if (cacheKey) setExtractCopyTaskLock(cacheKey, taskId);

    const tmpDir = path.join(os.tmpdir(), "ipfactory");
    fs.mkdirSync(tmpDir, { recursive: true });

    send("parse", "正在识别抖音链接并跟进分享跳转...");
    const resolved = await resolveRedirects(url, { headers });
    touchExtractCopyTaskLock(cacheKey, taskId);
    const awemeId = extractAwemeId(resolved) || extractAwemeId(url);
    const douyinCandidateUrls = buildDouyinVideoCandidateUrls(url, resolved, awemeId);
    const shareUrl = awemeId ? `https://www.iesdouyin.com/share/video/${awemeId}` : "";
    const preferredResolveUrl = String(douyinCandidateUrls[0] || resolved || url).trim();
    const cachePaths = resolveExtractCopyCacheEntryPaths({ inputUrl: url, resolvedUrl: preferredResolveUrl, awemeId });
    const canonicalCacheKey = String(cachePaths.cacheKey || "").trim();
    if (canonicalCacheKey && canonicalCacheKey !== cacheKey) {
      const canonicalLock = getExtractCopyTaskLock(canonicalCacheKey);
      if (canonicalLock && canonicalLock.taskId !== taskId) {
        deleteExtractCopyTaskLock(cacheKey, taskId);
        return fail("当前链接已经在提取中，请等待当前任务完成，本次不会重复下载视频。");
      }
      setExtractCopyTaskLock(canonicalCacheKey, taskId);
      deleteExtractCopyTaskLock(cacheKey, taskId);
      cacheKey = canonicalCacheKey;
    } else {
      touchExtractCopyTaskLock(cacheKey, taskId);
    }

    const cachedManifest = readExtractCopyCacheManifest(cachePaths.manifestPath);
    if (cachedManifest) {
      const cachedText = String(cachedManifest.recognizedText || "").trim();
      const cachedVideoPath = String(cachedManifest.videoPath || "").trim();
      send("done", "命中文案缓存，直接读取标记文件内容");
      sendLog("info", `缓存标记文件：${cachePaths.manifestPath}`);
      updateLiveTaskState(task, {
        status: "completed",
        progress: 100,
        message: "文案提取完成（命中缓存）",
        result: {
          recognizedText: cachedText,
          videoPath: cachedVideoPath && fs.existsSync(cachedVideoPath) ? cachedVideoPath : "",
          cacheHit: true,
          manifestPath: cachePaths.manifestPath
        }
      });
      return {
        ok: true,
        taskId,
        recognizedText: cachedText,
        videoPath: cachedVideoPath && fs.existsSync(cachedVideoPath) ? cachedVideoPath : "",
        cacheHit: true,
        manifestPath: cachePaths.manifestPath
      };
    }

    const baseName = "source";
    const saveVideoPath = cachePaths.directVideoPath;
    let videoPath = saveVideoPath;
    const audioPath = cachePaths.audioPath;
    const configPath = path.join(tmpDir, `asr_${taskId}.json`);
    cleanup.push(configPath);

    let downloadedByYtDlp = false;

    if (awemeId) {
      send("download_page", "正在解析视频下载地址...");
      touchExtractCopyTaskLock(cacheKey, taskId);
      sendLog("info", `候选下载地址：${douyinCandidateUrls.join(" | ")}`);
      let playUrl = "";
      try {
        const apiUrl = `https://www.iesdouyin.com/web/api/v2/aweme/iteminfo/?item_ids=${awemeId}`;
        const info = await fetchJson(apiUrl, { headers: { ...headers, Referer: shareUrl } });
        playUrl = findVideoPlayUrlFromItemInfo(info);
      } catch {}

      if (!playUrl) {
        const html = await fetchText(shareUrl, { headers: { ...headers, Referer: shareUrl } });
        if (/验证|验证码|captcha|verify/i.test(html)) {
          playUrl = "";
        } else {
          playUrl = findVideoPlayUrlFromHtml(html);
        }
      }

      if (!playUrl) {
        send("download_page", "正在使用内置浏览器解析下载地址...");
        try {
          playUrl = await resolvePlayUrlViaElectron(awemeId, { timeoutMs: 25000, entryUrl: preferredResolveUrl });
        } catch {}
      }

      if (playUrl) {
        send("download_video", "正在下载视频到提取文案缓存...");
        try {
          await downloadToFile(playUrl, videoPath, {
            headers: { ...headers, Referer: shareUrl },
            isCanceled,
            onProgress: reportDownloadProgress
          });
          downloadReady = fs.existsSync(videoPath);
        } catch (e) {
          lastDownloadError = String(e?.message || e);
          clearPartialVideoFile();
          downloadReady = false;
        }
      }
    }

    if (!downloadReady) {
      send("download_page", "正在使用开源解析接口获取下载地址...");
      for (const candidateUrl of douyinCandidateUrls) {
        touchExtractCopyTaskLock(cacheKey, taskId);
        const apiRes = await resolveDownloadUrlViaGalaxyApi(candidateUrl, { timeoutMs: 3500 });
        const apiDownloadUrl = String(apiRes?.url || "");
        if (apiRes?.fatal) {
          sendLog("warn", `开源解析接口不可用：${String(apiRes?.endpoint || "")} | ${String(apiRes?.error || "").trim()}`);
          break;
        }
        if (!apiDownloadUrl) continue;
        sendLog("info", `开源解析命中候选地址：${candidateUrl} | ${String(apiRes?.endpoint || "").trim()}`);
        send("download_video", "正在下载视频到提取文案缓存...");
        try {
          await downloadToFile(apiDownloadUrl, videoPath, {
            headers: { ...headers, Referer: candidateUrl },
            isCanceled,
            onProgress: reportDownloadProgress
          });
          downloadReady = fs.existsSync(videoPath);
        } catch (e) {
          lastDownloadError = String(e?.message || e);
          clearPartialVideoFile();
          downloadReady = false;
        }
        if (downloadReady) break;
      }
    }

    if (!downloadReady) {
      send("download_page", "视频直链解析失败，正在调用 yt-dlp 尝试下载...");
      const ytDlpUserAgent =
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36";
      const ytDlpCookiesPath = path.join(cachePaths.entryDir, `douyin_cookies_${taskId}.txt`);
      cleanup.push(ytDlpCookiesPath);
      try {
        const warmUrl =
          String(preferredResolveUrl || "").trim() || String(shareUrl || "").trim() || String(douyinCandidateUrls[0] || "").trim();
        if (warmUrl) await warmupElectronCookies(warmUrl, { timeoutMs: 9000 });
        await writeElectronCookiesToNetscapeFile({
          outputPath: ytDlpCookiesPath,
          urls: [warmUrl, shareUrl, "https://www.douyin.com", "https://www.iesdouyin.com"].filter(Boolean),
          domains: ["douyin.com", "iesdouyin.com"]
        });
        const stat = fs.existsSync(ytDlpCookiesPath) ? fs.statSync(ytDlpCookiesPath) : null;
        if (stat && stat.size > 80) sendLog("info", "已从内置浏览器提取抖音 Cookies，交给 yt-dlp 继续下载。");
      } catch {}
      for (const candidateUrl of douyinCandidateUrls) {
        try {
          touchExtractCopyTaskLock(cacheKey, taskId);
          sendLog("info", `yt-dlp 尝试地址：${candidateUrl}`);
          sendLog("info", "yt-dlp 若未安装，将自动下载到 userData/runtime-tools 目录。");
          videoPath = await runYtDlpDownload(candidateUrl, cachePaths.entryDir, baseName, {
            isCanceled,
            task,
            cookiesPath: fs.existsSync(ytDlpCookiesPath) ? ytDlpCookiesPath : "",
            userAgent: ytDlpUserAgent,
            referer: candidateUrl,
            onStderr: (s) => {
              const txt = String(s || "").trim();
              if (txt) sendLog("warn", txt.length > 260 ? `${txt.slice(0, 260)}...` : txt);
            }
          });
          downloadedByYtDlp = fs.existsSync(videoPath);
          downloadReady = downloadedByYtDlp;
        } catch (e) {
          const msg = String(e?.message || e);
          lastDownloadError = msg;
          downloadReady = false;
          if (/Fresh cookies/i.test(msg)) {
            sendLog("warn", "检测到抖音风控：当前环境需要读取浏览器 Cookie 才能继续下载（不要求登录）。");
            try {
              sendLog("info", "正在尝试读取 Edge 浏览器 Cookie 交给 yt-dlp...");
              videoPath = await runYtDlpDownload(candidateUrl, cachePaths.entryDir, baseName, {
                isCanceled,
                task,
                cookiesFromBrowser: "edge",
                userAgent: ytDlpUserAgent,
                referer: candidateUrl,
                onStderr: (s) => {
                  const txt = String(s || "").trim();
                  if (txt) sendLog("warn", txt.length > 260 ? `${txt.slice(0, 260)}...` : txt);
                }
              });
              downloadedByYtDlp = fs.existsSync(videoPath);
              downloadReady = downloadedByYtDlp;
              if (downloadReady) break;
            } catch (e2) {
              lastDownloadError = String(e2?.message || e2);
              downloadReady = false;
            }
          }
        }
        if (downloadReady) break;
      }
    }
    if (!downloadReady) {
      return fail(lastDownloadError ? `视频下载失败：${lastDownloadError}` : "视频下载失败（未解析到可用直链）");
    }

    send("extract_audio", "正在提取音频...");
    touchExtractCopyTaskLock(cacheKey, taskId);
    await runFfmpeg(ffmpegExe, ["-y", "-i", videoPath, "-vn", "-ac", "1", "-ar", "16000", "-c:a", "pcm_s16le", audioPath], {
      cwd: cachePaths.entryDir,
      isCanceled,
      task
    });

    let recognizedText = "";
    if (useCloudRecognition) {
      send("asr", "正在调用云端识别模型提取文案...");
      touchExtractCopyTaskLock(cacheKey, taskId);
      sendLog("info", `云端识别模型：${String(modelChoice?.label || modelChoice?.modelId || modelChoice?.model || "未命名模型")}`);
      recognizedText = await transcribeAudioByCloudModel(audioPath, modelChoice);
    } else {
      send("asr", "正在识别文案...");
      touchExtractCopyTaskLock(cacheKey, taskId);
      fs.writeFileSync(
        configPath,
        JSON.stringify(
          {
            modelConfig: { audio: audioPath, param: { language: "auto", use_itn: true } }
          },
          null,
          2
        ),
        "utf-8"
      );

      const asrRes = await runAsrCommand(pythonExe, asrScript, configPath, {
        cwd: bundleDir,
        isCanceled,
        task
      });
      const asrStdout = String(asrRes?.stdout || "");
      const recordTexts = parseAigcPanelRecords(asrStdout);
      const rawText = recordTexts.join(" ").trim();
      recognizedText = String(rawText || "").trim();
    }
    if (!recognizedText) return fail("未识别到文案内容");

    writeExtractCopyCacheManifest(cachePaths, {
      sourceUrl: url,
      resolvedUrl: preferredResolveUrl,
      shareUrl,
      awemeId,
      recognizedText,
      videoPath: videoPath && fs.existsSync(videoPath) ? videoPath : "",
      audioPath: audioPath && fs.existsSync(audioPath) ? audioPath : "",
      modelChoice,
      createdAt: Date.now()
    });

    send("done", "文案提取完成");
    updateLiveTaskState(task, {
      status: "completed",
      progress: 100,
      message: "文案提取完成",
      result: {
        recognizedText,
        videoPath: downloadedByYtDlp || fs.existsSync(saveVideoPath) ? videoPath : "",
        cacheHit: false,
        manifestPath: cachePaths.manifestPath
      }
    });
    return {
      ok: true,
      taskId,
      recognizedText,
      videoPath: downloadedByYtDlp || fs.existsSync(saveVideoPath) ? videoPath : "",
      cacheHit: false,
      manifestPath: cachePaths.manifestPath
    };
  } catch (e) {
    const msg = String(e?.message || e);
    sendLog("error", msg);
    if (task.canceled === true || msg === "canceled" || /canceled/i.test(msg)) {
      updateLiveTaskState(task, { status: "canceled", message: "已取消" });
      return { ok: false, taskId, canceled: true, message: "canceled" };
    }
    updateLiveTaskState(task, { status: "failed", message: msg || "文案提取失败" });
    return { ok: false, taskId, message: msg };
  } finally {
    runningTasks.delete(taskId);
    cleanup.forEach((p) => {
      try {
        if (p && fs.existsSync(p)) fs.unlinkSync(p);
      } catch {}
    });
    deleteExtractCopyTaskLock(cacheKey, taskId);
  }
}

