async function handleModelsScanBundleTreeRequest(_event, payload) {
  const bundleRoot = String(payload?.bundleRoot || "").trim();
  if (!bundleRoot) return { ok: false, message: "bundleRoot 为空" };
  const bundles = scanBundleRoot(bundleRoot);
  return {
    ok: true,
    bundleRoot,
    bundles,
    report: buildBundleImportReport(bundles, bundleRoot)
  };
}

registerSingletonHandle("models:scanBundleTree", handleModelsScanBundleTreeRequest);

async function handleModelsImportBundlesRequest(_event, payload) {
  const bundleRoot = String(payload?.bundleRoot || "").trim();
  if (!bundleRoot) return { ok: false, message: "bundleRoot 为空" };
  const bundles = scanBundleRoot(bundleRoot);
  const validBundles = bundles.filter((item) => item?.validation?.ok !== false);
  const report = buildBundleImportReport(bundles, bundleRoot);
  const config = readModelCenterConfigFromFile();
  const importedBundles = [
    ...validBundles.map((item) => ({
      type: String(item?.type || "").trim(),
      name: String(item?.name || "").trim(),
      bundleDir: String(item?.bundleDir || "").trim(),
      configPath: String(item?.configPath || "").trim(),
      status: "已导入",
      importedAt: new Date().toISOString()
    })),
    ...config.importedBundles
  ].filter((item, index, list) => list.findIndex((row) => row.configPath === item.configPath) === index);
  const writeRes = writeModelCenterConfigToFile({
    rootPath: String(payload?.setAsRootPath ? bundleRoot : config.rootPath || "").trim(),
    importedBundles,
    lastImportLog: {
      summary: `共扫描 ${report.totalCount} 个模型包，可导入 ${report.successCount} 个，失败 ${report.failureCount} 个`,
      exportedAt: new Date().toISOString(),
      report
    }
  });
  return {
    ok: writeRes.ok,
    config: writeRes.config,
    bundles: validBundles,
    report,
    message: writeRes.ok ? "" : String(writeRes.message || "模型配置写入失败")
  };
}

registerSingletonHandle("models:importBundles", handleModelsImportBundlesRequest);

registerSingletonHandle("avatar:list", async () => {
  const items = readAvatarIndex();
  return { ok: true, items };
});

async function handleAvatarImportVideoRequest(_event, payload) {
  try {
    const name = String(payload?.name || "").trim();
    const filePath = String(payload?.filePath || "").trim();
    if (!name) return { ok: false, message: "empty name" };
    if (!filePath) return { ok: false, message: "empty filePath" };
    if (!fs.existsSync(filePath)) return { ok: false, message: "file not found" };

    const id = `avatar_${Date.now()}_${crypto.randomBytes(3).toString("hex")}`;
    const itemsRoot = resolveAvatarItemsRoot();
    ensureDir(itemsRoot);
    const dir = path.join(itemsRoot, id);
    ensureDir(dir);

    const ext = path.extname(filePath) || ".mp4";
    const videoPath = path.join(dir, `video${ext}`);
    fs.copyFileSync(filePath, videoPath);

    const ffmpegExe = pickFfmpegExeFromBundles();
    const meta = await probeVideoMetaViaFfmpeg(ffmpegExe, videoPath);
    const thumbPath = path.join(dir, "thumb.jpg");
    const hasThumb = await generateVideoThumb(ffmpegExe, videoPath, thumbPath);

    const item = {
      id,
      name,
      createdAt: Date.now(),
      videoPath,
      thumbPath: hasThumb ? thumbPath : "",
      width: Number(meta?.width || 0) || 0,
      height: Number(meta?.height || 0) || 0,
      durationSec: Number(meta?.durationSec || 0) || 0,
      fps: Number(meta?.fps || 0) || 0
    };

    try {
      fs.writeFileSync(path.join(dir, "meta.json"), JSON.stringify(item, null, 2), "utf-8");
    } catch {}

    const next = [item, ...readAvatarIndex()];
    writeAvatarIndex(next);
    return { ok: true, item };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

registerSingletonHandle("avatar:importVideo", handleAvatarImportVideoRequest);

async function handleAvatarUpdateNameRequest(_event, payload) {
  try {
    const id = String(payload?.id || "").trim();
    const name = String(payload?.name || "").trim();
    if (!id) return { ok: false, message: "empty id" };
    if (!name) return { ok: false, message: "empty name" };
    const items = readAvatarIndex();
    const idx = items.findIndex((x) => String(x?.id || "") === id);
    if (idx < 0) return { ok: false, message: "not found" };
    const item = { ...items[idx], name, updatedAt: Date.now() };
    const next = items.slice();
    next[idx] = item;
    writeAvatarIndex(next);
    try {
      const dir = item?.videoPath ? path.dirname(String(item.videoPath)) : "";
      if (dir && fs.existsSync(dir)) fs.writeFileSync(path.join(dir, "meta.json"), JSON.stringify(item, null, 2), "utf-8");
    } catch {}
    return { ok: true, item };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

registerSingletonHandle("avatar:updateName", handleAvatarUpdateNameRequest);

async function handleAvatarRemoveRequest(_event, payload) {
  try {
    const id = String(payload?.id || "").trim();
    if (!id) return { ok: false, message: "empty id" };
    const items = readAvatarIndex();
    const item = items.find((x) => String(x?.id || "") === id) || null;
    const next = items.filter((x) => String(x?.id || "") !== id);
    writeAvatarIndex(next);

    const dir = item?.videoPath ? path.dirname(String(item.videoPath)) : path.join(resolveAvatarItemsRoot(), id);
    try {
      if (fs.existsSync(dir)) fs.rmSync(dir, { recursive: true, force: true });
    } catch {}
    return { ok: true };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

registerSingletonHandle("avatar:remove", handleAvatarRemoveRequest);

async function handleAvatarRevealRequest(_event, payload) {
  try {
    const id = String(payload?.id || "").trim();
    if (!id) return { ok: false, message: "empty id" };
    const item = readAvatarIndex().find((x) => String(x?.id || "") === id) || null;
    const videoPath = String(item?.videoPath || "");
    if (!videoPath || !fs.existsSync(videoPath)) return { ok: false, message: "file not found" };
    shell.showItemInFolder(videoPath);
    return { ok: true, path: videoPath, item };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

registerSingletonHandle("avatar:reveal", handleAvatarRevealRequest);

