ipcMain.handle("auth:safeEncrypt", async (_event, payload) => {
  try {
    const text = String(payload?.text || "");
    if (!safeStorage || typeof safeStorage.isEncryptionAvailable !== "function") {
      return { ok: false, message: "safeStorage not supported" };
    }
    if (!safeStorage.isEncryptionAvailable()) {
      return { ok: false, message: "safeStorage encryption unavailable" };
    }
    const buf = safeStorage.encryptString(text);
    return { ok: true, data: Buffer.from(buf).toString("base64") };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

ipcMain.handle("auth:safeDecrypt", async (_event, payload) => {
  try {
    const data = String(payload?.data || "");
    if (!safeStorage || typeof safeStorage.isEncryptionAvailable !== "function") {
      return { ok: false, message: "safeStorage not supported" };
    }
    if (!safeStorage.isEncryptionAvailable()) {
      return { ok: false, message: "safeStorage encryption unavailable" };
    }
    if (!data) return { ok: true, text: "" };
    const buf = Buffer.from(data, "base64");
    const text = safeStorage.decryptString(buf);
    return { ok: true, text };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

