function normalizeCloudUrl(raw) {
  const rawText = String(raw || "").trim();
  if (!rawText) return "";
  let s = rawText;
  if (!/^https?:\/\//i.test(s)) s = `https://${s.replace(/^\/+/, "")}`;
  try {
    const u = new URL(s);
    if (u.protocol === "http:" && /bspapp\.com$/i.test(u.hostname)) u.protocol = "https:";
    return u.toString();
  } catch {
    return "";
  }
}

function readCloudDomainFromFile() {
  try {
    if (!fs.existsSync(YUMING_JSON_PATH)) return DEFAULT_CLOUD_DOMAIN;
    const raw = fs.readFileSync(YUMING_JSON_PATH, "utf-8");
    const obj = JSON.parse(raw || "{}");
    const domain = normalizeCloudUrl(obj?.domain);
    return domain || DEFAULT_CLOUD_DOMAIN;
  } catch {
    return DEFAULT_CLOUD_DOMAIN;
  }
}

function writeCloudDomainToFile(domain) {
  const d = normalizeCloudUrl(domain) || DEFAULT_CLOUD_DOMAIN;
  try {
    const next = { domain: d, updatedAt: new Date().toISOString() };
    fs.writeFileSync(YUMING_JSON_PATH, JSON.stringify(next, null, 2), "utf-8");
    return { ok: true, domain: d };
  } catch (e) {
    return { ok: false, domain: d, message: String(e?.message || e) };
  }
}

function normalizeDetectionConfig(input = {}) {
  const intervalRaw = Number(input.intervalMs || input.interval || 0);
  const intervalMs = Math.max(3000, Number.isFinite(intervalRaw) && intervalRaw > 0 ? Math.floor(intervalRaw) : 10000);
  const lastSyncAt = String(input.lastSyncAt || "").trim();
  const lastMenuUpdatedAt = String(input.lastMenuUpdatedAt || "").trim();
  const updatedAt = String(input.updatedAt || "").trim();
  return {
    enabled: input.enabled !== false,
    scene: String(input.scene || "desktop").trim() || "desktop",
    intervalMs,
    lastSyncAt: lastSyncAt || null,
    lastMenuUpdatedAt: lastMenuUpdatedAt || null,
    updatedAt: updatedAt || null
  };
}

function readDetectionConfigFromFile() {
  try {
    const raw = fs.readFileSync(DINGSHIJIANCE_JSON_PATH, "utf-8");
    const parsed = raw ? JSON.parse(raw) : {};
    const next = normalizeDetectionConfig(parsed || {});
    if (JSON.stringify(parsed || {}) !== JSON.stringify(next)) {
      fs.writeFileSync(DINGSHIJIANCE_JSON_PATH, JSON.stringify({
        ...next,
        updatedAt: next.updatedAt || new Date().toISOString()
      }, null, 2), "utf-8");
    }
    return {
      ...next,
      updatedAt: next.updatedAt || null
    };
  } catch {
    const next = {
      ...normalizeDetectionConfig({}),
      updatedAt: new Date().toISOString()
    };
    try {
      fs.writeFileSync(DINGSHIJIANCE_JSON_PATH, JSON.stringify(next, null, 2), "utf-8");
    } catch {}
    return next;
  }
}

function writeDetectionConfigToFile(input = {}) {
  const current = readDetectionConfigFromFile();
  const next = {
    ...normalizeDetectionConfig({
    ...current,
    ...input
    }),
    updatedAt: new Date().toISOString()
  };
  try {
    fs.writeFileSync(DINGSHIJIANCE_JSON_PATH, JSON.stringify(next, null, 2), "utf-8");
    return { ok: true, config: next };
  } catch (e) {
    return { ok: false, config: next, message: String(e?.message || e) };
  }
}

function buildCloudObjectUrlWithQuery(rawUrl, params = {}) {
  const url = normalizeCloudUrl(rawUrl);
  if (!url) return "";
  const u = new URL(url);
  Object.entries(params || {}).forEach(([key, value]) => {
    if (value === undefined || value === null) return;
    u.searchParams.set(key, String(value));
  });
  return u.toString();
}

function buildCloudHeaders(token) {
  const t = String(token || "").trim();
  if (!t) return {};
  return { Authorization: `Bearer ${t}` };
}

const APP_UPDATE_TEMPLATE_JSON_PATH = path.join(__dirname, "zidonggengxin.json");
const APP_UPDATE_CLOUD_OBJECT_NAME = "qd-zidonggengxin";
const APP_UPDATE_REQUEST_TIMEOUT_MS = 45000;
const OPENCLAW_CONFIG_TEMPLATE_JSON_PATH = path.join(__dirname, "xiaolongxiaopenclaw.json");
let _appUpdateState = { stage: "idle", progress: 0, message: "" };

function resolveCurrentInstallDirForLog() {
  return (
    resolvePreferredInstallDir({
      app,
      projectRoot: resolveProjectRoot(),
      isPackaged: app.isPackaged,
      execPath: process.execPath
    }) ||
    (process.execPath ? path.dirname(process.execPath) : "")
  );
}

function buildAppInstallLogCloudUrl(methodName = "appendLog") {
  const domain = readCloudDomainFromFile();
  return normalizeCloudUrl(`${domain}/${APP_INSTALL_LOG_CLOUD_OBJECT_NAME}/${String(methodName || "appendLog").trim()}`);
}

async function appendAppInstallCloudLog(input = {}) {
  const payload = normalizeInstallLogEntry({
    scene: "desktop",
    currentVersion: String(app.getVersion() || "").trim(),
    deviceId: getOrCreateDeviceId(),
    installDir: resolveCurrentInstallDirForLog(),
    appExePath: String(process.execPath || "").trim(),
    parentPid: Math.max(0, Number(process.pid || 0) || 0),
    ...(input && typeof input === "object" ? input : {})
  });
  if (!payload.installSessionId || !payload.message) {
    return { ok: false, message: "缺少 installSessionId 或 message" };
  }
  const url = buildAppInstallLogCloudUrl("appendLog");
  if (!url) return { ok: false, message: "未配置安装日志云对象地址" };
  try {
    const { statusCode, data, raw } = await requestJson(url, {
      timeoutMs: 8000,
      body: payload
    });
    if (statusCode < 200 || statusCode >= 300) {
      return { ok: false, message: `云端请求失败：http ${statusCode}`, raw };
    }
    return data && typeof data === "object" ? data : { ok: false, message: "云端返回异常", raw };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

function queueAppInstallCloudLog(input = {}) {
  Promise.resolve()
    .then(() => appendAppInstallCloudLog(input))
    .catch(() => {});
}

function getAppUpdateConfigFilePath() {
  try {
    return path.join(app.getPath("userData"), "config", "zidonggengxin.json");
  } catch {
    return APP_UPDATE_TEMPLATE_JSON_PATH;
  }
}

function getOpenClawConfigFilePath() {
  try {
    return path.join(app.getPath("userData"), "config", "xiaolongxiaopenclaw.json");
  } catch {
    return OPENCLAW_CONFIG_TEMPLATE_JSON_PATH;
  }
}

function readJsonObjectIfExists(filePath, fallback = {}) {
  try {
    if (!filePath || !fs.existsSync(filePath)) return fallback;
    const raw = String(fs.readFileSync(filePath, "utf-8") || "").trim();
    if (!raw) return fallback;
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : fallback;
  } catch {
    return fallback;
  }
}

function sanitizeAppUpdateFileName(name, fallback = "") {
  const raw = String(name || "").trim();
  if (!raw) return String(fallback || "").trim();
  return path.basename(raw).replace(/[<>:"/\\|?*\u0000-\u001F]/g, "_");
}

function normalizeAppUpdatePositiveInt(value) {
  const num = Number(value || 0);
  return Number.isFinite(num) && num > 0 ? Math.floor(num) : 0;
}

function normalizeOpenClawConfig(input = {}) {
  return {
    enabled: input?.enabled !== false,
    host: OPENCLAW_TOOL_HOST,
    port: OPENCLAW_TOOL_PORT,
    updatedAt: String(input?.updatedAt || "").trim() || null
  };
}

function pickAppUpdateValue(source, updateData, keys = []) {
  for (const key of keys) {
    const direct = source ? source[key] : undefined;
    if (direct !== undefined && direct !== null && direct !== "") return direct;
    const nested = updateData ? updateData[key] : undefined;
    if (nested !== undefined && nested !== null && nested !== "") return nested;
  }
  return "";
}

function normalizeBinaryDiffPatchEntry(item = {}, defaultTargetVersion = "", defaultTargetArtifactName = "") {
  if (!item || typeof item !== "object") return null;
  const patchUrl = normalizeCloudUrl(item.patchUrl || item.url || "");
  const baseVersion = String(item.baseVersion || item.fromVersion || "").trim();
  const targetVersion = String(item.targetVersion || defaultTargetVersion || "").trim();
  const baseArtifactName = sanitizeAppUpdateFileName(item.baseArtifactName || item.fromArtifactName || "", "");
  const targetArtifactName = sanitizeAppUpdateFileName(item.targetArtifactName || defaultTargetArtifactName || "", "");
  const patchName = sanitizeAppUpdateFileName(item.patchName || path.basename(patchUrl || ""), "");
  if (!baseVersion || !targetVersion || !patchUrl) return null;
  return {
    baseVersion,
    baseArtifactName,
    baseSha512: String(item.baseSha512 || "").trim(),
    baseSize: normalizeAppUpdatePositiveInt(item.baseSize),
    baseDownloadUrl: normalizeCloudUrl(item.baseDownloadUrl || ""),
    targetVersion,
    targetArtifactName,
    targetSha512: String(item.targetSha512 || "").trim(),
    targetSize: normalizeAppUpdatePositiveInt(item.targetSize),
    patchName,
    patchUrl,
    patchSha512: String(item.patchSha512 || item.sha512 || "").trim(),
    patchSize: normalizeAppUpdatePositiveInt(item.patchSize || item.size),
    verified: item.verified === true
  };
}

function extractBinaryDiffPatchList(source = {}, defaultTargetVersion = "", defaultTargetArtifactName = "") {
  const primary = Array.isArray(source?.binaryDiffPatches)
    ? source.binaryDiffPatches
    : source?.patch && typeof source.patch === "object"
      ? [source.patch]
      : [];
  const nested = source?.updateData && typeof source.updateData === "object"
    ? Array.isArray(source.updateData.binaryDiffPatches)
      ? source.updateData.binaryDiffPatches
      : source.updateData.patch && typeof source.updateData.patch === "object"
        ? [source.updateData.patch]
        : []
    : [];
  const seen = new Set();
  return [...primary, ...nested]
    .map((item) => normalizeBinaryDiffPatchEntry(item, defaultTargetVersion, defaultTargetArtifactName))
    .filter((item) => {
      if (!item) return false;
      const key = `${item.baseVersion}|${item.targetVersion}|${item.patchUrl}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function normalizeAppUpdateConfig(input = {}) {
  const updateData = input?.updateData && typeof input.updateData === "object" && !Array.isArray(input.updateData) ? input.updateData : {};
  const latestVersion = String(
    pickAppUpdateValue(input, updateData, ["latestVersion", "version"])
  ).trim();
  const artifactName = sanitizeAppUpdateFileName(
    pickAppUpdateValue(input, updateData, ["artifactName"]),
    ""
  );
  const binaryDiffPatches = extractBinaryDiffPatchList(input, latestVersion, artifactName);
  const manualManifestUrl = normalizeCloudUrl(input.manualManifestUrl || "");
  return {
    scene: String(pickAppUpdateValue(input, updateData, ["scene"]) || "desktop").trim() || "desktop",
    sourceType: String(pickAppUpdateValue(input, updateData, ["sourceType"]) || "cloud-db-update").trim() || "cloud-db-update",
    releaseId: String(pickAppUpdateValue(input, updateData, ["releaseId"])).trim(),
    version: latestVersion,
    latestVersion,
    manifestUrl: normalizeCloudUrl(pickAppUpdateValue(input, updateData, ["manifestUrl"])),
    manualManifestUrl,
    manifestCloudPath: String(pickAppUpdateValue(input, updateData, ["manifestCloudPath"])).trim(),
    downloadUrl: normalizeCloudUrl(pickAppUpdateValue(input, updateData, ["downloadUrl"])),
    providerBaseUrl: normalizeCloudUrl(pickAppUpdateValue(input, updateData, ["providerBaseUrl"])),
    latestYmlUrl: normalizeCloudUrl(pickAppUpdateValue(input, updateData, ["latestYmlUrl"])),
    blockMapUrl: normalizeCloudUrl(pickAppUpdateValue(input, updateData, ["blockMapUrl"])),
    channel: String(pickAppUpdateValue(input, updateData, ["channel"]) || "latest").trim() || "latest",
    artifactName,
    notes: String(pickAppUpdateValue(input, updateData, ["notes"])).trim(),
    publishedAt: String(pickAppUpdateValue(input, updateData, ["publishedAt"])).trim(),
    sha512: String(pickAppUpdateValue(input, updateData, ["sha512"])).trim(),
    size: normalizeAppUpdatePositiveInt(pickAppUpdateValue(input, updateData, ["size"])),
    blockMapSize: normalizeAppUpdatePositiveInt(pickAppUpdateValue(input, updateData, ["blockMapSize"])),
    binaryDiffPreferred:
      input?.binaryDiffPreferred === true ||
      updateData?.binaryDiffPreferred === true ||
      binaryDiffPatches.length > 0,
    binaryDiffPatches,
    patch:
      normalizeBinaryDiffPatchEntry(input?.patch || updateData?.patch || {}, latestVersion, artifactName) || null,
    forceUpdate: input?.forceUpdate === true || updateData?.forceUpdate === true,
    autoCheckOnLaunch: input?.autoCheckOnLaunch !== false,
    updatedAt: String(input?.updatedAt || "").trim() || new Date().toISOString(),
    cloudSyncedAt: String(input?.cloudSyncedAt || "").trim() || "",
    updateData
  };
}

function readAppUpdateConfigFromFile() {
  const template = readJsonObjectIfExists(APP_UPDATE_TEMPLATE_JSON_PATH, {});
  const current = readJsonObjectIfExists(getAppUpdateConfigFilePath(), {});
  return normalizeAppUpdateConfig({
    ...template,
    ...current,
    updateData:
      current?.updateData && typeof current.updateData === "object" && !Array.isArray(current.updateData)
        ? current.updateData
        : template?.updateData && typeof template.updateData === "object" && !Array.isArray(template.updateData)
          ? template.updateData
          : {}
  });
}

function writeAppUpdateConfigToFile(input = {}) {
  const current = readAppUpdateConfigFromFile();
  const next = normalizeAppUpdateConfig({
    ...current,
    ...input,
    updateData:
      input?.updateData && typeof input.updateData === "object" && !Array.isArray(input.updateData)
        ? input.updateData
        : current.updateData,
    updatedAt: new Date().toISOString()
  });
  const filePath = getAppUpdateConfigFilePath();
  try {
    ensureDir(path.dirname(filePath));
    fs.writeFileSync(filePath, JSON.stringify(next, null, 2), "utf-8");
    return { ok: true, config: next, filePath };
  } catch (e) {
    return { ok: false, config: next, filePath, message: String(e?.message || e) };
  }
}

function readOpenClawConfigFromFile() {
  const template = readJsonObjectIfExists(OPENCLAW_CONFIG_TEMPLATE_JSON_PATH, {});
  const current = readJsonObjectIfExists(getOpenClawConfigFilePath(), {});
  return normalizeOpenClawConfig({
    ...template,
    ...current
  });
}

function writeOpenClawConfigToFile(input = {}) {
  const current = readOpenClawConfigFromFile();
  const next = normalizeOpenClawConfig({
    ...current,
    ...input,
    updatedAt: new Date().toISOString()
  });
  const filePath = getOpenClawConfigFilePath();
  try {
    ensureDir(path.dirname(filePath));
    fs.writeFileSync(filePath, JSON.stringify(next, null, 2), "utf-8");
    return { ok: true, config: next, filePath };
  } catch (e) {
    return { ok: false, config: next, filePath, message: String(e?.message || e) };
  }
}

function mergeAppUpdateConfigs(baseConfig = {}, manifestConfig = {}) {
  const base = normalizeAppUpdateConfig(baseConfig || {});
  const manifest = normalizeAppUpdateConfig(manifestConfig || {});
  const mergedUpdateData = {
    ...(base.updateData && typeof base.updateData === "object" ? base.updateData : {}),
    ...(manifest.updateData && typeof manifest.updateData === "object" ? manifest.updateData : {})
  };
  if (Array.isArray(manifest.binaryDiffPatches) && manifest.binaryDiffPatches.length) {
    mergedUpdateData.binaryDiffPatches = manifest.binaryDiffPatches;
  } else if (Array.isArray(base.binaryDiffPatches) && base.binaryDiffPatches.length) {
    mergedUpdateData.binaryDiffPatches = base.binaryDiffPatches;
  }
  if (manifest.binaryDiffPreferred === true || base.binaryDiffPreferred === true) {
    mergedUpdateData.binaryDiffPreferred = true;
  }
  if (manifest.patch && typeof manifest.patch === "object") {
    mergedUpdateData.patch = manifest.patch;
  } else if (base.patch && typeof base.patch === "object") {
    mergedUpdateData.patch = base.patch;
  }
  return normalizeAppUpdateConfig({
    ...base,
    ...manifest,
    scene: String(base.scene || manifest.scene || "desktop").trim() || "desktop",
    sourceType: String(base.sourceType || manifest.sourceType || "cloud-db-update").trim() || "cloud-db-update",
    manualManifestUrl: String(base.manualManifestUrl || "").trim(),
    forceUpdate: base.forceUpdate === true || manifest.forceUpdate === true,
    autoCheckOnLaunch: base.autoCheckOnLaunch !== false,
    updateData: mergedUpdateData
  });
}

async function fetchRemoteUpdateManifestConfig(manifestUrl, { token = "" } = {}) {
  const url = normalizeCloudUrl(manifestUrl);
  if (!url) return { ok: false, message: "云端更新清单地址不正确", manifestUrl: "" };
  try {
    const { statusCode, raw, contentType } = await requestText(url, {
      method: "GET",
      timeoutMs: APP_UPDATE_REQUEST_TIMEOUT_MS,
      headers: buildCloudHeaders(token)
    });
    if (statusCode < 200 || statusCode >= 300) {
      return {
        ok: false,
        message: buildManifestFetchErrorMessage({ manifestUrl: url, statusCode, contentType, raw }),
        manifestUrl: url,
        raw,
        statusCode,
        contentType
      };
    }
    let data = null;
    try {
      data = raw ? JSON.parse(raw) : null;
    } catch (error) {
      return {
        ok: false,
        message: buildManifestFetchErrorMessage({ manifestUrl: url, statusCode, contentType, raw }),
        manifestUrl: url,
        raw,
        statusCode,
        contentType
      };
    }
    if (!data || typeof data !== "object") {
      return {
        ok: false,
        message: "云端更新清单返回异常",
        manifestUrl: url,
        raw,
        statusCode,
        contentType
      };
    }
    return {
      ok: true,
      manifestUrl: url,
      raw,
      config: normalizeAppUpdateConfig({
        ...data,
        sourceType: "cloud-manifest",
        manifestUrl: url
      })
    };
  } catch (e) {
    return { ok: false, message: String(e?.message || e), manifestUrl: url };
  }
}

async function hydrateAppUpdateConfigFromManifest(config = {}, options = {}) {
  const current = normalizeAppUpdateConfig(config || {});
  const manifestUrl = normalizeCloudUrl(current.manualManifestUrl || current.manifestUrl || "");
  if (!manifestUrl) {
    return { ok: true, hydrated: false, manifestUrl: "", config: current };
  }
  const manifestRes = await fetchRemoteUpdateManifestConfig(manifestUrl, options);
  if (!manifestRes?.ok) {
    return {
      ok: false,
      hydrated: false,
      manifestUrl,
      message: String(manifestRes?.message || "读取云端更新清单失败"),
      config: current,
      raw: manifestRes?.raw
    };
  }
  return {
    ok: true,
    hydrated: true,
    manifestUrl,
    raw: manifestRes.raw,
    config: mergeAppUpdateConfigs(current, {
      ...manifestRes.config,
      manifestUrl
    })
  };
}

function compareAppVersion(a = "", b = "") {
  const normalize = (value) =>
    String(value || "")
      .trim()
      .replace(/^v/i, "")
      .split(/[.-]/)
      .map((item) => Number(item || 0) || 0);
  const aa = normalize(a);
  const bb = normalize(b);
  const len = Math.max(aa.length, bb.length);
  for (let i = 0; i < len; i += 1) {
    const av = aa[i] || 0;
    const bv = bb[i] || 0;
    if (av > bv) return 1;
    if (av < bv) return -1;
  }
  return 0;
}

function findBinaryDiffPatchForVersion(config = {}, currentVersion = "") {
  const normalizedCurrent = String(currentVersion || "").trim();
  if (!normalizedCurrent) return null;
  const list = Array.isArray(config?.binaryDiffPatches) ? config.binaryDiffPatches : [];
  const exact = list.find((item) => String(item?.baseVersion || "").trim() === normalizedCurrent);
  if (exact) return exact;
  const legacy = config?.patch && typeof config.patch === "object" ? config.patch : null;
  if (legacy && String(legacy.baseVersion || "").trim() === normalizedCurrent) return legacy;
  return null;
}

function broadcastAppUpdateState() {
  BrowserWindow.getAllWindows().forEach((win) => {
    try {
      win.webContents.send("appUpdate:state", _appUpdateState);
    } catch {}
  });
}

function setAppUpdateState(next = {}) {
  _appUpdateState = {
    ..._appUpdateState,
    ...(next && typeof next === "object" ? next : {}),
    updatedAt: Date.now()
  };
  // #region debug-point A:update-state
  try {
    const normalized = {
      stage: String(_appUpdateState?.stage || "").trim(),
      updateMode: String(_appUpdateState?.updateMode || "").trim(),
      installPhase: String(_appUpdateState?.installPhase || "").trim(),
      progress: Math.max(0, Number(_appUpdateState?.progress || 0) || 0),
      message: String(_appUpdateState?.message || "").trim(),
      errorMessage: String(_appUpdateState?.errorMessage || "").trim(),
      latestVersion: String(_appUpdateState?.latestVersion || "").trim(),
      artifactName: String(_appUpdateState?.artifactName || "").trim()
    };
    if (normalized.stage === "installing" || normalized.stage === "error" || normalized.stage === "idle") {
      dbgLocalInstall96Emit("A", "main.js:setAppUpdateState", "更新状态变化", normalized);
    }
  } catch {}
  // #endregion
  broadcastAppUpdateState();
  return _appUpdateState;
}

async function syncAppUpdateFromCloud(payload = {}) {
  const scene = String(payload?.scene || "desktop").trim() || "desktop";
  const domain = readCloudDomainFromFile();
  const url = buildCloudObjectUrlWithQuery(`${domain}/${APP_UPDATE_CLOUD_OBJECT_NAME}/getLatest`, { scene });
  const token = String(payload?.token || "").trim();
  const { statusCode, data, raw } = await requestJson(url, {
    timeoutMs: APP_UPDATE_REQUEST_TIMEOUT_MS,
    headers: buildCloudHeaders(token),
    body: {}
  });
  if (statusCode < 200 || statusCode >= 300) {
    return { ok: false, message: `云端请求失败：http ${statusCode}`, raw, domain };
  }
  if (!data || typeof data !== "object") {
    return { ok: false, message: "云端返回异常", raw, domain };
  }
  if (data.errCode) {
    return { ok: false, message: String(data.errMsg || "同步更新配置失败"), data, domain };
  }
  const localConfig = readAppUpdateConfigFromFile();
  const cloudConfig = normalizeAppUpdateConfig({
    ...data,
    scene,
    sourceType: "cloud-db-update",
    cloudSyncedAt: new Date().toISOString()
  });
  const hydratedRes = await hydrateAppUpdateConfigFromManifest(cloudConfig, { token });
  const hasUsableCloudConfig =
    !!String(cloudConfig?.latestVersion || "").trim() &&
    (!!String(cloudConfig?.downloadUrl || "").trim() ||
      (Array.isArray(cloudConfig?.binaryDiffPatches) && cloudConfig.binaryDiffPatches.length > 0) ||
      !!String(cloudConfig?.patch?.patchUrl || "").trim());
  let finalConfig = cloudConfig;
  let manifestHydrationWarning = "";
  if (!hydratedRes?.ok) {
    if (!hasUsableCloudConfig) {
      return {
        ok: false,
        message: String(hydratedRes?.message || "同步更新配置失败"),
        domain,
        config: hydratedRes?.config || cloudConfig,
        raw: data,
        manifestUrl: hydratedRes?.manifestUrl || ""
      };
    }
    manifestHydrationWarning = String(hydratedRes?.message || "").trim();
  } else {
    finalConfig = hydratedRes?.config || cloudConfig;
  }
  const writeRes = writeAppUpdateConfigToFile({
    ...localConfig,
    ...finalConfig,
    manualManifestUrl: localConfig.manualManifestUrl || "",
    autoCheckOnLaunch: localConfig.autoCheckOnLaunch !== false,
    cloudSyncedAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  });
  if (!writeRes.ok) return writeRes;
  return {
    ok: true,
    domain,
    config: writeRes.config,
    raw: data,
    hydratedFromManifest: hydratedRes?.hydrated === true,
    manifestUrl: hydratedRes?.manifestUrl || normalizeCloudUrl(finalConfig?.manifestUrl || ""),
    manifestHydrationWarning
  };
}

function checkAppUpdateFromConfig(config = {}) {
  const currentVersion = String(app.getVersion() || "0.0.0").trim() || "0.0.0";
  const latestVersion = String(config?.latestVersion || config?.version || "").trim();
  if (!latestVersion) {
    return { ok: false, message: "云端更新数据缺少版本号", currentVersion };
  }
  if (compareAppVersion(currentVersion, latestVersion) >= 0) {
    return { ok: true, hasUpdate: false, currentVersion, latestVersion, config };
  }
  const downloadUrl = String(config?.downloadUrl || "").trim();
  if (!downloadUrl) {
    return { ok: false, hasUpdate: true, currentVersion, latestVersion, message: "云端更新数据缺少安装包下载地址", config };
  }
  return {
    ok: true,
    hasUpdate: true,
    currentVersion,
    latestVersion,
    downloadUrl,
    artifactName: String(config?.artifactName || "").trim(),
    providerBaseUrl: String(config?.providerBaseUrl || "").trim(),
    notes: String(config?.notes || "").trim(),
    publishedAt: String(config?.publishedAt || "").trim(),
    forceUpdate: config?.forceUpdate === true,
    binaryDiffPatch: null,
    manifestOnly: false,
    raw: {
      source: "cloud-db-update",
      manifest: config?.updateData || null,
      config
    }
  };
}

function getAppUpdateCacheDir() {
  const installRoot =
    resolvePreferredInstallDir({
      app,
      projectRoot: resolveProjectRoot(),
      isPackaged: app.isPackaged,
      execPath: process.execPath
    }) ||
    (process.execPath ? path.dirname(process.execPath) : "") ||
    resolveProjectRoot();
  return path.join(installRoot, "gengxin");
}

function getAppUpdateInstallerStagingDir() {
  return path.join(app.getPath("temp"), "bukong-ip-agent-installer");
}

function formatAppUpdateLocalTime(value = Date.now()) {
  try {
    const date = value instanceof Date ? value : new Date(value);
    const pad = (num) => String(num).padStart(2, "0");
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(
      date.getSeconds()
    )}`;
  } catch {
    return "";
  }
}

function appendAppUpdateHelperLog(filePath, text) {
  try {
    const targetPath = String(filePath || "").trim();
    if (!targetPath) return;
    ensureDir(path.dirname(targetPath));
    fs.appendFileSync(targetPath, `${formatAppUpdateLocalTime()} ${String(text || "").trim()}${os.EOL}`, "utf-8");
  } catch {}
}

function readAppUpdateTextTail(filePath, { maxLines = 24, maxChars = 4000 } = {}) {
  try {
    const targetPath = String(filePath || "").trim();
    if (!targetPath || !fs.existsSync(targetPath)) return "";
    const raw = String(fs.readFileSync(targetPath, "utf-8") || "");
    if (!raw) return "";
    const trimmed = raw.length > maxChars ? raw.slice(raw.length - maxChars) : raw;
    const lines = trimmed.split(/\r?\n/).filter((line) => String(line || "").trim());
    return lines.slice(-Math.max(1, Number(maxLines || 0) || 24)).join(os.EOL);
  } catch {
    return "";
  }
}

function resolvePowerShellExePath() {
  const systemRoot = String(process.env.SystemRoot || process.env.WINDIR || "C:\\Windows").trim() || "C:\\Windows";
  const candidates = [
    path.join(systemRoot, "System32", "WindowsPowerShell", "v1.0", "powershell.exe"),
    path.join(systemRoot, "Sysnative", "WindowsPowerShell", "v1.0", "powershell.exe"),
    "powershell.exe"
  ];
  for (const item of candidates) {
    try {
      if (!item) continue;
      if ((item.includes("\\") || item.includes("/")) && !fs.existsSync(item)) continue;
      return item;
    } catch {}
  }
  return "powershell.exe";
}

function getCurrentInstalledExeMeta() {
  const exePath = String(process.execPath || "").trim();
  try {
    if (!exePath || !fs.existsSync(exePath)) {
      return { path: exePath, version: "", lastWriteTime: "" };
    }
    const stat = fs.statSync(exePath);
    return {
      path: exePath,
      version: String(app.getVersion() || "").trim(),
      lastWriteTime: formatAppUpdateLocalTime(stat.mtime)
    };
  } catch {
    return { path: exePath, version: "", lastWriteTime: "" };
  }
}

function escapePowerShellSingleQuotedText(value = "") {
  return String(value || "").replace(/'/g, "''");
}

function listAppUpdateCacheFiles(cacheDir) {
  try {
    if (!cacheDir || !fs.existsSync(cacheDir)) return [];
    return fs
      .readdirSync(cacheDir, { withFileTypes: true })
      .map((entry) => {
        const fullPath = path.join(cacheDir, entry.name);
        let size = 0;
        let updatedAt = "";
        try {
          const stat = fs.statSync(fullPath);
          size = stat.isFile() ? stat.size : 0;
          updatedAt = formatAppUpdateLocalTime(stat.mtime);
        } catch {}
        return {
          name: entry.name,
          path: fullPath,
          type: entry.isDirectory() ? "dir" : "file",
          size,
          updatedAt
        };
      })
      .sort((a, b) => String(b.updatedAt || "").localeCompare(String(a.updatedAt || "")));
  } catch {
    return [];
  }
}

function parseVersionFromInstallerName(fileName = "") {
  const normalized = sanitizeAppUpdateFileName(fileName, "");
  const match = normalized.match(/-v(\d+\.\d+\.\d+(?:[a-z0-9._-]*)?)\.exe$/i) || normalized.match(/v(\d+\.\d+\.\d+(?:[a-z0-9._-]*)?)/i);
  return String(match?.[1] || "").trim();
}

function computeFileSha512Base64(filePath = "") {
  const normalizedPath = String(filePath || "").trim();
  if (!normalizedPath || !fs.existsSync(normalizedPath)) return "";
  const hash = crypto.createHash("sha512");
  hash.update(fs.readFileSync(normalizedPath));
  return hash.digest("base64");
}

function validateCachedInstallerFile(filePath = "", { expectedSize = 0, expectedSha512 = "", expectedVersion = "" } = {}) {
  const normalizedPath = String(filePath || "").trim();
  if (!normalizedPath || !fs.existsSync(normalizedPath)) {
    return { ok: false, reason: "missing-file", size: 0, sha512: "", version: "" };
  }
  try {
    const stat = fs.statSync(normalizedPath);
    const size = Math.max(0, Number(stat?.size || 0) || 0);
    const version = parseVersionFromInstallerName(path.basename(normalizedPath));
    const normalizedExpectedSha512 = String(expectedSha512 || "").trim();
    const sha512 = normalizedExpectedSha512 ? computeFileSha512Base64(normalizedPath) : "";
    if (size <= 0) return { ok: false, reason: "empty-file", size, sha512, version };
    if (Number(expectedSize || 0) > 0 && size !== Number(expectedSize || 0)) {
      return { ok: false, reason: "size-mismatch", size, sha512, version };
    }
    if (normalizedExpectedSha512 && sha512 !== normalizedExpectedSha512) {
      return { ok: false, reason: "sha512-mismatch", size, sha512, version };
    }
    if (!Number(expectedSize || 0) && !normalizedExpectedSha512 && String(expectedVersion || "").trim() && version !== String(expectedVersion || "").trim()) {
      return { ok: false, reason: "version-mismatch", size, sha512, version };
    }
    return { ok: true, reason: "validated", size, sha512, version };
  } catch (error) {
    return {
      ok: false,
      reason: "stat-failed",
      size: 0,
      sha512: "",
      version: "",
      errorMessage: String(error?.message || error || "").trim()
    };
  }
}

function listLocalInstallerCandidates(directoryPath = "", options = {}) {
  const targetRoot = String(directoryPath || "").trim();
  if (!targetRoot || !fs.existsSync(targetRoot)) return [];
  const maxDepth = Math.max(0, Number(options?.maxDepth || 3) || 3);
  const maxEntries = Math.max(20, Number(options?.maxEntries || 300) || 300);
  const currentExeName = sanitizeAppUpdateFileName(path.basename(process.execPath || ""), "").toLowerCase();
  const currentAppName = sanitizeAppUpdateFileName(app?.getName?.() || "", "").toLowerCase();
  const results = [];
  const stack = [{ dir: targetRoot, depth: 0 }];
  let scannedEntries = 0;
  while (stack.length && scannedEntries < maxEntries) {
    const current = stack.pop();
    if (!current?.dir || current.depth > maxDepth) continue;
    let entries = [];
    try {
      entries = fs.readdirSync(current.dir, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const entry of entries) {
      scannedEntries += 1;
      const fullPath = path.join(current.dir, entry.name);
      if (entry.isDirectory()) {
        if (current.depth < maxDepth) stack.push({ dir: fullPath, depth: current.depth + 1 });
        continue;
      }
      if (!entry.isFile()) continue;
      const fileName = sanitizeAppUpdateFileName(entry.name, "");
      const lowerName = fileName.toLowerCase();
      if (!lowerName.endsWith(".exe")) continue;
      if (lowerName.includes(".blockmap") || lowerName.includes(".patch")) continue;
      let stat = null;
      try {
        stat = fs.statSync(fullPath);
      } catch {}
      const size = stat?.size || 0;
      const version = parseVersionFromInstallerName(fileName);
      const relativePath = path.relative(targetRoot, fullPath);
      let score = 0;
      if (lowerName.includes("不空ip智能体")) score += 80;
      if (currentExeName && lowerName === currentExeName) score += 60;
      if (currentAppName && lowerName.includes(currentAppName)) score += 30;
      if (version) score += 25;
      if (/^exe[\\/]/i.test(relativePath)) score += 15;
      if (size >= 50 * 1024 * 1024) score += 20;
      results.push({
        fileName,
        fullPath,
        relativePath,
        size,
        version,
        depth: current.depth,
        score,
        updatedAt: stat?.mtimeMs || 0
      });
    }
  }
  return results
    .sort((a, b) => {
      if (b.score !== a.score) return b.score - a.score;
      if ((b.size || 0) !== (a.size || 0)) return (b.size || 0) - (a.size || 0);
      return (b.updatedAt || 0) - (a.updatedAt || 0);
    })
    .slice(0, 20);
}

function resolveLocalInstallerFromDirectory(directoryPath = "") {
  const targetRoot = String(directoryPath || "").trim();
  if (!targetRoot) return { ok: false, message: "请选择安装包所在文件夹。" };
  if (!fs.existsSync(targetRoot)) return { ok: false, message: "所选安装包文件夹不存在。" };
  let stat = null;
  try {
    stat = fs.statSync(targetRoot);
  } catch {}
  if (!stat?.isDirectory?.()) return { ok: false, message: "所选路径不是文件夹。" };
  const candidates = listLocalInstallerCandidates(targetRoot, { maxDepth: 3, maxEntries: 300 });
  if (!candidates.length) {
    return { ok: false, message: "所选文件夹中没有找到可安装的新版本 exe 安装包。" };
  }
  return {
    ok: true,
    installerPath: candidates[0].fullPath,
    installerName: candidates[0].fileName,
    expectedVersion: candidates[0].version,
    candidates
  };
}

function resolveLocalInstallerFromPath(localPath = "") {
  const targetPath = String(localPath || "").trim();
  if (!targetPath) return { ok: false, message: "请选择 EXE 安装包文件或安装包文件夹。" };
  if (!fs.existsSync(targetPath)) return { ok: false, message: "所选安装包路径不存在。" };
  let stat = null;
  try {
    stat = fs.statSync(targetPath);
  } catch {}
  if (!stat) return { ok: false, message: "读取安装包路径失败。" };
  if (stat.isDirectory()) return resolveLocalInstallerFromDirectory(targetPath);
  if (!stat.isFile()) return { ok: false, message: "所选路径不是可安装文件。" };
  const fileName = sanitizeAppUpdateFileName(path.basename(targetPath), "");
  if (!/\.exe$/i.test(fileName)) return { ok: false, message: "请选择 EXE 安装包文件。" };
  const expectedVersion = parseVersionFromInstallerName(fileName);
  return {
    ok: true,
    installerPath: targetPath,
    installerName: fileName,
    expectedVersion,
    candidates: [
      {
        fileName,
        fullPath: targetPath,
        relativePath: fileName,
        size: stat.size || 0,
        version: expectedVersion,
        depth: 0,
        score: 999,
        updatedAt: stat.mtimeMs || 0
      }
    ]
  };
}

function buildAppUpdateDiagnostics() {
  const cacheDir = getAppUpdateCacheDir();
  const helperPath = path.join(cacheDir, "anzhuanggengxin.ps1");
  const helperLogPath = path.join(cacheDir, "anzhuanggengxin.log");
  const installRecordRes = readInstallDirRecord({
    app,
    projectRoot: resolveProjectRoot(),
    isPackaged: app.isPackaged,
    execPath: process.execPath
  });
  const helperLogTail = readAppUpdateTextTail(helperLogPath, { maxLines: 20, maxChars: 5000 });
  let lastInstallStatus = helperLogTail ? "已生成安装日志，请按日志内容判断。" : "尚未生成安装日志，说明安装助手没有真正启动。";
  if (helperLogTail.includes("restart ok=")) {
    lastInstallStatus = "安装助手已重启新程序，请继续核对当前 exe 版本。";
  } else if (helperLogTail.includes("restart skipped:")) {
    lastInstallStatus = "安装助手已运行，但未找到正确版本的 exe。";
  } else if (helperLogTail.includes("installer error=") || helperLogTail.includes("spawn error=") || helperLogTail.includes("spawn throw=")) {
    lastInstallStatus = "安装助手启动失败或安装器执行失败。";
  } else if (helperLogTail.includes("installer exitCode=")) {
    lastInstallStatus = "安装器已执行，请继续核对 exitCode 与 restart check。";
  }
  return {
    ok: true,
    currentVersion: String(app.getVersion() || "0.0.0"),
    currentExe: getCurrentInstalledExeMeta(),
    cacheDir,
    cacheFiles: listAppUpdateCacheFiles(cacheDir),
    configFilePath: getAppUpdateConfigFilePath(),
    helperPath,
    helperLogPath,
    helperLogExists: fs.existsSync(helperLogPath),
    helperScriptExists: fs.existsSync(helperPath),
    installRecordPath: getInstallDirRecordPath({
      app,
      projectRoot: resolveProjectRoot(),
      isPackaged: app.isPackaged,
      execPath: process.execPath
    }),
    installRecord: installRecordRes.record || {},
    powerShellPath: resolvePowerShellExePath(),
    lastInstallStatus,
    helperLogTail
  };
}

function updateAppDownloadProgress({
  receivedBytes = 0,
  totalBytes = 0,
  message = "",
  updateMode = "",
  latestVersion = "",
  artifactName = "",
  downloadKind = ""
} = {}) {
  const total = Math.max(0, Number(totalBytes || 0) || 0);
  const received = Math.max(0, Number(receivedBytes || 0) || 0);
  setAppUpdateState({
    stage: "downloading",
    updateMode: String(updateMode || "").trim(),
    latestVersion: String(latestVersion || "").trim(),
    artifactName: String(artifactName || "").trim(),
    downloadKind: String(downloadKind || "").trim(),
    progress: total > 0 ? Math.max(0, Math.min(100, (received / total) * 100)) : 0,
    isProgressIndeterminate: total <= 0 && received > 0,
    receivedBytes: received,
    totalBytes: total,
    message: String(message || "正在下载更新资源...").trim() || "正在下载更新资源..."
  });
}

function wrapAppUpdateDownloadError(error, { label = "下载文件", url = "", http404Hint = "" } = {}) {
  const statusCode = Number(error?.statusCode || 0) || 0;
  const targetUrl = String(error?.downloadUrl || url || "").trim();
  const baseMessage = String(error?.message || error || "下载失败").trim() || "下载失败";
  if (statusCode === 404) {
    return new Error(
      `${label}下载失败：云端文件不存在（HTTP 404）。${http404Hint || "请确认该文件已经上传到云端且地址与云数据一致。"}${
        targetUrl ? `\n${targetUrl}` : ""
      }`
    );
  }
  if (statusCode > 0) {
    return new Error(`${label}下载失败：HTTP ${statusCode}${targetUrl ? `\n${targetUrl}` : ""}`);
  }
  return new Error(`${label}下载失败：${baseMessage}${targetUrl ? `\n${targetUrl}` : ""}`);
}

function startAppUpdateInstallerHelper(installerPath, options = {}) {
  const helperDir = getAppUpdateCacheDir();
  ensureDir(helperDir);
  const helperPath = path.join(helperDir, "anzhuanggengxin.ps1");
  const helperLauncherPath = path.join(helperDir, "anzhuanggengxin-launcher.ps1");
  const helperLogPath = path.join(helperDir, "anzhuanggengxin.log");
  const appExePath = String(process.execPath || "").trim();
  const appExeName = sanitizeAppUpdateFileName(path.basename(appExePath || ""), "app.exe");
  const installDir =
    resolvePreferredInstallDir({
      app,
      projectRoot: resolveProjectRoot(),
      isPackaged: app.isPackaged,
      execPath: process.execPath
    }) ||
    (appExePath ? path.dirname(appExePath) : "");
  const expectedVersion = String(options?.expectedVersion || "").trim();
  const installSessionId = String(options?.installSessionId || "").trim();
  const releaseId = String(options?.releaseId || "").trim();
  const installMode = String(options?.installMode || "").trim();
  const artifactName = sanitizeAppUpdateFileName(options?.artifactName || path.basename(installerPath || ""), "");
  const cloudLogUrl = buildAppInstallLogCloudUrl("appendLog");
  const currentVersion = String(options?.currentVersion || app.getVersion() || "").trim();
  const deviceId = getOrCreateDeviceId();
  const powerShellPath = resolvePowerShellExePath();
  const esc = (value) => String(value || "").replace(/'/g, "''");
  // #region debug-point A:helper-input
  try {
    dbgV046Emit("A", "main.js:startAppUpdateInstallerHelper", "自动更新 helper 准备启动", {
      installerPath: String(installerPath || "").trim(),
      helperPath,
      helperLogPath,
      appExePath,
      appExeName,
      installDir,
      expectedVersion,
      installSessionId,
      releaseId,
      installMode,
      artifactName,
      powerShellPath,
      installerExists: !!(installerPath && fs.existsSync(installerPath)),
      currentVersion: String(app.getVersion() || "").trim()
    });
  } catch {}
  // #endregion
  const script = [
    "$ErrorActionPreference = 'Continue'",
    "try { $Host.UI.RawUI.WindowTitle = '不空IP智能体安装助手' } catch {}",
    `$installer = '${esc(installerPath)}'`,
    `$appExe = '${esc(appExePath)}'`,
    `$appExeName = '${esc(appExeName)}'`,
    `$installDir = '${esc(installDir)}'`,
    `$helperLog = '${esc(helperLogPath)}'`,
    `$expectedVersion = '${esc(expectedVersion)}'`,
    `$cloudLogUrl = '${esc(cloudLogUrl)}'`,
    `$cloudSessionId = '${esc(installSessionId)}'`,
    `$cloudReleaseId = '${esc(releaseId)}'`,
    `$cloudInstallMode = '${esc(installMode)}'`,
    `$cloudArtifactName = '${esc(artifactName)}'`,
    `$cloudCurrentVersion = '${esc(currentVersion)}'`,
    `$cloudTargetVersion = '${esc(expectedVersion)}'`,
    `$cloudDeviceId = '${esc(deviceId)}'`,
    `$waitPid = ${Math.max(0, Number(process.pid || 0) || 0)}`,
    "function Write-InstallLog([string]$text) {",
    "  try {",
    "    $line = (Get-Date -Format 'yyyy-MM-dd HH:mm:ss') + ' ' + $text",
    "    Add-Content -Path $helperLog -Value $line -Encoding UTF8",
    "    Write-Host $line",
    "  } catch {}",
    "}",
    "function Write-InstallCloudLog([string]$eventType, [string]$message, [string]$level = 'info', [hashtable]$extra = $null) {",
    "  try {",
    "    if (-not $cloudLogUrl -or -not $cloudSessionId -or -not $message) { return }",
    "    $body = @{",
    "      scene = 'desktop'",
    "      installSessionId = $cloudSessionId",
    "      releaseId = $cloudReleaseId",
    "      source = 'helper'",
    "      stage = 'helper'",
    "      eventType = $eventType",
    "      level = $level",
    "      message = $message",
    "      currentVersion = $cloudCurrentVersion",
    "      targetVersion = $cloudTargetVersion",
    "      artifactName = $cloudArtifactName",
    "      installMode = $cloudInstallMode",
    "      deviceId = $cloudDeviceId",
    "      installDir = $installDir",
    "      appExePath = $appExe",
    "      installerPath = $installer",
    "      helperPath = $PSCommandPath",
    "      helperLogPath = $helperLog",
    "      helperPid = $PID",
    "      parentPid = $waitPid",
    "      extra = $extra",
    "      createdAt = [DateTimeOffset]::Now.ToUnixTimeMilliseconds()",
    "    } | ConvertTo-Json -Depth 8 -Compress",
    "    Invoke-RestMethod -Uri $cloudLogUrl -Method POST -ContentType 'application/json' -Body $body | Out-Null",
    "  } catch {}",
    "}",
    "Write-InstallLog ('helper start installer=' + $installer)",
    "Write-InstallCloudLog 'helper.start' ('helper start installer=' + $installer) 'info' @{ installDir = $installDir; helperLogPath = $helperLog }",
    "Start-Sleep -Seconds 1",
    "if ($waitPid -gt 0) {",
    "  try { Wait-Process -Id $waitPid -Timeout 12 } catch {}",
    "  try { taskkill /PID $waitPid /T /F | Out-Null } catch {}",
    "  Write-InstallLog ('wait old pid=' + $waitPid)",
    "  Write-InstallCloudLog 'helper.wait-old-pid' ('wait old pid=' + $waitPid) 'info' @{ waitPid = $waitPid }",
    "}",
    "Start-Sleep -Seconds 1",
    "if (Test-Path $installer) {",
    "  $installArgs = @('/S')",
    "  if ($installDir) { $installArgs += ('/D=' + $installDir) }",
    "  Write-InstallLog ('installer args=' + ($installArgs -join ' '))",
    "  Write-InstallCloudLog 'installer.start' ('installer args=' + ($installArgs -join ' ')) 'info' @{ installArgs = ($installArgs -join ' ') }",
    "  try {",
    "    $proc = Start-Process -FilePath $installer -ArgumentList $installArgs -WindowStyle Normal -Wait -PassThru",
    "    Write-InstallLog ('installer exitCode=' + $proc.ExitCode)",
    "    Write-InstallCloudLog 'installer.exit' ('installer exitCode=' + $proc.ExitCode) 'info' @{ exitCode = $proc.ExitCode }",
    "  } catch {",
    "    Write-InstallLog ('installer error=' + $_.Exception.Message)",
    "    Write-InstallCloudLog 'installer.error' ('installer error=' + $_.Exception.Message) 'error' @{ error = $_.Exception.Message }",
    "  }",
    "} else {",
    "  Write-InstallLog ('installer missing=' + $installer)",
    "  Write-InstallCloudLog 'installer.missing' ('installer missing=' + $installer) 'error' @{ installer = $installer }",
    "}",
    "$restartExe = ''",
    "if ($installDir -and $appExeName) {",
    "  try { $restartExe = Join-Path $installDir $appExeName } catch {}",
    "}",
    "if (-not $restartExe -and (Test-Path $appExe)) { $restartExe = $appExe }",
    "Write-InstallLog ('restart candidate=' + $restartExe)",
    "Write-InstallCloudLog 'restart.candidate' ('restart candidate=' + $restartExe) 'info' @{ restartExe = $restartExe }",
    "$started = $false",
    "for ($i = 0; $i -lt 20; $i++) {",
    "  if (Test-Path $restartExe) {",
    "    $fileVersion = ''",
    "    try { $fileVersion = (Get-Item $restartExe).VersionInfo.ProductVersion } catch {}",
    "    Write-InstallLog ('restart check=' + $restartExe + ' version=' + $fileVersion + ' expected=' + $expectedVersion + ' try=' + $i)",
    "    Write-InstallCloudLog 'restart.check' ('restart check=' + $restartExe + ' version=' + $fileVersion + ' expected=' + $expectedVersion + ' try=' + $i) 'info' @{ restartExe = $restartExe; fileVersion = $fileVersion; expectedVersion = $expectedVersion; tryIndex = $i }",
    "    if (-not $expectedVersion -or $fileVersion -eq $expectedVersion) {",
    "      try {",
    "        Start-Process -FilePath $restartExe -WorkingDirectory (Split-Path $restartExe -Parent)",
    "        Write-InstallLog ('restart ok=' + $restartExe)",
    "        Write-InstallCloudLog 'restart.ok' ('restart ok=' + $restartExe) 'info' @{ restartExe = $restartExe; fileVersion = $fileVersion }",
    "        $started = $true",
    "        break",
    "      } catch {",
    "        Write-InstallLog ('restart error=' + $_.Exception.Message)",
    "        Write-InstallCloudLog 'restart.error' ('restart error=' + $_.Exception.Message) 'error' @{ error = $_.Exception.Message; restartExe = $restartExe }",
    "      }",
    "    }",
    "  }",
    "  Start-Sleep -Seconds 1",
    "}",
    "if (-not $started) {",
    "  Write-InstallLog ('restart skipped: exe missing or version mismatch, expected=' + $expectedVersion + ' candidate=' + $restartExe)",
    "  Write-InstallCloudLog 'restart.skipped' ('restart skipped: exe missing or version mismatch, expected=' + $expectedVersion + ' candidate=' + $restartExe) 'warn' @{ expectedVersion = $expectedVersion; restartExe = $restartExe }",
    "}",
    "Write-InstallLog 'helper finished, window will close after 8 seconds'",
    "Start-Sleep -Seconds 8"
  ].join(os.EOL);
  fs.writeFileSync(helperPath, script, "utf-8");
  const launcherScript = [
    "$ErrorActionPreference = 'Continue'",
    `$helperPath = '${esc(helperPath)}'`,
    `$helperLog = '${esc(helperLogPath)}'`,
    `$powerShellPath = '${esc(powerShellPath)}'`,
    "$helperArgs = @('-NoLogo','-ExecutionPolicy','Bypass','-File',$helperPath)",
    "$launcherNow = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'",
    "try { Add-Content -Path $helperLog -Value ($launcherNow + ' launcher start args=' + ($helperArgs -join ' ')) -Encoding UTF8 } catch {}",
    "try {",
    "  $launcherProc = Start-Process -FilePath $powerShellPath -ArgumentList $helperArgs -WindowStyle Normal -PassThru",
    "  $launcherNow = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'",
    "  try { Add-Content -Path $helperLog -Value ($launcherNow + ' launcher visible pid=' + $launcherProc.Id) -Encoding UTF8 } catch {}",
    "} catch {",
    "  $launcherNow = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'",
    "  try { Add-Content -Path $helperLog -Value ($launcherNow + ' launcher error=' + $_.Exception.Message) -Encoding UTF8 } catch {}",
    "}"
  ].join(os.EOL);
  fs.writeFileSync(helperLauncherPath, launcherScript, "utf-8");
  appendAppUpdateHelperLog(helperLogPath, `helper bootstrap script=${helperPath}`);
  appendAppUpdateHelperLog(helperLogPath, `helper bootstrap launcher=${helperLauncherPath}`);
  appendAppUpdateHelperLog(helperLogPath, `helper bootstrap powershell=${powerShellPath}`);
  appendAppUpdateHelperLog(helperLogPath, `helper bootstrap installer=${installerPath}`);
  appendAppUpdateHelperLog(helperLogPath, `helper bootstrap session=${installSessionId}`);
  queueAppInstallCloudLog({
    installSessionId,
    releaseId,
    source: "main",
    stage: "helper",
    eventType: "helper.bootstrap",
    level: "info",
    message: "自动更新 helper 已写入本地脚本并准备启动",
    targetVersion: expectedVersion,
    artifactName,
    installMode,
    installerPath,
    helperPath,
    helperLogPath,
    extra: {
      powerShellPath,
      helperLauncherPath,
      installDir
    }
  });
  // #region debug-point A:helper-script-written
  try {
    dbgV046Emit("A", "main.js:startAppUpdateInstallerHelper", "helper 脚本已写入并完成 bootstrap 记录", {
      helperExists: fs.existsSync(helperPath),
      helperLauncherExists: fs.existsSync(helperLauncherPath),
      helperLogExists: fs.existsSync(helperLogPath),
      helperLogTail: readAppUpdateTextTail(helperLogPath, { maxLines: 6, maxChars: 1200 })
    });
  } catch {}
  // #endregion
  try {
    const cmdExe = process.env.ComSpec || "C:\\Windows\\System32\\cmd.exe";
    const launchVisibleHelperCommand = `start "" "${powerShellPath}" -NoLogo -ExecutionPolicy Bypass -File "${helperLauncherPath}"`;
    const child = spawn(cmdExe, ["/d", "/s", "/c", launchVisibleHelperCommand], {
      windowsHide: true,
      stdio: "ignore"
    });
    // #region debug-point B:helper-child-events
    try {
      child.on("spawn", () => {
        queueAppInstallCloudLog({
          installSessionId,
          releaseId,
          source: "main",
          stage: "helper",
          eventType: "helper.spawned",
          level: "info",
          message: "PowerShell 安装助手进程已启动",
          targetVersion: expectedVersion,
          artifactName,
          installMode,
          installerPath,
          helperPath,
          helperLogPath,
          helperPid: Math.max(0, Number(child?.pid || 0) || 0),
          extra: {
            powerShellPath
          }
        });
        dbgV046Emit("B", "main.js:startAppUpdateInstallerHelper", "PowerShell helper 进程已触发 spawn", {
          childPid: Math.max(0, Number(child?.pid || 0) || 0),
          helperPath,
          powerShellPath
        });
      });
      child.on("exit", (code, signal) => {
        queueAppInstallCloudLog({
          installSessionId,
          releaseId,
          source: "main",
          stage: "helper",
          eventType: "helper.exit",
          level: "info",
          message: `PowerShell 安装助手进程已退出 code=${Number(code)} signal=${String(signal || "")}`,
          targetVersion: expectedVersion,
          artifactName,
          installMode,
          installerPath,
          helperPath,
          helperLogPath,
          helperPid: Math.max(0, Number(child?.pid || 0) || 0),
          exitCode: Number(code),
          signal: String(signal || ""),
          extra: {
            helperLogTail: readAppUpdateTextTail(helperLogPath, { maxLines: 8, maxChars: 1500 })
          }
        });
        dbgV046Emit("B", "main.js:startAppUpdateInstallerHelper", "PowerShell helper 进程 exit", {
          childPid: Math.max(0, Number(child?.pid || 0) || 0),
          exitCode: Number(code),
          signal: String(signal || ""),
          helperLogTail: readAppUpdateTextTail(helperLogPath, { maxLines: 8, maxChars: 1500 })
        });
      });
      child.on("close", (code, signal) => {
        dbgV046Emit("B", "main.js:startAppUpdateInstallerHelper", "PowerShell helper 进程 close", {
          childPid: Math.max(0, Number(child?.pid || 0) || 0),
          closeCode: Number(code),
          signal: String(signal || "")
        });
      });
    } catch {}
    // #endregion
    child.on("error", (error) => {
      appendAppUpdateHelperLog(helperLogPath, `spawn error=${String(error?.message || error)}`);
      queueAppInstallCloudLog({
        installSessionId,
        releaseId,
        source: "main",
        stage: "helper",
        eventType: "helper.spawn-error",
        level: "error",
        message: `PowerShell 安装助手进程启动失败：${String(error?.message || error || "")}`,
        targetVersion: expectedVersion,
        artifactName,
        installMode,
        installerPath,
        helperPath,
        helperLogPath,
        extra: {
          error: String(error?.message || error || "")
        }
      });
      // #region debug-point B:helper-spawn-error
      try {
        dbgV046Emit("B", "main.js:startAppUpdateInstallerHelper", "PowerShell helper spawn error", {
          error: String(error?.message || error || ""),
          helperLogTail: readAppUpdateTextTail(helperLogPath, { maxLines: 8, maxChars: 1500 })
        });
      } catch {}
      // #endregion
    });
    appendAppUpdateHelperLog(helperLogPath, `helper spawned pid=${Math.max(0, Number(child?.pid || 0) || 0)}`);
    // #region debug-point C:helper-log-growth
    try {
      setTimeout(() => {
        try {
          dbgV046Emit("C", "main.js:startAppUpdateInstallerHelper", "helper 启动后首次检查日志增长", {
            helperLogExists: fs.existsSync(helperLogPath),
            helperLogTail: readAppUpdateTextTail(helperLogPath, { maxLines: 10, maxChars: 1800 })
          });
        } catch {}
      }, 350);
      setTimeout(() => {
        try {
          dbgV046Emit("C", "main.js:startAppUpdateInstallerHelper", "helper 启动后第二次检查日志增长", {
            helperLogExists: fs.existsSync(helperLogPath),
            helperLogTail: readAppUpdateTextTail(helperLogPath, { maxLines: 12, maxChars: 2200 }),
            installerExists: !!(installerPath && fs.existsSync(installerPath)),
            restartCandidate: installDir && appExeName ? path.join(installDir, appExeName) : appExePath
          });
        } catch {}
      }, 900);
    } catch {}
    // #endregion
    child.unref();
  } catch (error) {
    appendAppUpdateHelperLog(helperLogPath, `spawn throw=${String(error?.message || error)}`);
    queueAppInstallCloudLog({
      installSessionId,
      releaseId,
      source: "main",
      stage: "helper",
      eventType: "helper.spawn-throw",
      level: "error",
      message: `启动静默安装助手抛异常：${String(error?.message || error || "")}`,
      targetVersion: expectedVersion,
      artifactName,
      installMode,
      installerPath,
      helperPath,
      helperLogPath,
      extra: {
        error: String(error?.message || error || "")
      }
    });
    // #region debug-point B:helper-spawn-throw
    try {
      dbgV046Emit("B", "main.js:startAppUpdateInstallerHelper", "PowerShell helper 启动抛异常", {
        error: String(error?.message || error || ""),
        helperPath,
        helperLogPath
      });
    } catch {}
    // #endregion
    return { ok: false, message: `启动静默安装助手失败：${String(error?.message || error)}`, helperPath, helperLogPath, installDir };
  }
  return { ok: true, helperPath, helperLogPath, installDir };
}

async function startLocalInteractiveInstaller(installerPath, options = {}) {
  const helperDir = getAppUpdateCacheDir();
  ensureDir(helperDir);
  const helperLogPath = path.join(helperDir, "anzhuanggengxin.log");
  const installDir =
    resolvePreferredInstallDir({
      app,
      projectRoot: resolveProjectRoot(),
      isPackaged: app.isPackaged,
      execPath: process.execPath
    }) ||
    (process.execPath ? path.dirname(process.execPath) : "");
  const installSessionId = String(options?.installSessionId || "").trim();
  const releaseId = String(options?.releaseId || "").trim();
  const artifactName = sanitizeAppUpdateFileName(options?.artifactName || path.basename(installerPath || ""), "");
  const expectedVersion = String(options?.expectedVersion || "").trim();
  const currentVersion = String(options?.currentVersion || app.getVersion() || "").trim();
  const exitDelayMs = 0;
  let launchInstallerPath = String(installerPath || "").trim();
  let installerStaged = false;
  let installerStageReason = "";
  try {
    const stagedInstaller = stageInstallerOutsideInstallDir({
      installerPath,
      installDir,
      stagingRoot: getAppUpdateInstallerStagingDir(),
      artifactName
    });
    launchInstallerPath = String(stagedInstaller?.launchPath || installerPath || "").trim();
    installerStaged = !!stagedInstaller?.staged;
    installerStageReason = String(stagedInstaller?.reason || "").trim();
    // #region debug-point B:interactive-installer-entry
    try {
      dbgLocalInstall96Emit("B", "main.js:startLocalInteractiveInstaller", "准备启动交互式安装器", {
        installerPath,
        launchInstallerPath,
        installerStaged,
        installerStageReason,
        installerExists: !!(installerPath && fs.existsSync(installerPath)),
        installerSize: installerPath && fs.existsSync(installerPath) ? fs.statSync(installerPath).size : 0,
        installDir,
        helperLogPath,
        currentVersion,
        expectedVersion,
        processPid: Math.max(0, Number(process.pid || 0) || 0)
      });
    } catch {}
    dbgInstallerCloseMidwayEmit("A", "main.js:startLocalInteractiveInstaller", "准备启动交互式安装器", {
      installerPath,
      launchInstallerPath,
      installerStaged,
      installerStageReason,
      installerExists: !!(installerPath && fs.existsSync(installerPath)),
      installerSize: installerPath && fs.existsSync(installerPath) ? fs.statSync(installerPath).size : 0,
      installDir,
      helperLogPath,
      currentVersion,
      expectedVersion,
      processPid: Math.max(0, Number(process.pid || 0) || 0)
    });
    captureInstallerCloseMidwayProcessSnapshot("A", "main.js:startLocalInteractiveInstaller", "before-shell-open-path", {
      installerPath,
      launchInstallerPath,
      installDir,
      currentVersion,
      expectedVersion
    });
    // #endregion
    appendAppUpdateHelperLog(helperLogPath, `interactive installer open-local-file installer=${installerPath}`);
    appendAppUpdateHelperLog(helperLogPath, `interactive installer launch-path=${launchInstallerPath}`);
    appendAppUpdateHelperLog(helperLogPath, `interactive installer staged=${installerStaged} reason=${installerStageReason}`);
    appendAppUpdateHelperLog(helperLogPath, `interactive installer open-local-file installDir=${installDir}`);
    const openError = await shell.openPath(launchInstallerPath);
    if (String(openError || "").trim()) {
      appendAppUpdateHelperLog(helperLogPath, `interactive installer open-local-file error=${String(openError || "").trim()}`);
      return {
        ok: false,
        message: `启动安装界面失败：${String(openError || "").trim()}`,
        installDir,
        helperLogPath,
        helperPath: "shell.openPath"
      };
    }
    appendAppUpdateHelperLog(helperLogPath, "interactive installer open-local-file ok");
    dbgInstallerCloseMidwayEmit("A", "main.js:startLocalInteractiveInstaller", "交互式安装器已打开，准备关闭旧版软件", {
      installerPath,
      launchInstallerPath,
      installerStaged,
      installerStageReason,
      helperLogPath,
      installDir
    });
    captureInstallerCloseMidwayProcessSnapshot("A", "main.js:startLocalInteractiveInstaller", "after-shell-open-path", {
      installerPath,
      launchInstallerPath,
      installDir
    });
    const closeRes = scheduleGracefulAppClose({
      delayMs: exitDelayMs,
      reason: "manual-local-installer",
      excludeProcessPaths: [installerPath, launchInstallerPath].filter(Boolean)
    });
    dbgInstallerCloseMidwayEmit("B", "main.js:startLocalInteractiveInstaller", "已安排关闭旧版软件", {
      installerPath,
      launchInstallerPath,
      installerStaged,
      installerStageReason,
      helperLogPath,
      installDir,
      closeMode: String(closeRes?.closeMode || "").trim(),
      delayMs: Math.max(0, Number(closeRes?.delayMs || 0) || 0),
      killDelayMs: Math.max(0, Number(closeRes?.killDelayMs || 0) || 0)
    });
    appendAppUpdateHelperLog(
      helperLogPath,
      `interactive installer app-close scheduled delayMs=${Math.max(0, Number(closeRes?.delayMs || 0) || 0)} killDelayMs=${Math.max(
        0,
        Number(closeRes?.killDelayMs || 0) || 0
      )} closeMode=${String(closeRes?.closeMode || "").trim()}`
    );
    // #region debug-point C:interactive-installer-spawned
    try {
      dbgLocalInstall96Emit("C", "main.js:startLocalInteractiveInstaller", "交互式安装启动器已拉起", {
        installerPid: 0,
        killerPid: 0,
        helperLogPath,
        helperPath: "shell.openPath",
        closeMode: String(closeRes?.closeMode || "").trim()
      });
    } catch {}
    try {
      setTimeout(() => {
        try {
          const helperExists = !!(helperLogPath && fs.existsSync(helperLogPath));
          const helperTail = helperExists ? String(fs.readFileSync(helperLogPath, "utf-8") || "").split(/\r?\n/).filter(Boolean).slice(-8).join(" | ") : "";
          dbgLocalInstall96Emit("C", "main.js:startLocalInteractiveInstaller", "启动器拉起后读取 helper 日志", {
            helperLogPath,
            helperExists,
            helperTail
          });
        } catch (peekError) {
          dbgLocalInstall96Emit("C", "main.js:startLocalInteractiveInstaller", "读取 helper 日志失败", {
            helperLogPath,
            error: String(peekError?.message || peekError || "")
          });
        }
      }, 1800);
    } catch {}
    // #endregion
    queueAppInstallCloudLog({
      installSessionId,
      releaseId,
      source: "main",
      stage: "manual-install",
      eventType: "manual.install.ui-launched",
      level: "info",
      message: "已先按打开文件按钮同方式拉起本地安装包界面，随后将优雅关闭当前软件而不影响已打开的安装界面",
      currentVersion,
      targetVersion: expectedVersion,
      artifactName,
      installMode: "local-installer-ui",
      installerPath,
      launchInstallerPath,
      helperLogPath,
      helperPath: "shell.openPath",
      extra: {
        installDir,
        installerStaged,
        installerStageReason,
        installerPid: 0,
        launchMethod: "shell.openPath",
        killerPid: 0,
        exitDelayMs,
        closeMode: String(closeRes?.closeMode || "").trim(),
        killDelayMs: Math.max(0, Number(closeRes?.killDelayMs || 0) || 0)
      }
    });
    return {
      ok: true,
      installDir,
      helperLogPath,
      helperPath: "shell.openPath",
      launchInstallerPath,
      launcherPid: 0,
      killerPid: 0
    };
  } catch (error) {
    appendAppUpdateHelperLog(helperLogPath, `interactive installer error=${String(error?.message || error || "")}`);
    // #region debug-point B:interactive-installer-error
    try {
      dbgLocalInstall96Emit("B", "main.js:startLocalInteractiveInstaller", "交互式安装器启动失败", {
        error: String(error?.message || error || ""),
        helperLogPath,
        installerPath,
        launchInstallerPath
      });
    } catch {}
    // #endregion
    return {
      ok: false,
      message: `启动安装界面失败：${String(error?.message || error || "")}`,
      installDir,
      helperLogPath,
      helperPath: "shell.openPath"
    };
  }
}

async function downloadBinaryDiffInstaller(payload = {}) {
  const patch = payload?.binaryDiffPatch && typeof payload.binaryDiffPatch === "object" ? payload.binaryDiffPatch : null;
  if (!patch) throw new Error("缺少差分包信息");
  const baseDownloadUrl = normalizeCloudUrl(patch.baseDownloadUrl || "");
  const patchUrl = normalizeCloudUrl(patch.patchUrl || "");
  if (!baseDownloadUrl) throw new Error("差分包缺少基线安装包地址");
  if (!patchUrl) throw new Error("差分包缺少下载地址");
  const cacheDir = getAppUpdateCacheDir();
  ensureDir(cacheDir);
  const baseFilePath = path.join(cacheDir, sanitizeAppUpdateFileName(patch.baseArtifactName || path.basename(baseDownloadUrl), "base-installer.exe"));
  const patchFilePath = path.join(cacheDir, sanitizeAppUpdateFileName(patch.patchName || path.basename(patchUrl), "update.patch"));
  const restoredInstallerPath = path.join(
    cacheDir,
    sanitizeAppUpdateFileName(payload?.artifactName || patch.targetArtifactName || `update-${Date.now()}.exe`, `update-${Date.now()}.exe`)
  );
  const totalBytes = normalizeAppUpdatePositiveInt(patch.baseSize) + normalizeAppUpdatePositiveInt(patch.patchSize);
  let receivedBytes = 0;
  const report = (message, downloadKind = "") => {
    updateAppDownloadProgress({
      receivedBytes,
      totalBytes,
      message,
      updateMode: "binary-diff",
      latestVersion: String(payload?.latestVersion || patch.targetVersion || "").trim(),
      artifactName: String(payload?.artifactName || patch.targetArtifactName || "").trim(),
      downloadKind
    });
  };
  report("正在下载差分更新所需的基线安装包...", "base-installer");
  try {
    await downloadToFile(baseDownloadUrl, baseFilePath, {
      onProgress: (received) => {
        receivedBytes = Math.max(receivedBytes, normalizeAppUpdatePositiveInt(received));
        report("正在下载差分更新所需的基线安装包...", "base-installer");
      }
    });
  } catch (e) {
    throw wrapAppUpdateDownloadError(e, {
      label: "差分更新基线安装包",
      url: baseDownloadUrl,
      http404Hint: "差分更新必须先下载旧版本安装包。请确认云端仍然保留基线版本 exe 文件，例如旧版 release 目录下的 exe 安装包。"
    });
  }
  report("正在下载本次版本差分包...", "patch-file");
  try {
    await downloadToFile(patchUrl, patchFilePath, {
      onProgress: (received) => {
        receivedBytes = normalizeAppUpdatePositiveInt(patch.baseSize) + normalizeAppUpdatePositiveInt(received);
        report("正在下载本次版本差分包...", "patch-file");
      }
    });
  } catch (e) {
    throw wrapAppUpdateDownloadError(e, {
      label: "差分包",
      url: patchUrl,
      http404Hint: "请确认本次发布目录中的 patch 文件已经上传到云端，并且 update 云数据里的 patchUrl 指向的是最终发布目录。"
    });
  }
  setAppUpdateState({
    stage: "installing",
    updateMode: "binary-diff",
    installPhase: "merge",
    progress: 56,
    message: "差分包下载完成，正在合并新安装包..."
  });
  applyBinaryDiffPatch({
    baseFilePath,
    patchFilePath,
    outputFilePath: restoredInstallerPath,
    targetSha512: String(patch.targetSha512 || "").trim(),
    targetSize: normalizeAppUpdatePositiveInt(patch.targetSize)
  });
  return restoredInstallerPath;
}

async function downloadFullInstaller(payload = {}) {
  const downloadUrl = normalizeCloudUrl(payload?.downloadUrl || "");
  if (!downloadUrl) throw new Error("缺少安装包下载地址");
  const cacheDir = getAppUpdateCacheDir();
  ensureDir(cacheDir);
  const latestVersion = String(payload?.latestVersion || "").trim();
  const artifactName = String(payload?.artifactName || path.basename(downloadUrl) || "").trim();
  const installerPath = path.join(
    cacheDir,
    sanitizeAppUpdateFileName(artifactName, `update-${Date.now()}.exe`)
  );
  let totalBytes = normalizeAppUpdatePositiveInt(payload?.size);
  const expectedSha512 = String(payload?.sha512 || "").trim();
  const installerTempPath = `${installerPath}.download`;
  try {
    if (installerPath && fs.existsSync(installerPath)) {
      const cachedValidation = validateCachedInstallerFile(installerPath, {
        expectedSize: totalBytes,
        expectedSha512,
        expectedVersion: latestVersion
      });
      if (cachedValidation.ok) {
        updateAppDownloadProgress({
          receivedBytes: cachedValidation.size,
          totalBytes: totalBytes > 0 ? totalBytes : cachedValidation.size,
          message: "检测到 gengxin 中已有安装包，直接使用本地缓存...",
          updateMode: "full-installer",
          latestVersion,
          artifactName,
          downloadKind: "full-installer"
        });
        // #region debug-point A:download-cache-hit
        dbgInstallerCloseBlockedEmit("A", "main.js:downloadFullInstaller", "命中本地缓存安装包，跳过重复下载", {
          downloadUrl,
          installerPath,
          cacheDir,
          cachedSize: cachedValidation.size,
          payloadSize: totalBytes,
          cachedVersion: cachedValidation.version,
          cachedSha512: cachedValidation.sha512,
          latestVersion,
          artifactName,
          expectedSha512
        });
        // #endregion
        return installerPath;
      }
      try {
        fs.unlinkSync(installerPath);
      } catch {}
      // #region debug-point A:download-cache-miss
      dbgInstallerCloseBlockedEmit("A", "main.js:downloadFullInstaller", "本地缓存安装包未命中，继续重新下载", {
        downloadUrl,
        installerPath,
        cacheDir,
        cachedSize: cachedValidation.size,
        payloadSize: totalBytes,
        cachedVersion: cachedValidation.version,
        cachedSha512: cachedValidation.sha512,
        latestVersion,
        artifactName,
        expectedSha512,
        cacheInvalidReason: cachedValidation.reason,
        cacheInvalidErrorMessage: String(cachedValidation.errorMessage || "").trim()
      });
      // #endregion
    }
    if (installerTempPath && fs.existsSync(installerTempPath)) {
      try {
        fs.unlinkSync(installerTempPath);
      } catch {}
    }
  } catch {}
  updateAppDownloadProgress({
    receivedBytes: 0,
    totalBytes,
    message: "正在下载完整安装包...",
    updateMode: "full-installer",
    latestVersion,
    artifactName,
    downloadKind: "full-installer"
  });
  // #region debug-point A:download-full-installer
  dbgInstallerCloseBlockedEmit("A", "main.js:downloadFullInstaller", "开始下载完整安装包", {
    downloadUrl,
    installerPath,
    cacheDir,
    payloadSize: Math.max(0, Number(payload?.size || 0) || 0),
    latestVersion,
    artifactName
  });
  // #endregion
  try {
    await downloadToFile(downloadUrl, installerTempPath, {
      onMeta: (meta = {}) => {
        const headerTotalBytes = Math.max(0, Number(meta?.totalBytes || 0) || 0);
        // #region debug-point A:download-meta
        dbgInstallerCloseBlockedEmit("A", "main.js:downloadFullInstaller:onMeta", "收到安装包响应头", {
          headerTotalBytes,
          totalBytesBefore: totalBytes,
          finalUrl: String(meta?.finalUrl || "").trim()
        });
        // #endregion
        if (totalBytes <= 0 && headerTotalBytes > 0) {
          totalBytes = headerTotalBytes;
          updateAppDownloadProgress({
            receivedBytes: 0,
            totalBytes,
            message: "正在下载完整安装包...",
            updateMode: "full-installer",
            latestVersion,
            artifactName,
            downloadKind: "full-installer"
          });
        }
      },
      onProgress: (received, meta = {}) => {
        const headerTotalBytes = Math.max(0, Number(meta?.totalBytes || 0) || 0);
        if (totalBytes <= 0 && headerTotalBytes > 0) totalBytes = headerTotalBytes;
        updateAppDownloadProgress({
          receivedBytes: received,
          totalBytes,
          message: "正在下载完整安装包...",
          updateMode: "full-installer",
          latestVersion,
          artifactName,
          downloadKind: "full-installer"
        });
      }
    });
    const downloadedValidation = validateCachedInstallerFile(installerTempPath, {
      expectedSize: totalBytes,
      expectedSha512,
      expectedVersion: latestVersion
    });
    if (!downloadedValidation.ok) {
      try {
        fs.unlinkSync(installerTempPath);
      } catch {}
      throw new Error(`下载的安装包校验失败：${String(downloadedValidation.reason || "unknown").trim()}`);
    }
    try {
      if (fs.existsSync(installerPath)) fs.unlinkSync(installerPath);
    } catch {}
    fs.renameSync(installerTempPath, installerPath);
    updateAppDownloadProgress({
      receivedBytes: totalBytes > 0 ? totalBytes : 0,
      totalBytes,
      message: "完整安装包下载完成，正在准备打开安装界面...",
      updateMode: "full-installer",
      latestVersion,
      artifactName,
      downloadKind: "full-installer"
    });
    // #region debug-point A:download-complete
    dbgInstallerCloseBlockedEmit("A", "main.js:downloadFullInstaller", "完整安装包下载完成", {
      installerPath,
      installerExists: !!(installerPath && fs.existsSync(installerPath)),
      installerSize: installerPath && fs.existsSync(installerPath) ? Math.max(0, Number(fs.statSync(installerPath).size || 0) || 0) : 0,
      totalBytes,
      expectedSha512
    });
    // #endregion
  } catch (e) {
    try {
      if (installerTempPath && fs.existsSync(installerTempPath)) fs.unlinkSync(installerTempPath);
    } catch {}
    throw wrapAppUpdateDownloadError(e, {
      label: "完整安装包",
      url: downloadUrl,
      http404Hint: "请确认本次发布目录中的 exe 安装包已经上传到云端，并且 update 云数据里的 downloadUrl 指向的是最终发布目录。"
    });
  }
  return installerPath;
}

function scheduleGracefulAppClose({ delayMs = 0, fallbackDelayMs = 450, reason = "", excludeProcessPaths = [] } = {}) {
  const safeDelayMs = Math.max(0, Number(delayMs || 0) || 0);
  const safeFallbackDelayMs = Math.max(0, Number(fallbackDelayMs || 0) || 0);
  const appPid = Math.max(0, Number(process.pid || 0) || 0);
  const appExePath = String(process.execPath || "").trim();
  const appExeName = sanitizeAppUpdateFileName(path.basename(String(process.execPath || "").trim() || ""), "");
  const appInstallDir = appExePath ? path.dirname(appExePath) : "";
  const normalizedExcludeProcessPaths = Array.isArray(excludeProcessPaths)
    ? excludeProcessPaths.map((item) => String(item || "").trim()).filter(Boolean)
    : [];
  const killerRounds = 14;
  const killerGapMs = 350;
  const killDelayMs = safeDelayMs;
  // #region debug-point B:schedule-close
  dbgInstallerCloseBlockedEmit("B", "main.js:scheduleGracefulAppClose", "计划关闭当前软件", {
    reason: String(reason || "").trim(),
    appPid,
    appExeName,
    appExePath,
    appInstallDir,
    execPath: String(process.execPath || "").trim(),
    safeDelayMs,
    safeFallbackDelayMs,
    killDelayMs,
    killerRounds,
    killerGapMs,
    excludeProcessPaths: normalizedExcludeProcessPaths
  });
  captureInstallerCloseBlockedProcessSnapshot("B", "main.js:scheduleGracefulAppClose", "before-close-scheduled", {
    reason: String(reason || "").trim(),
    appPid,
    appExeName
  });
  dbgInstallerCloseMidwayEmit("B", "main.js:scheduleGracefulAppClose", "计划关闭当前软件", {
    reason: String(reason || "").trim(),
    appPid,
    appExeName,
    appExePath,
    appInstallDir,
    safeDelayMs,
    safeFallbackDelayMs,
    killDelayMs,
    killerRounds,
    killerGapMs,
    excludeProcessPaths: normalizedExcludeProcessPaths
  });
  captureInstallerCloseMidwayProcessSnapshot("B", "main.js:scheduleGracefulAppClose", "before-close-scheduled", {
    reason: String(reason || "").trim(),
    appPid,
    appExeName,
    appExePath
  });
  // #endregion
  try {
    const powerShellPath = resolvePowerShellExePath();
    const psAppExeName = escapePowerShellSingleQuotedText(appExeName);
    const psAppExePath = escapePowerShellSingleQuotedText(appExePath);
    const psAppInstallDir = escapePowerShellSingleQuotedText(appInstallDir);
    const psExcludeArray = normalizedExcludeProcessPaths
      .map((item) => `'${escapePowerShellSingleQuotedText(item)}'.ToLowerInvariant()`)
      .join(", ");
    const killCommand = [
      "$ErrorActionPreference = 'SilentlyContinue'",
      `$appPid = ${appPid}`,
      `$appExeName = '${psAppExeName}'`,
      `$appExePath = '${psAppExePath}'`,
      `$appInstallDir = '${psAppInstallDir}'`,
      `$excludePaths = @(${psExcludeArray})`,
      "$killNames = @('crashpad_handler.exe','elevate.exe','un_a.exe')",
      `$killerGapMs = ${killerGapMs}`,
      `$killerRounds = ${killerRounds}`,
      "function Stop-AppTargets() {",
      "  try {",
      "    $targets = @(Get-CimInstance Win32_Process | Where-Object {",
      "      $procId = [int]($_.ProcessId)",
      "      if ($procId -le 0 -or $procId -eq $PID) { return $false }",
      "      $name = [string]($_.Name)",
      "      $exe = [string]($_.ExecutablePath)",
      "      $cmd = [string]($_.CommandLine)",
      "      $exeLower = $exe.ToLowerInvariant()",
      "      $cmdLower = $cmd.ToLowerInvariant()",
      "      if ($excludePaths.Count -gt 0 -and $exeLower -and ($excludePaths -contains $exeLower)) { return $false }",
      "      if ($appPid -gt 0 -and $procId -eq $appPid) { return $true }",
      "      if ($appExePath -and $exeLower -and $exeLower -eq $appExePath.ToLowerInvariant()) { return $true }",
      "      if ($appExeName -and $name -and $name.Equals($appExeName, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }",
      "      if ($killNames -contains $name.ToLowerInvariant()) {",
      "        if ($appInstallDir -and $exeLower -and $exeLower.StartsWith($appInstallDir.ToLowerInvariant())) { return $true }",
      "        if ($appExePath -and $cmdLower -and $cmdLower.Contains($appExePath.ToLowerInvariant())) { return $true }",
      "      }",
      "      if ($name -and $name.Equals('crashpad_handler.exe', [System.StringComparison]::OrdinalIgnoreCase)) {",
      "        if ($_.ParentProcessId -eq $appPid) { return $true }",
      "        if ($appExePath -and $cmdLower -and $cmdLower.Contains($appExePath.ToLowerInvariant())) { return $true }",
      "        if ($appInstallDir -and $exeLower -and $exeLower.StartsWith($appInstallDir.ToLowerInvariant())) { return $true }",
      "      }",
      "      return $false",
      "    })",
      "    foreach ($target in $targets) {",
      "      try { Stop-Process -Id ([int]$target.ProcessId) -Force -ErrorAction SilentlyContinue } catch {}",
      "    }",
      "    if ($appExeName) { try { taskkill /IM $appExeName /F | Out-Null } catch {} }",
      "    foreach ($name in $killNames) { try { taskkill /IM $name /F | Out-Null } catch {} }",
      "  } catch {}",
      "}",
      `Start-Sleep -Milliseconds ${killDelayMs}`,
      "for ($i = 0; $i -lt $killerRounds; $i++) {",
      "  Stop-AppTargets",
      "  Start-Sleep -Milliseconds $killerGapMs",
      "}"
    ]
      .filter(Boolean)
      .join("; ");
    // #region debug-point C:taskkill-scheduled
    dbgInstallerCloseBlockedEmit("C", "main.js:scheduleGracefulAppClose", "已安排延迟 taskkill", {
      powerShellPath,
      killCommand,
      appPid,
      appExeName,
      appExePath,
      excludeProcessPaths: normalizedExcludeProcessPaths
    });
    dbgInstallerCloseMidwayEmit("C", "main.js:scheduleGracefulAppClose", "已安排关闭软件强杀脚本", {
      powerShellPath,
      appPid,
      appExeName,
      appExePath,
      excludeProcessPaths: normalizedExcludeProcessPaths,
      killerRounds,
      killerGapMs
    });
    // #endregion
    const killerChild = spawn(powerShellPath, ["-NoLogo", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", killCommand], {
      detached: true,
      windowsHide: true,
      stdio: "ignore"
    });
    killerChild.unref();
    // #region debug-point C:taskkill-child
    dbgInstallerCloseBlockedEmit("C", "main.js:scheduleGracefulAppClose", "延迟 taskkill 进程已启动", {
      killerPid: Math.max(0, Number(killerChild?.pid || 0) || 0),
      powerShellPath,
      killerRounds,
      killerGapMs
    });
    dbgInstallerCloseMidwayEmit("C", "main.js:scheduleGracefulAppClose", "关闭软件强杀脚本已启动", {
      killerPid: Math.max(0, Number(killerChild?.pid || 0) || 0),
      powerShellPath,
      killerRounds,
      killerGapMs
    });
    // #endregion
  } catch {}
  setTimeout(() => {
    // #region debug-point B:before-app-quit
    dbgInstallerCloseBlockedEmit("B", "main.js:scheduleGracefulAppClose", "开始执行 app.quit 前置动作", {
      reason: String(reason || "").trim(),
      appPid,
      appExeName
    });
    captureInstallerCloseBlockedProcessSnapshot("B", "main.js:scheduleGracefulAppClose", "before-app-quit", {
      reason: String(reason || "").trim(),
      appPid,
      appExeName
    });
    dbgInstallerCloseMidwayEmit("B", "main.js:scheduleGracefulAppClose", "开始执行 app.quit 前置动作", {
      reason: String(reason || "").trim(),
      appPid,
      appExeName
    });
    captureInstallerCloseMidwayProcessSnapshot("B", "main.js:scheduleGracefulAppClose", "before-app-quit", {
      reason: String(reason || "").trim(),
      appPid,
      appExeName
    });
    // #endregion
    try {
      BrowserWindow.getAllWindows().forEach((win) => {
        try {
          win.destroy();
        } catch {}
      });
    } catch {}
    try {
      app.releaseSingleInstanceLock();
    } catch {}
    try {
      app.quit();
    } catch {}
    setTimeout(() => {
      // #region debug-point C:before-app-exit-fallback
      dbgInstallerCloseBlockedEmit("C", "main.js:scheduleGracefulAppClose", "即将执行 app.exit 兜底", {
        reason: String(reason || "").trim(),
        appPid,
        appExeName
      });
      captureInstallerCloseBlockedProcessSnapshot("C", "main.js:scheduleGracefulAppClose", "before-app-exit-fallback", {
        reason: String(reason || "").trim(),
        appPid,
        appExeName
      });
      dbgInstallerCloseMidwayEmit("C", "main.js:scheduleGracefulAppClose", "即将执行 app.exit 兜底", {
        reason: String(reason || "").trim(),
        appPid,
        appExeName
      });
      captureInstallerCloseMidwayProcessSnapshot("C", "main.js:scheduleGracefulAppClose", "before-app-exit-fallback", {
        reason: String(reason || "").trim(),
        appPid,
        appExeName
      });
      // #endregion
      try {
        app.exit(0);
      } catch {}
    }, safeFallbackDelayMs);
  }, safeDelayMs);
  return {
    ok: true,
    reason: String(reason || "").trim(),
    closeMode: "app.quit+force-kill-loop",
    delayMs: safeDelayMs,
    fallbackDelayMs: safeFallbackDelayMs,
    killDelayMs,
    killerRounds,
    killerGapMs
  };
}

ipcMain.handle("appUpdate:readConfig", async () => {
  return {
    ok: true,
    config: readAppUpdateConfigFromFile(),
    currentVersion: String(app.getVersion() || "0.0.0"),
    state: _appUpdateState
  };
});

ipcMain.handle("appUpdate:writeConfig", async (_event, payload) => {
  const current = readAppUpdateConfigFromFile();
  const manualManifestUrl = normalizeCloudUrl(payload?.config?.manifestUrl || payload?.config?.manualManifestUrl || "");
  const autoCheckOnLaunch = payload?.config?.autoCheckOnLaunch !== false;
  const res = writeAppUpdateConfigToFile({
    ...current,
    manualManifestUrl,
    autoCheckOnLaunch
  });
  return {
    ...res,
    currentVersion: String(app.getVersion() || "0.0.0"),
    state: _appUpdateState
  };
});

ipcMain.handle("appUpdate:getState", async () => ({ ok: true, state: _appUpdateState }));

ipcMain.handle("openClaw:readConfig", async () => {
  return getOpenClawServiceState();
});

ipcMain.handle("openClaw:writeConfig", async (_event, payload) => {
  const res = writeOpenClawConfigToFile({
    enabled: payload?.config?.enabled !== false
  });
  if (res?.ok) {
    await syncOpenClawToolServiceGate().catch(() => {});
  }
  const stateRes = getOpenClawServiceState();
  return {
    ...res,
    ...stateRes
  };
});

ipcMain.handle("openClaw:getState", async () => {
  return getOpenClawServiceState();
});

ipcMain.handle("openClaw:generateSkillPackage", handleOpenClawGenerateSkillPackageRequest);

ipcMain.handle("appUpdate:getDiagnostics", async () => {
  try {
    return buildAppUpdateDiagnostics();
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

ipcMain.handle("appUpdate:syncFromCloud", async (_event, payload) => {
  try {
    return await syncAppUpdateFromCloud(payload || {});
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

ipcMain.handle("appUpdate:check", async (_event, payload) => {
  try {
    let config = readAppUpdateConfigFromFile();
    const forceSync = payload?.forceSync === true;
    const allowCachedOnSyncFailure = payload?.allowCachedOnSyncFailure === true;
    if (forceSync || !config?.latestVersion) {
      const syncRes = await syncAppUpdateFromCloud({
        scene: payload?.scene || config?.scene || "desktop",
        token: payload?.token || ""
      });
      if (!syncRes?.ok) {
        if (!allowCachedOnSyncFailure || !config?.latestVersion) return syncRes;
      } else {
        config = syncRes.config;
      }
    }
    return checkAppUpdateFromConfig(config);
  } catch (e) {
    const message = String(e?.message || e || "");
    return {
      ok: false,
      message: message === "timeout" ? "检查更新超时，请确认云端更新数据可正常访问后重试。" : message || "检查更新失败。"
    };
  }
});

ipcMain.handle("appUpdate:downloadAndInstall", async (_event, payload) => {
  try {
    if (!app.isPackaged) {
      return {
        ok: false,
        message: `当前是调试运行环境，不支持执行自动更新安装。请使用已安装的正式版本测试；当前运行 exe：${String(process.execPath || "").trim()}`
      };
    }
    persistInstallDirRecord({
      app,
      projectRoot: resolveProjectRoot(),
      isPackaged: app.isPackaged,
      execPath: process.execPath,
      appVersion: String(app.getVersion() || ""),
      note: "开始自动更新前再次校验安装目录"
    });
    const currentConfig = readAppUpdateConfigFromFile();
    const latestVersion = String(payload?.latestVersion || currentConfig?.latestVersion || "").trim();
    const artifactName = sanitizeAppUpdateFileName(payload?.artifactName || "", "");
    const installSessionId = createInstallLogSessionId("install");
    const installMode = "full-installer";
    // #region debug-point E:download-install-entry
    try {
      dbgV046Emit("E", "main.js:appUpdate:downloadAndInstall", "进入下载并安装流程", {
        currentVersion: String(app.getVersion() || "").trim(),
        latestVersion,
        hasBinaryDiffPatch: false,
        artifactName,
        payloadDownloadUrl: String(payload?.downloadUrl || "").trim()
      });
    } catch {}
    // #endregion
    queueAppInstallCloudLog({
      installSessionId,
      releaseId: String(currentConfig?.releaseId || payload?.releaseId || "").trim(),
      source: "main",
      stage: "download",
      eventType: "download.install.entry",
      level: "info",
      message: "进入自动更新下载并安装流程，将仅下载完整安装包并执行覆盖安装",
      targetVersion: latestVersion,
      artifactName,
      installMode,
      extra: {
        hasBinaryDiffPatch: false,
        downloadUrl: String(payload?.downloadUrl || "").trim()
      }
    });
    const installerPath = await downloadFullInstaller(payload || {});
    setAppUpdateState({
      stage: "installing",
      updateMode: "full-installer",
      installPhase: "prepare-installer",
      progress: 72,
      latestVersion,
      artifactName,
      installerPath,
      message: "完整安装包已下载完成，正在打开安装界面..."
    });
    // #region debug-point E:installer-ready
    try {
      dbgV046Emit("E", "main.js:appUpdate:downloadAndInstall", "安装包已准备完成，准备移交 helper", {
        installerPath,
        installerExists: !!(installerPath && fs.existsSync(installerPath)),
        installerSize: installerPath && fs.existsSync(installerPath) ? fs.statSync(installerPath).size : 0,
        mode: "full-installer"
      });
    } catch {}
    // #endregion
    // #region debug-point E:auto-update-reuse-manual-installer
    dbgInstallerCloseBlockedEmit("E", "main.js:appUpdate:downloadAndInstall", "自动更新已切换为复用安装新版本链路", {
      installerPath,
      installerExists: !!(installerPath && fs.existsSync(installerPath)),
      installerSize: installerPath && fs.existsSync(installerPath) ? Math.max(0, Number(fs.statSync(installerPath).size || 0) || 0) : 0,
      latestVersion,
      artifactName,
      mode: "download-then-startLocalInteractiveInstaller"
    });
    captureInstallerCloseBlockedProcessSnapshot("E", "main.js:appUpdate:downloadAndInstall", "before-start-local-interactive-installer", {
      installerPath,
      latestVersion,
      artifactName
    });
    dbgInstallerCloseMidwayEmit("D", "main.js:appUpdate:downloadAndInstall", "自动更新准备复用安装新版本链路", {
      installerPath,
      installerExists: !!(installerPath && fs.existsSync(installerPath)),
      installerSize: installerPath && fs.existsSync(installerPath) ? Math.max(0, Number(fs.statSync(installerPath).size || 0) || 0) : 0,
      latestVersion,
      artifactName,
      installSessionId
    });
    captureInstallerCloseMidwayProcessSnapshot("D", "main.js:appUpdate:downloadAndInstall", "before-start-local-interactive-installer", {
      installerPath,
      latestVersion,
      artifactName,
      installSessionId
    });
    // #endregion
    const helperRes = await startLocalInteractiveInstaller(installerPath, {
      expectedVersion: latestVersion,
      installSessionId,
      releaseId: String(currentConfig?.releaseId || payload?.releaseId || "").trim(),
      artifactName,
      currentVersion: String(app.getVersion() || "").trim()
    });
    if (!helperRes?.ok) {
      throw new Error(String(helperRes?.message || "自动更新启动安装新版本流程失败。"));
    }
    queueAppInstallCloudLog({
      installSessionId,
      releaseId: String(currentConfig?.releaseId || payload?.releaseId || "").trim(),
      source: "main",
      stage: "install",
      eventType: "full-installer.opened",
      level: "info",
      message: "完整安装包已下载到 gengxin，并已按“安装新版本”同一链路启动安装界面和关闭软件",
      targetVersion: latestVersion,
      artifactName,
      installMode,
      installerPath,
      extra: {
        cacheDir: getAppUpdateCacheDir(),
        installDir: String(helperRes?.installDir || "").trim()
      },
      helperPath: String(helperRes?.helperPath || "").trim(),
      helperLogPath: String(helperRes?.helperLogPath || "").trim()
    });
    setAppUpdateState({
      stage: "installing",
      updateMode: "full-installer",
      installPhase: "handoff",
      progress: 96,
      latestVersion,
      artifactName,
      installerPath,
      message: "完整安装包已下载完成，并已按“安装新版本”同流程启动安装界面和关闭软件。"
    });
    return {
      ok: true,
      mode: "full-installer-via-local-installer-flow",
      state: _appUpdateState,
      installerPath,
      installDir: String(helperRes?.installDir || "").trim(),
      helperPath: helperRes?.helperPath || "",
      helperLogPath: helperRes?.helperLogPath || ""
    };
  } catch (e) {
    const message = String(e?.message || e || "启动更新失败");
    setAppUpdateState({
      stage: "error",
      progress: 0,
      errorMessage: message,
      message
    });
    return { ok: false, message, state: _appUpdateState };
  }
});

