ipcMain.handle("appUpdate:installFromDirectory", async (_event, payload) => {
  try {
    if (!app.isPackaged) {
      return {
        ok: false,
        message: `当前是调试运行环境，不支持执行“安装新版本”。请使用已安装的正式版本测试；当前运行 exe：${String(process.execPath || "").trim()}`
      };
    }
    const localPath = String(payload?.localPath || payload?.filePath || payload?.directoryPath || "").trim();
    // #region debug-point D:install-from-directory-entry
    try {
      dbgLocalInstall96Emit("D", "main.js:appUpdate:installFromDirectory", "进入本地安装新版本入口", {
        localPath,
        currentVersion: String(app.getVersion() || "").trim(),
        execPath: String(process.execPath || "").trim(),
        isPackaged: app.isPackaged === true
      });
    } catch {}
    // #endregion
    const resolvedInstaller = resolveLocalInstallerFromPath(localPath);
    if (!resolvedInstaller?.ok) {
      return { ok: false, message: String(resolvedInstaller?.message || "未找到可安装的新版本安装包。") };
    }
    persistInstallDirRecord({
      app,
      projectRoot: resolveProjectRoot(),
      isPackaged: app.isPackaged,
      execPath: process.execPath,
      appVersion: String(app.getVersion() || ""),
      note: "开始本地安装新版本前再次校验安装目录"
    });
    const installSessionId = createInstallLogSessionId("manual-install");
    const installerPath = String(resolvedInstaller.installerPath || "").trim();
    const artifactName = sanitizeAppUpdateFileName(resolvedInstaller.installerName || path.basename(installerPath || ""), "");
    const expectedVersion = String(payload?.expectedVersion || resolvedInstaller.expectedVersion || "").trim();
    const selectedPath = localPath;
    setAppUpdateState({
      stage: "installing",
      updateMode: "local-installer",
      installPhase: "prepare-installer",
      progress: 36,
      latestVersion: expectedVersion,
      artifactName,
      installerPath,
      selectedPath,
      message: "已找到本地安装包，正在准备覆盖当前软件目录..."
    });
    queueAppInstallCloudLog({
      installSessionId,
      releaseId: "manual-local-installer",
      source: "main",
      stage: "manual-install",
      eventType: "manual.install.selected",
      level: "info",
      message: "已选择本地安装包，准备执行覆盖安装",
      targetVersion: expectedVersion,
      artifactName,
      installMode: "local-installer",
      installerPath,
      extra: {
        selectedPath,
        candidateCount: Array.isArray(resolvedInstaller?.candidates) ? resolvedInstaller.candidates.length : 0
      }
    });
    const helperRes = await startLocalInteractiveInstaller(installerPath, {
      expectedVersion,
      installSessionId,
      releaseId: "manual-local-installer",
      artifactName,
      currentVersion: String(app.getVersion() || "").trim()
    });
    if (!helperRes?.ok) {
      const message = String(helperRes?.message || "启动本地安装失败。");
      setAppUpdateState({
        stage: "error",
        progress: 0,
        updateMode: "local-installer",
        latestVersion: expectedVersion,
        artifactName,
        errorMessage: message,
        message
      });
      return { ok: false, message, state: _appUpdateState };
    }
    // #region debug-point D:install-from-directory-handoff
    try {
      dbgLocalInstall96Emit("D", "main.js:appUpdate:installFromDirectory", "本地安装入口已进入 96% 交接态", {
        selectedPath,
        installerPath,
        helperPath: String(helperRes?.helperPath || "").trim(),
        helperLogPath: String(helperRes?.helperLogPath || "").trim(),
        latestVersion: expectedVersion
      });
    } catch {}
    // #endregion
    setAppUpdateState({
      stage: "installing",
      updateMode: "local-installer",
      installPhase: "handoff",
      progress: 96,
      latestVersion: expectedVersion,
      artifactName,
      installerPath,
      selectedPath,
      message: "安装界面正在打开，软件即将自动关闭并进入新版本安装流程。"
    });
    queueAppInstallCloudLog({
      installSessionId,
      releaseId: "manual-local-installer",
      source: "main",
      stage: "manual-install",
      eventType: "manual.install.ui-started",
      level: "info",
      message: "本地安装包界面已启动，软件即将自动关闭并进入安装界面",
      targetVersion: expectedVersion,
      artifactName,
      installMode: "local-installer-ui",
      installerPath,
      helperPath: String(helperRes?.helperPath || "").trim(),
      helperLogPath: String(helperRes?.helperLogPath || "").trim(),
      extra: {
        selectedPath,
        installDir: String(helperRes?.installDir || "").trim()
      }
    });
    return {
      ok: true,
      mode: "local-installer-ui",
      selectedPath,
      installerPath,
      artifactName,
      latestVersion: expectedVersion,
      helperPath: helperRes?.helperPath || "",
      helperLogPath: helperRes?.helperLogPath || "",
      state: _appUpdateState
    };
  } catch (e) {
    const message = String(e?.message || e || "启动本地安装失败。");
    setAppUpdateState({
      stage: "error",
      progress: 0,
      updateMode: "local-installer",
      errorMessage: message,
      message
    });
    return { ok: false, message, state: _appUpdateState };
  }
});

ipcMain.handle("appUpdate:openLocalFile", async (_event, payload) => {
  try {
    const localPath = String(payload?.localPath || payload?.filePath || "").trim();
    const resolvedInstaller = resolveLocalInstallerFromPath(localPath);
    if (!resolvedInstaller?.ok) {
      return { ok: false, message: String(resolvedInstaller?.message || "请选择可直接打开的 EXE 文件。") };
    }
    const installerPath = String(resolvedInstaller?.installerPath || "").trim();
    if (!installerPath) {
      return { ok: false, message: "未读取到可直接打开的 EXE 文件路径。" };
    }
    const openError = await shell.openPath(installerPath);
    if (String(openError || "").trim()) {
      return { ok: false, message: String(openError || "打开 EXE 文件失败。") };
    }
    return {
      ok: true,
      openedPath: installerPath,
      installerName: String(resolvedInstaller?.installerName || path.basename(installerPath || "")).trim()
    };
  } catch (e) {
    return { ok: false, message: String(e?.message || e || "打开 EXE 文件失败。") };
  }
});

