ipcMain.handle("cloudAuth:login", async (_event, payload) => {
  try {
    const body = payload?.body && typeof payload.body === "object" ? payload.body : {};
    const url = buildCloudObjectUrlWithQuery(payload?.url, body);
    if (!url) return { ok: false, errMsg: "未配置云端登录接口URL" };
    const token = String(payload?.token || "").trim();
    const { statusCode, data, raw } = await requestJson(url, {
      timeoutMs: 20000,
      headers: buildCloudHeaders(token),
      body: {}
    });
    if (statusCode < 200 || statusCode >= 300) return { ok: false, errMsg: `云端请求失败：http ${statusCode}`, raw };
    return data && typeof data === "object" ? data : { ok: false, errMsg: "云端返回异常", raw };
  } catch (e) {
    return { ok: false, errMsg: String(e?.message || e) };
  }
});

