ipcMain.handle("domain:write", async (_event, payload) => {
  const domain = normalizeCloudUrl(payload?.domain);
  if (!domain) return { ok: false, message: "域名格式不正确" };
  return writeCloudDomainToFile(domain);
});

ipcMain.handle("domain:syncFromCloud", async (_event, payload) => {
  try {
    const scene = String(payload?.scene || "desktop").trim() || "desktop";
    const domain = readCloudDomainFromFile();
    const url = buildCloudObjectUrlWithQuery(`${domain}/qd-yumingguanli/getLatest`, { scene });
    const token = String(payload?.token || "").trim();
    const { statusCode, data, raw } = await requestJson(url, {
      timeoutMs: 20000,
      headers: buildCloudHeaders(token),
      body: {}
    });
    if (statusCode < 200 || statusCode >= 300) return { ok: false, message: `云端请求失败：http ${statusCode}`, raw, domain };
    if (!data || typeof data !== "object") return { ok: false, message: "云端返回异常", raw, domain };
    if (data.errCode) return { ok: false, message: String(data.errMsg || "获取域名失败"), data, domain };
    const nextDomain = normalizeCloudUrl(data.domain);
    if (!nextDomain) return { ok: false, message: "云端返回域名格式不正确", data, domain };
    const writeRes = writeCloudDomainToFile(nextDomain);
    return { ok: true, domain: writeRes.domain || nextDomain };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

