async function handleLlmRewriteRequest(event, payload) {
  const taskId = String(payload?.taskId || "").trim() || `llm_${Date.now()}_${crypto.randomBytes(3).toString("hex")}`;
  const content = String(payload?.content || "").trim();
  const prompt = String(payload?.prompt || "").trim();
  const count = Number(payload?.count || 0) || 300;
  const model = String(payload?.model || "").trim();
  const endpoint = String(payload?.endpoint || "").trim();
  const apiKey = String(payload?.apiKey || "").trim();
  const systemPrompt = String(payload?.systemPrompt || "").trim();
  if (!content) return { ok: false, message: "empty content" };
  if (!prompt) return { ok: false, message: "empty prompt" };

  const resolvedPrompt = prompt.replaceAll("{{count}}", String(count));
  const task = { taskId, controller: new AbortController(), canceled: false, tool: "copy.rewrite", status: "running", progress: 5, message: "开始改写" };
  const _llmTasks = global.__ipfactoryLlmTasks || (global.__ipfactoryLlmTasks = new Map());
  _llmTasks.set(taskId, task);
  updateLiveTaskState(task);
  try {
    const out = await tryRewriteViaTokenhub({
      content,
      prompt: resolvedPrompt,
      apiKey,
      model,
      endpoint,
      systemPrompt,
      signal: task.controller.signal
    });
    updateLiveTaskState(task, { status: "completed", progress: 100, message: "改写完成" });
    return { ok: true, content: out, taskId };
  } catch (e) {
    const msg = String(e?.message || e);
    if (task.canceled === true || msg === "canceled" || /canceled/i.test(msg)) {
      updateLiveTaskState(task, { status: "canceled", progress: Math.max(0, Number(task.progress || 0) || 0), message: "已取消" });
      return { ok: false, taskId, canceled: true, message: "canceled" };
    }
    updateLiveTaskState(task, { status: "failed", message: msg || "改写失败" });
    return { ok: false, taskId, message: msg };
  } finally {
    _llmTasks.delete(taskId);
  }
}

ipcMain.handle("llm:rewrite", handleLlmRewriteRequest);

ipcMain.handle("llm:cancel", async (_event, payload) => {
  try {
    const taskId = String(payload?.taskId || "").trim();
    if (!taskId) return { ok: false, message: "empty taskId" };
    const _llmTasks = global.__ipfactoryLlmTasks || (global.__ipfactoryLlmTasks = new Map());
    const task = _llmTasks.get(taskId);
    if (!task) return { ok: false, message: "task not found" };
    task.canceled = true;
    try {
      task.controller?.abort?.();
    } catch {}
    return { ok: true };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

