ipcMain.handle("ipbrain:collect", async (event, payload) => {
  const input = String(payload?.input || "").trim();
  if (!input) return { ok: false, message: "empty input" };

  const headers = {
    "User-Agent":
      "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36",
    Accept: "application/json,text/html,*/*",
    "Accept-Encoding": "identity"
  };

  try {
    const rawUrl = extractDouyinUrl(input);
    if (!rawUrl) return { ok: false, message: "no douyin url found" };
    const resolved = await resolveRedirects(rawUrl, { headers });

    const directSecUid = extractDouyinSecUid(resolved);
    let secUid = directSecUid;
    let nickname = "";
    let titles = [];

    if (!secUid) {
      const awemeId = extractAwemeId(resolved);
      if (!awemeId) return { ok: false, message: "no aweme id" };
      const apiUrl = `https://www.iesdouyin.com/web/api/v2/aweme/iteminfo/?item_ids=${awemeId}`;
      const info = await fetchJson(apiUrl, { headers });
      const item = info?.item_list?.[0] || info?.itemList?.[0] || null;
      nickname = String(item?.author?.nickname || item?.authorInfo?.nickname || "").trim();
      secUid = String(item?.author?.sec_uid || item?.author?.secUid || "").trim();
      const singleTitle = String(item?.desc || "").replace(/\s+/g, " ").trim();
      if (singleTitle) titles = [singleTitle];
    }

    if (!secUid) return { ok: false, message: "no sec_uid" };

    const userInfo = await fetchIesDouyinUserInfo(secUid, { headers });
    if (!nickname) nickname = String(userInfo?.nickname || userInfo?.unique_id || userInfo?.short_id || "").trim();
    if (!nickname) nickname = "抖音账号";

    const latest = await fetchIesDouyinUserLatestTitles(secUid, { count: 5, headers });
    let picked = latest.length ? latest : titles;
    if (!picked.length) {
      const pageUrl = `https://www.douyin.com/user/${encodeURIComponent(secUid)}`;
      try {
        const scraped = await scrapeDouyinUserViaBrowserWindow(pageUrl, { timeoutMs: 25000, userAgent: headers["User-Agent"] });
        const scrapedTitles = Array.isArray(scraped?.titles) ? scraped.titles.map((x) => String(x || "").trim()).filter(Boolean) : [];
        if (scrapedTitles.length) picked = scrapedTitles.slice(0, 5);
        const scrapedName = String(scraped?.accountName || "").trim();
        if (scrapedName && (!nickname || nickname === "抖音账号")) nickname = scrapedName;
      } catch {}
    }
    if (!picked.length) return { ok: false, message: "empty titles" };
    return { ok: true, sourceUrl: resolved, secUid, accountName: nickname, titles: picked.slice(0, 5) };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

