function resolveHomeCloneVoiceJsonPath() {
  let targetPath = path.join(resolveProjectRoot(), "electron通用模板", "shouye", "kelongyinpin", "kelongyinpin.json");
  const scopedUserId = getCurrentRuntimeUserId();
  if (scopedUserId) {
    targetPath = path.join(resolveUserRuntimeDataRoot(scopedUserId), "shouye", "kelongyinpin", "kelongyinpin.json");
  } else if (app.isPackaged && !fs.existsSync(path.dirname(targetPath))) {
    targetPath = path.join(resolveRuntimeDataRoot(), "shouye", "kelongyinpin", "kelongyinpin.json");
  }
  ensureDir(path.dirname(targetPath));
  if (!fs.existsSync(targetPath)) fs.writeFileSync(targetPath, JSON.stringify({ items: [], updatedAt: Date.now() }, null, 2), "utf-8");
  return targetPath;
}

function readHomeCloneVoiceItems() {
  try {
    const filePath = resolveHomeCloneVoiceJsonPath();
    const raw = String(fs.readFileSync(filePath, "utf-8") || "").trim();
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) return parsed;
    return Array.isArray(parsed?.items) ? parsed.items : [];
  } catch {
    return [];
  }
}

function writeHomeCloneVoiceItems(items) {
  const filePath = resolveHomeCloneVoiceJsonPath();
  fs.writeFileSync(filePath, JSON.stringify({ items: Array.isArray(items) ? items : [], updatedAt: Date.now() }, null, 2), "utf-8");
  return filePath;
}

function buildDashscopeVoicePrefix(name) {
  const normalized = String(name || "")
    .replace(/[^0-9a-z]/gi, "")
    .slice(0, 10);
  if (normalized) return normalized;
  return `vc${crypto.randomBytes(3).toString("hex").slice(0, 8)}`;
}

function pickTtsBundle() {
  const bundles = scanProjectBundles();
  return bundles.find((b) => b.type === "TTS") || null;
}

function toWavFromAny(ffmpegExe, inputPath, outWavPath, { cwd, isCanceled, task } = {}) {
  return runFfmpeg(ffmpegExe, ["-y", "-i", inputPath, "-ac", "1", "-ar", "16000", "-c:a", "pcm_s16le", outWavPath], {
    cwd,
    isCanceled,
    task
  });
}

function resolveDashscopeTtsLanguageHint(language) {
  const raw = String(language || "").trim().toLowerCase();
  if (!raw) return "";
  if (raw.includes("中文")) return "zh";
  if (raw.includes("普通话")) return "zh";
  if (raw.includes("英文")) return "en";
  if (raw.includes("english")) return "en";
  if (raw.includes("日语")) return "ja";
  if (raw.includes("日文")) return "ja";
  if (raw.includes("韩语")) return "ko";
  if (raw.includes("法语")) return "fr";
  if (raw.includes("德语")) return "de";
  if (raw.includes("俄语")) return "ru";
  if (raw.includes("葡萄牙")) return "pt";
  if (raw.includes("泰语")) return "th";
  if (raw.includes("印尼")) return "id";
  if (raw === "zh" || raw === "en" || raw === "ja" || raw === "ko" || raw === "fr" || raw === "de" || raw === "ru" || raw === "pt" || raw === "th" || raw === "id") return raw;
  return "";
}

async function synthesizeSpeechByDashscope({ event, task, taskId, voiceId, text, speed, emotion, language, modelChoice }) {
  const endpoint = String(modelChoice?.endpoint || "https://dashscope.aliyuncs.com/api/v1/services/audio/tts/SpeechSynthesizer").trim();
  const apiKey = String(modelChoice?.apiKey || "").trim();
  const model = String(modelChoice?.modelId || modelChoice?.model || "").trim();
  const voice = String(modelChoice?.voice || modelChoice?.aliyunVoiceId || "").trim();
  if (!apiKey) return { ok: false, message: "当前云端 TTS 未匹配到可用的 API Key。" };
  if (!model) return { ok: false, message: "当前云端 TTS 缺少模型标识。" };
  if (!voice) return { ok: false, message: "当前云端 CosyVoice 缺少可用音色，请改用系统音色后重试。" };

  const ttsOutDir = resolveTtsOutputRoot();
  ensureDir(ttsOutDir);
  const outPath = path.join(ttsOutDir, `tts_cloud_${Date.now()}_${crypto.randomBytes(3).toString("hex")}.wav`);
  const langHint = resolveDashscopeTtsLanguageHint(language);
  const input = {
    text,
    voice,
    format: "wav",
    sample_rate: 24000,
    rate: Math.max(0.5, Math.min(2.0, Number(speed || 1.0) || 1.0))
  };
  if (langHint) input.language_hints = [langHint];
  if (emotion) input.instruction = `请使用${String(emotion || "").trim()}的情感语气进行播报。`;

  sendVoiceLog(event, taskId, "info", `准备调用云端 TTS：${model}｜${voice}`);
  task.controller = new AbortController();
  try {
    const { statusCode, data, raw } = await requestJson(endpoint, {
      timeoutMs: 60000,
      signal: task.controller.signal,
      headers: {
        Authorization: `Bearer ${apiKey}`
      },
      body: {
        model,
        input
      }
    });
    if (task.canceled) return { ok: false, canceled: true, message: "canceled" };
    if (Number(statusCode || 0) >= 400) {
      const message = String(data?.message || data?.code || raw || `dashscope http ${statusCode}`).trim();
      return { ok: false, message: `云端 TTS 调用失败：${message}` };
    }
    const audioUrl = String(data?.output?.audio?.url || "").trim();
    if (!audioUrl) {
      const message = String(data?.message || data?.code || raw || "empty audio url").trim();
      return { ok: false, message: `云端 TTS 未返回音频地址：${message}` };
    }
    sendVoiceLog(event, taskId, "info", "云端 TTS 已返回音频地址，开始下载结果...");
    await downloadToFile(audioUrl, outPath, {
      isCanceled: () => task.canceled === true
    });
    if (task.canceled) return { ok: false, canceled: true, message: "canceled" };
    sendVoiceLog(event, taskId, "info", `云端语音生成完成：${outPath}`);
    return { ok: true, audioPath: outPath, voiceId, speed, emotion, language };
  } finally {
    task.controller = null;
  }
}

async function createCloneVoiceByDashscope({ name, refText, publicAudioUrl, event, taskId, task, modelChoice }) {
  const apiKey = String(modelChoice?.apiKey || "").trim();
  const cloneEndpoint = String(modelChoice?.cloneEndpoint || "https://dashscope.aliyuncs.com/api/v1/services/audio/tts/customization").trim();
  const targetModel = String(modelChoice?.modelId || modelChoice?.model || "").trim();
  const safeUrl = String(publicAudioUrl || "").trim();
  if (!apiKey) return { ok: false, message: "当前云端克隆模型没有可用的阿里云百炼 API Key。" };
  if (!safeUrl) return { ok: false, message: "云端克隆必须提供可公网访问的参考音频 URL。" };
  if (!targetModel) return { ok: false, message: "当前云端克隆模型缺少 target_model。" };
  const prefix = buildDashscopeVoicePrefix(name);
  sendVoiceLog(event, taskId, "info", `开始调用阿里云百炼声音复刻：${targetModel}`);
  sendVoiceLog(event, taskId, "info", `参考音频公网 URL：${safeUrl}`);
  task.controller = new AbortController();
  let remoteVoiceId = "";
  try {
    const { statusCode, data, raw } = await requestJson(cloneEndpoint, {
      timeoutMs: 60000,
      signal: task.controller.signal,
      headers: {
        Authorization: `Bearer ${apiKey}`
      },
      body: {
        model: "voice-enrollment",
        input: {
          action: "create_voice",
          target_model: targetModel,
          url: safeUrl,
          prefix,
          language_hints: ["zh"]
        }
      }
    });
    if (task.canceled) return { ok: false, canceled: true, message: "canceled" };
    if (Number(statusCode || 0) >= 400) {
      return { ok: false, message: String(data?.message || data?.code || raw || `dashscope http ${statusCode}`).trim() || "云端声音复刻失败" };
    }
    remoteVoiceId = String(data?.output?.voice || data?.output?.voice_id || "").trim();
    if (!remoteVoiceId) {
      return { ok: false, message: String(data?.message || data?.code || raw || "empty voice id").trim() || "云端声音复刻未返回音色 ID" };
    }
    sendVoiceLog(event, taskId, "info", `云端声音复刻成功：${remoteVoiceId}`);
  } finally {
    task.controller = null;
  }
  const previewRes = await synthesizeSpeechByDashscope({
    event,
    task,
    taskId,
    voiceId: remoteVoiceId,
    text: String(refText || "").trim() || "你好，我是你的专属音色。",
    speed: 1.0,
    emotion: "",
    language: "中文（普通话）",
    modelChoice: {
      ...(modelChoice || {}),
      voice: remoteVoiceId
    }
  });
  if (!previewRes?.ok || !previewRes?.audioPath) {
    return { ok: false, message: String(previewRes?.message || "云端预览音频生成失败") };
  }
  return {
    ok: true,
    voice: {
      id: remoteVoiceId,
      name: String(name || "").trim() || remoteVoiceId,
      source: "cloud",
      providerId: "aliyun-bailian",
      providerLabel: "阿里云百炼",
      targetModel,
      publicAudioUrl: safeUrl,
      previewWavPath: String(previewRes.audioPath || "").trim(),
      createdAt: Date.now()
    }
  };
}

async function createCloneVoiceFromPrompt({ name, refText, promptInputPath, publicAudioUrl, modelChoice, event, taskId, task }) {
  if (String(modelChoice?.source || "").trim() === "cloud" && String(modelChoice?.providerId || "").trim() === "aliyun-bailian") {
    return await createCloneVoiceByDashscope({ name, refText, publicAudioUrl, event, taskId, task, modelChoice });
  }
  const ttsBundle = pickTtsBundle();
  if (!ttsBundle) return { ok: false, message: buildMissingBundleMessage("TTS") };
  const bundleDir = ttsBundle.bundleDir;
  const pythonExe = path.join(bundleDir, "runtime", "tts", "python", "python.exe");
  const ttsScript = path.join(bundleDir, "services", "tts_server.py");
  const ffmpegExe = path.join(bundleDir, "runtime", "ffmpeg", "bin", "ffmpeg.exe");
  if (!fs.existsSync(pythonExe)) return { ok: false, message: `python 不存在：${pythonExe}` };
  if (!fs.existsSync(ttsScript)) return { ok: false, message: `tts_server.py 不存在：${ttsScript}` };
  if (!fs.existsSync(ffmpegExe)) return { ok: false, message: `ffmpeg 不存在：${ffmpegExe}` };

  const voiceId = `clone_${Date.now()}_${crypto.randomBytes(3).toString("hex")}`;
  const cloneRoot = resolveVoiceCloneRoot();
  const dir = path.join(cloneRoot, voiceId);
  ensureDir(dir);

  const promptWav = path.join(dir, "prompt.wav");
  const previewWav = path.join(dir, "preview.wav");
  const metaPath = path.join(dir, "meta.json");
  const tmpDir = path.join(os.tmpdir(), "ipfactory");
  ensureDir(tmpDir);

  sendVoiceLog(event, taskId, "info", "准备参考音频（转换为 16k 单声道 wav）...");
  await toWavFromAny(ffmpegExe, promptInputPath, promptWav, {
    cwd: tmpDir,
    isCanceled: () => task?.canceled === true,
    task,
    taskId,
    onProgress: null
  });

  const innerTaskId = crypto.randomBytes(8).toString("hex");
  const configPath = path.join(tmpDir, `tts_${innerTaskId}.json`);
  const text = String(refText || "").trim() || "你好，我是你的专属音色。";
  fs.writeFileSync(
    configPath,
    JSON.stringify(
      {
        id: innerTaskId,
        modelConfig: {
          text,
          promptAudio: promptWav,
          outputPath: previewWav,
          param: { speed: 1.0, emotion_weight: 1.0, emotion_text: "" }
        }
      },
      null,
      2
    ),
    "utf-8"
  );

  try {
    sendVoiceLog(event, taskId, "info", "启动本地 TTS 引擎（可能需要加载模型）...");
    const { stdout, stderr } = await runTtsCommand(pythonExe, ttsScript, configPath, {
      cwd: bundleDir,
      isCanceled: () => task?.canceled === true,
      task,
      onStdout: (s) => {
        const msg = String(s || "").trim();
        if (msg) sendVoiceLog(event, taskId, "debug", msg);
      },
      onStderr: (s) => {
        const msg = String(s || "").trim();
        if (msg) sendVoiceLog(event, taskId, "warn", msg);
      }
    });
    const outPath = String(parseAigcPanelValue(stdout, "url") || "");
    if (!outPath) return { ok: false, message: "TTS 返回空输出" };

    const voice = {
      id: voiceId,
      name: String(name || "").trim() || voiceId,
      promptWavPath: promptWav,
      previewWavPath: previewWav,
      createdAt: Date.now()
    };
    fs.writeFileSync(metaPath, JSON.stringify(voice, null, 2), "utf-8");
    sendVoiceLog(event, taskId, "info", "生成完成：预览音频已保存。");
    return { ok: true, voice };
  } finally {
    try {
      if (fs.existsSync(configPath)) fs.unlinkSync(configPath);
    } catch {}
  }
}

ipcMain.handle("voice:cloneCreateFromMic", async (event, payload) => {
  const taskId = String(payload?.taskId || crypto.randomBytes(8).toString("hex"));
  const task = { taskId, proc: null, canceled: false, controller: null };
  _voiceTasks.set(taskId, task);
  try {
    const name = String(payload?.name || "").trim();
    const refText = String(payload?.refText || "").trim();
    const mimeType = String(payload?.mimeType || "").trim().toLowerCase();
    const bytes = payload?.audioBytes;
    const publicAudioUrl = String(payload?.publicAudioUrl || "").trim();
    const modelChoice = payload?.modelChoice && typeof payload.modelChoice === "object" ? payload.modelChoice : null;
    if (!bytes || bytes.length === 0) return { ok: false, message: "empty audioBytes" };
    const buf = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes);

    const tmpDir = path.join(os.tmpdir(), "ipfactory");
    ensureDir(tmpDir);
    const ext = mimeType.includes("webm") ? "webm" : mimeType.includes("ogg") ? "ogg" : "webm";
    const inputPath = path.join(tmpDir, `prompt_${Date.now()}_${crypto.randomBytes(3).toString("hex")}.${ext}`);
    fs.writeFileSync(inputPath, buf);
    try {
      return await createCloneVoiceFromPrompt({ name, refText, promptInputPath: inputPath, publicAudioUrl, modelChoice, event, taskId, task });
    } finally {
      try {
        if (fs.existsSync(inputPath)) fs.unlinkSync(inputPath);
      } catch {}
    }
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  } finally {
    _voiceTasks.delete(taskId);
  }
});

ipcMain.handle("voice:cloneCreateFromFile", async (event, payload) => {
  const taskId = String(payload?.taskId || crypto.randomBytes(8).toString("hex"));
  const task = { taskId, proc: null, canceled: false, controller: null };
  _voiceTasks.set(taskId, task);
  try {
    const name = String(payload?.name || "").trim();
    const refText = String(payload?.refText || "").trim();
    const filePath = String(payload?.filePath || "").trim();
    const publicAudioUrl = String(payload?.publicAudioUrl || "").trim();
    const modelChoice = payload?.modelChoice && typeof payload.modelChoice === "object" ? payload.modelChoice : null;
    if (!filePath && !publicAudioUrl) return { ok: false, message: "empty filePath" };
    if (filePath && !fs.existsSync(filePath)) return { ok: false, message: "file not found" };
    return await createCloneVoiceFromPrompt({ name, refText, promptInputPath: filePath, publicAudioUrl, modelChoice, event, taskId, task });
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  } finally {
    _voiceTasks.delete(taskId);
  }
});

ipcMain.handle("voice:cancel", async (event, payload) => {
  const taskId = String(payload?.taskId || "").trim();
  if (!taskId) return { ok: false, message: "empty taskId" };
  const task = _voiceTasks.get(taskId);
  if (!task) return { ok: false, message: "task not found" };
  task.canceled = true;
  try {
    task.controller?.abort?.();
  } catch {}
  try {
    task.proc?.kill?.();
  } catch {}
  sendVoiceLog(event, taskId, "warn", "已请求停止生成。");
  return { ok: true };
});

ipcMain.handle("voice:resolvePreviewPath", async (_event, payload) => {
  try {
    const voiceId = String(payload?.voiceId || "").trim();
    const cloneItems = readHomeCloneVoiceItems();
    const storedVoice = cloneItems.find((item) => String(item?.id || "").trim() === voiceId) || null;
    const candidatePaths = Array.from(
      new Set(
        [
          String(storedVoice?.previewWavPath || "").trim(),
          resolvePreviewAudioPathByVoiceId(voiceId),
          String(storedVoice?.promptWavPath || "").trim(),
          resolvePromptAudioPathByVoiceId(voiceId)
        ].filter(Boolean)
      )
    );
    const filePath = candidatePaths.find((item) => fs.existsSync(item)) || "";
    if (filePath) return { ok: true, filePath, checkedPaths: candidatePaths };
    if (!voiceId) {
      return { ok: false, message: "缺少音色 ID", filePath: "", checkedPaths: candidatePaths };
    }
    if (!voiceId.startsWith("sys_") && !storedVoice) {
      return {
        ok: false,
        message: "当前登录账号下没有找到这个音色，请先点击刷新音色列表。",
        filePath: "",
        checkedPaths: candidatePaths
      };
    }
    return {
      ok: false,
      message: candidatePaths.length
        ? `未找到音色试听文件，可能是预览文件已丢失：${candidatePaths[0]}`
        : "当前音色没有可用的试听文件。",
      filePath: "",
      checkedPaths: candidatePaths
    };
  } catch (e) {
    return { ok: false, message: String(e?.message || e), filePath: "" };
  }
});

async function handleVoiceGenerateSpeechRequest(event, payload) {
  const taskId = String(payload?.taskId || crypto.randomBytes(8).toString("hex"));
  const task = { taskId, proc: null, canceled: false, controller: null, tool: "tts.generate", status: "running", progress: 5, message: "开始生成语音" };
  _voiceTasks.set(taskId, task);
  updateLiveTaskState(task);
  try {
    const voiceId = String(payload?.voiceId || "").trim();
    const text = String(payload?.text || "").trim();
    const speed = Number(payload?.speed || 1.0) || 1.0;
    const emotion = String(payload?.emotion || "").trim();
    const language = String(payload?.language || "").trim();
    const modelChoice = payload?.modelChoice && typeof payload.modelChoice === "object" ? payload.modelChoice : null;
    if (!voiceId) {
      updateLiveTaskState(task, { status: "failed", message: "empty voiceId" });
      return { ok: false, taskId, message: "empty voiceId" };
    }
    if (!text) {
      updateLiveTaskState(task, { status: "failed", message: "empty text" });
      return { ok: false, taskId, message: "empty text" };
    }
    if (String(modelChoice?.source || "").trim() === "cloud" && String(modelChoice?.providerId || "").trim() === "aliyun-bailian") {
      updateLiveTaskState(task, { progress: 20, message: "准备调用云端 TTS" });
      const cloudRes = await synthesizeSpeechByDashscope({ event, task, taskId, voiceId, text, speed, emotion, language, modelChoice });
      if (cloudRes?.ok) {
        updateLiveTaskState(task, {
          status: "completed",
          progress: 100,
          message: "语音生成完成",
          result: { audioPath: cloudRes.audioPath, voiceId, speed, emotion, language }
        });
        return { ...cloudRes, taskId };
      }
      if (cloudRes?.canceled === true || task.canceled === true) {
        updateLiveTaskState(task, { status: "canceled", message: "已取消" });
        return { ...cloudRes, ok: false, taskId, canceled: true, message: "canceled" };
      }
      updateLiveTaskState(task, { status: "failed", message: String(cloudRes?.message || "语音生成失败") });
      return { ...cloudRes, ok: false, taskId };
    }

    const ttsBundle = pickTtsBundle();
    if (!ttsBundle) {
      const msg = buildMissingBundleMessage("TTS");
      updateLiveTaskState(task, { status: "failed", message: msg });
      return { ok: false, taskId, message: msg };
    }
    const bundleDir = ttsBundle.bundleDir;
    const pythonExe = path.join(bundleDir, "runtime", "tts", "python", "python.exe");
    const ttsScript = path.join(bundleDir, "services", "tts_server.py");
    const ffmpegExe = path.join(bundleDir, "runtime", "ffmpeg", "bin", "ffmpeg.exe");
    if (!fs.existsSync(pythonExe)) {
      const msg = `python 不存在：${pythonExe}`;
      updateLiveTaskState(task, { status: "failed", message: msg });
      return { ok: false, taskId, message: msg };
    }
    if (!fs.existsSync(ttsScript)) {
      const msg = `tts_server.py 不存在：${ttsScript}`;
      updateLiveTaskState(task, { status: "failed", message: msg });
      return { ok: false, taskId, message: msg };
    }
    if (!fs.existsSync(ffmpegExe)) {
      const msg = `ffmpeg 不存在：${ffmpegExe}`;
      updateLiveTaskState(task, { status: "failed", message: msg });
      return { ok: false, taskId, message: msg };
    }

    const promptPath = resolvePromptAudioPathByVoiceId(voiceId);
    if (!promptPath || !fs.existsSync(promptPath)) {
      const msg = `未找到音色参考音频：${promptPath || "(empty)"}`;
      updateLiveTaskState(task, { status: "failed", message: msg });
      return { ok: false, taskId, message: msg };
    }

    const tmpDir = path.join(os.tmpdir(), "ipfactory");
    ensureDir(tmpDir);
    const ttsOutDir = resolveTtsOutputRoot();
    ensureDir(ttsOutDir);

    const promptWav = path.join(tmpDir, `tts_prompt_${taskId}.wav`);
    const outWav = path.join(ttsOutDir, `tts_${Date.now()}_${crypto.randomBytes(3).toString("hex")}.wav`);

    sendVoiceLog(event, taskId, "info", `准备音色参考音频：${voiceId}`);
    updateLiveTaskState(task, { progress: 18, message: "准备音色参考音频" });
    await toWavFromAny(ffmpegExe, promptPath, promptWav, {
      cwd: tmpDir,
      isCanceled: () => task.canceled === true,
      task
    });

    const innerTaskId = crypto.randomBytes(8).toString("hex");
    const configPath = path.join(tmpDir, `tts_gen_${innerTaskId}.json`);
    fs.writeFileSync(
      configPath,
      JSON.stringify(
        {
          id: innerTaskId,
          modelConfig: {
            text,
            promptAudio: promptWav,
            outputPath: outWav,
            param: {
              speed,
              emotion_weight: 1.0,
              emotion_text: emotion ? `${emotion}${language ? `｜${language}` : ""}` : language
            }
          }
        },
        null,
        2
      ),
      "utf-8"
    );

    try {
      sendVoiceLog(event, taskId, "info", "开始生成语音...");
      updateLiveTaskState(task, { progress: 60, message: "开始生成语音" });
      const { stdout } = await runTtsCommand(pythonExe, ttsScript, configPath, {
        cwd: bundleDir,
        isCanceled: () => task.canceled === true,
        task,
        onStdout: (s) => {
          const msg = String(s || "").trim();
          if (msg) sendVoiceLog(event, taskId, "debug", msg);
        },
        onStderr: (s) => {
          const msg = String(s || "").trim();
          if (msg) sendVoiceLog(event, taskId, "warn", msg);
        }
      });
      const outPath = String(parseAigcPanelValue(stdout, "url") || outWav || "");
      if (!outPath || !fs.existsSync(outPath)) {
        updateLiveTaskState(task, { status: "failed", message: "TTS 输出文件不存在" });
        return { ok: false, taskId, message: "TTS 输出文件不存在" };
      }
      sendVoiceLog(event, taskId, "info", "语音生成完成。");
      updateLiveTaskState(task, {
        status: "completed",
        progress: 100,
        message: "语音生成完成",
        result: { audioPath: outPath, voiceId, speed, emotion, language }
      });
      return { ok: true, taskId, audioPath: outPath, voiceId, speed, emotion, language };
    } finally {
      try {
        if (fs.existsSync(configPath)) fs.unlinkSync(configPath);
      } catch {}
      try {
        if (fs.existsSync(promptWav)) fs.unlinkSync(promptWav);
      } catch {}
    }
  } catch (e) {
    const msg = String(e?.message || e);
    if (task.canceled === true || msg === "canceled" || /canceled/i.test(msg)) {
      updateLiveTaskState(task, { status: "canceled", message: "已取消" });
      return { ok: false, taskId, canceled: true, message: "canceled" };
    }
    updateLiveTaskState(task, { status: "failed", message: msg || "语音生成失败" });
    return { ok: false, taskId, message: msg };
  } finally {
    _voiceTasks.delete(taskId);
  }
}

ipcMain.handle("voice:generateSpeech", handleVoiceGenerateSpeechRequest);

ipcMain.handle("video:cancel", async (event, payload) => {
  const taskId = String(payload?.taskId || "").trim();
  if (!taskId) return { ok: false, message: "empty taskId" };
  const task = _videoTasks.get(taskId);
  if (!task) return { ok: false, message: "task not found" };
  task.canceled = true;
  updateLiveTaskState(task, { status: "canceling", message: "正在停止生成..." });
  sendVideoProgress(event, taskId, 0, "正在停止生成...");
  sendVideoLog(event, taskId, "warn", "已请求停止生成，正在终止进程树...");
  try {
    await killProcTree(task.proc);
    const exited = await waitProcExit(task.proc, 12000);
    if (!exited) {
      sendVideoLog(event, taskId, "warn", "进程停止超时，可能仍在后台运行。");
      sendVideoProgress(event, taskId, 0, "停止超时");
      return { ok: false, message: "stop timeout" };
    }
    sendVideoProgress(event, taskId, 0, "已停止");
    return { ok: true };
  } catch (e) {
    sendVideoLog(event, taskId, "error", String(e?.message || e));
    return { ok: false, message: String(e?.message || e) };
  }
});

async function handleVideoExtractAudioRequest(_event, payload) {
  try {
    const inputVideo = String(payload?.inputVideo || "").trim();
    const outPath = String(payload?.outPath || "").trim();
    const format = String(payload?.format || "").trim().toLowerCase() || "mp3";
    const bitrateKbps = Math.max(32, Math.min(512, Number(payload?.bitrateKbps || 192) || 192));
    const sampleRate = Math.max(8000, Math.min(192000, Number(payload?.sampleRate || 44100) || 44100));
    if (!inputVideo) return { ok: false, message: "empty inputVideo", outPath: "" };
    if (!outPath) return { ok: false, message: "empty outPath", outPath: "" };
    if (!fs.existsSync(inputVideo)) return { ok: false, message: `video not found: ${inputVideo}`, outPath: "" };
    const ffmpegExe = pickFfmpegExeFromBundles();
    if (!ffmpegExe || !fs.existsSync(ffmpegExe)) return { ok: false, message: "ffmpeg.exe not found", outPath: "" };
    ensureDir(path.dirname(outPath));
    const codecArgs =
      format === "wav"
        ? ["-vn", "-ar", String(sampleRate), "-ac", "2", "-c:a", "pcm_s16le"]
        : ["-vn", "-ar", String(sampleRate), "-ac", "2", "-c:a", format === "aac" ? "aac" : "libmp3lame", "-b:a", `${bitrateKbps}k`];
    await runFfmpeg(ffmpegExe, ["-y", "-i", inputVideo, ...codecArgs, outPath], {
      cwd: path.dirname(outPath)
    });
    return { ok: true, outPath, log: `已输出音频：${outPath}` };
  } catch (e) {
    return { ok: false, message: String(e?.message || e), outPath: "" };
  }
}

ipcMain.handle("video:extractAudio", handleVideoExtractAudioRequest);

async function handleVideoGenerateTalkingVideoRequest(event, payload) {
  const taskId = String(payload?.taskId || crypto.randomBytes(8).toString("hex"));
  const task = { taskId, proc: null, canceled: false, tool: "videosync.generate", status: "running", progress: 1, message: "开始生成口播视频" };
  _videoTasks.set(taskId, task);
  updateLiveTaskState(task);
  try {
    const videoPath = String(payload?.videoPath || "").trim();
    const audioPath = String(payload?.audioPath || "").trim();
    const modelChoice = payload?.modelChoice && typeof payload.modelChoice === "object" ? payload.modelChoice : null;
    const useCloudVideoSync = String(modelChoice?.source || "").trim().toLowerCase() === "cloud";
    if (!videoPath) return { ok: false, taskId, message: "empty videoPath" };
    if (!audioPath) return { ok: false, taskId, message: "empty audioPath" };
    if (!fs.existsSync(videoPath)) return { ok: false, taskId, message: `video not found: ${videoPath}` };
    if (!fs.existsSync(audioPath)) return { ok: false, taskId, message: `audio not found: ${audioPath}` };
    if (useCloudVideoSync) {
      const endpoint = String(modelChoice?.endpoint || "").trim();
      const apiKey = String(modelChoice?.apiKey || "").trim();
      const model = String(modelChoice?.modelId || modelChoice?.model || "").trim();
      const providerId = String(modelChoice?.providerId || "").trim().toLowerCase();
      if (!endpoint) return { ok: false, taskId, message: "当前云端数字人模型未配置 endpoint" };
      if (!apiKey) return { ok: false, taskId, message: "当前云端数字人模型未配置 API Key" };
      if (!model) return { ok: false, taskId, message: "当前云端数字人模型未配置 modelId" };

      if (providerId === "aliyun-bailian" && model.toLowerCase() === "videoretalk") {
        const aliyunRes = await generateTalkingVideoByAliyunVideoRetalk({
          event,
          taskId,
          task,
          videoPath,
          audioPath,
          modelChoice
        });
        if (aliyunRes?.canceled) {
          updateLiveTaskState(task, { status: "canceled", message: "已停止" });
          return { ok: false, canceled: true, taskId, message: "canceled" };
        }
        if (!aliyunRes?.ok || !aliyunRes?.videoPath) {
          const message = String(aliyunRes?.message || "阿里云百炼 VideoRetalk 生成失败").trim() || "阿里云百炼 VideoRetalk 生成失败";
          updateLiveTaskState(task, { status: "failed", message });
          return { ok: false, taskId, message };
        }
        sendVideoProgress(event, taskId, 100, "生成完成");
        updateLiveTaskState(task, {
          status: "completed",
          progress: 100,
          message: "生成完成",
          result: {
            videoPath: aliyunRes.videoPath,
            templateId: aliyunRes.templateId,
            templateDir: aliyunRes.templateDir,
            source: "cloud",
            providerId: "aliyun-bailian",
            model: model.toLowerCase()
          }
        });
        return aliyunRes;
      }

      sendVideoProgress(event, taskId, 8, "正在上传形象视频和音频到云端模型...");
      sendVideoLog(event, taskId, "info", `云端数字人模型：${String(modelChoice?.label || model || "未命名模型")}`);

      const videoBase64 = fs.readFileSync(videoPath).toString("base64");
      const audioBase64 = fs.readFileSync(audioPath).toString("base64");
      const { statusCode, data, raw } = await requestJson(endpoint, {
        timeoutMs: 300000,
        headers: {
          Authorization: `Bearer ${apiKey}`
        },
        body: {
          model,
          taskId,
          input: {
            video: {
              name: path.basename(videoPath),
              mimeType: detectMimeTypeByFilePath(videoPath, "video/mp4"),
              base64: videoBase64
            },
            audio: {
              name: path.basename(audioPath),
              mimeType: detectMimeTypeByFilePath(audioPath, "audio/wav"),
              base64: audioBase64
            }
          }
        }
      });
      if (statusCode < 200 || statusCode >= 300) {
        return { ok: false, taskId, message: `云端数字人接口调用失败 HTTP ${statusCode}${raw ? `：${String(raw).slice(0, 200)}` : ""}` };
      }

      const nestedVideoUrl =
        String(
          data?.videoUrl ||
            data?.url ||
            data?.result?.videoUrl ||
            data?.result?.url ||
            data?.data?.videoUrl ||
            data?.data?.url ||
            data?.output?.videoUrl ||
            ""
        ).trim();
      const nestedVideoBase64 = String(data?.videoBase64 || data?.result?.videoBase64 || data?.data?.videoBase64 || data?.output?.videoBase64 || "").trim();
      const outRoot = resolveVideoTemplateRoot();
      ensureDir(outRoot);
      const templateId = `talk_${taskId}_${Date.now()}`;
      const templateDir = path.join(outRoot, templateId);
      ensureDir(templateDir);
      const outPath = path.join(templateDir, "result.mp4");

      sendVideoProgress(event, taskId, 75, "正在接收云端数字人结果...");
      if (nestedVideoBase64) {
        fs.writeFileSync(outPath, Buffer.from(nestedVideoBase64, "base64"));
      } else if (nestedVideoUrl) {
        await downloadToFile(nestedVideoUrl, outPath, { maxHops: 6 });
      } else {
        return { ok: false, taskId, message: "云端数字人接口未返回 videoUrl 或 videoBase64" };
      }

      fs.writeFileSync(
        path.join(templateDir, "meta.json"),
        JSON.stringify({ id: templateId, taskId, createdAt: Date.now(), type: "talking_video", source: "cloud" }, null, 2),
        "utf-8"
      );
      sendVideoProgress(event, taskId, 100, "生成完成");
      updateLiveTaskState(task, {
        status: "completed",
        progress: 100,
        message: "生成完成",
        result: { videoPath: outPath, templateId, templateDir, source: "cloud" }
      });
      return { ok: true, taskId, videoPath: outPath, templateId, templateDir, source: "cloud" };
    }

    const bundle = pickVideoSyncBundle();
    if (!bundle) return { ok: false, taskId, message: buildMissingBundleMessage("VideoSync") };
    const bundleDir = bundle.bundleDir;
    const pythonExe = path.join(bundleDir, "runtime", "python", "python.exe");
    const launcherPy = path.join(bundleDir, "launcher.py");
    if (!fs.existsSync(pythonExe)) return { ok: false, taskId, message: `python 不存在：${pythonExe}` };
    if (!fs.existsSync(launcherPy)) return { ok: false, taskId, message: `launcher.py 不存在：${launcherPy}` };

    const tmpDir = path.join(os.tmpdir(), "ipfactory");
    ensureDir(tmpDir);
    const configPath = path.join(tmpDir, `videosync_${taskId}.json`);

    try {
      sendVideoProgress(event, taskId, 1, "开始生成口播视频...");
      const ffmpegExe = pickVideoSyncFfmpegExe(bundleDir);

      const attempts = [
        { name: "balanced", batchSize: 2, weightType: "fp16", outW: 720, outH: 1280 },
        { name: "lowmem", batchSize: 1, weightType: "fp16", outW: 540, outH: 960 }
      ];

      let finalUrl = "";
      let finalPayload = null;
      let finalCode = 0;
      let finalStderr = "";
      let usedVideoPath = videoPath;
      let lastErrorMsg = "";

      for (let i = 0; i < attempts.length; i += 1) {
        if (task.canceled) break;
        const a = attempts[i];

        usedVideoPath = videoPath;
        const scaled = path.join(tmpDir, `videosync_in_${taskId}_${a.name}.mp4`);
        const didScale = await maybeDownscaleVideoForVideoSync(ffmpegExe, videoPath, scaled, { width: a.outW, height: a.outH });
        if (didScale) usedVideoPath = scaled;

        sendVideoLog(event, taskId, "info", `输入形象视频：${usedVideoPath}`);
        sendVideoLog(event, taskId, "info", `输入音频：${audioPath}`);
        sendVideoLog(event, taskId, "info", `参数：batch_size=${a.batchSize}，weight_type=${a.weightType}，预处理=${didScale ? `${a.outW}x${a.outH}` : "无"}`);

        fs.writeFileSync(
          configPath,
          JSON.stringify(
            {
              id: taskId,
              modelConfig: { video: usedVideoPath, audio: audioPath },
              setting: {
                batch_size: a.batchSize,
                weight_type: a.weightType,
                human_weight: "256m"
              }
            },
            null,
            2
          ),
          "utf-8"
        );

        const { stdout, stderr, code } = await runVideoSyncCommand(pythonExe, launcherPy, configPath, {
          cwd: bundleDir,
          isCanceled: () => task.canceled === true,
          task,
          event,
          taskId
        });

        finalCode = code;
        finalStderr = stderr || "";
        finalPayload = pickLastVideoSyncPayload(stdout, stderr, taskId);

        if (finalPayload?.url && code === 0) {
          finalUrl = String(finalPayload.url || "").trim();
          break;
        }

        lastErrorMsg = toFriendlyVideoSyncError(finalPayload, code === 0 ? "" : `video sync exit code: ${code}`);
        if (!isLikelyVideoSyncMemoryError(finalStderr)) break;
        sendVideoLog(event, taskId, "warn", `检测到可能的内存不足，尝试更低内存参数重试（${a.name} → ${attempts[i + 1]?.name || "无"}）`);
      }

      if (task.canceled) return { ok: false, taskId, canceled: true, message: "canceled" };

      if (!finalUrl || finalCode !== 0) {
        const msg = lastErrorMsg || toFriendlyVideoSyncError(finalPayload, `video sync exit code: ${finalCode}`);
        sendVideoLog(event, taskId, "error", msg);
        return { ok: false, taskId, message: msg, raw: String(finalPayload?.error || "") };
      }

      const url = String(finalUrl || "").trim();
      if (!url) return { ok: false, taskId, message: "Video Sync 未返回输出路径" };

      const srcOut = path.normalize(url);
      if (!fs.existsSync(srcOut)) return { ok: false, taskId, message: "输出文件不存在" };

      const outRoot = resolveVideoTemplateRoot();
      ensureDir(outRoot);
      const templateId = `talk_${taskId}_${Date.now()}`;
      const templateDir = path.join(outRoot, templateId);
      ensureDir(templateDir);
      const outPath = path.join(templateDir, "result.mp4");
      try {
        fs.copyFileSync(srcOut, outPath);
      } catch {
        sendVideoLog(event, taskId, "warn", "复制输出文件失败，直接使用原输出路径。");
        updateLiveTaskState(task, {
          status: "completed",
          progress: 100,
          message: "生成完成",
          result: { videoPath: srcOut }
        });
        return { ok: true, taskId, videoPath: srcOut };
      }
      try {
        fs.writeFileSync(
          path.join(templateDir, "meta.json"),
          JSON.stringify({ id: templateId, taskId, createdAt: Date.now(), type: "talking_video" }, null, 2),
          "utf-8"
        );
      } catch {}
      sendVideoProgress(event, taskId, 100, "生成完成");
      sendVideoLog(event, taskId, "info", `输出视频：${outPath}`);
      updateLiveTaskState(task, {
        status: "completed",
        progress: 100,
        message: "生成完成",
        result: { videoPath: outPath, templateId, templateDir }
      });
      return { ok: true, taskId, videoPath: outPath, templateId, templateDir };
    } finally {
      try {
        if (fs.existsSync(configPath)) fs.unlinkSync(configPath);
      } catch {}
    }
  } catch (e) {
    const msg = String(e?.message || e);
    if (msg === "canceled" || /canceled/i.test(msg)) {
      updateLiveTaskState(task, { status: "canceled", message: "已取消" });
      return { ok: false, taskId, canceled: true, message: "canceled" };
    }
    updateLiveTaskState(task, { status: "failed", message: msg || "口播视频生成失败" });
    return { ok: false, taskId, message: msg };
  } finally {
    _videoTasks.delete(taskId);
  }
}

ipcMain.handle("video:generateTalkingVideo", handleVideoGenerateTalkingVideoRequest);

async function handleVideoEditProcessSilenceDetection(_event, payload) {
  const taskId = String(payload?.taskId || crypto.randomBytes(8).toString("hex"));
  const task = { taskId, proc: null, canceled: false, tool: "video.edit.cutSilence", status: "running", progress: 5, message: "开始静音剪辑" };
  _videoEditTasks.set(taskId, task);
  updateLiveTaskState(task);
  try {
    const inputVideoRaw = String(payload?.inputVideo || "").trim().replace(/^file:\/\//i, "");
    const silenceThreshold = Number(payload?.silenceThreshold ?? -40);
    const silenceDuration = Number(payload?.silenceDuration ?? 1);
    const minPauseDuration = Number(payload?.minPauseDuration ?? 0.15);

    if (!inputVideoRaw) {
      updateLiveTaskState(task, { status: "failed", message: "empty inputVideo" });
      return { ok: false, taskId, message: "empty inputVideo" };
    }
    if (!fs.existsSync(inputVideoRaw)) {
      const msg = `video not found: ${inputVideoRaw}`;
      updateLiveTaskState(task, { status: "failed", message: msg });
      return { ok: false, taskId, message: msg };
    }

    const ffmpegExe = pickFfmpegExeFromBundles();
    if (!ffmpegExe || !fs.existsSync(ffmpegExe)) {
      updateLiveTaskState(task, { status: "failed", message: "ffmpeg.exe not found" });
      return { ok: false, taskId, message: "ffmpeg.exe not found" };
    }

    let inputVideo = inputVideoRaw;
    const inputExt = path.extname(inputVideoRaw) || ".mp4";
    const tmpRoot = path.join(os.tmpdir(), "ipfactory", "video_edit");
    ensureDir(tmpRoot);

    const needTemp =
      /[\u4e00-\u9fa5]/.test(inputVideoRaw) || /[^\x00-\x7F]/.test(inputVideoRaw) || inputVideoRaw.includes(" ");
    if (needTemp) {
      const tmpIn = path.join(tmpRoot, `in_${Date.now()}${inputExt}`);
      fs.copyFileSync(inputVideoRaw, tmpIn);
      inputVideo = tmpIn;
    }

    const outRoot = resolveVideoEditsRoot();
    ensureDir(outRoot);
    const editId = `edit_${Date.now()}_${crypto.randomBytes(3).toString("hex")}`;
    const editDir = path.join(outRoot, editId);
    ensureDir(editDir);
    const outPath = path.join(editDir, "result.mp4");

    const minPauseDurationMs = Math.round((Number.isFinite(minPauseDuration) ? minPauseDuration : 0.15) * 1000);
    const audioFilter = `silenceremove=stop_periods=-1:stop_duration=${Number.isFinite(silenceDuration) ? silenceDuration : 1}:stop_threshold=${Number.isFinite(silenceThreshold) ? silenceThreshold : -40}dB,adelay=${minPauseDurationMs}ms|${minPauseDurationMs}ms`;

    updateLiveTaskState(task, { progress: 35, message: "正在执行静音剪辑" });
    await runFfmpeg(ffmpegExe, ["-y", "-i", inputVideo, "-af", audioFilter, "-c:v", "copy", outPath], {
      cwd: editDir,
      isCanceled: () => task.canceled === true,
      task
    });
    try {
      fs.writeFileSync(
        path.join(editDir, "meta.json"),
        JSON.stringify(
          {
            id: editId,
            createdAt: Date.now(),
            type: "auto_cut_silence",
            inputVideo: inputVideoRaw,
            params: { silenceThreshold, silenceDuration, minPauseDuration }
          },
          null,
          2
        ),
        "utf-8"
      );
    } catch {}
    updateLiveTaskState(task, {
      status: "completed",
      progress: 100,
      message: "静音剪辑完成",
      result: { editId, editDir, outputVideo: outPath }
    });
    return { ok: true, taskId, editId, editDir, outputVideo: outPath };
  } catch (e) {
    const msg = String(e?.message || e);
    if (msg === "canceled" || /canceled/i.test(msg)) {
      updateLiveTaskState(task, { status: "canceled", message: "已取消" });
      return { ok: false, taskId, canceled: true, message: "canceled" };
    }
    updateLiveTaskState(task, { status: "failed", message: msg || "静音剪辑失败" });
    return { ok: false, taskId, message: msg };
  } finally {
    _videoEditTasks.delete(taskId);
  }
}

ipcMain.handle("videoEdit:processSilenceDetection", handleVideoEditProcessSilenceDetection);

ipcMain.handle("videoEdit:cancel", async (_event, payload) => {
  const taskId = String(payload?.taskId || "").trim();
  if (!taskId) return { ok: false, message: "empty taskId" };
  const task = _videoEditTasks.get(taskId);
  if (!task) return { ok: false, message: "task not found" };
  task.canceled = true;
  updateLiveTaskState(task, { status: "canceling", message: "正在取消静音剪辑" });
  try {
    task.proc?.kill?.();
  } catch {}
  return { ok: true };
});

function parseAigcPanelSubtitleSegments(stdoutText) {
  const out = [];
  const lines = String(stdoutText || "").split(/\r?\n/);
  for (const line of lines) {
    const m = line.match(/^AigcPanelRunResult\[(.+?)\]\[(.+?)\]$/);
    if (!m) continue;
    try {
      const payload = JSON.parse(Buffer.from(m[2], "base64").toString("utf-8"));
      const records = Array.isArray(payload?.records) ? payload.records : [];
      for (const r of records) {
        const text = String(r?.text || "").trim();
        const startMs = Number(r?.start ?? 0) || 0;
        const endMs = Number(r?.end ?? 0) || 0;
        if (!text) continue;
        if (endMs <= startMs) continue;
        out.push({ startSec: startMs / 1000, endSec: endMs / 1000, text });
      }
    } catch {}
  }
  return out
    .filter((x) => Number.isFinite(x.startSec) && Number.isFinite(x.endSec) && x.endSec > x.startSec && x.text)
    .sort((a, b) => Number(a.startSec || 0) - Number(b.startSec || 0));
}

function formatAssTime(sec) {
  const s = Math.max(0, Number(sec || 0) || 0);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const ss = s % 60;
  const pad2 = (n) => String(n).padStart(2, "0");
  const v = ss.toFixed(2).padStart(5, "0");
  return `${h}:${pad2(m)}:${v}`;
}

function cleanSubtitleTextForAss(text) {
  return String(text || "")
    .replace(/[\u0000-\u001f]/g, " ")
    .replace(/[\u200B-\u200F\uFEFF]/g, "")
    .replace(/[{}]/g, "")
    .replace(/\\/g, "")
    .replace(/&H[0-9A-Fa-f]{2,8}&/g, "")
    .replace(/[^\u4e00-\u9fa5a-zA-Z0-9\s]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function wrapSubtitleToAssLines(text, maxChars) {
  const t = cleanSubtitleTextForAss(text);
  const max = Math.max(6, Math.min(24, Number(maxChars || 14) || 14));
  if (!t) return "";
  const words = t.split(/\s+/).filter(Boolean);
  const lines = [];
  let cur = "";
  const flush = () => {
    const x = cur.trim();
    if (x) lines.push(x);
    cur = "";
  };
  const pushLong = (w) => {
    const s = String(w || "").trim();
    if (!s) return;
    if (s.length <= max) {
      if (!cur) cur = s;
      else if ((cur + s).length <= max) cur += s;
      else {
        flush();
        cur = s;
      }
      return;
    }
    flush();
    for (let i = 0; i < s.length; i += max) {
      const part = s.slice(i, i + max);
      if (part) lines.push(part);
    }
  };
  for (const w of words) {
    if (String(w).length > max) {
      pushLong(w);
      continue;
    }
    if (!cur) {
      cur = w;
      continue;
    }
    const next = `${cur}${w}`;
    if (next.length <= max) cur = next;
    else {
      flush();
      cur = w;
    }
  }
  flush();
  return lines.join("\\N");
}

function wrapAssTextPreserveTags(text, maxChars) {
  const max = Math.max(6, Math.min(24, Number(maxChars || 14) || 14));
  const raw = String(text || "").replace(/[\u0000-\u001f]/g, " ").replace(/[\u200B-\u200F\uFEFF]/g, "");
  if (!raw.trim()) return "";

  const tokens = [];
  let i = 0;
  while (i < raw.length) {
    if (raw[i] === "{") {
      const j = raw.indexOf("}", i + 1);
      if (j > i) {
        tokens.push({ t: "tag", v: raw.slice(i, j + 1) });
        i = j + 1;
        continue;
      }
    }
    const nextTag = raw.indexOf("{", i);
    const chunk = nextTag >= 0 ? raw.slice(i, nextTag) : raw.slice(i);
    tokens.push({ t: "txt", v: chunk });
    i = nextTag >= 0 ? nextTag : raw.length;
  }

  let out = "";
  let curLen = 0;
  const pushChar = (ch) => {
    out += ch;
    curLen += 1;
    if (curLen >= max) {
      out += "\\N";
      curLen = 0;
    }
  };

  for (const tok of tokens) {
    if (tok.t === "tag") {
      out += tok.v;
      continue;
    }
    const cleaned = cleanSubtitleTextForAss(tok.v);
    if (!cleaned) continue;
    for (const ch of cleaned.split("")) pushChar(ch);
  }
  return out.replace(/(\\N)+$/g, "");
}

function wrapAssTextLinesPreserveTags(text, maxChars, maxLines) {
  const max = Math.max(6, Math.min(24, Number(maxChars || 14) || 14));
  const limit = Math.max(1, Math.min(6, Number(maxLines || 2) || 2));
  const raw = String(text || "").replace(/[\u0000-\u001f]/g, " ").replace(/[\u200B-\u200F\uFEFF]/g, "");
  if (!raw.trim()) return [];

  const tokens = [];
  let i = 0;
  while (i < raw.length) {
    if (raw[i] === "{") {
      const j = raw.indexOf("}", i + 1);
      if (j > i) {
        tokens.push({ t: "tag", v: raw.slice(i, j + 1) });
        i = j + 1;
        continue;
      }
    }
    const nextTag = raw.indexOf("{", i);
    const chunk = nextTag >= 0 ? raw.slice(i, nextTag) : raw.slice(i);
    tokens.push({ t: "txt", v: chunk });
    i = nextTag >= 0 ? nextTag : raw.length;
  }

  const lines = [];
  let line = "";
  let lineLen = 0;
  const flush = () => {
    const textLine = String(line || "").replace(/(\\N)+$/g, "");
    if (textLine.trim()) lines.push(textLine);
    line = "";
    lineLen = 0;
  };
  const pushChar = (ch) => {
    line += ch;
    lineLen += 1;
    if (lineLen >= max) flush();
  };

  for (const tok of tokens) {
    if (tok.t === "tag") {
      line += tok.v;
      continue;
    }
    const cleaned = cleanSubtitleTextForAss(tok.v);
    if (!cleaned) continue;
    for (const ch of cleaned.split("")) pushChar(ch);
  }
  flush();
  return lines.slice(0, limit);
}

function buildAssFromSegments(segments, { playResX, playResY, fontSize, marginV }) {
  const x = Math.max(0, Number(playResX || 720) || 720);
  const y = Math.max(0, Number(playResY || 1280) || 1280);
  const fs0 = Math.max(18, Math.min(96, Number(fontSize || 44) || 44));
  const mv0 = Math.max(0, Number(marginV || 0) || 0);
  const header = [
    "[Script Info]",
    "ScriptType: v4.00+",
    "Collisions: Normal",
    `PlayResX: ${x}`,
    `PlayResY: ${y}`,
    "ScaledBorderAndShadow: yes",
    "",
    "[V4+ Styles]",
    "Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding",
    `Style: Default,Microsoft YaHei,${fs0},&H00FFFFFF,&H000000FF,&H00101010,&H64000000,1,0,0,0,100,100,0,0,1,3,1,2,40,40,${mv0},1`,
    "",
    "[Events]",
    "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text"
  ].join("\n");
  const rows = (Array.isArray(segments) ? segments : []).map((s) => {
    const start = formatAssTime(s.startSec);
    const end = formatAssTime(s.endSec);
    const txt = wrapSubtitleToAssLines(s.text, 14);
    return `Dialogue: 0,${start},${end},Default,,0,0,0,,${txt}`;
  });
  return `${header}\n${rows.join("\n")}\n`;
}

function wrapTextToLines(text, maxChars) {
  const max = Math.max(1, Number(maxChars || 14) || 14);
  const raw = String(text || "").replace(/\r\n/g, "\n").trim();
  if (!raw) return [];
  const normalized = raw.replace(/[ \t]+/g, " ").replace(/\n+/g, " ").trim();
  if (!normalized) return [];
  const asciiLen = normalized.replace(/[^\x00-\x7F]/g, "").length;
  const mostlyAscii = normalized.length > 0 ? asciiLen / normalized.length > 0.6 : false;
  const hasSpace = /\s/.test(normalized);

  if (mostlyAscii && hasSpace) {
    const words = normalized.split(/\s+/).filter(Boolean);
    const lines = [];
    let cur = "";
    for (const w of words) {
      const next = cur ? `${cur} ${w}` : w;
      if (next.length <= max) {
        cur = next;
        continue;
      }
      if (cur) lines.push(cur);
      cur = w.length > max ? w.slice(0, max) : w;
    }
    if (cur) lines.push(cur);
    return lines;
  }

  const chars = Array.from(normalized.replace(/\s+/g, ""));
  const lines = [];
  for (let i = 0; i < chars.length; i += max) lines.push(chars.slice(i, i + max).join(""));
  return lines.filter((x) => String(x || "").trim());
}

function normalizeSubtitlePlainText(text) {
  return cleanSubtitleTextForAss(text).replace(/\s+/g, "");
}

function calcBigramDiceSimilarity(a, b) {
  const s1 = normalizeSubtitlePlainText(a);
  const s2 = normalizeSubtitlePlainText(b);
  if (!s1 || !s2) return 0;
  if (s1 === s2) return 1;
  const toBigrams = (s) => {
    const arr = Array.from(s || "");
    const out = new Map();
    for (let i = 0; i < arr.length - 1; i += 1) {
      const bg = `${arr[i]}${arr[i + 1]}`;
      out.set(bg, (out.get(bg) || 0) + 1);
    }
    return out;
  };
  const m1 = toBigrams(s1);
  const m2 = toBigrams(s2);
  let inter = 0;
  let n1 = 0;
  let n2 = 0;
  for (const v of m1.values()) n1 += v;
  for (const v of m2.values()) n2 += v;
  if (!n1 || !n2) return 0;
  for (const [k, v1] of m1.entries()) {
    const v2 = m2.get(k) || 0;
    if (v2 > 0) inter += Math.min(v1, v2);
  }
  return (2 * inter) / (n1 + n2);
}

function normalizeSubtitleSegmentsByTiming(segments, { maxGapSec = 0.18, minSegDurSec = 0.4, maxSegDurSec = 2.8, minTextChars = 3 } = {}) {
  const segs = Array.isArray(segments) ? segments.map((s) => ({ ...s })) : [];
  const list = segs
    .map((s) => ({
      ...s,
      startSec: Math.max(0, Number(s?.startSec || 0) || 0),
      endSec: Math.max(0, Number(s?.endSec || 0) || 0),
      text: String(s?.text || "")
    }))
    .filter((s) => Number.isFinite(s.startSec) && Number.isFinite(s.endSec) && s.endSec > s.startSec);
  list.sort((a, b) => Number(a.startSec || 0) - Number(b.startSec || 0));
  if (!list.length) return [];

  const out = [];
  const appendText = (a, b) => {
    const x = String(a || "").trim();
    const y = String(b || "").trim();
    if (!x) return y;
    if (!y) return x;
    return `${x} ${y}`;
  };
  for (const s of list) {
    const last = out[out.length - 1];
    if (!last) {
      out.push({ ...s });
      continue;
    }
    const gap = Number(s.startSec || 0) - Number(last.endSec || 0);
    const lastDur = Number(last.endSec || 0) - Number(last.startSec || 0);
    const lastLen = Array.from(normalizeSubtitlePlainText(last.text)).length;
    const curLen = Array.from(normalizeSubtitlePlainText(s.text)).length;
    const canMergeByGap = gap >= 0 && gap <= Math.max(0, Number(maxGapSec || 0) || 0);
    const wantMergeShort = lastDur < Math.max(0.05, Number(minSegDurSec || 0) || 0) || lastLen < minTextChars || curLen < minTextChars;
    const mergedDur = Math.max(Number(s.endSec || 0), Number(last.endSec || 0)) - Number(last.startSec || 0);
    if (canMergeByGap && wantMergeShort && mergedDur <= Math.max(0.2, Number(maxSegDurSec || 0) || 0)) {
      last.endSec = Math.max(Number(last.endSec || 0), Number(s.endSec || 0));
      last.text = appendText(last.text, s.text);
      continue;
    }
    out.push({ ...s });
  }

  for (let i = 0; i < out.length - 1; i += 1) {
    const s = out[i];
    const dur = Number(s.endSec || 0) - Number(s.startSec || 0);
    if (dur >= Math.max(0.05, Number(minSegDurSec || 0) || 0)) continue;
    const next = out[i + 1];
    const gap = Number(next.startSec || 0) - Number(s.endSec || 0);
    const mergedDur = Number(next.endSec || 0) - Number(s.startSec || 0);
    if (gap >= 0 && gap <= Math.max(0, Number(maxGapSec || 0) || 0) && mergedDur <= Math.max(0.2, Number(maxSegDurSec || 0) || 0)) {
      next.startSec = Number(s.startSec || 0);
      next.text = appendText(s.text, next.text);
      s.__drop = true;
    }
  }
  return out.filter((s) => s && s.__drop !== true);
}

function padSubtitleSegmentEndTimes(
  segments,
  { durationSec = 0, endPadSec = 0.18, minHoldSec = 0.75, minGapToNextSec = 0.04, keepUntilNextStartGapSec = 1.2 } = {}
) {
  const segs = Array.isArray(segments) ? segments.map((s) => ({ ...s })) : [];
  const dur = Math.max(0, Number(durationSec || 0) || 0);
  const pad = Math.max(0, Math.min(1.2, Number(endPadSec || 0.18) || 0.18));
  const minHold = Math.max(0.05, Math.min(6, Number(minHoldSec || 0.75) || 0.75));
  const minGap = Math.max(0, Math.min(0.3, Number(minGapToNextSec || 0.04) || 0.04));
  const keepGap = Math.max(0.1, Math.min(3.5, Number(keepUntilNextStartGapSec || 1.2) || 1.2));

  const list = segs
    .map((s) => ({
      ...s,
      startSec: Math.max(0, Number(s?.startSec || 0) || 0),
      endSec: Math.max(0, Number(s?.endSec || 0) || 0)
    }))
    .filter((s) => Number.isFinite(s.startSec) && Number.isFinite(s.endSec) && s.endSec > s.startSec);
  list.sort((a, b) => Number(a.startSec || 0) - Number(b.startSec || 0));
  if (!list.length) return [];

  for (let i = 0; i < list.length; i += 1) {
    const s = list[i];
    const start = Number(s.startSec || 0);
    const end = Number(s.endSec || 0);
    const next = list[i + 1];
    const nextStart = next ? Number(next.startSec || 0) : NaN;
    const gapToNext = Number.isFinite(nextStart) ? nextStart - end : NaN;

    let targetEnd = Math.max(end + pad, start + minHold);
    if (Number.isFinite(gapToNext) && gapToNext >= minGap && gapToNext <= keepGap) {
      targetEnd = Math.max(targetEnd, nextStart - minGap);
    }
    if (Number.isFinite(nextStart) && nextStart > start) {
      const cap = Math.max(start + 0.05, nextStart - minGap);
      targetEnd = Math.min(targetEnd, cap);
    }
    if (dur > 0) {
      const cap = Math.max(start + 0.05, dur - 0.01);
      targetEnd = Math.min(targetEnd, cap);
    }
    if (targetEnd > end) s.endSec = targetEnd;
  }
  return list;
}

function applyPreferredSubtitleTextToSegments(segments, preferredText, { maxCharsPerLine = 14, maxLines = 2 } = {}) {
  const segs = Array.isArray(segments) ? segments.map((s) => ({ ...s })) : [];
  const n = segs.length;
  if (!n) return segs;

  const textRaw = cleanSubtitleTextForAss(preferredText);
  if (!textRaw) return segs;

  const max = Math.max(6, Math.min(24, Number(maxCharsPerLine || 14) || 14));
  const linesN = Math.max(1, Math.min(3, Number(maxLines || 2) || 2));
  const maxBlockChars = max * linesN;

  const srcChars = Array.from(String(textRaw || "").replace(/\s+/g, ""));
  if (!srcChars.length) return segs;

  const merged = [];
  for (const s of segs) {
    const a = Math.max(0, Number(s?.startSec || 0) || 0);
    const b = Math.max(0, Number(s?.endSec || 0) || 0);
    if (!Number.isFinite(a) || !Number.isFinite(b) || b <= a) continue;
    merged.push({ ...s, startSec: a, endSec: b });
  }
  merged.sort((a, b) => Number(a.startSec || 0) - Number(b.startSec || 0));

  const MIN_SEG_DUR = 0.26;
  const MAX_GAP_MERGE = 0.12;
  const normalized = [];
  for (const s of merged) {
    const last = normalized[normalized.length - 1];
    if (!last) {
      normalized.push({ ...s });
      continue;
    }
    const gap = Number(s.startSec || 0) - Number(last.endSec || 0);
    const curDur = Number(last.endSec || 0) - Number(last.startSec || 0);
    if (gap >= 0 && gap <= MAX_GAP_MERGE && curDur < MIN_SEG_DUR) {
      last.endSec = Math.max(Number(last.endSec || 0), Number(s.endSec || 0));
      continue;
    }
    normalized.push({ ...s });
  }
  const outSegs = normalized.length ? normalized : segs;

  const totalDur = outSegs.reduce((sum, s) => sum + Math.max(0.01, Number(s.endSec || 0) - Number(s.startSec || 0)), 0);
  const cpsRaw = srcChars.length / Math.max(0.01, totalDur);
  const charsPerSec = Math.max(6, Math.min(22, cpsRaw));
  const weightList = outSegs.map((s) => {
    const dur = Math.max(0.01, Number(s.endSec || 0) - Number(s.startSec || 0));
    const textLen = Math.max(1, Array.from(normalizeSubtitlePlainText(s.text)).length);
    const durWeight = dur * charsPerSec;
    return Math.max(1, textLen * 0.85 + durWeight * 0.15);
  });
  const totalWeight = weightList.reduce((sum, item) => sum + Math.max(1, Number(item || 0) || 0), 0);

  let cursor = 0;
  const takeChars = (count) => {
    const n = Math.max(0, Math.min(srcChars.length - cursor, Number(count || 0) || 0));
    if (n <= 0) return "";
    const chunk = srcChars.slice(cursor, cursor + n).join("");
    cursor += n;
    return chunk;
  };

  for (let i = 0; i < outSegs.length; i += 1) {
    const s = outSegs[i];
    const weight = Math.max(1, Number(weightList[i] || 0) || 0);
    let want = Math.round((srcChars.length * weight) / Math.max(1, totalWeight));
    if (want <= 0) want = 1;
    const remainingSegs = outSegs.length - i;
    const remainingChars = srcChars.length - cursor;
    if (remainingSegs <= 1) want = remainingChars;
    else want = Math.min(want, Math.max(1, remainingChars - (remainingSegs - 1)));

    let chunk = takeChars(want);
    if (chunk.length > maxBlockChars) {
      cursor -= Math.max(0, chunk.length - maxBlockChars);
      chunk = chunk.slice(0, maxBlockChars);
    }
    s.text = String(chunk || "").trim();
  }
  if (cursor < srcChars.length && outSegs.length) {
    outSegs[outSegs.length - 1].text = String(outSegs[outSegs.length - 1].text || "") + srcChars.slice(cursor).join("");
  }
  return outSegs;
}

function decodeSubtitleFontName(v) {
  const raw = String(v || "").trim();
  if (!raw) return "Microsoft YaHei";
  const decoded = (() => {
    try {
      return decodeURIComponent(raw);
    } catch {
      return raw;
    }
  })();
  const base = decoded.split(/[/\\]/).pop() || decoded;
  const noExt = base.replace(/\.(ttf|otf|ttc)$/i, "");
  return noExt || "Microsoft YaHei";
}

function hexToAssColor(hex, alpha00toFF = 0) {
  const s = String(hex || "").trim();
  const m = s.match(/^#?([0-9a-fA-F]{6})$/);
  const a = Math.max(0, Math.min(255, Number(alpha00toFF || 0) || 0));
  if (!m) return `&H${a.toString(16).padStart(2, "0").toUpperCase()}FFFFFF`;
  const h = m[1].toLowerCase();
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `&H${a.toString(16).padStart(2, "0").toUpperCase()}${b.toString(16).padStart(2, "0").toUpperCase()}${g
    .toString(16)
    .padStart(2, "0")
    .toUpperCase()}${r.toString(16).padStart(2, "0").toUpperCase()}`;
}

function sanitizeAssText(s) {
  return String(s || "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/\n/g, "\\N")
    .replace(/[\u0000-\u001f]/g, " ")
    .replace(/[\u200B-\u200F\uFEFF]/g, "")
    .replace(/[{}]/g, "")
    .replace(/\\/g, "");
}

function buildAssWithTemplate(segments, { playResX, playResY, durationSec, template } = {}) {
  const x = Math.max(0, Number(playResX || 720) || 720);
  const y = Math.max(0, Number(playResY || 1280) || 1280);
  const dur = Number(durationSec || 0) || 0;
  const segs = Array.isArray(segments) ? segments : [];

  const tpl = template && typeof template === "object" ? template : {};
  const body = tpl.body && typeof tpl.body === "object" ? tpl.body : {};
  const title = tpl.title && typeof tpl.title === "object" ? tpl.title : {};
  const keywordFx = tpl.keywordFx && typeof tpl.keywordFx === "object" ? tpl.keywordFx : {};
  const keywordMap = tpl.keywordMap && typeof tpl.keywordMap === "object" ? tpl.keywordMap : null;

  const bodyPos = String(body.pos || "bottom");
  const bodyAlign = bodyPos === "top" ? 8 : bodyPos === "middle" ? 5 : 2;
  const bodyMarginPct = Math.max(0, Math.min(60, Number(body.marginVPct ?? 34) || 34));
  const bodyMarginV = Math.round(y * (bodyMarginPct / 100));
  const bodyFont = decodeSubtitleFontName(body.font);
  const bodyFontSize = Math.max(18, Math.min(96, Number(body.fontSize || 44) || 44));
  const bodyLineCount = Math.max(1, Math.min(3, Number(body.lineCount || 2) || 2));
  const bodyMaxChars = Math.max(6, Math.min(24, Number(body.maxChars || 14) || 14));
  const bodyGapPx = Math.round(y * (Math.max(0, Math.min(30, Number(body.lineGapPct || 4) || 4)) / 100));
  const bodyLetterSpacing = Math.max(0, Math.min(20, Number(body.letterSpacing || 0) || 0));
  const bodyBold = body.bold !== false ? 1 : 0;
  const bodyShadow = body.shadow !== false ? 2 : 0;
  const bodyOutline = Math.max(0, Math.min(12, Number(body.outline ?? 3) || 3));
  const bodyPrimary = hexToAssColor(body.color || "#ffffff", 0);
  const bodyOutlineColor = hexToAssColor(body.outlineColor || "#101010", 0);
  const bodyBack = "&H64000000";

  const headerRows = [
    "[Script Info]",
    "ScriptType: v4.00+",
    "Collisions: Normal",
    `PlayResX: ${x}`,
    `PlayResY: ${y}`,
    "ScaledBorderAndShadow: yes",
    "",
    "[V4+ Styles]",
    "Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding",
    `Style: Body,${bodyFont},${bodyFontSize},${bodyPrimary},&H000000FF,${bodyOutlineColor},${bodyBack},${bodyBold},0,0,0,100,100,${bodyLetterSpacing},0,1,${bodyOutline},${bodyShadow},5,40,40,0,1`
  ];

  const rows = [];

  const maxEnd = segs.reduce((mx, s) => Math.max(mx, Number(s?.endSec || 0) || 0), 0);
  const titleEnd = formatAssTime(dur > 0 ? dur : Math.max(0.01, maxEnd || 0.01));

  const titleEnable = title.enable !== false;
  const titleText = String(title.text || "").trim();
  if (titleEnable && titleText) {
    const lineCount = Math.max(1, Math.min(3, Number(title.lineCount || 2) || 2));
    const maxChars = Math.max(8, Math.min(20, Number(title.maxChars || 12) || 12));
    const gapPct = Math.max(0, Math.min(30, Number(title.lineGapPct || 5) || 5));
    const titleLetterSpacing = Math.max(0, Math.min(20, Number(title.letterSpacing || 0) || 0));
    const topPct = Math.max(0, Math.min(30, Number(title.topMarginPct || 10) || 10));
    const gapPx = Math.round(y * (gapPct / 100));
    const topBasePx = Math.round(y * (topPct / 100));

    const lines = wrapTextToLines(cleanSubtitleTextForAss(titleText), maxChars).slice(0, lineCount);
    while (lines.length < lineCount) lines.push("");

    const styles = Array.isArray(title.lines) ? title.lines : [];
    for (let i = 0; i < lineCount; i += 1) {
      const s = styles[i] && typeof styles[i] === "object" ? styles[i] : {};
      const font = decodeSubtitleFontName(s.font);
      const fs = Math.max(18, Math.min(140, Number(s.fontSize || (i === 0 ? 64 : 56)) || 60));
      const bold = s.bold !== false ? 1 : 0;
      const shadow = s.shadow !== false ? 2 : 0;
      const outline = Math.max(0, Math.min(12, Number(s.outline ?? 4) || 4));
      const primary = hexToAssColor(s.color || (i === 0 ? "#b30b08" : "#ffffff"), 0);
      const ocolor = hexToAssColor(s.outlineColor || "#000000", 0);
      const mv = topBasePx + i * (fs + gapPx);
      headerRows.push(
        `Style: Title${i + 1},${font},${fs},${primary},&H000000FF,${ocolor},&H00000000,${bold},0,0,0,100,100,${titleLetterSpacing},0,1,${outline},${shadow},8,40,40,${mv},1`
      );
    }
    for (let i = 0; i < lineCount; i += 1) {
      const txt = String(lines[i] || "").trim();
      if (!txt) continue;
      rows.push(`Dialogue: 0,0:00:00.00,${titleEnd},Title${i + 1},,0,0,0,,${sanitizeAssText(txt)}`);
    }
  }

  headerRows.push("", "[Events]", "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text");

  const escapeRegex = (s) => String(s || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const pickKwList = (k) => {
    const arr = keywordMap && Array.isArray(keywordMap?.[k]) ? keywordMap[k] : [];
    return arr.map((x) => String(x || "").trim()).filter(Boolean);
  };
  const buildAssOverride = (s) => {
    const font = decodeSubtitleFontName(s?.font);
    const fs = Math.max(12, Math.min(200, Number(s?.fontSize || 0) || 0));
    const bold = s?.bold === true ? 1 : 0;
    const shadow = s?.shadow === true ? 2 : 0;
    const outline = Math.max(0, Math.min(20, Number(s?.outline || 0) || 0));
    const color = hexToAssColor(s?.color || "#ffffff", 0);
    const ocolor = hexToAssColor(s?.outlineColor || "#000000", 0);
    const parts = [];
    if (font) parts.push(`\\fn${font}`);
    if (fs) parts.push(`\\fs${Math.round(fs)}`);
    parts.push(`\\b${bold}`);
    parts.push(`\\shad${shadow}`);
    parts.push(`\\bord${Math.round(outline)}`);
    parts.push(`\\1c${color}`);
    parts.push(`\\3c${ocolor}`);
    return `{${parts.join("")}}`;
  };
  const applyKeywordFx = (text) => {
    if (!keywordFx || keywordFx.enable !== true) return text;
    if (!keywordMap) return text;
    const groups = [
      { key: "重点词/成语词", style: keywordFx?.groups?.["重点词/成语词"] },
      { key: "描述词", style: keywordFx?.groups?.["描述词"] },
      { key: "行动词", style: keywordFx?.groups?.["行动词"] },
      { key: "情感词", style: keywordFx?.groups?.["情感词"] }
    ];
    const dict = [];
    for (const g of groups) {
      if (!g?.style) continue;
      const words = pickKwList(g.key);
      for (const w of words) dict.push({ w, key: g.key, style: g.style });
    }
    dict.sort((a, b) => String(b.w).length - String(a.w).length);
    const raw = String(text || "");
    if (!raw.trim() || !dict.length) return raw;

    const ranges = [];
    const taken = (i) => ranges.some((r) => i >= r.s && i < r.e);
    for (const it of dict) {
      const w = String(it.w || "");
      if (!w) continue;
      const re = new RegExp(escapeRegex(w), "g");
      let m;
      while ((m = re.exec(raw))) {
        const s = m.index;
        const e = s + w.length;
        if (ranges.some((r) => !(e <= r.s || s >= r.e))) continue;
        if (taken(s) || taken(e - 1)) continue;
        ranges.push({ s, e, style: it.style });
      }
    }
    if (!ranges.length) return raw;
    ranges.sort((a, b) => a.s - b.s);
    let out = "";
    let cur = 0;
    for (const r of ranges) {
      out += raw.slice(cur, r.s);
      out += `${buildAssOverride(r.style)}${raw.slice(r.s, r.e)}{\\rBody}`;
      cur = r.e;
    }
    out += raw.slice(cur);
    return out;
  };

  segs.forEach((s) => {
    const segStartSec = Math.max(0, Number(s?.startSec || 0) || 0);
    const segEndSec = Math.max(segStartSec + 0.01, Number(s?.endSec || 0) || 0);
    const cleaned = cleanSubtitleTextForAss(s.text);
    if (!cleaned) return;
    const allLines0 = wrapTextToLines(cleaned, bodyMaxChars);
    const allLines = allLines0.length ? allLines0 : [cleaned].filter(Boolean);
    if (!allLines.length) return;

    const blocks = [];
    for (let i = 0; i < allLines.length; i += bodyLineCount) {
      blocks.push(allLines.slice(i, i + bodyLineCount));
    }

    const segDur = Math.max(0.01, segEndSec - segStartSec);
    const blockDur = segDur / Math.max(1, blocks.length);

    blocks.forEach((blkLines, blockIdx) => {
      const bs = segStartSec + blockIdx * blockDur;
      const be = blockIdx === blocks.length - 1 ? segEndSec : segStartSec + (blockIdx + 1) * blockDur;
      const start = formatAssTime(bs);
      const end = formatAssTime(Math.max(bs + 0.01, be));

      const blockHeight = blkLines.length * bodyFontSize + Math.max(0, blkLines.length - 1) * bodyGapPx;
      const startY =
        bodyPos === "top"
          ? bodyMarginV + Math.round(bodyFontSize * 0.92)
          : bodyPos === "middle"
            ? Math.round(y / 2 - blockHeight / 2 + bodyFontSize * 0.92)
            : Math.round(y - bodyMarginV - blockHeight + bodyFontSize * 0.92);
      blkLines.forEach((line, idx) => {
        const yPos = Math.round(startY + idx * (bodyFontSize + bodyGapPx));
        const txt = sanitizeAssText(line);
        if (!txt) return;
        rows.push(`Dialogue: 0,${start},${end},Body,,0,0,0,,{\\pos(${Math.round(x / 2)},${yPos})}${txt}`);
      });
    });
  });

  return `${headerRows.join("\n")}\n${rows.join("\n")}\n`;
}

function scaleSubtitleTemplateForVideo(template, { playResX, playResY } = {}) {
  const tpl = template && typeof template === "object" ? JSON.parse(JSON.stringify(template)) : {};
  const base = tpl.baseRes && typeof tpl.baseRes === "object" ? tpl.baseRes : {};
  const bw = Math.max(1, Number(base.w || 1080) || 1080);
  const bh = Math.max(1, Number(base.h || 1920) || 1920);
  const x = Math.max(1, Number(playResX || 1080) || 1080);
  const y = Math.max(1, Number(playResY || 1920) || 1920);
  const s = Math.max(0.2, Math.min(4.0, Math.min(x / bw, y / bh)));

  const scaleNum = (v, { min = 0, max = 1e9 } = {}) => {
    const n = Number(v);
    if (!Number.isFinite(n)) return v;
    return Math.max(min, Math.min(max, n * s));
  };

  if (tpl.body && typeof tpl.body === "object") {
    tpl.body.fontSize = scaleNum(tpl.body.fontSize, { min: 10, max: 200 });
    tpl.body.outline = scaleNum(tpl.body.outline, { min: 0, max: 24 });
    tpl.body.letterSpacing = scaleNum(tpl.body.letterSpacing, { min: 0, max: 40 });
  }
  if (tpl.title && typeof tpl.title === "object") {
    tpl.title.letterSpacing = scaleNum(tpl.title.letterSpacing, { min: 0, max: 40 });
    if (Array.isArray(tpl.title.lines)) {
      tpl.title.lines = tpl.title.lines.map((ln) => {
        if (!ln || typeof ln !== "object") return ln;
        return { ...ln, fontSize: scaleNum(ln.fontSize, { min: 10, max: 260 }), outline: scaleNum(ln.outline, { min: 0, max: 30 }) };
      });
    }
  }
  if (tpl.keywordFx && typeof tpl.keywordFx === "object") {
    const groups = tpl.keywordFx.groups && typeof tpl.keywordFx.groups === "object" ? tpl.keywordFx.groups : {};
    const nextGroups = {};
    for (const [k, v] of Object.entries(groups)) {
      if (!v || typeof v !== "object") continue;
      nextGroups[k] = { ...v, fontSize: scaleNum(v.fontSize, { min: 10, max: 260 }), outline: scaleNum(v.outline, { min: 0, max: 30 }) };
    }
    tpl.keywordFx.groups = nextGroups;
  }
  return tpl;
}

function buildCoverAssText(template, { playResX, playResY, titleText, subTitleText } = {}) {
  const x = Math.max(240, Number(playResX || 1080) || 1080);
  const y = Math.max(240, Number(playResY || 1440) || 1440);
  const tpl = template && typeof template === "object" ? template : {};
  const main = tpl.main && typeof tpl.main === "object" ? tpl.main : {};
  const sub = tpl.sub && typeof tpl.sub === "object" ? tpl.sub : {};
  const wrapLines = (conf, text, fallbackMax, fallbackLines) => {
    const raw = String(text || "").trim();
    if (!raw) return [];
    const maxChars = Math.max(4, Math.min(30, Number(conf?.maxChars || fallbackMax) || fallbackMax));
    const lineCount = Math.max(1, Math.min(6, Number(conf?.lineCount || fallbackLines) || fallbackLines));
    return wrapTextToLines(raw, maxChars).slice(0, lineCount);
  };
  const mainLines = wrapLines(main, titleText, 8, 2);
  const subLinesRaw = wrapLines(sub, subTitleText, 14, 2);
  const subLines = sub.enable === true && mainLines.length >= 2 ? subLinesRaw : [];
  if (!mainLines.length && !subLines.length) return "";

  const alignMap = {
    left: 7,
    center: 8,
    right: 9
  };
  const headerRows = [
    "[Script Info]",
    "ScriptType: v4.00+",
    "Collisions: Normal",
    `PlayResX: ${x}`,
    `PlayResY: ${y}`,
    "ScaledBorderAndShadow: yes",
    "",
    "[V4+ Styles]",
    "Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding"
  ];
  const rows = [];
  const pushBlock = (styleName, conf, lines, fallback = {}) => {
    if (!Array.isArray(lines) || !lines.length) return;
    const font = decodeSubtitleFontName(conf.font || fallback.font || "Microsoft YaHei");
    const fontSize = Math.max(10, Math.min(300, Number(conf.fontSize || fallback.fontSize || 60) || 60));
    const bold = conf.bold !== false ? 1 : 0;
    const shadow = conf.shadow !== false ? 2 : 0;
    const outline = Math.max(0, Math.min(30, Number(conf.outline || fallback.outline || 0) || 0));
    const color = hexToAssColor(conf.color || fallback.color || "#ffffff", 0);
    const outlineColor = hexToAssColor(conf.outlineColor || fallback.outlineColor || "#000000", 0);
    const align = alignMap[String(conf.align || fallback.align || "center")] || 8;
    const spacing = Math.max(0, Math.min(20, Number(conf.letterSpacing || fallback.letterSpacing || 0) || 0));
    const gapPx = Math.round(y * (Math.max(0, Math.min(30, Number(conf.lineGapPct || fallback.lineGapPct || 4) || 4)) / 100));
    const posX = Math.round((Math.max(0, Math.min(100, Number(conf.xPct ?? fallback.xPct ?? 50) || 50)) / 100) * x);
    const posY = Math.round((Math.max(0, Math.min(100, Number(conf.yPct ?? fallback.yPct ?? 10) || 10)) / 100) * y);
    headerRows.push(
      `Style: ${styleName},${font},${fontSize},${color},&H000000FF,${outlineColor},&H00000000,${bold},0,0,0,100,100,${spacing},0,1,${outline},${shadow},${align},40,40,40,1`
    );
    lines.forEach((line, idx) => {
      const yPos = posY + idx * (fontSize + gapPx);
      rows.push(`Dialogue: 0,0:00:00.00,0:00:10.00,${styleName},,0,0,0,,{\\pos(${posX},${yPos})}${sanitizeAssText(line)}`);
    });
  };

  pushBlock("Main", main, mainLines, { fontSize: 98, color: "#f5c400", outline: 6, align: "center", xPct: 50, yPct: 10 });
  pushBlock("Sub", sub, subLines, { fontSize: 54, color: "#ffffff", outline: 4, align: "center", xPct: 50, yPct: 76 });
  headerRows.push("", "[Events]", "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text");
  return `${headerRows.join("\n")}\n${rows.join("\n")}\n`;
}

async function handleSubBgmRenderRequest(event, payload) {
  const taskId = String(payload?.taskId || "").trim() || `subbgm_${Date.now()}_${crypto.randomBytes(3).toString("hex")}`;
  const task = { taskId, proc: null, canceled: false, tool: "subbgm.render", status: "running", progress: 1, message: "开始字幕和背景音乐合成" };
  _subBgmTasks.set(taskId, task);
  updateLiveTaskState(task);
  try {
    const externalTaskId = String(payload?.taskId || "").trim();
    const inputVideoRaw = String(payload?.videoPath || "").trim().replace(/^file:\/\//i, "");
    const bgmRaw = String(payload?.bgmPath || "").trim().replace(/^file:\/\//i, "");
    const bgmEnable = payload?.bgmEnable === true && !!bgmRaw;
    const sourceVolPct = Math.max(0, Math.min(300, Number(payload?.sourceVolPct ?? 100) || 100));
    const bgmVolPct = Math.max(0, Math.min(100, Number(payload?.bgmVolPct ?? 10) || 10));
    const needSubtitle = payload?.subtitleEnable === true;
    const asrModelChoice = payload?.asrModelChoice && typeof payload.asrModelChoice === "object" ? payload.asrModelChoice : null;
    const preferredSubtitleText = String(payload?.preferredSubtitleText || "").trim();
    const titleText = String(payload?.titleText || "").trim();
    const subtitleTemplate = payload?.subtitleTemplate && typeof payload.subtitleTemplate === "object" ? payload.subtitleTemplate : null;
    const keywordMap = payload?.keywordMap && typeof payload.keywordMap === "object" ? payload.keywordMap : null;
    const segmentsOverrideRaw = Array.isArray(payload?.segmentsOverride) ? payload.segmentsOverride : null;
    const storyboardRaw = payload?.storyboard && typeof payload.storyboard === "object" ? payload.storyboard : null;
    const pipConfigRaw = payload?.pipConfig && typeof payload.pipConfig === "object" ? payload.pipConfig : null;

    const jobId = externalTaskId || taskId;
    const sendLog = (level, message) => {
      try {
        event?.sender?.send?.("subBgm:log", { taskId, level, message: String(message || "") });
      } catch {}
    };
    const sendProgress = (progress, message) => {
      const p = Math.max(0, Math.min(100, Number(progress || 0) || 0));
      try {
        event?.sender?.send?.("subBgm:progress", { taskId, progress: p, message: String(message || "") });
      } catch {}
      updateLiveTaskState(task, {
        status: p >= 100 ? "completed" : "running",
        progress: p,
        message: String(message || task.message || "")
      });
    };

    sendLog("info", "开始合成（字幕烧录 + 背景音乐混音）...");
    sendProgress(1, "准备任务");

    if (!inputVideoRaw) {
      sendLog("warn", "参数 videoPath 为空");
      sendProgress(0, "合成失败");
      return { ok: false, message: "empty videoPath" };
    }
    if (!fs.existsSync(inputVideoRaw)) {
      sendLog("warn", `视频文件不存在：${inputVideoRaw}`);
      sendProgress(0, "合成失败");
      return { ok: false, message: `video not found: ${inputVideoRaw}` };
    }
    if (bgmEnable && !fs.existsSync(bgmRaw)) {
      sendLog("warn", `背景音乐文件不存在：${bgmRaw}`);
      sendProgress(0, "合成失败");
      return { ok: false, message: `bgm not found: ${bgmRaw}` };
    }

    sendProgress(2, "扫描本地模型包");
    const scan = scanProjectBundles();
    const segmentsOverride = (Array.isArray(segmentsOverrideRaw) ? segmentsOverrideRaw : [])
      .map((seg) => ({
        startSec: Number(seg?.startSec || 0) || 0,
        endSec: Number(seg?.endSec || 0) || 0,
        text: String(seg?.text || "")
      }))
      .filter((x) => Number.isFinite(x.startSec) && Number.isFinite(x.endSec) && x.endSec > x.startSec);
    const hasSegmentsOverride = segmentsOverride.length > 0;
    const useCloudSubtitleAsr = needSubtitle && !hasSegmentsOverride && String(asrModelChoice?.source || "").trim().toLowerCase() === "cloud";
    const asrBundle = scan.find((b) => b.type === "ASR");
    if (needSubtitle && !hasSegmentsOverride && !useCloudSubtitleAsr && !asrBundle) {
      sendLog("warn", buildMissingBundleMessage("ASR"));
      sendProgress(0, "合成失败");
      return { ok: false, message: buildMissingBundleMessage("ASR") };
    }
    if (useCloudSubtitleAsr) {
      if (!String(asrModelChoice?.endpoint || "").trim()) {
        sendLog("warn", "当前云端字幕识别模型未配置 endpoint");
        sendProgress(0, "合成失败");
        return { ok: false, message: "当前云端字幕识别模型未配置 endpoint" };
      }
      if (!String(asrModelChoice?.apiKey || "").trim()) {
        sendLog("warn", "当前云端字幕识别模型未配置 API Key");
        sendProgress(0, "合成失败");
        return { ok: false, message: "当前云端字幕识别模型未配置 API Key" };
      }
      if (!String(asrModelChoice?.modelId || asrModelChoice?.model || "").trim()) {
        sendLog("warn", "当前云端字幕识别模型未配置 modelId");
        sendProgress(0, "合成失败");
        return { ok: false, message: "当前云端字幕识别模型未配置 modelId" };
      }
    }

    sendProgress(2, "定位 ffmpeg");
    const ffmpegExe = pickFfmpegExeFromBundles();
    if (!ffmpegExe || !fs.existsSync(ffmpegExe)) {
      sendLog("warn", "ffmpeg.exe not found");
      sendProgress(0, "合成失败");
      return { ok: false, message: "ffmpeg.exe not found" };
    }

    const outRoot = resolveVideoEditsRoot();
    ensureDir(outRoot);
    let jobDir = path.join(outRoot, jobId);
    let outPath = path.join(jobDir, "result.mp4");

    try {
      const inAbs = path.resolve(inputVideoRaw);
      const rootAbs = path.resolve(outRoot);
      if (inAbs.startsWith(rootAbs)) {
        const parent = path.dirname(inAbs);
        if (fs.existsSync(parent)) {
          const rendersDir = path.join(parent, "renders");
          ensureDir(rendersDir);
          jobDir = rendersDir;
          outPath = path.join(rendersDir, `${jobId}.mp4`);
        }
      }
    } catch {}
    ensureDir(jobDir);

    sendProgress(3, "探测视频信息");
    const baseMeta = await probeVideoMetaViaFfmpeg(ffmpegExe, inputVideoRaw);
    const w = Number(baseMeta?.width || 720) || 720;
    const h = Number(baseMeta?.height || 1280) || 1280;
    const hasAudio = baseMeta?.hasAudio === true;
    const baseDuration = Number(baseMeta?.durationSec || 0) || 0;
    sendLog("info", `输入：${inputVideoRaw}`);
    sendLog("info", `视频：${w}x${h}，时长：${baseDuration ? `${baseDuration.toFixed(2)}s` : "未知"}`);

    let subtitleSegments = [];
    let assPath = "";
    if (needSubtitle) {
      let segmentsRaw = [];
      if (hasSegmentsOverride) {
        sendProgress(18, "使用已有分段字幕");
        segmentsRaw = segmentsOverride;
        sendLog("info", `字幕来源：已绑定分段（条数：${segmentsRaw.length}）`);
      } else {
        sendProgress(8, "准备 ASR（抽取音频）");
        const tmpDir = path.join(os.tmpdir(), "ipfactory", "sub_bgm");
        ensureDir(tmpDir);
        const audioPath = path.join(tmpDir, `${jobId}.wav`);

        await runFfmpeg(ffmpegExe, ["-y", "-i", inputVideoRaw, "-vn", "-ac", "1", "-ar", "16000", "-c:a", "pcm_s16le", audioPath], {
          cwd: tmpDir,
          isCanceled: () => task.canceled === true,
          task,
          onStderr: (s) => {
            const t = String(s || "");
            if (/error|Invalid|failed/i.test(t)) sendLog("warn", t.trim());
          }
        });
        sendLog("info", `音频抽取完成：${audioPath}`);
        const configPath = path.join(tmpDir, `asr_${jobId}.json`);
        if (useCloudSubtitleAsr) {
        sendProgress(18, "ASR 识别字幕（云端模型）");
        sendLog("info", `云端字幕识别模型：${String(asrModelChoice?.label || asrModelChoice?.modelId || asrModelChoice?.model || "未命名模型")}`);
        const cloudResult = await transcribeSubtitleByCloudModel(audioPath, asrModelChoice, {
          durationSec: baseDuration,
          onLog: (level, message) => sendLog(level, message)
        });
        segmentsRaw = Array.isArray(cloudResult?.segments) ? cloudResult.segments : [];
        const cloudText = String(cloudResult?.text || "").trim();
        const cloudTextLen = Array.from(cloudText.replace(/\s+/g, "")).length;
        if (segmentsRaw.length <= 1 && cloudTextLen > 12) {
          const rebuiltSegments = buildApproxSubtitleSegmentsFromText(cloudText, { durationSec: baseDuration });
          if (rebuiltSegments.length > segmentsRaw.length) {
            segmentsRaw = rebuiltSegments;
            sendLog("warn", `当前云端 ASR 返回的句级时间轴过少（${Array.isArray(cloudResult?.segments) ? cloudResult.segments.length : 0} 条），已按识别全文自动重建为 ${rebuiltSegments.length} 条字幕。`);
          }
        }
        if (cloudResult?.approximateSegments === true) {
          sendLog("warn", "当前云端模型未直接返回完整时间轴，已按识别文本近似生成字幕时间段。");
        }
        } else {
        const bundleDir = asrBundle.bundleDir;
        const pythonExe = path.join(bundleDir, "runtime", "asr", "python", "python.exe");
        const asrScript = path.join(bundleDir, "services", "asr_server.py");
        if (!fs.existsSync(pythonExe)) {
          sendLog("warn", `python 不存在：${pythonExe}`);
          sendProgress(0, "合成失败");
          return { ok: false, message: `python 不存在：${pythonExe}` };
        }
        if (!fs.existsSync(asrScript)) {
          sendLog("warn", `asr_server.py 不存在：${asrScript}`);
          sendProgress(0, "合成失败");
          return { ok: false, message: `asr_server.py 不存在：${asrScript}` };
        }
        fs.writeFileSync(
          configPath,
          JSON.stringify(
            {
              id: jobId,
              modelConfig: { audio: audioPath, param: { language: "auto", use_itn: true } }
            },
            null,
            2
          ),
          "utf-8"
        );

        sendProgress(18, "ASR 识别字幕（本地模型）");
        const asrStartAt = Date.now();
        let asrBeat = null;
        try {
          asrBeat = setInterval(() => {
            const sec = Math.floor((Date.now() - asrStartAt) / 1000);
            if (sec > 0 && sec % 5 === 0) sendLog("info", `ASR 识别中... 已等待 ${sec}s`);
          }, 1000);
        } catch {}
        let lastAsrLogAt = 0;
        let stdout = "";
        let stderr = "";
        try {
          const asrRes = await runAsrCommand(pythonExe, asrScript, configPath, {
            cwd: bundleDir,
            isCanceled: () => task.canceled === true,
            task,
            onStdout: (s) => {
              const now = Date.now();
              if (now - lastAsrLogAt < 800) return;
              lastAsrLogAt = now;
              const txt = String(s || "").trim();
              if (txt) sendLog("debug", txt.length > 260 ? `${txt.slice(0, 260)}...` : txt);
            },
            onStderr: (s) => {
              const txt = String(s || "").trim();
              if (txt) sendLog("warn", txt.length > 260 ? `${txt.slice(0, 260)}...` : txt);
            }
          });
          stdout = String(asrRes?.stdout || "");
          stderr = String(asrRes?.stderr || "");
        } catch (asrErr) {
          throw asrErr;
        } finally {
          try {
            if (asrBeat) clearInterval(asrBeat);
          } catch {}
        }
        if (stderr) sendLog("warn", String(stderr || "").trim());
          segmentsRaw = parseAigcPanelSubtitleSegments(stdout);
        }
      }
      const tplBody = subtitleTemplate?.body && typeof subtitleTemplate.body === "object" ? subtitleTemplate.body : {};
      const smartMaxChars = Math.max(6, Math.min(24, Number(tplBody?.maxChars || 14) || 14));
      const smartMaxLines = Math.max(1, Math.min(3, Number(tplBody?.lineCount || 2) || 2));
      const avOffset = Number(baseMeta?.avOffsetSec || 0) || 0;
      const shiftSec = Math.abs(avOffset) >= 0.03 && Math.abs(avOffset) <= 10 ? avOffset : 0;
      let segments = segmentsRaw;
      if (shiftSec) {
        segments = (Array.isArray(segments) ? segments : [])
          .map((seg) => {
            const a = Math.max(0, Number(seg?.startSec || 0) + shiftSec);
            const b = Math.max(0, Number(seg?.endSec || 0) + shiftSec);
            return { ...seg, startSec: a, endSec: b };
          })
          .filter((x) => Number.isFinite(x.startSec) && Number.isFinite(x.endSec) && x.endSec > x.startSec);
        sendLog("info", `检测到音视频时间轴偏移 ${shiftSec.toFixed(3)}s，已自动平移字幕以对齐原视频说话时间。`);
      }
      segments = normalizeSubtitleSegmentsByTiming(segments, { maxGapSec: 0.18, minSegDurSec: 0.4, maxSegDurSec: 2.8, minTextChars: 3 });
      segments = padSubtitleSegmentEndTimes(segments, {
        durationSec: baseDuration,
        endPadSec: 0.18,
        minHoldSec: 0.75,
        minGapToNextSec: 0.04,
        keepUntilNextStartGapSec: 1.2
      });
      if (!segments.length) {
        sendLog("warn", "ASR 返回空字幕");
        sendProgress(0, "合成失败");
        return { ok: false, message: "ASR 返回空字幕" };
      }
      sendLog("info", `字幕时间轴分段数：${segments.length}`);
      sendLog("info", "字幕停留时间已按相邻口播节奏自动延展，避免字幕过早消失。");
      const smartText = normalizeSubtitlePlainText(preferredSubtitleText);
      if (preferredSubtitleText && smartText && segments.length) {
        const asrText = segments.map((s) => String(s?.text || "")).join("");
        const sim = calcBigramDiceSimilarity(smartText, asrText);
        const asrLen = Math.max(1, Array.from(String(asrText || "").replace(/\s+/g, "")).length);
        const smartLen = Math.max(0, Array.from(String(smartText || "").replace(/\s+/g, "")).length);
        const lenRatio = smartLen / asrLen;
        const lengthMatched = lenRatio >= 0.7 && lenRatio <= 1.35;
        sendLog("info", `智能字幕匹配度=${Number.isFinite(sim) ? sim.toFixed(2) : "0.00"}，长度比=${Number.isFinite(lenRatio) ? lenRatio.toFixed(2) : "0.00"}`);
        if (Number.isFinite(sim) && sim >= 0.45 && lengthMatched) {
          segments = applyPreferredSubtitleTextToSegments(segments, smartText, { maxCharsPerLine: smartMaxChars, maxLines: smartMaxLines });
          sendLog("info", `字幕文本来源：视频文案编辑（启用智能字幕）相似度=${sim.toFixed(2)}（已启用按口播时间切割）`);
        } else {
          sendLog("warn", `字幕文本来源：${useCloudSubtitleAsr ? "云端 ASR 原始识别" : "本地 ASR 原始识别"}（文案与口播差异过大，相似度=${Number.isFinite(sim) ? sim.toFixed(2) : "0.00"}，已自动回退）`);
        }
      } else {
        sendLog("info", `字幕文本来源：${useCloudSubtitleAsr ? "云端 ASR 原始识别" : "本地 ASR 原始识别"}`);
      }
      subtitleSegments = segments;

      const marginV = Math.round(h * 0.34);
      const fontSize = Math.round(Math.max(26, Math.min(56, h * 0.045)));
      const baseTpl = {
        baseRes: { w: 1080, h: 1920 },
        body: {
          pos: "bottom",
          font: "Microsoft YaHei",
          fontSize,
          bold: true,
          shadow: true,
          color: "#ffffff",
          outlineColor: "#101010",
          outline: 3,
          marginVPct: 34
        },
        title: { enable: false }
      };
      const mergedTpl0 = subtitleTemplate
        ? {
            baseRes:
              subtitleTemplate?.baseRes && typeof subtitleTemplate.baseRes === "object" ? { ...baseTpl.baseRes, ...subtitleTemplate.baseRes } : baseTpl.baseRes,
            body: { ...baseTpl.body, ...(subtitleTemplate?.body && typeof subtitleTemplate.body === "object" ? subtitleTemplate.body : {}) },
            title: { ...(subtitleTemplate?.title && typeof subtitleTemplate.title === "object" ? subtitleTemplate.title : {}) },
            keywordFx: subtitleTemplate?.keywordFx && typeof subtitleTemplate.keywordFx === "object" ? subtitleTemplate.keywordFx : null
          }
        : baseTpl;
      const mergedTpl = scaleSubtitleTemplateForVideo(mergedTpl0, { playResX: w, playResY: h });
      if (mergedTpl?.title && typeof mergedTpl.title === "object" && titleText) mergedTpl.title.text = titleText;
      if (keywordMap) mergedTpl.keywordMap = keywordMap;
      if (subtitleTemplate) {
        sendLog("info", `字幕模板：${String(subtitleTemplate?.name || subtitleTemplate?.id || "自定义模板")}`);
      } else {
        sendLog("info", "字幕模板：系统默认");
      }
      const ass = buildAssWithTemplate(segments, { playResX: w, playResY: h, durationSec: baseDuration, template: mergedTpl });
      assPath = path.join(jobDir, `${jobId}.ass`);
      fs.writeFileSync(assPath, ass, "utf-8");
      sendLog("info", `字幕生成完成：${assPath}（条数：${segments.length}）`);
    }
    if (!needSubtitle && hasSegmentsOverride) subtitleSegments = segmentsOverride;

    let vf = "";
    if (assPath) {
      const fontsDir = resolveProjectMediaDir("ziti");
      if (fontsDir && fs.existsSync(fontsDir)) vf = `ass='${escapeFfmpegSubtitlesPath(assPath)}':fontsdir='${escapeFfmpegSubtitlesPath(fontsDir)}'`;
      else vf = `ass='${escapeFfmpegSubtitlesPath(assPath)}'`;
    }
    const args = ["-y", "-i", inputVideoRaw];

    if (bgmEnable) {
      args.push("-stream_loop", "-1", "-i", bgmRaw);
      sendLog("info", `背景音乐：${bgmRaw}（音量：${bgmVolPct}%）`);
    }
    if (hasAudio) sendLog("info", `原视频音量：${sourceVolPct}%`);

    const storyboard = storyboardRaw?.enable === true ? storyboardRaw : null;
    const storyboardAssets = Array.isArray(storyboard?.assets) ? storyboard.assets : [];
    const storyboardBindings = storyboard?.bindings && typeof storyboard.bindings === "object" ? storyboard.bindings : {};
    const storyboardEnabled = storyboard?.enable === true && storyboardAssets.length > 0 && Object.keys(storyboardBindings).length > 0;
    const storyboardSegs = Array.isArray(subtitleSegments) ? subtitleSegments : [];
    if (storyboardEnabled && storyboardSegs.length <= 0) {
      sendLog("warn", "画中画已启用，但分段字幕为空（需要先生成分段字幕并绑定素材）");
      sendProgress(0, "合成失败");
      return { ok: false, message: "storyboard requires subtitle segments" };
    }
    const pipPos = String(pipConfigRaw?.pos || "tr").trim() || "tr";
    const pipScale = Math.max(0.1, Math.min(2.2, Number(pipConfigRaw?.scale ?? 0.35) || 0.35));
    const defaultXPct = pipPos.includes("r") ? 1 : 0;
    const defaultYPct = pipPos.includes("b") ? 1 : 0;

    const overlayItems = [];
    if (storyboardEnabled) {
      const assetMap = new Map(
        storyboardAssets
          .map((a) => {
            const id = String(a?.id || a?.path || "").trim();
            const p = String(a?.path || "").trim();
            const name = String(a?.name || "").trim();
            const scale = Math.max(0.1, Math.min(2.2, Number(a?.scale ?? pipScale) || pipScale));
            const xPct = Math.max(0, Math.min(1, Number(a?.xPct ?? defaultXPct) || defaultXPct));
            const yPct = Math.max(0, Math.min(1, Number(a?.yPct ?? defaultYPct) || defaultYPct));
            return id && p ? [id, { id, path: p, name, scale, xPct, yPct }] : null;
          })
          .filter(Boolean)
      );
      const grouped = new Map();
      Object.keys(storyboardBindings || {}).forEach((k) => {
        const idx = Number(k);
        if (!Number.isFinite(idx) || idx < 0) return;
        const seg = storyboardSegs[idx];
        if (!seg) return;
        const binding = storyboardBindings[k];
        const assetId = String(binding && typeof binding === "object" ? binding.assetId || "" : binding || "").trim();
        if (!assetId) return;
        const a = assetMap.get(assetId);
        if (!a) return;
        const s = Math.max(0, Number(seg?.startSec || 0) || 0);
        const e = Math.max(0, Number(seg?.endSec || 0) || 0);
        if (!(e > s)) return;
        const arr = grouped.get(assetId) || [];
        arr.push({ s, e });
        grouped.set(assetId, arr);
      });
      grouped.forEach((ranges, assetId) => {
        const a = assetMap.get(assetId);
        if (!a?.path || !fs.existsSync(a.path)) return;
        const ext = String(path.extname(a.path || "") || "").toLowerCase();
        const type =
          [".png", ".jpg", ".jpeg", ".webp"].includes(ext) ? "image" : [".gif"].includes(ext) ? "gif" : "video";
        overlayItems.push({
          assetId,
          path: a.path,
          name: a.name,
          type,
          scale: a.scale,
          xPct: a.xPct,
          yPct: a.yPct,
          ranges: Array.isArray(ranges) ? ranges : []
        });
      });
      if (!overlayItems.length) {
        sendLog("warn", "画中画已启用，但未解析到可用素材（素材路径无效或未绑定）");
        sendProgress(0, "合成失败");
        return { ok: false, message: "storyboard has no usable overlays" };
      }
    }
    if (overlayItems.length) {
      let nextIdx = bgmEnable ? 2 : 1;
      overlayItems.forEach((it) => {
        it.inputIndex = nextIdx++;
        if (it.type === "image") {
          args.push("-loop", "1", "-i", it.path);
        } else {
          args.push("-i", it.path);
        }
      });
      sendLog("info", `画中画：已绑定素材 ${overlayItems.length} 个`);
    }

    const filters = [];
    const mapVideo = (label) => args.push("-map", label || "0:v:0");
    const mapAudio = (label) => args.push("-map", label);

    const hasVideoFilters = !!vf || overlayItems.length > 0;
    let videoOutLabel = "0:v:0";
    if (vf) {
      filters.push(`[0:v]${vf}[v0]`);
      videoOutLabel = "[v0]";
    } else if (overlayItems.length) {
      filters.push(`[0:v]null[v0]`);
      videoOutLabel = "[v0]";
    }
    if (overlayItems.length) {
      overlayItems.forEach((it, idx) => {
        const ranges = Array.isArray(it.ranges) ? it.ranges : [];
        const enableExpr = ranges.map((r) => `between(t\\,${Number(r.s || 0).toFixed(3)}\\,${Number(r.e || 0).toFixed(3)})`).join("+") || "0";
        const itemScale = Math.max(0.1, Math.min(2.2, Number(it?.scale ?? pipScale) || pipScale));
        const itemW = Math.max(2, Math.round(w * itemScale));
        const itemX = `(main_w-overlay_w)*${Math.max(0, Math.min(1, Number(it?.xPct ?? defaultXPct) || defaultXPct))}`;
        const itemY = `(main_h-overlay_h)*${Math.max(0, Math.min(1, Number(it?.yPct ?? defaultYPct) || defaultYPct))}`;
        let overlayInputLabel = `[${it.inputIndex}:v]`;
        if (it.type === "gif") {
          filters.push(`[${it.inputIndex}:v]fps=15,scale=${itemW}:-1:flags=lanczos[ov${idx}]`);
          overlayInputLabel = `[ov${idx}]`;
        } else if (it.type === "video") {
          filters.push(`[${it.inputIndex}:v]scale=${itemW}:-1:flags=lanczos[ov${idx}]`);
          overlayInputLabel = `[ov${idx}]`;
        } else {
          filters.push(`[${it.inputIndex}:v]scale=${itemW}:-1[ov${idx}]`);
          overlayInputLabel = `[ov${idx}]`;
        }
        const out = `[v${idx + 1}]`;
        filters.push(`${videoOutLabel}${overlayInputLabel}overlay=${itemX}:${itemY}:eof_action=pass:repeatlast=0:enable='${enableExpr}'${out}`);
        videoOutLabel = out;
      });
    }

    if (bgmEnable) {
      const bgmVol = Math.max(0, Math.min(1.5, bgmVolPct / 100));
      const sourceVol = Math.max(0, Math.min(3, sourceVolPct / 100));
      if (hasAudio) {
        filters.push(`[0:a]aformat=sample_fmts=fltp:sample_rates=44100:channel_layouts=stereo,volume=${sourceVol},asplit=2[orig_mix][orig_sc]`);
        filters.push(`[1:a]aformat=sample_fmts=fltp:sample_rates=44100:channel_layouts=stereo,volume=${bgmVol}[bgm0]`);
        filters.push(`[bgm0][orig_sc]sidechaincompress=threshold=0.03:ratio=12:attack=20:release=250[bgm]`);
        filters.push(`[orig_mix][bgm]amix=inputs=2:duration=first:dropout_transition=2:normalize=0[aout]`);
        args.push("-filter_complex", filters.join(";"));
        mapVideo(hasVideoFilters ? videoOutLabel : "0:v:0");
        mapAudio("[aout]");
      } else {
        if (baseDuration && baseDuration > 0) {
          filters.push(`[1:a]aformat=sample_fmts=fltp:sample_rates=44100:channel_layouts=stereo,volume=${bgmVol},atrim=0:${Math.max(0.01, baseDuration.toFixed ? Number(baseDuration.toFixed(3)) : baseDuration)},asetpts=N/SR/TB[aout]`);
        } else {
          filters.push(`[1:a]aformat=sample_fmts=fltp:sample_rates=44100:channel_layouts=stereo,volume=${bgmVol}[aout]`);
        }
        args.push("-filter_complex", filters.join(";"));
        mapVideo(hasVideoFilters ? videoOutLabel : "0:v:0");
        mapAudio("[aout]");
      }
    } else if (hasVideoFilters || (hasAudio && sourceVolPct !== 100)) {
      if (hasAudio) {
        const sourceVol = Math.max(0, Math.min(3, sourceVolPct / 100));
        filters.push(`[0:a]aformat=sample_fmts=fltp:sample_rates=44100:channel_layouts=stereo,volume=${sourceVol}[aout]`);
      }
      args.push("-filter_complex", filters.join(";"));
      mapVideo(hasVideoFilters ? videoOutLabel : "0:v:0");
      if (hasAudio) mapAudio("[aout]");
    } else {
      mapVideo("0:v:0");
      if (hasAudio) mapAudio("0:a:0");
    }

    args.push("-c:v", "libx264", "-preset", "veryfast", "-crf", "20");
    if (bgmEnable || hasAudio) args.push("-c:a", "aac", "-b:a", "192k");
    if (bgmEnable && baseDuration && baseDuration > 0) args.push("-t", String(Math.max(0.01, baseDuration)));
    if (bgmEnable || overlayItems.length) args.push("-shortest");
    args.push("-hide_banner", "-nostats", "-progress", "pipe:2");
    args.push("-movflags", "+faststart", outPath);

    sendProgress(55, "FFmpeg 合成中...");
    let lastProg = -1;
    let lastTimeSec = -1;
    let lastProgAt = 0;
    let progBuf = "";
    const parseFfmpegTimeToSec = (text) => {
      const m = String(text || "").match(/\btime=(\d+):(\d+):(\d+(?:\.\d+)?)\b/);
      if (!m) return -1;
      const hh = Number(m[1] || 0);
      const mm = Number(m[2] || 0);
      const ss = Number(m[3] || 0);
      return hh * 3600 + mm * 60 + ss;
    };
    await runFfmpeg(ffmpegExe, args, {
      cwd: jobDir,
      isCanceled: () => task.canceled === true,
      task,
      onStderr: (s) => {
        const now = Date.now();
        const txt = String(s || "");
        if (/error|failed|Invalid/i.test(txt)) sendLog("warn", txt.trim());

        progBuf += txt;
        if (progBuf.length > 20000) progBuf = progBuf.slice(-20000);
        const parts = progBuf.split(/\r?\n/);
        progBuf = parts.pop() || "";
        let timeSecFromProgress = -1;
        let gotEnd = false;
        for (const line of parts) {
          const ln = String(line || "").trim();
          if (!ln) continue;
          const mm = ln.match(/^out_time_ms=(\d+)$/);
          if (mm) {
            timeSecFromProgress = Number(mm[1] || 0) / 1000000;
            continue;
          }
          const mt = ln.match(/^out_time=(\d+):(\d+):(\d+(?:\.\d+)?)$/);
          if (mt) {
            const hh = Number(mt[1] || 0);
            const mi = Number(mt[2] || 0);
            const ss = Number(mt[3] || 0);
            timeSecFromProgress = hh * 3600 + mi * 60 + ss;
          }
          if (ln === "progress=end") gotEnd = true;
        }

        if (gotEnd) {
          sendProgress(100, "收尾写文件中...");
          sendLog("info", "FFmpeg 编码结束，正在收尾写文件...");
        }

        const t = timeSecFromProgress >= 0 ? timeSecFromProgress : parseFfmpegTimeToSec(txt);
        if (t < 0) return;
        if (t === lastTimeSec) return;
        lastTimeSec = t;
        if (!baseDuration || baseDuration <= 0) {
          if (now - lastProgAt > 1200) {
            lastProgAt = now;
            sendProgress(60, `合成中...（${t.toFixed(1)}s）`);
          }
          return;
        }
        const pct = Math.max(0, Math.min(99, Math.floor((t / baseDuration) * 100)));
        if (pct === lastProg) return;
        if (now - lastProgAt < 300) return;
        lastProgAt = now;
        lastProg = pct;
        sendProgress(pct, `合成中...（${pct}%）`);
        if (pct % 10 === 0) sendLog("info", `FFmpeg 进度：${pct}%`);
      }
    });
    sendProgress(100, "合成完成");
    sendLog("info", `输出：${outPath}`);
    try {
      fs.writeFileSync(
        path.join(jobDir, `${jobId}.json`),
        JSON.stringify(
          {
            id: jobId,
            createdAt: Date.now(),
            type: "subtitle_bgm_render",
            inputVideo: inputVideoRaw,
            bgmEnable,
            bgmPath: bgmEnable ? bgmRaw : "",
            sourceVolPct,
            bgmVolPct,
            subtitleEnable: needSubtitle
          },
          null,
          2
        ),
        "utf-8"
      );
    } catch {}
    updateLiveTaskState(task, {
      status: "completed",
      progress: 100,
      message: "合成完成",
      result: { jobId, jobDir, outPath }
    });
    return { ok: true, taskId, jobId, jobDir, outPath };
  } catch (e) {
    try {
      const msg = String(e?.message || e);
      event?.sender?.send?.("subBgm:log", { taskId: String(taskId || ""), level: "error", message: msg });
      event?.sender?.send?.("subBgm:progress", { taskId: String(taskId || ""), progress: 0, message: /canceled/i.test(msg) ? "已取消" : "合成失败" });
    } catch {}
    const msg = String(e?.message || e);
    if (msg === "canceled" || /canceled/i.test(msg)) {
      updateLiveTaskState(task, { status: "canceled", message: "已取消" });
      return { ok: false, taskId, canceled: true, message: "canceled" };
    }
    updateLiveTaskState(task, { status: "failed", progress: 0, message: msg || "合成失败" });
    return { ok: false, taskId, message: msg };
  } finally {
    _subBgmTasks.delete(taskId);
  }
}

ipcMain.handle("subBgm:render", handleSubBgmRenderRequest);

async function handleSubBgmPlanSegmentsRequest(_event, payload) {
  try {
    const inputVideoRaw = String(payload?.videoPath || "").trim().replace(/^file:\/\//i, "");
    const asrModelChoice = payload?.asrModelChoice && typeof payload.asrModelChoice === "object" ? payload.asrModelChoice : null;
    const preferredSubtitleText = String(payload?.preferredSubtitleText || "").trim();
    const subtitleTemplate = payload?.subtitleTemplate && typeof payload.subtitleTemplate === "object" ? payload.subtitleTemplate : null;

    if (!inputVideoRaw) return { ok: false, message: "empty videoPath", segments: [] };
    if (!fs.existsSync(inputVideoRaw)) return { ok: false, message: `video not found: ${inputVideoRaw}`, segments: [] };

    const scan = scanProjectBundles();
    const useCloudSubtitleAsr = String(asrModelChoice?.source || "").trim().toLowerCase() === "cloud";
    const asrBundle = scan.find((b) => b.type === "ASR");
    if (!useCloudSubtitleAsr && !asrBundle) return { ok: false, message: buildMissingBundleMessage("ASR"), segments: [] };
    if (useCloudSubtitleAsr) {
      if (!String(asrModelChoice?.endpoint || "").trim()) return { ok: false, message: "当前云端字幕识别模型未配置 endpoint", segments: [] };
      if (!String(asrModelChoice?.apiKey || "").trim()) return { ok: false, message: "当前云端字幕识别模型未配置 API Key", segments: [] };
      if (!String(asrModelChoice?.modelId || asrModelChoice?.model || "").trim()) return { ok: false, message: "当前云端字幕识别模型未配置 modelId", segments: [] };
    }

    const ffmpegExe = pickFfmpegExeFromBundles();
    if (!ffmpegExe || !fs.existsSync(ffmpegExe)) return { ok: false, message: "ffmpeg.exe not found", segments: [] };

    const baseMeta = await probeVideoMetaViaFfmpeg(ffmpegExe, inputVideoRaw);
    const baseDuration = Number(baseMeta?.durationSec || 0) || 0;
    const tmpDir = path.join(os.tmpdir(), "ipfactory", "sub_bgm");
    ensureDir(tmpDir);
    const jobId = `plan_${Date.now()}_${crypto.randomBytes(3).toString("hex")}`;
    const audioPath = path.join(tmpDir, `${jobId}.wav`);
    await runFfmpeg(ffmpegExe, ["-y", "-i", inputVideoRaw, "-vn", "-ac", "1", "-ar", "16000", "-c:a", "pcm_s16le", audioPath], { cwd: tmpDir });

    let segmentsRaw = [];
    if (useCloudSubtitleAsr) {
      const cloudResult = await transcribeSubtitleByCloudModel(audioPath, asrModelChoice, { durationSec: baseDuration });
      segmentsRaw = Array.isArray(cloudResult?.segments) ? cloudResult.segments : [];
      const cloudText = String(cloudResult?.text || "").trim();
      const cloudTextLen = Array.from(cloudText.replace(/\s+/g, "")).length;
      if (segmentsRaw.length <= 1 && cloudTextLen > 12) {
        const rebuiltSegments = buildApproxSubtitleSegmentsFromText(cloudText, { durationSec: baseDuration });
        if (rebuiltSegments.length > segmentsRaw.length) segmentsRaw = rebuiltSegments;
      }
    } else {
      const bundleDir = asrBundle.bundleDir;
      const pythonExe = path.join(bundleDir, "runtime", "asr", "python", "python.exe");
      const asrScript = path.join(bundleDir, "services", "asr_server.py");
      if (!fs.existsSync(pythonExe)) return { ok: false, message: `python 不存在：${pythonExe}`, segments: [] };
      if (!fs.existsSync(asrScript)) return { ok: false, message: `asr_server.py 不存在：${asrScript}`, segments: [] };
      const configPath = path.join(tmpDir, `asr_${jobId}.json`);
      fs.writeFileSync(
        configPath,
        JSON.stringify({ id: jobId, modelConfig: { audio: audioPath, param: { language: "auto", use_itn: true } } }, null, 2),
        "utf-8"
      );
      const asrRes = await runAsrCommand(pythonExe, asrScript, configPath, { cwd: bundleDir });
      segmentsRaw = parseAigcPanelSubtitleSegments(String(asrRes?.stdout || ""));
    }

    const tplBody = subtitleTemplate?.body && typeof subtitleTemplate.body === "object" ? subtitleTemplate.body : {};
    const smartMaxChars = Math.max(6, Math.min(24, Number(tplBody?.maxChars || 14) || 14));
    const smartMaxLines = Math.max(1, Math.min(3, Number(tplBody?.lineCount || 2) || 2));
    const avOffset = Number(baseMeta?.avOffsetSec || 0) || 0;
    const shiftSec = Math.abs(avOffset) >= 0.03 && Math.abs(avOffset) <= 10 ? avOffset : 0;
    let segments = segmentsRaw;
    if (shiftSec) {
      segments = (Array.isArray(segments) ? segments : [])
        .map((seg) => {
          const a = Math.max(0, Number(seg?.startSec || 0) + shiftSec);
          const b = Math.max(0, Number(seg?.endSec || 0) + shiftSec);
          return { ...seg, startSec: a, endSec: b };
        })
        .filter((x) => Number.isFinite(x.startSec) && Number.isFinite(x.endSec) && x.endSec > x.startSec);
    }
    segments = normalizeSubtitleSegmentsByTiming(segments, { maxGapSec: 0.18, minSegDurSec: 0.4, maxSegDurSec: 2.8, minTextChars: 3 });
    segments = padSubtitleSegmentEndTimes(segments, {
      durationSec: baseDuration,
      endPadSec: 0.18,
      minHoldSec: 0.75,
      minGapToNextSec: 0.04,
      keepUntilNextStartGapSec: 1.2
    });
    if (!segments.length) return { ok: false, message: "ASR 返回空字幕", segments: [] };

    const smartText = normalizeSubtitlePlainText(preferredSubtitleText);
    if (preferredSubtitleText && smartText && segments.length) {
      const asrText = segments.map((s) => String(s?.text || "")).join("");
      const sim = calcBigramDiceSimilarity(smartText, asrText);
      const asrLen = Math.max(1, Array.from(String(asrText || "").replace(/\s+/g, "")).length);
      const smartLen = Math.max(0, Array.from(String(smartText || "").replace(/\s+/g, "")).length);
      const lenRatio = smartLen / asrLen;
      const lengthMatched = lenRatio >= 0.7 && lenRatio <= 1.35;
      if (Number.isFinite(sim) && sim >= 0.45 && lengthMatched) {
        segments = applyPreferredSubtitleTextToSegments(segments, smartText, { maxCharsPerLine: smartMaxChars, maxLines: smartMaxLines });
      }
    }
    return { ok: true, segments, durationSec: baseDuration };
  } catch (e) {
    return { ok: false, message: String(e?.message || e), segments: [] };
  }
}

ipcMain.handle("subBgm:planSegments", handleSubBgmPlanSegmentsRequest);

ipcMain.handle("subBgm:importStoryboardAssets", async (_event, payload) => {
  try {
    const filePaths = Array.isArray(payload?.filePaths) ? payload.filePaths.map((x) => String(x || "").trim()).filter(Boolean) : [];
    if (!filePaths.length) return { ok: false, message: "empty filePaths", items: [] };
    const outDir = path.join(resolveRuntimeDataRoot(), "storyboard-assets");
    ensureDir(outDir);
    const items = [];
    for (const fp of filePaths) {
      if (!fp || !fs.existsSync(fp)) continue;
      const ext = (path.extname(fp) || "").toLowerCase();
      const isImage = [".png", ".jpg", ".jpeg", ".webp"].includes(ext);
      const isGif = ext === ".gif";
      const isVideo = [".mp4", ".mov", ".webm", ".mkv"].includes(ext);
      if (!isImage && !isGif && !isVideo) continue;
      let stat = null;
      try {
        stat = fs.statSync(fp);
      } catch {}
      const basis = `${fp}|${Number(stat?.size || 0)}|${Number(stat?.mtimeMs || 0)}`;
      const hash = crypto.createHash("md5").update(basis).digest("hex").slice(0, 16);
      const id = `sb_${hash}`;
      const name = path.basename(fp);
      const normExt = ext === ".jpeg" ? ".jpg" : ext;
      const dst = path.join(outDir, `${id}${normExt}`);
      if (!fs.existsSync(dst)) {
        fs.copyFileSync(fp, dst);
      }
      const type = isImage ? "image" : isGif ? "gif" : "video";
      items.push({ id, name, path: dst, type });
    }
    if (!items.length) return { ok: false, message: "no valid assets", items: [] };
    return { ok: true, items };
  } catch (e) {
    return { ok: false, message: String(e?.message || e), items: [] };
  }
});

ipcMain.handle("subBgm:cancel", async (_event, payload) => {
  const taskId = String(payload?.taskId || "").trim();
  if (!taskId) return { ok: false, message: "empty taskId" };
  const task = _subBgmTasks.get(taskId);
  if (!task) return { ok: false, message: "task not found" };
  task.canceled = true;
  updateLiveTaskState(task, { status: "canceling", message: "正在取消字幕和背景音乐合成" });
  try {
    task.proc?.kill?.();
  } catch {}
  return { ok: true };
});

async function handleCoverGenerateRequest(_event, payload) {
  const taskId = String(payload?.taskId || "").trim() || `cover_${Date.now()}_${crypto.randomBytes(3).toString("hex")}`;
  const task = { taskId, proc: null, canceled: false, tool: "cover.generate", status: "running", progress: 5, message: "开始生成封面" };
  _coverTasks.set(taskId, task);
  updateLiveTaskState(task);
  try {
    const inputVideoRaw = String(payload?.videoPath || "").trim().replace(/^file:\/\//i, "");
    if (!inputVideoRaw) {
      updateLiveTaskState(task, { status: "failed", message: "empty videoPath" });
      return { ok: false, taskId, message: "empty videoPath" };
    }
    if (!fs.existsSync(inputVideoRaw)) {
      const msg = `video not found: ${inputVideoRaw}`;
      updateLiveTaskState(task, { status: "failed", message: msg });
      return { ok: false, taskId, message: msg };
    }

    const ffmpegExe = pickFfmpegExeFromBundles();
    if (!ffmpegExe || !fs.existsSync(ffmpegExe)) {
      updateLiveTaskState(task, { status: "failed", message: "ffmpeg.exe not found" });
      return { ok: false, taskId, message: "ffmpeg.exe not found" };
    }

    const tplIn = payload?.template && typeof payload.template === "object" ? payload.template : {};
    const baseRes = tplIn?.baseRes && typeof tplIn.baseRes === "object" ? tplIn.baseRes : { w: 1080, h: 1440 };
    const W = Math.max(240, Math.min(99999, Number(baseRes?.w || 1080) || 1080));
    const H = Math.max(240, Math.min(99999, Number(baseRes?.h || 1440) || 1440));

    const titleText = String(payload?.titleText || "").trim();
    const subTitleText = String(payload?.subTitleText || "").trim();

    const meta = await probeVideoMetaViaFfmpeg(ffmpegExe, inputVideoRaw);
    updateLiveTaskState(task, { progress: 20, message: "分析视频帧信息" });
    const dur = Math.max(0, Number(meta?.durationSec || 0) || 0);
    const maxPick = dur > 0 ? Math.max(0.05, Math.min(5, dur - 0.05)) : 5;
    const pickT = Math.max(0.02, Math.min(maxPick, 0.08 + Math.random() * Math.max(0.02, maxPick - 0.08)));

    const outRoot = resolveVideoEditsRoot();
    ensureDir(outRoot);
    const jobId = taskId;
    let jobDir = path.join(outRoot, jobId);
    let outPath = path.join(jobDir, "cover.png");

    try {
      const inAbs = path.resolve(inputVideoRaw);
      const rootAbs = path.resolve(outRoot);
      if (inAbs.startsWith(rootAbs)) {
        const parent = path.dirname(inAbs);
        if (fs.existsSync(parent)) {
          const coversDir = path.join(parent, "covers");
          ensureDir(coversDir);
          jobDir = coversDir;
          outPath = path.join(coversDir, `${jobId}.png`);
        }
      }
    } catch {}
    ensureDir(jobDir);
    syncRuntimeFontsFromInstall();

    const normalizeHex = (v, fallback = "#ffffff") => {
      const s = String(v || "").trim();
      if (/^#[0-9a-fA-F]{6}$/.test(s)) return s.toLowerCase();
      return fallback;
    };
    const toFfmpegColor = (hex, alpha01) => {
      const h = normalizeHex(hex, "#000000").replace("#", "0x");
      const a = Math.max(0, Math.min(1, Number(alpha01 || 0) || 0));
      return `${h}@${a.toFixed(3)}`;
    };
    const decodeFontName = (v) => {
      const raw = String(v || "").trim();
      if (!raw) return "";
      try {
        return decodeURIComponent(raw);
      } catch {
        return raw;
      }
    };
    const ensureAsciiSafeFontFile = (sourcePath) => {
      const fp = String(sourcePath || "").trim();
      if (!fp || !fs.existsSync(fp)) return "";
      try {
        const safeDir = path.join(resolveRuntimeDataRoot(), "ziti-ffmpeg");
        ensureDir(safeDir);
        const ext = path.extname(fp) || ".ttf";
        const hash = crypto.createHash("md5").update(fp).digest("hex").slice(0, 16);
        const safePath = path.join(safeDir, `font-${hash}${ext.toLowerCase()}`);
        const srcStat = fs.statSync(fp);
        const dstStat = fs.existsSync(safePath) ? fs.statSync(safePath) : null;
        if (!dstStat || Number(dstStat.size || 0) !== Number(srcStat.size || 0) || Number(dstStat.mtimeMs || 0) < Number(srcStat.mtimeMs || 0)) {
          fs.copyFileSync(fp, safePath);
        }
        return safePath;
      } catch {
        return fp;
      }
    };
    const resolveFontFile = (fontKey) => {
      const runtimeFontsDir = path.join(resolveRuntimeDataRoot(), "ziti");
      const fontsDir = resolveProjectMediaDir("ziti");
      const name = decodeFontName(fontKey);
      const tryPickExistingFontFile = (p) => {
        try {
          const fp = String(p || "").trim();
          if (!fp) return "";
          if (!fs.existsSync(fp)) return "";
          const ext = path.extname(fp).toLowerCase();
          if (![".ttf", ".otf", ".ttc"].includes(ext)) return "";
          return fp;
        } catch {
          return "";
        }
      };
      const sysFontsDir = (() => {
        try {
          const base = String(process.env.WINDIR || process.env.SystemRoot || "C:\\Windows");
          const dir = path.join(base, "Fonts");
          return fs.existsSync(dir) ? dir : "";
        } catch {
          return "";
        }
      })();
      const normalizeFontKey = (s) =>
        String(s || "")
          .trim()
          .toLowerCase()
          .replace(/\s+/g, " ")
          .replace(/[()（）]/g, "");
      const stripFontExtension = (s) => String(s || "").trim().replace(/\.(ttf|otf|ttc)$/i, "");

      const searchDirs = [runtimeFontsDir, fontsDir].filter((dir) => dir && fs.existsSync(dir));
      const packagedFonts = searchDirs.flatMap((dir) => listFilesInDir(dir, [".ttf", ".otf", ".ttc"]));
      const findPackagedFontByName = (matcher) => {
        if (typeof matcher !== "function") return "";
        const hit = packagedFonts.find((item) => matcher(String(item?.name || "").trim(), String(item?.path || "").trim()));
        return tryPickExistingFontFile(hit?.path || "");
      };
      const findPreferredPackagedFallback = () => {
        const preferred = ["黑体.ttf", "阿里普惠体-Regular.otf", "思源黑体 Normal.otf", "MaokenAssortedSans-Lite.ttf"];
        for (const wanted of preferred) {
          const hit = findPackagedFontByName((fileName) => String(fileName || "").trim().toLowerCase() === wanted.toLowerCase());
          if (hit) return hit;
        }
        return tryPickExistingFontFile(packagedFonts?.[0]?.path || "");
      };
      if (!name) {
        const packagedFallback = findPreferredPackagedFallback();
        return packagedFallback ? { fontfile: packagedFallback, fontname: "" } : { fontfile: "", fontname: "" };
      }

      const directFile = tryPickExistingFontFile(name);
      if (directFile) return { fontfile: directFile, fontname: "" };
      if (searchDirs.length) {
        const base = name.split(/[/\\]/).pop() || name;
        const candidates = [base, `${base}.ttf`, `${base}.otf`, `${base}.ttc`];
        for (const d of searchDirs) {
          for (const c of candidates) {
            const p = path.join(d, c);
            if (fs.existsSync(p)) return { fontfile: p, fontname: "" };
          }
        }
        const normalizedBase = normalizeFontKey(stripFontExtension(base));
        const packagedHit = findPackagedFontByName((fileName) => {
          const candidateBase = normalizeFontKey(stripFontExtension(fileName));
          return candidateBase === normalizedBase;
        });
        if (packagedHit) return { fontfile: packagedHit, fontname: "" };
      }

      const sysCandidatesByName = (() => {
        const key = normalizeFontKey(name);
        const map = {
          "microsoft yahei": ["msyh.ttc", "msyh.ttf", "msyhbd.ttc", "msyhbd.ttf"],
          "microsoftyahei": ["msyh.ttc", "msyh.ttf", "msyhbd.ttc", "msyhbd.ttf"],
          "微软雅黑": ["msyh.ttc", "msyh.ttf", "msyhbd.ttc", "msyhbd.ttf"],
          "microsoft yahei ui": ["msyh.ttc", "msyh.ttf", "msyhbd.ttc", "msyhbd.ttf"],
          "microsoft yahei ui light": ["msyh.ttc", "msyhl.ttc", "msyh.ttf"],
          "microsoft yahei light": ["msyh.ttc", "msyhl.ttc", "msyh.ttf"],
          "simhei": ["simhei.ttf"],
          "黑体": ["simhei.ttf"],
          "simsun": ["simsun.ttc", "simsun.ttf"],
          "宋体": ["simsun.ttc", "simsun.ttf"],
          "arial": ["arial.ttf", "arialbd.ttf"],
          "segoe ui": ["segoeui.ttf", "segoeuib.ttf"],
          "tahoma": ["tahoma.ttf"]
        };
        return map[key] || [];
      })();

      const packagedSystemAliasFallback = (() => {
        const key = normalizeFontKey(name);
        const aliasKeys = [
          "microsoft yahei",
          "microsoftyahei",
          "微软雅黑",
          "microsoft yahei ui",
          "microsoft yahei ui light",
          "microsoft yahei light",
          "simhei",
          "黑体",
          "simsun",
          "宋体"
        ];
        if (!aliasKeys.includes(key)) return "";
        return findPreferredPackagedFallback();
      })();
      if (packagedSystemAliasFallback) return { fontfile: packagedSystemAliasFallback, fontname: "" };

      const sysFallbacks = ["msyh.ttc", "arial.ttf", "segoeui.ttf"];
      const allSysCandidates = [...sysCandidatesByName, ...sysFallbacks];

      if (sysFontsDir) {
        for (const file of allSysCandidates) {
          const p = path.join(sysFontsDir, file);
          if (fs.existsSync(p)) return { fontfile: p, fontname: "" };
        }
        try {
          const key = normalizeFontKey(name);
          const entries = fs.readdirSync(sysFontsDir, { withFileTypes: true });
          const files = entries
            .filter((e) => e.isFile())
            .map((e) => String(e.name || ""))
            .filter((n) => /\.(ttf|otf|ttc)$/i.test(n));
          const hit = files.find((n) => normalizeFontKey(n).includes(key.replace(/\s/g, "")) || normalizeFontKey(n).includes(key));
          if (hit) {
            const p = path.join(sysFontsDir, hit);
            if (fs.existsSync(p)) return { fontfile: p, fontname: "" };
          }
        } catch {}
      }

      const packagedFallback = findPreferredPackagedFallback();
      if (packagedFallback) return { fontfile: packagedFallback, fontname: "" };

      return { fontfile: "", fontname: name };
    };
    const wrapForCoverLines = (text, maxChars, lineCount) => {
      const max = Math.max(4, Math.min(30, Number(maxChars || 8) || 8));
      const linesN = Math.max(1, Math.min(6, Number(lineCount || 2) || 2));
      const raw = String(text || "").trim();
      if (!raw) return [];
      const parts = wrapTextToLines(raw, max);
      return parts.slice(0, linesN);
    };
    const bg = tplIn?.background && typeof tplIn.background === "object" ? tplIn.background : {};
    const bgBlur = Math.max(0, Math.min(20, Number(bg?.blur || 0) || 0));
    const dimPct = Math.max(0, Math.min(80, Number(bg?.dimPct ?? bg?.dim ?? 10) || 10));
    const dimAlpha = (dimPct / 100) * 0.9;

    const m = tplIn?.mask && typeof tplIn.mask === "object" ? tplIn.mask : {};
    const mOn = m?.enable === true;
    const mx = Math.max(0, Math.min(100, Number(m?.xPct ?? 0) || 0));
    const my = Math.max(0, Math.min(100, Number(m?.yPct ?? 0) || 0));
    const mw = Math.max(0, Math.min(100, Number(m?.wPct ?? 0) || 0));
    const mh = Math.max(0, Math.min(100, Number(m?.hPct ?? 0) || 0));
    const mAlpha = Math.max(0, Math.min(80, Number(m?.alphaPct ?? 25) || 25)) / 100;
    const mColor = normalizeHex(m?.color || "#000000", "#000000");

    const main = tplIn?.main && typeof tplIn.main === "object" ? tplIn.main : {};
    const sub = tplIn?.sub && typeof tplIn.sub === "object" ? tplIn.sub : {};

    const mainLineCount = Number(main?.lineCount || 2) || 2;
    const mainLines = wrapForCoverLines(titleText || "", Number(main?.maxChars || 8) || 8, mainLineCount);
    const mainHasSecondLine = mainLineCount >= 2 ? mainLines.length >= 2 : mainLines.length >= 1;

    const subLineCount = Number(sub?.lineCount || 2) || 2;
    const subLines = wrapForCoverLines(subTitleText || "", Number(sub?.maxChars || 14) || 14, subLineCount);
    const subText = sub?.enable === true && mainHasSecondLine ? subLines.join("\n") : "";

    let vf = `scale=${W}:${H}:force_original_aspect_ratio=increase,crop=${W}:${H},setsar=1`;
    if (bgBlur > 0) vf += `,boxblur=luma_radius=${bgBlur}:luma_power=1:chroma_radius=${bgBlur}:chroma_power=1`;
    if (dimAlpha > 0.001) vf += `,drawbox=x=0:y=0:w=iw:h=ih:color=${toFfmpegColor("#000000", dimAlpha)}:t=fill`;
    if (mOn && mw > 0 && mh > 0) {
      vf += `,drawbox=x=${Math.round((mx / 100) * W)}:y=${Math.round((my / 100) * H)}:w=${Math.round((mw / 100) * W)}:h=${Math.round((mh / 100) * H)}:color=${toFfmpegColor(
        mColor,
        mAlpha
      )}:t=fill`;
    }
    const coverAssText = buildCoverAssText(tplIn, {
      playResX: W,
      playResY: H,
      titleText,
      subTitleText: sub?.enable === true && mainHasSecondLine ? subTitleText : ""
    });
    let coverAssPath = "";
    if (coverAssText) {
      coverAssPath = path.join(jobDir, `${jobId}.ass`);
      fs.writeFileSync(coverAssPath, coverAssText, "utf-8");
      const fontsDir = resolveProjectMediaDir("ziti");
      if (fontsDir && fs.existsSync(fontsDir)) vf += `,ass='${escapeFfmpegSubtitlesPath(coverAssPath)}':fontsdir='${escapeFfmpegSubtitlesPath(fontsDir)}'`;
      else vf += `,ass='${escapeFfmpegSubtitlesPath(coverAssPath)}'`;
    }

    const args = [
      "-y",
      "-ss",
      String(pickT.toFixed(3)),
      "-i",
      inputVideoRaw,
      "-frames:v",
      "1",
      "-vf",
      vf,
      "-hide_banner",
      "-nostats",
      outPath
    ];
    try {
      updateLiveTaskState(task, { progress: 70, message: "正在渲染封面" });
      await runFfmpeg(ffmpegExe, args, {
        cwd: jobDir,
        isCanceled: () => task.canceled === true,
        task
      });
    } catch (err) {
      const msg = String(err?.message || err || "");
      if (/Fontconfig error/i.test(msg)) {
        throw new Error(
          "封面生成失败：字体加载失败（FFmpeg drawtext 无法找到字体）。请在运行时数据目录 runtime-data/ziti 放入字体文件（ttf/ttc/otf），或在封面模板中选择系统可用字体后重试。"
        );
      }
      throw err;
    }

    try {
      fs.writeFileSync(
        path.join(jobDir, `${jobId}.json`),
        JSON.stringify(
          {
            id: jobId,
            createdAt: Date.now(),
            type: "cover_render",
            inputVideo: inputVideoRaw,
            pickTimeSec: Number(pickT.toFixed(3)),
            baseRes: { w: W, h: H },
            outPath
          },
          null,
          2
        ),
        "utf-8"
      );
    } catch {}

    updateLiveTaskState(task, {
      status: "completed",
      progress: 100,
      message: "封面生成完成",
      result: { jobId, outPath, pickTimeSec: Number(pickT.toFixed(3)) }
    });
    return { ok: true, taskId, jobId, outPath, pickTimeSec: Number(pickT.toFixed(3)) };
  } catch (e) {
    const msg = String(e?.message || e);
    if (msg === "canceled" || /canceled/i.test(msg)) {
      updateLiveTaskState(task, { status: "canceled", message: "已取消" });
      return { ok: false, taskId, canceled: true, message: "canceled" };
    }
    updateLiveTaskState(task, { status: "failed", message: msg || "封面生成失败" });
    return { ok: false, taskId, message: msg };
  } finally {
    _coverTasks.delete(taskId);
  }
}

ipcMain.handle("cover:generate", handleCoverGenerateRequest);

ipcMain.handle("cover:cancel", async (_event, payload) => {
  const taskId = String(payload?.taskId || "").trim();
  if (!taskId) return { ok: false, message: "empty taskId" };
  const task = _coverTasks.get(taskId);
  if (!task) return { ok: false, message: "task not found" };
  task.canceled = true;
  updateLiveTaskState(task, { status: "canceling", message: "正在取消封面生成" });
  try {
    task.proc?.kill?.();
  } catch {}
  return { ok: true };
});

function resolveTemplateStoresRoot() {
  return path.join(resolveUserRuntimeDataRoot(), "template_stores");
}

function safeTemplateFileName(id) {
  const raw = String(id || "").trim();
  const s = raw.replace(/[<>:"/\\|?*\x00-\x1F]/g, "_").replace(/\s+/g, "_");
  return s ? s.slice(0, 120) : `tpl_${Date.now()}_${crypto.randomBytes(3).toString("hex")}`;
}

ipcMain.handle("templateStore:saveSubtitleTemplate", async (_event, payload) => {
  try {
    const tpl = payload?.template && typeof payload.template === "object" ? payload.template : null;
    if (!tpl) return { ok: false, message: "empty template" };
    const root = resolveTemplateStoresRoot();
    const baseDir = path.join(root, "subtitle_templates");
    ensureDir(baseDir);
    const fileBase = safeTemplateFileName(tpl.id || tpl.name || "");
    const dir = path.join(baseDir, fileBase);
    ensureDir(dir);
    const outPath = path.join(dir, "template.json");
    fs.writeFileSync(outPath, JSON.stringify(tpl, null, 2), "utf-8");
    return { ok: true, outPath, dir };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

ipcMain.handle("templateStore:saveCoverTemplate", async (_event, payload) => {
  try {
    const tpl = payload?.template && typeof payload.template === "object" ? payload.template : null;
    if (!tpl) return { ok: false, message: "empty template" };
    const root = resolveTemplateStoresRoot();
    const baseDir = path.join(root, "cover_templates");
    ensureDir(baseDir);
    const fileBase = safeTemplateFileName(tpl.id || tpl.name || "");
    const dir = path.join(baseDir, fileBase);
    ensureDir(dir);
    const outPath = path.join(dir, "template.json");
    fs.writeFileSync(outPath, JSON.stringify(tpl, null, 2), "utf-8");
    return { ok: true, outPath, dir };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

function resolveAccountsRoot() {
  return path.join(resolveUserRuntimeDataRoot(), "accounts");
}

function readJsonSafe(p) {
  try {
    if (!p || !fs.existsSync(p)) return null;
    const raw = fs.readFileSync(p, "utf-8");
    const obj = JSON.parse(raw || "{}");
    return obj && typeof obj === "object" ? obj : null;
  } catch {
    return null;
  }
}

function writeJsonSafe(p, obj) {
  try {
    ensureDir(path.dirname(p));
    fs.writeFileSync(p, JSON.stringify(obj || {}, null, 2), "utf-8");
    return true;
  } catch {
    return false;
  }
}

function safeAccountId() {
  return `acc_${Date.now()}_${crypto.randomBytes(3).toString("hex")}`;
}

function getAccountMetaPath(id) {
  const root = resolveAccountsRoot();
  ensureDir(root);
  const file = safeTemplateFileName(id);
  return path.join(root, `${file}.json`);
}

function getPlatformLoginUrl(platform) {
  const p = String(platform || "").trim();
  if (p === "douyin") return "https://creator.douyin.com/";
  if (p === "kuaishou") return "https://cp.kuaishou.com/profile";
  if (p === "xiaohongshu") return "https://creator.xiaohongshu.com/login";
  if (p === "shipinhao") return "https://channels.weixin.qq.com/";
  return "https://www.douyin.com/";
}

function getPlatformHomeUrl(platform) {
  const p = String(platform || "").trim();
  if (p === "douyin") return "https://creator.douyin.com/creator-micro/home";
  if (p === "xiaohongshu") return "https://creator.xiaohongshu.com/new/home";
  if (p === "kuaishou") return "https://cp.kuaishou.com/profile";
  if (p === "shipinhao") return "https://channels.weixin.qq.com/";
  return getPlatformLoginUrl(p);
}

function buildCookieHeader(cookies) {
  const items = Array.isArray(cookies) ? cookies : [];
  return items
    .filter((c) => c && typeof c === "object" && String(c.name || "").trim())
    .map((c) => `${String(c.name || "").trim()}=${String(c.value || "")}`)
    .join("; ");
}

const KUAISHOU_INFO_V2_URL =
  "https://cp.kuaishou.com/rest/cp/creator/pc/home/infoV2?__NS_sig3=d0c087b72322a9e9fc8d8e8fe88526fc55b119f5919193939c9d9e84";
const KUAISHOU_INFO_V2_URL_RUNTIME =
  "https://cp.kuaishou.com/rest/cp/creator/pc/home/infoV2?__NS_sig3=041453631bed7d3d28595a5b524879e78165cd214545474748494a50";
const KUAISHOU_INFO_V2_URL_BASE = "https://cp.kuaishou.com/rest/cp/creator/pc/home/infoV2";
const KUAISHOU_USERINFO_URL =
  "https://cp.kuaishou.com/rest/cp/creator/pc/home/userInfo?__NS_sig3=b5a5e2d26b28cc8c98e8ebea9139c34e30d47c90f4f4f6f6f9f8fbe1";
const KUAISHOU_USERINFO_URL_BASE = "https://cp.kuaishou.com/rest/cp/creator/pc/home/userInfo";

async function fetchKuaishouUserInfoByCookieHeader(cookieHeader, timeoutMs = 15000) {
  const ck = String(cookieHeader || "").trim();
  if (!ck) return { ok: false, message: "missing cookie header" };
  const headers = {
    cookie: ck,
    accept: "application/json, text/plain, */*",
    Origin: "https://cp.kuaishou.com",
    Referer: "https://cp.kuaishou.com/profile",
    "X-Requested-With": "XMLHttpRequest",
    returnsetrootdomainloginurl: "true",
    "Accept-Encoding": "identity",
    "Content-Type": "application/json;charset=UTF-8",
    "User-Agent": chromeUserAgent()
  };
  const bodies = [
    undefined,
    {},
    { returnSetRootDomainLoginUrl: true },
    { sid: "kuaishou.web.cp.api" },
    { sid: "kuaishou.web.cp.api", returnSetRootDomainLoginUrl: true }
  ];
  let last = null;
  for (const u of [KUAISHOU_USERINFO_URL, KUAISHOU_USERINFO_URL_BASE, KUAISHOU_INFO_V2_URL_RUNTIME, KUAISHOU_INFO_V2_URL, KUAISHOU_INFO_V2_URL_BASE]) {
    for (const body of bodies) {
      try {
        const r = await requestJson(u, { method: "POST", headers, timeoutMs, body });
        last = { ...(r || {}), requestBody: body };
        const statusCode = Number(r?.statusCode || 0) || 0;
        if (statusCode >= 200 && statusCode < 300 && r?.data) {
          return { ok: true, url: u, statusCode, parsed: r.data, raw: String(r.raw || ""), requestBody: body };
        }
      } catch (e) {
        last = { error: String(e?.message || e), requestBody: body, url: u };
      }
    }
  }
  return { ok: false, message: "no userInfo response", last };
}

async function fetchKuaishouUserInfoByPageFetch(evalJs, timeoutMs = 12000) {
  if (typeof evalJs !== "function") return { ok: false, message: "evalJs missing" };
  const script = `(() => new Promise(async (resolve) => {
  const urls = [
    ${JSON.stringify(KUAISHOU_USERINFO_URL)},
    ${JSON.stringify(KUAISHOU_USERINFO_URL_BASE)},
    ${JSON.stringify(KUAISHOU_INFO_V2_URL_RUNTIME)},
    ${JSON.stringify(KUAISHOU_INFO_V2_URL)},
    ${JSON.stringify(KUAISHOU_INFO_V2_URL_BASE)}
  ];
  const bodies = [
    undefined,
    {},
    { returnSetRootDomainLoginUrl: true },
    { sid: "kuaishou.web.cp.api" },
    { sid: "kuaishou.web.cp.api", returnSetRootDomainLoginUrl: true }
  ];
  for (const url of urls) {
    for (const body of bodies) {
      try {
        const headers = {
          "accept": "application/json, text/plain, */*",
          "content-type": "application/json;charset=UTF-8",
          "x-requested-with": "XMLHttpRequest",
          "returnsetrootdomainloginurl": "true"
        };
        const resp = await fetch(url, {
          method: "POST",
          credentials: "include",
          headers,
          body: body === undefined ? undefined : JSON.stringify(body)
        });
        const text = await resp.text();
        let parsed = null;
        try { parsed = text ? JSON.parse(text) : null; } catch {}
        if (resp.status >= 200 && resp.status < 300 && parsed) {
          return resolve({ ok: true, url, statusCode: resp.status, parsed, raw: text, requestBody: body });
        }
      } catch {}
    }
  }
  resolve({ ok: false, message: "page fetch empty" });
}))()`;
  return (await evalJs(script, true).catch(() => null)) || { ok: false, message: "page fetch failed" };
}

function normalizeCookieSnapshot(cookies) {
  const items = Array.isArray(cookies) ? cookies : [];
  return items.map((c) => ({
    name: String(c?.name || ""),
    value: String(c?.value || ""),
    domain: String(c?.domain || ""),
    path: String(c?.path || ""),
    expires: Number(c?.expires ?? c?.expirationDate ?? 0) || 0,
    httpOnly: c?.httpOnly === true,
    secure: c?.secure === true,
    sameSite: String(c?.sameSite || "")
  }));
}

function getCookieValue(cookies, name) {
  const target = String(name || "").trim();
  if (!target) return "";
  const items = Array.isArray(cookies) ? cookies : [];
  const found = items.find((c) => String(c?.name || "").trim() === target);
  return String(found?.value || "").trim();
}

function extractXiaohongshuProfileFromCreatorPayload(parsed) {
  try {
    const root = parsed && typeof parsed === "object" ? parsed : {};
    const data = root?.data && typeof root.data === "object" ? root.data : root;
    const user =
      data?.userInfo ||
      data?.user_info ||
      data?.creatorInfo ||
      data?.creator_info ||
      data?.accountInfo ||
      data?.account_info ||
      data?.profile ||
      data?.baseInfo ||
      data?.base_info ||
      {};
    const avatarUrl = String(
      user?.avatar ||
        user?.avatarUrl ||
        user?.avatar_url ||
        user?.image ||
        user?.headImage ||
        user?.head_image ||
        ""
    ).trim();
    const nickName = String(
      user?.nickname ||
        user?.nickName ||
        user?.name ||
        user?.userName ||
        user?.user_name ||
        user?.accountName ||
        user?.account_name ||
        ""
    ).trim();
    const xhsUserId = String(
      user?.userId || user?.user_id || user?.creatorId || user?.creator_id || user?.accountId || user?.account_id || ""
    ).trim();
    const xhsRedId = String(user?.redId || user?.red_id || user?.xhsId || user?.xhs_id || "").trim();
    return { nickName, avatarUrl, xhsUserId, xhsRedId };
  } catch {
    return { nickName: "", avatarUrl: "", xhsUserId: "", xhsRedId: "" };
  }
}

function extractXiaohongshuProfileFromPersonalInfoJson(parsed, cookies) {
  try {
    const root = parsed && typeof parsed === "object" ? parsed : {};
    const data = root?.data && typeof root.data === "object" ? root.data : {};
    return {
      nickName: String(data?.name || "").trim(),
      avatarUrl: String(data?.avatar || "").trim(),
      xhsUserId: getCookieValue(cookies, "x-user-id-creator.xiaohongshu.com"),
      xhsRedId: String(data?.red_num || "").trim(),
      followerCount: Number(data?.fans_count ?? 0) || 0,
      followingCount: Number(data?.follow_count ?? 0) || 0,
      totalFavorited: Number(data?.faved_count ?? 0) || 0,
      signature: String(data?.personal_desc || "").trim()
    };
  } catch {
    return {
      nickName: "",
      avatarUrl: "",
      xhsUserId: "",
      xhsRedId: "",
      followerCount: 0,
      followingCount: 0,
      totalFavorited: 0,
      signature: ""
    };
  }
}

function getAccountsGroupsPath() {
  return path.join(resolveAccountsRoot(), "groups.json");
}

function readGroups() {
  const p = getAccountsGroupsPath();
  const obj = readJsonSafe(p) || {};
  const items = Array.isArray(obj.items) ? obj.items : [];
  return items
    .filter((x) => x && typeof x === "object")
    .map((x) => ({
      id: String(x.id || ""),
      name: String(x.name || ""),
      createdAt: Number(x.createdAt || 0) || 0,
      updatedAt: Number(x.updatedAt || 0) || 0
    }))
    .filter((x) => x.id && x.name);
}

function writeGroups(items) {
  const p = getAccountsGroupsPath();
  const ok = writeJsonSafe(p, { items: Array.isArray(items) ? items : [], updatedAt: Date.now() });
  return ok;
}

