ipcMain.handle("accounts:test", async (_event, payload) => {
  try {
    const id = String(payload?.id || "").trim();
    if (!id) return { ok: false, message: "empty id" };
    const metaPath = getAccountMetaPath(id);
    const meta0 = readJsonSafe(metaPath) || null;
    if (!meta0) return { ok: false, message: "account not found" };

    const platform = String(meta0.platform || "").trim() || "douyin";
    const partition = String(meta0.partition || "").trim();
    const chromeProfileDir = String(meta0.chromeProfileDir || "").trim();
    const loginMethod = String(meta0.loginMethod || "").trim();
    if (platform === "shipinhao" && !chromeProfileDir) {
      const mod = loadShipinhaoAccountTestMod();
      const now = Date.now();
      const res =
        mod && typeof mod.testShipinhaoAccountByCookieHeader === "function"
          ? await mod.testShipinhaoAccountByCookieHeader({
              cookieHeader: String(meta0.cookieHeader || "").trim() || buildCookieHeader(meta0.cookieSnapshot),
              chromeUserAgent: chromeUserAgent(),
              timeoutMs: 12000
            })
          : { valid: false, info: { ok: false, message: "shipinhao test module missing", raw: "", statusCode: 0 } };
      const valid = !!res?.valid;
      const next = {
        ...meta0,
        status: valid ? "normal" : "invalid",
        updatedAt: now,
        lastTestLog: {
          at: now,
          method: "cookie",
          url: String(res?.info?.url || ""),
          statusCode: Number(res?.info?.statusCode || 0) || 0,
          ok: !!res?.info?.ok,
          extracted: {
            nick_name: String(res?.extractedNick || ""),
            unique_id: String(res?.extractedUid || ""),
            avatar_url: String(res?.extractedAvatarUrl || ""),
            follower_count: Number(res?.extractedFollowerCount ?? 0) || 0,
            video_count: Number(res?.extractedVideoCount ?? 0) || 0
          },
          message: valid ? "" : String(res?.info?.message || "视频号 Cookie 不可用"),
          raw: String(res?.info?.raw || "").slice(0, 12000)
        }
      };
      if (valid) {
        if (String(res?.extractedNick || "").trim()) next.name = String(res.extractedNick || "").trim();
        if (String(res?.extractedUid || "").trim()) next.shipinhaoId = String(res.extractedUid || "").trim();
        if (String(res?.extractedAvatarUrl || "").trim()) next.avatarUrl = String(res.extractedAvatarUrl || "").trim();
        next.followerCount = Number(res?.extractedFollowerCount ?? next.followerCount ?? 0) || 0;
        next.videoCount = Number(res?.extractedVideoCount ?? next.videoCount ?? 0) || 0;
      }
      writeJsonSafe(metaPath, next);
      return { ok: true, valid, item: next, log: next.lastTestLog };
    }
    if (platform === "kuaishou" && !chromeProfileDir) {
      const now = Date.now();
      const cookieHeader = String(meta0.cookieHeader || "").trim() || buildCookieHeader(meta0.cookieSnapshot);
      const info = await fetchKuaishouUserInfoByCookieHeader(cookieHeader, 15000);
      const mod = loadKuaishouLoginCookieMod();
      const prof0 = info?.ok && mod && typeof mod.extractKuaishouProfileFromInfoV2Json === "function" ? mod.extractKuaishouProfileFromInfoV2Json(info.parsed) : null;
      const valid = !!prof0?.ok;
      const next = {
        ...meta0,
        status: valid ? "normal" : "invalid",
        updatedAt: now,
        lastTestLog: {
          at: now,
          method: "cookie",
          url: String(info?.url || ""),
          statusCode: Number(info?.statusCode || 0) || 0,
          ok: !!info?.ok,
          extracted: { userName: String(prof0?.userName || ""), userId: String(prof0?.userId || "") },
          message: valid ? "" : "没有获取到账号信息，登录失败",
          raw: String(info?.raw || "").slice(0, 12000)
        }
      };
      if (valid) {
        if (String(prof0.userName || "").trim()) next.name = String(prof0.userName || "").trim();
        if (String(prof0.userId || "").trim()) next.kuaishouId = String(prof0.userId || "").trim();
        next.followerCount = Number(prof0.fansCnt ?? next.followerCount ?? 0) || 0;
        next.followingCount = Number(prof0.followCnt ?? next.followingCount ?? 0) || 0;
        next.totalFavorited = Number(prof0.likeCnt ?? next.totalFavorited ?? 0) || 0;
        if (String(prof0.desc || "").trim()) next.signature = String(prof0.desc || "").trim();
        if (String(prof0.avatarUrl || "").trim()) next.avatarUrl = String(prof0.avatarUrl || "").trim();
      }
      writeJsonSafe(metaPath, next);
      return { ok: true, valid, item: next, log: next.lastTestLog };
    }
    if (!partition && chromeProfileDir) {
      const url = getPlatformLoginUrl(platform);
      const resolveChromeExe = () => {
        const candidates = [];
        try {
          const pf = String(process.env.ProgramFiles || "C:\\Program Files");
          const pf86 = String(process.env["ProgramFiles(x86)"] || "C:\\Program Files (x86)");
          const lad = String(process.env.LOCALAPPDATA || "");
          candidates.push(path.join(pf, "Google", "Chrome", "Application", "chrome.exe"));
          candidates.push(path.join(pf86, "Google", "Chrome", "Application", "chrome.exe"));
          if (lad) candidates.push(path.join(lad, "Google", "Chrome", "Application", "chrome.exe"));
        } catch {}
        return candidates.find((p) => p && fs.existsSync(p)) || "";
      };
      const chromeExe = resolveChromeExe();
      if (!chromeExe) return { ok: false, message: "chrome not found" };

      let startedChrome = false;
      let chromePid = 0;
      let browserWsUrl = "";

      const getFreePort = () =>
        new Promise((resolve) => {
          const srv = net.createServer();
          srv.listen(0, "127.0.0.1", () => {
            const a = srv.address();
            const port = typeof a === "object" && a ? Number(a.port || 0) : 0;
            srv.close(() => resolve(port || 0));
          });
          srv.on("error", () => resolve(0));
        });
      const delay = (ms) => new Promise((r) => setTimeout(r, ms));
      const httpGetJson = async (u, timeoutMs = 4000) => {
        const res = await requestUrl(u, { method: "GET", timeoutMs });
        const buf = await readResponseBody(res);
        const raw = buf.toString("utf-8");
        try {
          return { ok: true, statusCode: res.statusCode || 0, data: JSON.parse(raw || "null"), raw };
        } catch {
          return { ok: false, statusCode: res.statusCode || 0, raw };
        }
      };
      const waitChromeDebugReady = async (port, timeoutMs = 12000) => {
        const start = Date.now();
        while (Date.now() - start < timeoutMs) {
          try {
            const r = await httpGetJson(`http://127.0.0.1:${port}/json/version`, 1200);
            if (r?.ok && r.statusCode >= 200 && r.statusCode < 300) return true;
          } catch {}
          await delay(250);
        }
        return false;
      };
      const parseWsUrl = (wsUrl) => {
        const u = new URL(String(wsUrl || ""));
        const host = u.hostname || "127.0.0.1";
        const port = Number(u.port || 80) || 80;
        const pathAndQuery = (u.pathname || "/") + (u.search || "");
        return { host, port, pathAndQuery };
      };
      const wsConnect = (wsUrl, timeoutMs = 12000) =>
        new Promise((resolve, reject) => {
          let settled = false;
          const { host, port, pathAndQuery } = parseWsUrl(wsUrl);
          const socket = net.createConnection({ host, port });
          const key = crypto.randomBytes(16).toString("base64");
          let headerBuf = Buffer.alloc(0);
          let handshakeDone = false;
          let dataBuf = Buffer.alloc(0);
          const onMessageCbs = new Set();
          const pendingSend = [];
          const cleanup = () => socket.removeAllListeners();
          const fail = (err) => {
            if (settled) return;
            settled = true;
            cleanup();
            try {
              socket.destroy();
            } catch {}
            reject(err instanceof Error ? err : new Error(String(err || "ws connect error")));
          };
          const sendFrame = (payloadBuf) => {
            const payloadLen = payloadBuf.length;
            const maskKey = crypto.randomBytes(4);
            const masked = Buffer.alloc(payloadLen);
            for (let i = 0; i < payloadLen; i += 1) masked[i] = payloadBuf[i] ^ maskKey[i % 4];
            let header = null;
            if (payloadLen < 126) {
              header = Buffer.alloc(2);
              header[0] = 0x81;
              header[1] = 0x80 | payloadLen;
            } else if (payloadLen < 65536) {
              header = Buffer.alloc(4);
              header[0] = 0x81;
              header[1] = 0x80 | 126;
              header.writeUInt16BE(payloadLen, 2);
            } else {
              header = Buffer.alloc(10);
              header[0] = 0x81;
              header[1] = 0x80 | 127;
              header.writeBigUInt64BE(BigInt(payloadLen), 2);
            }
            const frame = Buffer.concat([header, maskKey, masked]);
            socket.write(frame);
          };
          const tryFlush = () => {
            while (pendingSend.length) sendFrame(pendingSend.shift());
          };
          const decodeFrames = () => {
            while (dataBuf.length >= 2) {
              const b0 = dataBuf[0];
              const b1 = dataBuf[1];
              const fin = (b0 & 0x80) !== 0;
              const opcode = b0 & 0x0f;
              const masked = (b1 & 0x80) !== 0;
              let len = b1 & 0x7f;
              let off = 2;
              if (len === 126) {
                if (dataBuf.length < off + 2) return;
                len = dataBuf.readUInt16BE(off);
                off += 2;
              } else if (len === 127) {
                if (dataBuf.length < off + 8) return;
                len = Number(dataBuf.readBigUInt64BE(off));
                off += 8;
              }
              const maskOff = masked ? 4 : 0;
              if (dataBuf.length < off + maskOff + len) return;
              let payload = dataBuf.subarray(off + maskOff, off + maskOff + len);
              if (masked) {
                const mk = dataBuf.subarray(off, off + 4);
                const un = Buffer.alloc(len);
                for (let i = 0; i < len; i += 1) un[i] = payload[i] ^ mk[i % 4];
                payload = un;
              }
              dataBuf = dataBuf.subarray(off + maskOff + len);
              if (opcode === 0x8) {
                try {
                  socket.end();
                } catch {}
                return;
              }
              if (opcode !== 0x1) continue;
              if (!fin) continue;
              const text = payload.toString("utf-8");
              onMessageCbs.forEach((cb) => {
                try {
                  cb(text);
                } catch {}
              });
            }
          };
          const timer = setTimeout(() => fail(new Error("ws connect timeout")), Number(timeoutMs || 0) || 12000);
          socket.on("connect", () => {
            const req =
              `GET ${pathAndQuery} HTTP/1.1\r\n` +
              `Host: ${host}:${port}\r\n` +
              "Upgrade: websocket\r\n" +
              "Connection: Upgrade\r\n" +
              `Sec-WebSocket-Key: ${key}\r\n` +
              "Sec-WebSocket-Version: 13\r\n" +
              "\r\n";
            socket.write(req);
          });
          socket.on("error", fail);
          socket.on("data", (chunk) => {
            if (!handshakeDone) {
              headerBuf = Buffer.concat([headerBuf, chunk]);
              const idx = headerBuf.indexOf("\r\n\r\n");
              if (idx === -1) return;
              const head = headerBuf.subarray(0, idx + 4).toString("utf-8");
              const rest = headerBuf.subarray(idx + 4);
              if (!/^HTTP\/1\.1 101/i.test(head)) return fail(new Error("ws handshake failed"));
              handshakeDone = true;
              clearTimeout(timer);
              dataBuf = Buffer.concat([dataBuf, rest]);
              decodeFrames();
              tryFlush();
              if (!settled) {
                settled = true;
                resolve({
                  sendText: (text) => {
                    const buf = Buffer.from(String(text || ""), "utf-8");
                    if (!handshakeDone) pendingSend.push(buf);
                    else sendFrame(buf);
                  },
                  onMessage: (cb) => {
                    if (typeof cb !== "function") return () => {};
                    onMessageCbs.add(cb);
                    return () => onMessageCbs.delete(cb);
                  },
                  close: () => {
                    try {
                      socket.end(Buffer.from([0x88, 0x00]));
                    } catch {}
                  }
                });
              }
              return;
            }
            dataBuf = Buffer.concat([dataBuf, chunk]);
            decodeFrames();
          });
        });
      const createCdp = async (wsUrl) => {
        const ws = await wsConnect(wsUrl, 12000);
        let idSeq = 1;
        const waits = new Map();
        const eventListeners = new Map();
        const onceWaiters = [];
        const off = ws.onMessage((text) => {
          try {
            const msg = JSON.parse(String(text || "{}"));
            const id = Number(msg?.id || 0) || 0;
            if (id && waits.has(id)) {
              const { resolve, reject } = waits.get(id);
              waits.delete(id);
              if (msg?.error) reject(new Error(String(msg?.error?.message || "cdp error")));
              else resolve(msg?.result);
              return;
            }
            const method = String(msg?.method || "").trim();
            if (method) {
              const params = msg?.params;
              const set = eventListeners.get(method);
              if (set && set.size) {
                set.forEach((cb) => {
                  try {
                    cb(params);
                  } catch {}
                });
              }
              for (let i = onceWaiters.length - 1; i >= 0; i -= 1) {
                const w = onceWaiters[i];
                if (w.method !== method) continue;
                let ok = true;
                try {
                  ok = typeof w.predicate === "function" ? !!w.predicate(params) : true;
                } catch {
                  ok = false;
                }
                if (!ok) continue;
                onceWaiters.splice(i, 1);
                try {
                  clearTimeout(w.timer);
                } catch {}
                try {
                  w.resolve({ method, params });
                } catch {}
              }
            }
          } catch {}
        });
        const send = (method, params) =>
          new Promise((resolve, reject) => {
            const id = idSeq++;
            waits.set(id, { resolve, reject });
            ws.sendText(JSON.stringify({ id, method, params: params || {} }));
          });
        const onEvent = (method, cb) => {
          const m = String(method || "").trim();
          if (!m || typeof cb !== "function") return () => {};
          const set = eventListeners.get(m) || new Set();
          set.add(cb);
          eventListeners.set(m, set);
          return () => {
            try {
              const s = eventListeners.get(m);
              if (s) s.delete(cb);
            } catch {}
          };
        };
        const waitForEvent = (method, timeoutMs = 8000, predicate) =>
          new Promise((resolve, reject) => {
            const m = String(method || "").trim();
            if (!m) return reject(new Error("empty event method"));
            const t = Number(timeoutMs || 0) || 8000;
            const timer = setTimeout(() => {
              const idx = onceWaiters.findIndex((x) => x && x.resolve === resolve);
              if (idx >= 0) onceWaiters.splice(idx, 1);
              reject(new Error(`wait event timeout: ${m}`));
            }, t);
            onceWaiters.push({ method: m, resolve, reject, predicate, timer });
          });
        const close = () => {
          try {
            onceWaiters.splice(0, onceWaiters.length);
            eventListeners.clear();
            off();
          } catch {}
          try {
            ws.close();
          } catch {}
        };
        return { send, close, onEvent, waitForEvent };
      };

      let port = Number(meta0.chromeDebugPort || 0) || 0;
      if (port && (await waitChromeDebugReady(port, 1200))) {
      } else {
        port = (await getFreePort()) || 0;
        if (!port) return { ok: false, message: "no free port" };
        const args = [
          `--remote-debugging-port=${port}`,
          `--user-data-dir=${chromeProfileDir}`,
          "--no-first-run",
          "--no-default-browser-check",
          "--disable-features=TranslateUI",
          url
        ];
        const proc = spawn(chromeExe, args, { windowsHide: true, detached: true, stdio: "ignore" });
        try {
          proc.unref();
        } catch {}
        startedChrome = true;
        chromePid = Number(proc?.pid || 0) || 0;
        const ready = await waitChromeDebugReady(port, 15000);
        if (!ready) return { ok: false, message: "chrome remote debugging not ready" };
      }

      try {
        const ver = await httpGetJson(`http://127.0.0.1:${port}/json/version`, 6000);
        browserWsUrl = String(ver?.data?.webSocketDebuggerUrl || "").trim();
      } catch {}

      const list = await httpGetJson(`http://127.0.0.1:${port}/json/list`, 6000);
      const pages = Array.isArray(list?.data) ? list.data : [];
      const pick = pages.find((x) => x && x.type === "page" && String(x.webSocketDebuggerUrl || "").startsWith("ws")) || null;
      const wsUrl = String(pick?.webSocketDebuggerUrl || "").trim();
      if (!wsUrl) return { ok: false, message: "no ws target" };
      const cdp = await createCdp(wsUrl);
      try {
        await cdp.send("Page.enable").catch(() => null);
        await cdp.send("Runtime.enable").catch(() => null);
        await cdp.send("Network.enable").catch(() => null);
        const r = await cdp.send("Network.getCookies", { urls: [url] }).catch(() => null);
        const cookies = Array.isArray(r?.cookies) ? r.cookies : [];
        const cookieOk = hasAuthCookie(platform, cookies);
        const now = Date.now();
        const evalJs = async (expression, returnByValue = true) => {
          const rr = await cdp.send("Runtime.evaluate", {
            expression: String(expression || ""),
            awaitPromise: true,
            returnByValue: !!returnByValue,
            userGesture: true
          });
          return rr?.result?.value;
        };

        let userInfoOk = false;
        let extractedNick = "";
        let extractedUid = "";
        let extractedAvatarUrl = "";
        let extractedFollowerCount = 0;
        let extractedFollowingCount = 0;
        let extractedTotalFavorited = 0;
        let extractedVideoCount = 0;
        let extractedSignature = "";
        let extractedDashboardOpendDate = "";
        let userInfoStatus = 0;
        let userInfoRaw = "";
        let userInfoMsg = "";
        if (platform === "douyin" && cookieOk) {
          const mod = loadDouyinAccountManageMod();
          const res =
            mod && typeof mod.testDouyinAccountByChrome === "function"
              ? await mod.testDouyinAccountByChrome({ cdp, evalJs, delay, homeUrl: getPlatformHomeUrl("douyin") })
              : null;
          userInfoOk = !!res?.userInfoOk;
          userInfoStatus = Number(res?.userInfoStatus || 0) || 0;
          userInfoRaw = String(res?.userInfoRaw || "");
          userInfoMsg = String(res?.userInfoMsg || (res ? "" : "douyin account module missing"));
          extractedNick = String(res?.extractedNick || "").trim();
          extractedUid = String(res?.extractedUid || "").trim();
          extractedAvatarUrl = String(res?.extractedAvatarUrl || "").trim();
          extractedFollowerCount = Number(res?.extractedFollowerCount ?? 0) || 0;
          extractedFollowingCount = Number(res?.extractedFollowingCount ?? 0) || 0;
          extractedTotalFavorited = Number(res?.extractedTotalFavorited ?? 0) || 0;
          extractedSignature = String(res?.extractedSignature || "").trim();
          extractedDashboardOpendDate = String(res?.extractedDashboardOpendDate || "").trim();
        } else if (platform === "xiaohongshu" && cookieOk) {
          try {
            const info = await fetchXiaohongshuCreatorPersonalInfoByCdp({
              cdp,
              homeUrl: getPlatformHomeUrl("xiaohongshu"),
              timeoutMs: 12000
            });
            userInfoStatus = Number(info?.statusCode || 0) || 0;
            userInfoRaw = String(info?.raw || "");
            if (info?.ok && info?.parsed) {
              const prof = extractXiaohongshuProfileFromPersonalInfoJson(info.parsed, cookies);
              extractedNick = String(prof?.nickName || "").trim();
              extractedUid = String(prof?.xhsRedId || "").trim();
              extractedAvatarUrl = String(prof?.avatarUrl || "").trim();
              extractedFollowerCount = Number(prof?.followerCount ?? 0) || 0;
              extractedFollowingCount = Number(prof?.followingCount ?? 0) || 0;
              extractedTotalFavorited = Number(prof?.totalFavorited ?? 0) || 0;
              extractedSignature = String(prof?.signature || "").trim();
              userInfoOk = !!(extractedNick || extractedUid);
              userInfoMsg = userInfoOk ? "" : "empty xiaohongshu name/red_num";
            } else {
              userInfoMsg = String(info?.message || "");
            }
          } catch (e) {
            userInfoMsg = String(e?.message || e);
          }
        } else if (platform === "kuaishou" && cookieOk) {
          try {
            const info = await fetchKuaishouUserInfoByCookieHeader(buildCookieHeader(cookies), 15000);
            const mod = loadKuaishouLoginCookieMod();
            const prof =
              info?.ok && mod && typeof mod.extractKuaishouProfileFromInfoV2Json === "function"
                ? mod.extractKuaishouProfileFromInfoV2Json(info.parsed)
                : null;
            userInfoStatus = Number(info?.statusCode || 0) || 0;
            userInfoRaw = String(info?.raw || "");
            if (prof?.ok) {
              extractedNick = String(prof?.userName || "").trim();
              extractedUid = String(prof?.userId || "").trim();
              extractedAvatarUrl = String(prof?.avatarUrl || "").trim();
              extractedFollowerCount = Number(prof?.fansCnt ?? 0) || 0;
              extractedFollowingCount = Number(prof?.followCnt ?? 0) || 0;
              extractedTotalFavorited = Number(prof?.likeCnt ?? 0) || 0;
              extractedSignature = String(prof?.desc || "").trim();
              userInfoOk = !!(extractedNick || extractedUid);
              userInfoMsg = userInfoOk ? "" : "empty kuaishou user fields";
            } else {
              userInfoMsg = String(info?.message || "没有获取到账号信息，登录失败");
            }
          } catch (e) {
            userInfoMsg = String(e?.message || e);
          }
        } else if (platform === "shipinhao" && cookieOk) {
          const mod = loadShipinhaoAccountTestMod();
          const res =
            mod && typeof mod.testShipinhaoAccountByChrome === "function"
              ? await mod.testShipinhaoAccountByChrome({
                  cdp,
                  delay,
                  homeUrl: getPlatformHomeUrl("shipinhao"),
                  cookieHeader: buildCookieHeader(cookies),
                  chromeUserAgent: chromeUserAgent()
                })
              : null;
          userInfoOk = !!res?.valid;
          userInfoStatus = Number(res?.info?.statusCode || 0) || 0;
          userInfoRaw = String(res?.info?.raw || "");
          userInfoMsg = String(res?.info?.message || (res ? "" : "shipinhao test module missing"));
          extractedNick = String(res?.extractedNick || "").trim();
          extractedUid = String(res?.extractedUid || "").trim();
          extractedAvatarUrl = String(res?.extractedAvatarUrl || "").trim();
          extractedFollowerCount = Number(res?.extractedFollowerCount ?? 0) || 0;
          extractedVideoCount = Number(res?.extractedVideoCount ?? 0) || 0;
        }

        const valid =
          platform === "douyin" || platform === "xiaohongshu" || platform === "kuaishou" || platform === "shipinhao"
            ? cookieOk && userInfoOk
            : cookieOk;
        const next = {
          ...meta0,
          cookieCount: cookies.length,
          status: valid ? "normal" : "invalid",
          updatedAt: now,
          chromeProfileDir,
          chromeDebugPort: port,
          loginMethod: loginMethod || "chrome",
          lastTestLog: {
            at: now,
            method: "chrome",
            cookieOk,
            cookieCount: cookies.length,
            userInfoOk,
            userInfoStatus,
            extracted: {
              nick_name: extractedNick,
              unique_id: extractedUid,
              avatar_url: extractedAvatarUrl,
              follower_count: extractedFollowerCount,
              following_count: extractedFollowingCount,
              video_count: extractedVideoCount,
              total_favorited: extractedTotalFavorited,
              signature: extractedSignature,
              dashboard_opend_date: extractedDashboardOpendDate
            },
            message: userInfoMsg,
            raw: String(userInfoRaw || "").slice(0, 12000)
          }
        };
        if (valid && platform === "douyin") {
          if (extractedNick) next.name = extractedNick;
          if (extractedUid) next.douyinId = extractedUid;
          if (extractedAvatarUrl) next.avatarUrl = extractedAvatarUrl;
          next.followerCount = Number(extractedFollowerCount ?? next.followerCount ?? 0) || 0;
          next.followingCount = Number(extractedFollowingCount ?? next.followingCount ?? 0) || 0;
          next.totalFavorited = Number(extractedTotalFavorited ?? next.totalFavorited ?? 0) || 0;
          if (extractedSignature) next.signature = extractedSignature;
          if (extractedDashboardOpendDate) next.dashboardOpendDate = extractedDashboardOpendDate;
        } else if (valid && platform === "xiaohongshu") {
          if (extractedNick) next.name = extractedNick;
          if (extractedUid) next.xhsRedId = extractedUid;
          if (extractedAvatarUrl) next.avatarUrl = extractedAvatarUrl;
          next.xhsUserId = String(getCookieValue(cookies, "x-user-id-creator.xiaohongshu.com") || next.xhsUserId || "").trim();
          next.followerCount = Number(extractedFollowerCount ?? next.followerCount ?? 0) || 0;
          next.followingCount = Number(extractedFollowingCount ?? next.followingCount ?? 0) || 0;
          next.totalFavorited = Number(extractedTotalFavorited ?? next.totalFavorited ?? 0) || 0;
          if (extractedSignature) next.signature = extractedSignature;
        } else if (valid && platform === "shipinhao") {
          if (extractedNick) next.name = extractedNick;
          if (extractedUid) next.shipinhaoId = extractedUid;
          if (extractedAvatarUrl) next.avatarUrl = extractedAvatarUrl;
          next.followerCount = Number(extractedFollowerCount ?? next.followerCount ?? 0) || 0;
          next.videoCount = Number(extractedVideoCount ?? next.videoCount ?? 0) || 0;
        }
        writeJsonSafe(metaPath, next);
        return { ok: true, valid, item: next, log: next.lastTestLog };
      } finally {
        try {
          cdp.close();
        } catch {}
        if (startedChrome) {
          let closed = false;
          if (browserWsUrl) {
            try {
              const b = await createCdp(browserWsUrl);
              try {
                await b.send("Browser.close");
                closed = true;
              } finally {
                try {
                  b.close();
                } catch {}
              }
            } catch {}
          }
          if (!closed && chromePid) {
            try {
              await killProcTree({ pid: chromePid });
            } catch {}
          }
        }
      }
    }
    if (!partition) return { ok: false, message: "missing partition" };
    ensureSessionProtocolBlockers(partition);
    const s = session.fromPartition(partition);
    const cookies = await s.cookies.get({});
    const cookieOk = hasAuthCookie(platform, cookies);

    if (platform === "shipinhao") {
      const mod = loadShipinhaoAccountTestMod();
      const res =
        mod && typeof mod.testShipinhaoAccountByPartition === "function"
          ? await mod.testShipinhaoAccountByPartition({
              deps: { session, chromeUserAgent },
              partition
            })
          : { valid: false, info: { ok: false, message: "shipinhao test module missing", raw: "", statusCode: 0 } };
      const valid = !!res?.valid;
      const next = {
        ...meta0,
        cookieCount: Array.isArray(cookies) ? cookies.length : 0,
        status: valid ? "normal" : "invalid",
        updatedAt: Date.now(),
        lastTestLog: {
          at: Date.now(),
          cookieOk,
          userInfoOk: !!res?.info?.ok,
          userInfoStatus: Number(res?.info?.statusCode || 0) || 0,
          extracted: {
            nick_name: String(res?.extractedNick || ""),
            unique_id: String(res?.extractedUid || ""),
            avatar_url: String(res?.extractedAvatarUrl || ""),
            follower_count: Number(res?.extractedFollowerCount ?? 0) || 0,
            video_count: Number(res?.extractedVideoCount ?? 0) || 0
          },
          message: String(res?.info?.message || ""),
          raw: String(res?.info?.raw || "").slice(0, 12000)
        }
      };
      if (valid) {
        next.name = String(res?.extractedNick || next.name || "").trim();
        next.shipinhaoId = String(res?.extractedUid || next.shipinhaoId || "").trim();
        next.avatarUrl = String(res?.extractedAvatarUrl || next.avatarUrl || "").trim();
        next.followerCount = Number(res?.extractedFollowerCount ?? next.followerCount ?? 0) || 0;
        next.videoCount = Number(res?.extractedVideoCount ?? next.videoCount ?? 0) || 0;
      }
      writeJsonSafe(metaPath, next);
      return { ok: true, valid, item: next, log: next.lastTestLog };
    }

    if (platform !== "douyin") {
      const next = {
        ...meta0,
        cookieCount: Array.isArray(cookies) ? cookies.length : 0,
        status: cookieOk ? "normal" : "invalid",
        updatedAt: Date.now()
      };
      writeJsonSafe(metaPath, next);
      return { ok: true, valid: next.status === "normal", item: next };
    }

    const mod = loadDouyinAccountManageMod();
    const dyTest =
      mod && typeof mod.testDouyinAccountByPartition === "function"
        ? await mod.testDouyinAccountByPartition({
            deps: { session, requestUrl, readResponseBody, chromeUserAgent },
            partition
          })
        : null;
    const info = dyTest?.info || null;
    const extractedNick = String(dyTest?.extractedNick || "").trim();
    const extractedUid = String(dyTest?.extractedUid || "").trim();
    const valid = !!dyTest?.valid;

    const next = {
      ...meta0,
      cookieCount: Array.isArray(cookies) ? cookies.length : 0,
      status: valid ? "normal" : "invalid",
      updatedAt: Date.now(),
      lastTestLog: {
        at: Date.now(),
        cookieOk,
        userInfoOk: !!info?.ok,
        extracted: {
          nick_name: extractedNick,
          unique_id: extractedUid,
          avatar_url: String(dyTest?.extractedAvatarUrl || "").trim(),
          follower_count: Number(dyTest?.extractedFollowerCount ?? 0) || 0,
          following_count: Number(dyTest?.extractedFollowingCount ?? 0) || 0,
          total_favorited: Number(dyTest?.extractedTotalFavorited ?? 0) || 0,
          signature: String(dyTest?.extractedSignature || "").trim(),
          dashboard_opend_date: String(dyTest?.extractedDashboardOpendDate || "").trim()
        },
        message: String(info?.message || ""),
        raw: String(info?.raw || "").slice(0, 12000)
      }
    };
    if (valid && info?.profile) {
      next.name = String(info.profile.nickName || extractedNick || next.name || "").trim();
      next.avatarUrl = String(dyTest?.extractedAvatarUrl || info.profile.avatarUrl || next.avatarUrl || "").trim();
      next.douyinId = String(extractedUid || info.profile.douyinId || next.douyinId || "").trim();
      next.followerCount = Number(dyTest?.extractedFollowerCount ?? info.profile.followerCount ?? next.followerCount ?? 0) || 0;
      next.followingCount = Number(dyTest?.extractedFollowingCount ?? info.profile.followingCount ?? next.followingCount ?? 0) || 0;
      next.totalFavorited = Number(dyTest?.extractedTotalFavorited ?? info.profile.totalFavorited ?? next.totalFavorited ?? 0) || 0;
      next.signature = String(dyTest?.extractedSignature || info.profile.signature || next.signature || "").trim();
      next.dashboardOpendDate = String(dyTest?.extractedDashboardOpendDate || info.profile.dashboardOpendDate || next.dashboardOpendDate || "").trim();
    }
    writeJsonSafe(metaPath, next);
    return { ok: true, valid, item: next, log: next.lastTestLog };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

ipcMain.handle("accounts:getLog", async (_event, payload) => {
  try {
    const id = String(payload?.id || "").trim();
    if (!id) return { ok: false, message: "empty id" };
    const metaPath = getAccountMetaPath(id);
    const meta0 = readJsonSafe(metaPath) || null;
    if (!meta0) return { ok: false, message: "account not found" };
    return { ok: true, log: { lastTestLog: meta0.lastTestLog || null, lastLoginLog: meta0.lastLoginLog || null }, item: meta0 };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

ipcMain.handle("accounts:clearLog", async (_event, payload) => {
  try {
    const id = String(payload?.id || "").trim();
    if (!id) return { ok: false, message: "empty id" };
    const metaPath = getAccountMetaPath(id);
    const meta0 = readJsonSafe(metaPath) || null;
    if (!meta0) return { ok: false, message: "account not found" };
    const next = { ...meta0, lastTestLog: null, lastLoginLog: null, updatedAt: Date.now() };
    writeJsonSafe(metaPath, next);
    return { ok: true, item: next };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

ipcMain.handle("accounts:groupsList", async () => {
  try {
    const items = readGroups();
    items.sort((a, b) => (b.updatedAt || b.createdAt) - (a.updatedAt || a.createdAt));
    return { ok: true, items };
  } catch (e) {
    return { ok: false, message: String(e?.message || e), items: [] };
  }
});

ipcMain.handle("accounts:groupsSave", async (_event, payload) => {
  try {
    const group = payload?.group && typeof payload.group === "object" ? payload.group : null;
    if (!group) return { ok: false, message: "empty group" };
    const id = String(group.id || "").trim() || `grp_${Date.now()}_${crypto.randomBytes(3).toString("hex")}`;
    const name = String(group.name || "").trim();
    if (!name) return { ok: false, message: "empty name" };
    const items = readGroups();
    const now = Date.now();
    const idx = items.findIndex((x) => String(x.id) === id);
    const next = { id, name, createdAt: idx >= 0 ? items[idx].createdAt || now : now, updatedAt: now };
    if (idx >= 0) items[idx] = next;
    else items.unshift(next);
    if (!writeGroups(items)) return { ok: false, message: "write failed" };
    return { ok: true, item: next, items };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

ipcMain.handle("accounts:groupsRemove", async (_event, payload) => {
  try {
    const id = String(payload?.id || "").trim();
    if (!id) return { ok: false, message: "empty id" };
    const items = readGroups().filter((x) => String(x.id) !== id);
    if (!writeGroups(items)) return { ok: false, message: "write failed" };
    return { ok: true, items };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

function resolveVideoTemplateRoot() {
  return path.join(resolveUserRuntimeDataRoot(), "talking_videos");
}

function resolvePipAssetLibraryId() {
  return "huazhonghuasucaiku";
}

function ensurePipAssetLibraryContainer() {
  const root = resolveVideoTemplateRoot();
  ensureDir(root);
  const id = resolvePipAssetLibraryId();
  const dir = path.join(root, id);
  ensureDir(dir);
  const metaPath = path.join(dir, "meta.json");
  const prev = readJsonFileSafe(metaPath, {});
  const createdAt = Number(prev?.createdAt || 0) || Date.now();
  const next = {
    ...prev,
    id,
    name: String(prev?.name || "画中画素材库"),
    createdAt,
    type: "asset_library",
    edit: prev?.edit && typeof prev.edit === "object" ? prev.edit : { baseVideoPath: "", main: { startSec: 0, endSec: 0 }, pipLayers: [], subtitleLayers: [], music: { enable: false, filePath: "", volume: 0.35 } }
  };
  fs.writeFileSync(metaPath, JSON.stringify(next, null, 2), "utf-8");
  ensureDir(path.join(dir, "assets"));
  ensureDir(path.join(dir, "renders"));
  return { id, dir, meta: next };
}

function resolveVideoEditsRoot() {
  return path.join(resolveUserRuntimeDataRoot(), "video_edits");
}

function safeResolveUnderRoot(rootDir, leaf) {
  const rootAbs = path.resolve(rootDir);
  const full = path.resolve(rootAbs, String(leaf || ""));
  if (!full.startsWith(rootAbs)) return "";
  return full;
}

function readJsonFileSafe(p, fallback) {
  try {
    if (!fs.existsSync(p)) return fallback;
    const raw = fs.readFileSync(p, "utf-8");
    const obj = JSON.parse(raw || "{}");
    return obj && typeof obj === "object" ? obj : fallback;
  } catch {
    return fallback;
  }
}

function escapeFfmpegSubtitlesPath(p) {
  const raw = String(p || "");
  return raw.replace(/\\/g, "\\\\").replace(/:/g, "\\:").replace(/'/g, "\\'");
}

function escapeFfmpegDrawtextText(s) {
  return String(s || "")
    .replace(/\\/g, "\\\\")
    .replace(/:/g, "\\:")
    .replace(/'/g, "\\'")
    .replace(/\n/g, "\\n")
    .replace(/\r/g, "");
}

function escapeFfmpegDrawtextFontFile(p) {
  const raw = String(p || "").replace(/\\/g, "/");
  return raw.replace(/:/g, "\\:").replace(/'/g, "\\'");
}

function resolveProjectMediaDir(name) {
  const projectRoot = resolveProjectRoot();
  const contentRoot = resolveInstalledContentRoot();
  const dirPath = path.join(contentRoot, String(name || ""));
  // #region debug-point assets-missing-media-dir
  dbgPostInstallAssetsMissingEmit("B", "main.js:resolveProjectMediaDir", "解析项目媒体目录", {
    appIsPackaged: app.isPackaged === true,
    execPath: String(process.execPath || "").trim(),
    __dirname: String(__dirname || "").trim(),
    projectRoot,
    contentRoot,
    mediaName: String(name || "").trim(),
    dirPath,
    exists: !!(dirPath && fs.existsSync(dirPath))
  });
  // #endregion
  return dirPath;
}

function listFilesInDir(dirPath, allowExts) {
  try {
    if (!dirPath || !fs.existsSync(dirPath)) return [];
    const entries = fs.readdirSync(dirPath, { withFileTypes: true });
    return entries
      .filter((e) => e.isFile())
      .map((e) => String(e.name || "").trim())
      .filter(Boolean)
      .filter((n) => {
        const ext = path.extname(n).toLowerCase();
        return allowExts.includes(ext);
      })
      .map((n) => ({ name: n, path: path.join(dirPath, n), ext: path.extname(n).toLowerCase() }));
  } catch {
    return [];
  }
}

function resolveWritableDefaultOutputDir() {
  const folderName = "不空IP智能体导出";
  const candidates = [
    path.join(app.getPath("videos"), folderName),
    path.join(app.getPath("documents"), folderName),
    path.join(app.getPath("downloads"), folderName),
    path.join(resolveRuntimeDataRoot(), "exports")
  ].filter(Boolean);
  for (const dirPath of candidates) {
    try {
      ensureDir(dirPath);
      fs.accessSync(dirPath, fs.constants.W_OK);
      return dirPath;
    } catch {}
  }
  const fallback = path.join(resolveRuntimeDataRoot(), "exports");
  ensureDir(fallback);
  return fallback;
}

function syncRuntimeFontsFromInstall() {
  const runtimeDir = path.join(resolveRuntimeDataRoot(), "ziti");
  ensureDir(runtimeDir);
  const installDir = resolveProjectMediaDir("ziti");
  const installFonts = listFilesInDir(installDir, [".ttf", ".otf", ".ttc"]);
  const copied = [];
  const skipped = [];
  installFonts.forEach((item) => {
    const src = String(item?.path || "").trim();
    const name = String(item?.name || "").trim();
    if (!src || !name) return;
    const dst = path.join(runtimeDir, name);
    try {
      if (fs.existsSync(dst)) {
        skipped.push(name);
        return;
      }
      fs.copyFileSync(src, dst);
      copied.push(name);
    } catch {}
  });
  const runtimeFonts = listFilesInDir(runtimeDir, [".ttf", ".otf", ".ttc"]);
  return {
    runtimeDir,
    installDir,
    installCount: installFonts.length,
    runtimeCount: runtimeFonts.length,
    copied,
    skipped
  };
}

function inspectBaseResourceMappings() {
  const installRoot = resolveInstalledContentRoot();
  const resourcesDir = String(process.resourcesPath || "").trim() || path.join(installRoot, "resources");
  const localesCandidates = [path.join(resourcesDir, "locales"), path.join(installRoot, "locales")];
  const localesDir = localesCandidates.find((p) => p && fs.existsSync(p)) || localesCandidates[0];
  const runtimeRoot = resolveRuntimeDataRoot();
  const voicePreviewRoot = resolveVoicePreviewCacheRoot();
  const bgmDir = resolveProjectMediaDir("bgm");
  const zitiDir = resolveProjectMediaDir("ziti");
  const checkDir = (dirPath, allowExts = []) => {
    try {
      const exists = !!(dirPath && fs.existsSync(dirPath));
      const count = exists && allowExts.length ? listFilesInDir(dirPath, allowExts).length : exists ? 1 : 0;
      return { exists, count };
    } catch {
      return { exists: false, count: 0 };
    }
  };
  const items = [
    {
      key: "bgm",
      label: "bgm",
      purpose: "首页字幕和音乐模块的系统背景音乐",
      path: bgmDir,
      ...checkDir(bgmDir, [".mp3", ".wav", ".m4a", ".aac", ".flac"])
    },
    {
      key: "voice-preview-cache",
      label: "voice-preview-cache",
      purpose: "系统音色试听与克隆音色预览缓存",
      path: voicePreviewRoot,
      ...checkDir(voicePreviewRoot, [".wav", ".mp3", ".m4a"])
    },
    {
      key: "ziti",
      label: "ziti",
      purpose: "封面生成、字幕模板、封面模板字体资源",
      path: zitiDir,
      ...checkDir(zitiDir, [".ttf", ".otf", ".ttc"])
    },
    {
      key: "resources",
      label: "resources",
      purpose: "Electron 运行时资源目录",
      path: resourcesDir,
      ...checkDir(resourcesDir)
    },
    {
      key: "locales",
      label: "locales",
      purpose: "Electron 语言资源目录",
      path: localesDir,
      ...checkDir(localesDir)
    },
    {
      key: "runtime-data",
      label: "runtime-data",
      purpose: "软件运行时用户数据目录",
      path: runtimeRoot,
      ...checkDir(runtimeRoot)
    }
  ];
  return { installRoot, resourcesDir, localesDir, runtimeRoot, items };
}

ipcMain.handle("app:initializeInstallFiles", async () => {
  try {
    const mapping = inspectBaseResourceMappings();
    const fontSync = syncRuntimeFontsFromInstall();
    const sysPreviewCount = listFilesInDir(resolveVoicePreviewCacheRoot(), [".wav"]).filter((item) => /^sys_/i.test(String(item?.name || ""))).length;
    const missing = mapping.items.filter((item) => item.exists !== true).map((item) => item.label);
    const summary = missing.length
      ? `文件初始化完成，但仍缺少：${missing.join("、")}`
      : `文件初始化完成：已检查 ${mapping.items.length} 个基础目录，字体同步 ${fontSync.copied.length} 个，系统音色 ${sysPreviewCount} 个。`;
    return {
      ok: true,
      summary,
      installRoot: mapping.installRoot,
      runtimeRoot: mapping.runtimeRoot,
      items: mapping.items,
      fontSync,
      sysPreviewCount
    };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

