ipcMain.handle("videoTemplate:importAssets", async (_event, payload) => {
  try {
    const fallback = ensurePipAssetLibraryContainer();
    const rawId = String(payload?.id || "").trim();
    const id = rawId || fallback.id;
    const filePaths = Array.isArray(payload?.filePaths) ? payload.filePaths.map((x) => String(x || "").trim()).filter(Boolean) : [];
    if (!filePaths.length) return { ok: false, message: "empty filePaths" };
    const root = resolveVideoTemplateRoot();
    const dir = safeResolveUnderRoot(root, id);
    if (!dir || !fs.existsSync(dir)) return { ok: false, message: "not found" };
    const assetsDir = path.join(dir, "assets");
    ensureDir(assetsDir);
    const items = [];
    for (const filePath of filePaths) {
      if (!filePath || !fs.existsSync(filePath)) continue;
      const ext = String(path.extname(filePath || "") || "").toLowerCase();
      const isImage = [".png", ".jpg", ".jpeg", ".webp"].includes(ext);
      const isGif = ext === ".gif";
      const isVideo = [".mp4", ".mov", ".webm", ".mkv"].includes(ext);
      if (!isImage && !isGif && !isVideo) continue;
      const baseName = sanitizeFsName(path.basename(filePath, ext), `asset_${Date.now()}`) || `asset_${Date.now()}`;
      const dst = path.join(assetsDir, `${baseName}_${Date.now()}${ext || ".dat"}`);
      fs.copyFileSync(filePath, dst);
      items.push({
        path: dst,
        type: isImage ? "image" : isGif ? "gif" : "video",
        name: path.basename(dst)
      });
    }
    return { ok: true, id, items };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

function parseSrtTimeToSec(s) {
  const raw = String(s || "").trim();
  const m = raw.match(/(\d+):(\d+):(\d+),(\d+)/);
  if (!m) return 0;
  const hh = Number(m[1] || 0);
  const mm = Number(m[2] || 0);
  const ss = Number(m[3] || 0);
  const ms = Number(m[4] || 0);
  return hh * 3600 + mm * 60 + ss + ms / 1000;
}

function parseSrtToSegments(srtText) {
  const raw = String(srtText || "").replace(/\r\n/g, "\n").trim();
  if (!raw) return [];
  const blocks = raw.split(/\n{2,}/g);
  const out = [];
  for (const b of blocks) {
    const lines = b.split("\n").map((x) => String(x || "").trim());
    const timeLineIdx = lines.findIndex((x) => x.includes("-->"));
    if (timeLineIdx < 0) continue;
    const timeLine = lines[timeLineIdx];
    const [a, c] = timeLine.split("-->").map((x) => String(x || "").trim());
    const startSec = parseSrtTimeToSec(a);
    const endSec = parseSrtTimeToSec(c);
    const text = lines.slice(timeLineIdx + 1).join("\n").trim();
    if (!text) continue;
    out.push({ startSec, endSec, text });
  }
  return out.filter((x) => Number.isFinite(x.startSec) && Number.isFinite(x.endSec) && x.endSec > x.startSec);
}

function normalizeSubtitleItems(obj) {
  const pick = (x) => ({
    startSec: Number(x?.startSec ?? x?.start ?? x?.start_time ?? x?.from ?? 0) || 0,
    endSec: Number(x?.endSec ?? x?.end ?? x?.end_time ?? x?.to ?? 0) || 0,
    text: String(x?.text ?? x?.content ?? x?.sentence ?? x?.line ?? "").trim()
  });
  if (Array.isArray(obj)) return obj.map(pick).filter((x) => x.text);
  if (obj && typeof obj === "object") {
    if (Array.isArray(obj.segments)) return obj.segments.map(pick).filter((x) => x.text);
    if (Array.isArray(obj.items)) return obj.items.map(pick).filter((x) => x.text);
    if (Array.isArray(obj.data?.segments)) return obj.data.segments.map(pick).filter((x) => x.text);
    if (Array.isArray(obj.result?.segments)) return obj.result.segments.map(pick).filter((x) => x.text);
  }
  return [];
}

