ipcMain.handle("videoTemplate:loadRecognizedSubtitles", async (event, payload) => {
  try {
    const id = String(payload?.id || "").trim();
    if (!id) return { ok: false, message: "empty id" };
    const root = resolveVideoTemplateRoot();
    const dir = safeResolveUnderRoot(root, id);
    if (!dir || !fs.existsSync(dir)) return { ok: false, message: "not found" };

    const candidates = [
      path.join(dir, "subtitles.json"),
      path.join(dir, "subtitle.json"),
      path.join(dir, "asr.json"),
      path.join(dir, "captions.json"),
      path.join(dir, "subtitles.srt"),
      path.join(dir, "subtitle.srt"),
      path.join(dir, "captions.srt"),
      path.join(dir, "sources", "subtitles.json"),
      path.join(dir, "sources", "subtitle.json"),
      path.join(dir, "sources", "subtitles.srt"),
      path.join(dir, "sources", "subtitle.srt")
    ];
    let found = "";
    for (const p of candidates) {
      if (fs.existsSync(p)) {
        found = p;
        break;
      }
    }
    if (!found) return { ok: true, items: [] };

    const ext = path.extname(found).toLowerCase();
    if (ext === ".srt") {
      const raw = fs.readFileSync(found, "utf-8");
      const items = parseSrtToSegments(raw);
      return { ok: true, items };
    }

    const raw = fs.readFileSync(found, "utf-8");
    const obj = JSON.parse(raw || "{}");
    const items = normalizeSubtitleItems(obj)
      .map((x) => ({ ...x, startSec: Math.max(0, x.startSec), endSec: Math.max(0, x.endSec) }))
      .filter((x) => x.text && x.endSec > x.startSec)
      .sort((a, b) => Number(a.startSec || 0) - Number(b.startSec || 0));
    return { ok: true, items };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

