ipcMain.handle("videoTemplate:render", async (event, payload) => {
  const taskId = String(payload?.taskId || crypto.randomBytes(8).toString("hex"));
  const task = { taskId, proc: null, canceled: false };
  _videoTasks.set(taskId, task);
  try {
    const id = String(payload?.id || "").trim();
    if (!id) return { ok: false, taskId, message: "empty id" };
    const root = resolveVideoTemplateRoot();
    const dir = safeResolveUnderRoot(root, id);
    if (!dir || !fs.existsSync(dir)) return { ok: false, taskId, message: "not found" };

    const config = payload?.config && typeof payload.config === "object" ? payload.config : {};
    const baseVideoPath = String(config?.baseVideoPath || payload?.baseVideoPath || path.join(dir, "result.mp4")).trim();
    if (!baseVideoPath || !fs.existsSync(baseVideoPath)) return { ok: false, taskId, message: "base video not found" };

    const layers = Array.isArray(config?.pipLayers) ? config.pipLayers : [];
    const subtitleLayers = Array.isArray(config?.subtitleLayers) ? config.subtitleLayers : [];
    const musicCfg = config?.music && typeof config.music === "object" ? config.music : {};
    const mainCfg = config?.main && typeof config.main === "object" ? config.main : {};

    const enablePip = layers.some((l) => l && l.enable !== false);
    const enableMusic = musicCfg?.enable === true;
    const enableSub = subtitleLayers.some((s) => s && s.enable !== false && String(s.text || "").trim());

    const musicPath = String(musicCfg?.filePath || "").trim();
    const musicVolume = Math.max(0, Math.min(2.0, Number(musicCfg?.volume || 0.35) || 0.35));

    if (enableMusic && (!musicPath || !fs.existsSync(musicPath))) return { ok: false, taskId, message: "background music not found" };
    if (enableSub) {
      for (const s of subtitleLayers) {
        if (!s || s.enable === false) continue;
        const text = String(s.text || "").trim();
        if (!text) continue;
        const fp = String(s.fontPath || "").trim();
        if (fp && !fs.existsSync(fp)) return { ok: false, taskId, message: "font not found" };
      }
    }

    const ffmpegExe = pickFfmpegExeFromBundles();
    if (!ffmpegExe || !fs.existsSync(ffmpegExe)) return { ok: false, taskId, message: "ffmpeg.exe not found" };

    const rendersDir = path.join(dir, "renders");
    ensureDir(rendersDir);
    const outPath = path.join(rendersDir, `edit_${Date.now()}.mp4`);

    const baseMeta = await probeVideoMetaViaFfmpeg(ffmpegExe, baseVideoPath);
    const hasBaseAudio = baseMeta?.hasAudio === true;
    const baseDuration = Number(baseMeta?.durationSec || 0) || 0;
    const mainStart = Math.max(0, Number(mainCfg?.startSec || 0) || 0);
    const mainEndRaw = Number(mainCfg?.endSec || 0) || 0;
    const mainEnd = mainEndRaw > 0 ? mainEndRaw : baseDuration;
    const mainDur = mainEnd > mainStart ? mainEnd - mainStart : 0;

    const args = ["-y", "-hide_banner"];
    if (mainStart > 0) args.push("-ss", String(mainStart.toFixed(3)));
    if (mainDur > 0) args.push("-t", String(mainDur.toFixed(3)));
    args.push("-i", baseVideoPath);
    const timelineTotalSec = mainDur > 0 ? mainDur : baseDuration;
    const inputLayers = layers
      .map((l) => ({
        enable: l?.enable !== false,
        path: String(l?.path || "").trim(),
        type: String(l?.type || "").trim(),
        scale: Math.max(0.05, Math.min(1.0, Number(l?.scale ?? 0.35) || 0.35)),
        xPct: Math.max(0, Math.min(1.0, Number(l?.xPct ?? 1.0) || 1.0)),
        yPct: Math.max(0, Math.min(1.0, Number(l?.yPct ?? 0.0) || 0.0)),
        startSec: Math.max(0, Number(l?.startSec || 0) || 0),
        endSec: Math.max(0, Number(l?.endSec || 0) || 0),
        chromaKey: l?.chromaKey === true
      }))
      .filter((l) => l.enable && l.path && fs.existsSync(l.path));
    const orderedLayers = inputLayers.slice().reverse();

    const imageExts = [".png", ".jpg", ".jpeg", ".webp", ".gif"];
    const videoExts = [".mp4", ".mov", ".webm", ".mkv"];

    const layerInputIndex = [];
    for (const l of orderedLayers) {
      const ext = path.extname(l.path).toLowerCase();
      const isImage = l.type === "image" || imageExts.includes(ext);
      const isVideo = l.type === "video" || videoExts.includes(ext);
      if (isImage) {
        args.push("-loop", "1", "-i", l.path);
        layerInputIndex.push({ ...l, kind: "image" });
      } else if (isVideo) {
        args.push("-i", l.path);
        layerInputIndex.push({ ...l, kind: "video" });
      }
    }

    const bgIndex = enableMusic ? 1 + layerInputIndex.length : -1;
    if (enableMusic) args.push("-stream_loop", "-1", "-i", musicPath);

    const filters = [];
    let vIn = "[v0]";
    filters.push("[0:v]setpts=PTS-STARTPTS[v0]");

    if (enablePip && layerInputIndex.length) {
      let seq = 0;
      for (let i = 0; i < layerInputIndex.length; i += 1) {
        const l = layerInputIndex[i];
        const inputIdx = 1 + i;
        const keyPart = l.chromaKey ? ",chromakey=0x00ff00:0.22:0.08" : "";
        filters.push(`[${inputIdx}:v]setpts=PTS-STARTPTS,scale=iw*${l.scale}:ih*${l.scale}${keyPart}[ov${i}]`);
        const x = `(W-w)*${l.xPct}`;
        const y = `(H-h)*${l.yPct}`;
        const end = l.endSec > 0 ? Math.min(l.endSec, timelineTotalSec || l.endSec) : timelineTotalSec;
        const enableExpr = timelineTotalSec > 0 ? `:enable='between(t,${l.startSec.toFixed(3)},${Number(end || 0).toFixed(3)})'` : "";
        filters.push(`${vIn}[ov${i}]overlay=${x}:${y}:eof_action=pass${enableExpr}[v${seq + 1}]`);
        seq += 1;
        vIn = `[v${seq}]`;
      }
    }

    if (enableSub) {
      const usableSubs = subtitleLayers
        .map((s) => ({
          enable: s?.enable !== false,
          text: String(s?.text || "").trim(),
          fontPath: String(s?.fontPath || "").trim(),
          fontSize: Math.max(18, Math.min(120, Number(s?.fontSize || 48) || 48)),
          xPct: Math.max(0, Math.min(1.0, Number(s?.xPct ?? 0.5) || 0.5)),
          yPct: Math.max(0, Math.min(1.0, Number(s?.yPct ?? 0.9) || 0.9)),
          startSec: Math.max(0, Number(s?.startSec || 0) || 0),
          endSec: Math.max(0, Number(s?.endSec || 0) || 0)
        }))
        .filter((s) => s.enable && s.text);
      const orderedSubs = usableSubs.slice().reverse();
      let subSeq = 0;
      for (const s of orderedSubs) {
        const escText = escapeFfmpegDrawtextText(s.text);
        const fontPart = s.fontPath ? `:fontfile='${escapeFfmpegDrawtextFontFile(s.fontPath)}'` : "";
        const x = `(w-text_w)*${s.xPct}`;
        const y = `(h-text_h)*${s.yPct}`;
        const end = s.endSec > 0 ? Math.min(s.endSec, timelineTotalSec || s.endSec) : timelineTotalSec;
        const enableExpr = timelineTotalSec > 0 ? `:enable='between(t,${s.startSec.toFixed(3)},${Number(end || 0).toFixed(3)})'` : "";
        filters.push(
          `${vIn}drawtext${fontPart}:text='${escText}':fontsize=${s.fontSize}:fontcolor=white:borderw=2:bordercolor=black@0.6:x=${x}:y=${y}${enableExpr}[vsub${subSeq}]`
        );
        vIn = `[vsub${subSeq}]`;
        subSeq += 1;
      }
    }

    let audioOutLabel = "";
    if (enableMusic) {
      if (hasBaseAudio) {
        filters.push(`[0:a]volume=1.0[a0]`);
        filters.push(`[${bgIndex}:a]volume=${musicVolume}[a1]`);
        filters.push(`[a0][a1]amix=inputs=2:duration=first:dropout_transition=2[aout]`);
      } else {
        filters.push(`[${bgIndex}:a]volume=${musicVolume}[aout]`);
      }
      audioOutLabel = "[aout]";
    }

    if (filters.length) {
      args.push("-filter_complex", filters.join(";"));
      args.push("-map", vIn);
      if (enableMusic) args.push("-map", audioOutLabel);
      else args.push("-map", "0:a?");
    } else {
      args.push("-map", "0:v", "-map", "0:a?");
    }

    args.push("-c:v", "libx264", "-preset", "veryfast", "-crf", "20");
    if (enableMusic || hasBaseAudio) args.push("-c:a", "aac", "-b:a", "192k");
    args.push("-shortest", outPath);

    await runFfmpeg(ffmpegExe, args, {
      cwd: rendersDir,
      isCanceled: () => task.canceled === true,
      task,
      onStderr: (line) => sendVideoLog(event, taskId, "debug", String(line || "").trim())
    });
    sendVideoLog(event, taskId, "info", `已输出：${outPath}`);
    return { ok: true, taskId, outPath };
  } catch (e) {
    return { ok: false, taskId, message: String(e?.message || e) };
  } finally {
    _videoTasks.delete(taskId);
  }
});

function resolveAvatarAssetsRoot() {
  const projectRoot = resolveProjectRoot();
  const contentRoot = resolveInstalledContentRoot();
  const root = path.join(contentRoot, "avatar-assets");
  // #region debug-point assets-missing-avatar-assets-root
  dbgPostInstallAssetsMissingEmit("C", "main.js:resolveAvatarAssetsRoot", "解析头像素材根目录", {
    appIsPackaged: app.isPackaged === true,
    execPath: String(process.execPath || "").trim(),
    __dirname: String(__dirname || "").trim(),
    projectRoot,
    contentRoot,
    root,
    exists: !!(root && fs.existsSync(root))
  });
  // #endregion
  return root;
}

function resolveRuntimeDataRoot() {
  const root = path.join(app.getPath("userData"), "runtime-data");
  ensureDir(root);
  return root;
}

function sanitizeRuntimeUserId(input) {
  return String(input || "")
    .trim()
    .replace(/[<>:"/\\|?*\x00-\x1F]/g, "_")
    .replace(/\s+/g, "_")
    .slice(0, 120);
}

function getRuntimeAuthStatePath() {
  return path.join(resolveRuntimeDataRoot(), "runtime-auth.json");
}

function readRuntimeAuthState() {
  const raw = readJsonSafe(getRuntimeAuthStatePath()) || {};
  return {
    userId: sanitizeRuntimeUserId(raw.userId),
    updatedAt: Number(raw.updatedAt || 0) || 0
  };
}

function writeRuntimeAuthState(userId) {
  const cleanUserId = sanitizeRuntimeUserId(userId);
  writeJsonSafe(getRuntimeAuthStatePath(), {
    userId: cleanUserId,
    updatedAt: Date.now()
  });
  return cleanUserId;
}

function getCurrentRuntimeUserId() {
  if (_currentRuntimeUserId) return _currentRuntimeUserId;
  const saved = readRuntimeAuthState();
  _currentRuntimeUserId = sanitizeRuntimeUserId(saved.userId);
  return _currentRuntimeUserId;
}

function hasFsEntries(targetPath) {
  try {
    if (!targetPath || !fs.existsSync(targetPath)) return false;
    const stat = fs.statSync(targetPath);
    if (stat.isFile()) return stat.size > 0;
    if (!stat.isDirectory()) return false;
    return fs.readdirSync(targetPath).length > 0;
  } catch {
    return false;
  }
}

function copyFsTreeIfNeeded(fromPath, toPath) {
  try {
    if (!fromPath || !toPath) return false;
    if (!fs.existsSync(fromPath)) return false;
    if (hasFsEntries(toPath)) return false;
    ensureDir(path.dirname(toPath));
    fs.cpSync(fromPath, toPath, { recursive: true, force: false, errorOnExist: false });
    return true;
  } catch {
    return false;
  }
}

function getRuntimeUserMigrationStatePath() {
  return path.join(resolveRuntimeDataRoot(), "user-scope-migration.json");
}

function resolveUserRuntimeDataRoot(userId) {
  const cleanUserId = sanitizeRuntimeUserId(userId || getCurrentRuntimeUserId());
  if (!cleanUserId) return resolveRuntimeDataRoot();
  const root = path.join(resolveRuntimeDataRoot(), "users", cleanUserId);
  ensureDir(root);
  return root;
}

function maybeMigrateLegacyRuntimeDataToUser(userId) {
  const cleanUserId = sanitizeRuntimeUserId(userId);
  if (!cleanUserId) return { ok: false, migrated: false, skipped: true };
  const statePath = getRuntimeUserMigrationStatePath();
  const state = readJsonSafe(statePath) || {};
  const migratedToUserId = sanitizeRuntimeUserId(state.migratedToUserId);
  if (migratedToUserId && migratedToUserId !== cleanUserId) {
    return { ok: true, migrated: false, skipped: true, migratedToUserId };
  }
  const legacyRoot = resolveRuntimeDataRoot();
  const userRoot = resolveUserRuntimeDataRoot(cleanUserId);
  const scopedDirs = ["accounts", "avatar-library", "publish_drafts", "template_stores", "talking_videos", "video_edits"];
  const copied = [];
  for (const dirName of scopedDirs) {
    const fromPath = path.join(legacyRoot, dirName);
    const toPath = path.join(userRoot, dirName);
    if (copyFsTreeIfNeeded(fromPath, toPath)) copied.push(dirName);
  }
  try {
    const legacyCloneVoicePath = path.join(legacyRoot, "shouye", "kelongyinpin", "kelongyinpin.json");
    const nextCloneVoicePath = path.join(userRoot, "shouye", "kelongyinpin", "kelongyinpin.json");
    if (copyFsTreeIfNeeded(legacyCloneVoicePath, nextCloneVoicePath)) copied.push("shouye/kelongyinpin/kelongyinpin.json");
  } catch {}
  if (!migratedToUserId || migratedToUserId === cleanUserId) {
    writeJsonSafe(statePath, {
      migratedToUserId: cleanUserId,
      migratedAt: Date.now(),
      copied
    });
  }
  return { ok: true, migrated: copied.length > 0, copied, migratedToUserId: cleanUserId };
}

function setCurrentRuntimeUserId(userId) {
  const cleanUserId = writeRuntimeAuthState(userId);
  const previous = _currentRuntimeUserId;
  _currentRuntimeUserId = cleanUserId;
  if (cleanUserId) maybeMigrateLegacyRuntimeDataToUser(cleanUserId);
  return previous !== cleanUserId;
}

function resolveAvatarLibraryRoot() {
  return path.join(resolveUserRuntimeDataRoot(), "avatar-library");
}

function resolveAvatarIndexPath() {
  return path.join(resolveAvatarLibraryRoot(), "index.json");
}

function resolveAvatarItemsRoot() {
  return path.join(resolveAvatarLibraryRoot(), "avatars");
}

function resolvePublishDraftsRoot() {
  return path.join(resolveUserRuntimeDataRoot(), "publish_drafts");
}

function sanitizeFsName(input, fallback = "draft") {
  const raw = String(input || "").trim();
  const s = raw || fallback;
  return s
    .replace(/[<>:"/\\|?*\x00-\x1F]/g, "_")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 80);
}

function readAvatarIndex() {
  const p = resolveAvatarIndexPath();
  try {
    if (!fs.existsSync(p)) return [];
    const raw = fs.readFileSync(p, "utf-8");
    const arr = JSON.parse(raw || "[]");
    return Array.isArray(arr) ? arr : [];
  } catch {
    return [];
  }
}

function writeAvatarIndex(items) {
  const root = resolveAvatarLibraryRoot();
  ensureDir(root);
  ensureDir(resolveAvatarItemsRoot());
  const p = resolveAvatarIndexPath();
  try {
    const next = Array.isArray(items) ? items : [];
    fs.writeFileSync(p, JSON.stringify(next, null, 2), "utf-8");
  } catch {}
}

function pickFfmpegExeFromBundles() {
  const bundles = scanProjectBundles();
  const order = ["TTS", "ASR", "VideoSync", "Unknown"];
  const sorted = bundles.slice().sort((a, b) => order.indexOf(a.type) - order.indexOf(b.type));
  for (const it of sorted) {
    const ffmpegExe = path.join(it.bundleDir, "runtime", "ffmpeg", "bin", "ffmpeg.exe");
    if (fs.existsSync(ffmpegExe)) return ffmpegExe;
  }
  return "";
}

function probeVideoMetaViaFfmpeg(ffmpegExe, inputPath) {
  return new Promise((resolve) => {
    if (!ffmpegExe || !fs.existsSync(ffmpegExe))
      return resolve({ width: 0, height: 0, durationSec: 0, fps: 0, hasAudio: false, videoStartSec: 0, audioStartSec: 0, avOffsetSec: 0 });
    if (!inputPath || !fs.existsSync(inputPath))
      return resolve({ width: 0, height: 0, durationSec: 0, fps: 0, hasAudio: false, videoStartSec: 0, audioStartSec: 0, avOffsetSec: 0 });
    const tryResolveViaFfprobe = () => {
      try {
        const ffprobeExe = String(ffmpegExe || "").replace(/ffmpeg\.exe$/i, "ffprobe.exe");
        if (!ffprobeExe || !fs.existsSync(ffprobeExe)) return false;
        const p = spawn(ffprobeExe, ["-v", "error", "-print_format", "json", "-show_format", "-show_streams", inputPath], {
          windowsHide: true
        });
        let stdout = "";
        p.stdout.on("data", (d) => {
          stdout += d.toString("utf-8");
          if (stdout.length > 240000) stdout = stdout.slice(-240000);
        });
        p.on("exit", () => {
          try {
            const parsed = JSON.parse(stdout || "{}");
            const streams = Array.isArray(parsed?.streams) ? parsed.streams : [];
            const format = parsed?.format && typeof parsed.format === "object" ? parsed.format : {};
            const v = streams.find((s) => String(s?.codec_type || "") === "video") || {};
            const a = streams.find((s) => String(s?.codec_type || "") === "audio") || {};
            const width = Number(v?.width || 0) || 0;
            const height = Number(v?.height || 0) || 0;
            const hasAudio = streams.some((s) => String(s?.codec_type || "") === "audio");
            const parseNum = (x) => {
              const n = Number(x);
              return Number.isFinite(n) ? n : 0;
            };
            const parseRate = (r) => {
              const s = String(r || "").trim();
              if (!s) return 0;
              if (/^\d+(\.\d+)?$/.test(s)) return Number(s) || 0;
              const m = s.match(/^(\d+(?:\.\d+)?)[/](\d+(?:\.\d+)?)$/);
              if (!m) return 0;
              const a = Number(m[1] || 0);
              const b = Number(m[2] || 0);
              if (!a || !b) return 0;
              return a / b;
            };
            const fps = Math.max(parseRate(v?.avg_frame_rate), parseRate(v?.r_frame_rate));
            const durationSec = Number(format?.duration || v?.duration || 0) || 0;
            const videoStartSec = parseNum(v?.start_time ?? 0);
            const audioStartSec = parseNum(a?.start_time ?? 0);
            const avOffsetSec = Number.isFinite(audioStartSec) && Number.isFinite(videoStartSec) ? audioStartSec - videoStartSec : 0;
            resolve({
              width,
              height,
              durationSec: Number.isFinite(durationSec) ? durationSec : 0,
              fps: Number.isFinite(fps) ? fps : 0,
              hasAudio,
              videoStartSec: Number.isFinite(videoStartSec) ? videoStartSec : 0,
              audioStartSec: Number.isFinite(audioStartSec) ? audioStartSec : 0,
              avOffsetSec: Number.isFinite(avOffsetSec) ? avOffsetSec : 0
            });
          } catch {
            resolveViaFfmpegText();
          }
        });
        p.on("error", () => resolveViaFfmpegText());
        return true;
      } catch {
        return false;
      }
    };

    const resolveViaFfmpegText = () => {
      const p = spawn(ffmpegExe, ["-hide_banner", "-i", inputPath], { windowsHide: true });
      let stderr = "";
      p.stderr.on("data", (d) => {
        stderr += d.toString("utf-8");
        if (stderr.length > 60000) stderr = stderr.slice(-60000);
      });
      p.on("exit", () => {
        let durationSec = 0;
        const dur = stderr.match(/Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)/i);
        if (dur) {
          const hh = Number(dur[1] || 0);
          const mm = Number(dur[2] || 0);
          const ss = Number(dur[3] || 0);
          durationSec = hh * 3600 + mm * 60 + ss;
        }
        let width = 0;
        let height = 0;
        const wh = stderr.match(/,\s*(\d{2,5})x(\d{2,5})[,\s]/i);
        if (wh) {
          width = Number(wh[1] || 0);
          height = Number(wh[2] || 0);
        }
        let fps = 0;
        const fpsM = stderr.match(/(\d+(?:\.\d+)?)\s*fps/i);
        if (fpsM) fps = Number(fpsM[1] || 0);
        const hasAudio = /\bAudio:\b/i.test(stderr);
        resolve({
          width,
          height,
          durationSec: Number.isFinite(durationSec) ? durationSec : 0,
          fps: Number.isFinite(fps) ? fps : 0,
          hasAudio,
          videoStartSec: 0,
          audioStartSec: 0,
          avOffsetSec: 0
        });
      });
      p.on("error", () => resolve({ width: 0, height: 0, durationSec: 0, fps: 0, hasAudio: false, videoStartSec: 0, audioStartSec: 0, avOffsetSec: 0 }));
    };

    if (!tryResolveViaFfprobe()) resolveViaFfmpegText();
  });
}

async function generateVideoThumb(ffmpegExe, inputPath, outJpgPath) {
  if (!ffmpegExe || !fs.existsSync(ffmpegExe)) return false;
  if (!inputPath || !fs.existsSync(inputPath)) return false;
  try {
    await runFfmpeg(ffmpegExe, ["-y", "-ss", "0.2", "-i", inputPath, "-frames:v", "1", "-q:v", "2", outJpgPath], {
      cwd: path.dirname(outJpgPath)
    });
    return fs.existsSync(outJpgPath);
  } catch {
    return false;
  }
}

ipcMain.handle("homeExport:exportBundle", async (_event, payload) => {
  try {
    const result = exportHomePublishBundle({
      outputDir: String(payload?.outputDir || "").trim(),
      videoPath: String(payload?.videoPath || "").trim(),
      coverPath: String(payload?.coverPath || "").trim(),
      title: String(payload?.title || "").trim()
    });
    return { ok: true, ...result };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
});

ipcMain.handle("audio:probeDuration", async (_event, payload) => {
  try {
    const filePath = String(payload?.filePath || "").trim();
    if (!filePath) return { ok: false, message: "empty filePath", duration: 0 };
    const ffmpegExe = pickFfmpegExeFromBundles();
    if (!ffmpegExe || !fs.existsSync(ffmpegExe)) return { ok: false, message: "ffmpeg.exe not found", duration: 0 };
    const meta = await probeVideoMetaViaFfmpeg(ffmpegExe, filePath);
    const duration = Number(meta?.durationSec || 0);
    return { ok: true, duration: Number.isFinite(duration) && duration > 0 ? duration : 0 };
  } catch (e) {
    return { ok: false, message: String(e?.message || e), duration: 0 };
  }
});

async function handlePublishDraftSaveRequest(_event, payload) {
  try {
    const nameRaw = String(payload?.name || "").trim();
    const draft = payload?.draft && typeof payload.draft === "object" ? payload.draft : null;
    if (!draft) return { ok: false, message: "empty draft" };
    const draftsRoot = resolvePublishDraftsRoot();
    ensureDir(draftsRoot);
    const safeName = sanitizeFsName(nameRaw, `draft_${new Date().toISOString().slice(0, 10)}`);
    const id = `pubdraft_${Date.now()}_${crypto.randomBytes(3).toString("hex")}_${safeName}`;
    const dirPath = path.join(draftsRoot, id);
    ensureDir(dirPath);
    const outPath = path.join(dirPath, "draft.json");
    const now = Date.now();
    fs.writeFileSync(
      outPath,
      JSON.stringify(
        {
          id,
          name: safeName,
          createdAt: now,
          updatedAt: now,
          draft
        },
        null,
        2
      ),
      "utf-8"
    );
    return { ok: true, id, name: safeName, dirPath, outPath };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

ipcMain.handle("publishDraft:save", handlePublishDraftSaveRequest);

async function handlePublishDraftListRequest() {
  try {
    const draftsRoot = resolvePublishDraftsRoot();
    ensureDir(draftsRoot);
    const items = [];
    const entries = fs.readdirSync(draftsRoot, { withFileTypes: true });
    for (const ent of entries) {
      try {
        if (!ent.isDirectory()) continue;
        const id = String(ent.name || "").trim();
        if (!id) continue;
        const p = path.join(draftsRoot, id, "draft.json");
        if (!fs.existsSync(p)) continue;
        const raw = fs.readFileSync(p, "utf-8");
        const obj = JSON.parse(raw || "{}");
        const name = sanitizeFsName(obj?.name || id, id);
        const createdAt = Number(obj?.createdAt || 0) || 0;
        const updatedAt = Number(obj?.updatedAt || createdAt || 0) || 0;
        items.push({ id, name, createdAt, updatedAt });
      } catch {}
    }
    items.sort((a, b) => (Number(b.updatedAt || 0) || 0) - (Number(a.updatedAt || 0) || 0));
    return { ok: true, items };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

ipcMain.handle("publishDraft:list", handlePublishDraftListRequest);

async function handlePublishDraftLoadRequest(_event, payload) {
  try {
    const id = String(payload?.id || "").trim();
    if (!id) return { ok: false, message: "empty id" };
    const draftsRoot = resolvePublishDraftsRoot();
    const p = path.join(draftsRoot, id, "draft.json");
    if (!fs.existsSync(p)) return { ok: false, message: "not found" };
    const raw = fs.readFileSync(p, "utf-8");
    const obj = JSON.parse(raw || "{}");
    const draft = obj?.draft && typeof obj.draft === "object" ? obj.draft : {};
    return { ok: true, id, name: String(obj?.name || id), draft };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

ipcMain.handle("publishDraft:load", handlePublishDraftLoadRequest);

async function handlePublishDraftRemoveRequest(_event, payload) {
  try {
    const id = String(payload?.id || "").trim();
    if (!id) return { ok: false, message: "empty id" };
    const dir = path.join(resolvePublishDraftsRoot(), id);
    if (!fs.existsSync(dir)) return { ok: false, message: "not found" };
    fs.rmSync(dir, { recursive: true, force: true });
    return { ok: true, id };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

ipcMain.handle("publishDraft:remove", handlePublishDraftRemoveRequest);

async function handlePublishDraftRevealRequest(_event, payload) {
  try {
    const id = String(payload?.id || "").trim();
    if (!id) return { ok: false, message: "empty id" };
    const dir = path.join(resolvePublishDraftsRoot(), id);
    if (!fs.existsSync(dir)) return { ok: false, message: "not found" };
    await shell.openPath(dir);
    return { ok: true, path: dir };
  } catch (e) {
    return { ok: false, message: String(e?.message || e) };
  }
}

ipcMain.handle("publishDraft:reveal", handlePublishDraftRevealRequest);

