      const trySetFileInputFilesInFrame = async (filePath, kind, preferSelector, frameId) => {
        const fp = String(filePath || "").trim();
        if (!fp) return { ok: false, message: "empty filePath" };
        const abs = path.resolve(fp);
        if (!fs.existsSync(abs)) return { ok: false, message: `file not found: ${abs}` };
        const fid = String(frameId || "").trim();
        let rootNodeId = 0;
        if (fid) rootNodeId = await getContentDocumentNodeIdForFrame(fid);
        try {
          if (!rootNodeId) {
            let doc = null;
            try {
              doc = await cdp.send("DOM.getDocument", { depth: -1, pierce: true });
            } catch {
              try {
                doc = await cdp.send("DOM.getDocument", { depth: -1 });
              } catch {
                doc = await cdp.send("DOM.getDocument");
              }
            }
            rootNodeId = Number(doc?.root?.nodeId || 0) || 0;
          }
          if (!rootNodeId) return { ok: false, message: "no root nodeId" };
          const prefer = String(preferSelector || "").trim();
          const selector = prefer || "input[type='file']";
          const q = await cdp.send("DOM.querySelectorAll", { nodeId: rootNodeId, selector });
          const nodeIds = Array.isArray(q?.nodeIds) ? q.nodeIds : [];
          if (!nodeIds.length) return { ok: false, message: "no file inputs" };
          const candidates = [];
          for (const nodeId of nodeIds) {
            try {
              const attrsRes = await cdp.send("DOM.getAttributes", { nodeId });
              const attrs = Array.isArray(attrsRes?.attributes) ? attrsRes.attributes : [];
              const map = {};
              for (let i = 0; i < attrs.length; i += 2) map[String(attrs[i] || "")] = String(attrs[i + 1] || "");
              const accept = String(map.accept || "");
              const id = String(map.id || "");
              const cls = String(map.class || "");
              const name = String(map.name || "");
              const dataRole = String(map["data-role"] || "");
              const bag = `${id} ${cls} ${name} ${dataRole}`.toLowerCase();
              let score = 0;
              try {
                const box = await cdp.send("DOM.getBoxModel", { nodeId });
                const qs = Array.isArray(box?.model?.content) ? box.model.content : [];
                if (qs.length >= 8) score += 2;
              } catch {}
              if (String(kind || "") === "video") {
                if (/video/i.test(accept) || /\.(mp4|mov|mkv|avi|webm|m4v)/i.test(accept)) score += 10;
                if (bag.includes("video")) score += 3;
                if (bag.includes("upload")) score += 1;
                if (/image/i.test(accept) || /\.(png|jpg|jpeg|webp)/i.test(accept)) score -= 6;
                if (bag.includes("cover") || bag.includes("image")) score -= 4;
              } else {
                if (/image/i.test(accept) || /\.(png|jpg|jpeg|webp)/i.test(accept)) score += 10;
                if (bag.includes("cover") || bag.includes("image")) score += 3;
                if (bag.includes("upload")) score += 1;
                if (/video/i.test(accept) || /\.(mp4|mov|mkv|avi|webm|m4v)/i.test(accept)) score -= 10;
                if (bag.includes("video")) score -= 6;
                if (bag.includes("upload-btn")) score -= 5;
              }
              candidates.push({ nodeId, score, accept, id, cls, name });
            } catch {}
          }
          candidates.sort((a, b) => (b.score || 0) - (a.score || 0));
          const best = candidates[0] || null;
          if (!best) return { ok: false, message: "no candidates" };
          await cdp.send("DOM.setFileInputFiles", { nodeId: best.nodeId, files: [abs] });
          return { ok: true, picked: best, abs };
        } catch (e) {
          return { ok: false, message: String(e?.message || e) };
        }
      };

